const $ = (sel) => document.querySelector(sel)

/**
 * 复杂页面的页内分组导航。
 * 只负责“当前看哪一组”和按钮状态，不重绘内容；页面数据与事件仍由各页自己管理。
 */
function mountSectionNav(root, key, fallback, onChange) {
  const buttons = [...root.querySelectorAll('[data-section-target]')]
  const panels = [...root.querySelectorAll('[data-section-panel]')]
  if (!buttons.length || !panels.length) return
  const activate = (value) => {
    const target = buttons.some((button) => button.dataset.sectionTarget === value) ? value : fallback
    for (const button of buttons) {
      const active = button.dataset.sectionTarget === target
      button.classList.toggle('is-active', active)
      button.setAttribute('aria-selected', active ? 'true' : 'false')
    }
    for (const panel of panels) {
      panel.hidden = panel.dataset.sectionPanel !== target
      // 兼容切换前已经挂上 reveal 的旧 DOM：显示时直接跳过，不让它卡在 opacity:0。
      if (!panel.hidden && panel.dataset.motion?.includes('reveal') && !panel.classList.contains('is-motion-in')) {
        panel.classList.add('is-motion-skip')
      }
    }
    onChange?.(target)
  }
  for (const button of buttons) {
    button.addEventListener('click', () => activate(button.dataset.sectionTarget))
  }
  activate(key || fallback)
}

function sectionNavHtml(items, active) {
  return `<nav class="section-nav" role="tablist" aria-label="页面功能区">
    ${items
      .map(
        (item) => `<button type="button" role="tab" data-section-target="${esc(item.key)}"
          class="${active === item.key ? 'is-active' : ''}${item.attention ? ' is-attention' : ''}"
          aria-selected="${active === item.key ? 'true' : 'false'}">
          <strong>${esc(item.label)}</strong>
          ${item.meta ? `<span>${esc(item.meta)}</span>` : ''}
        </button>`,
      )
      .join('')}
  </nav>`
}

function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (ch) => {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]
  })
}

/** 流水线预览用的轻量 Markdown：标题、表格、列表、引用、图片占位；输入已转义，避免二次注入。 */
function renderFlowRich(value) {
  const source = esc(String(value ?? '').replace(/\r\n?/g, '\n'))
  const lines = source.split('\n')
  const output = []
  const inline = (text) =>
    String(text ?? '')
      .replace(/`([^`\n]+)`/g, '<code>$1</code>')
      .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
      .replace(/\*([^*\n]+)\*/g, '<em>$1</em>')
  const isSeparator = (line) => {
    const cells = String(line ?? '').trim().replace(/^\|/, '').replace(/\|$/, '').split('|')
    return cells.length >= 2 && cells.every((cell) => /^:?-{3,}:?$/.test(cell.trim()))
  }
  const splitRow = (line) =>
    String(line ?? '').trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((cell) => cell.trim())
  const splitTabRow = (line) => String(line ?? '').split('\t').map((cell) => cell.trim())
  const tableHtml = (header, rows, caption = '') => {
    const columns = Math.max(header.length, ...rows.map((row) => row.length), 1)
    const pad = (row) => Array.from({ length: columns }, (_, index) => row[index] ?? '')
    return `<div class="kb-flow-table"><table>${
      caption ? `<caption>${inline(caption)}</caption>` : ''
    }<thead><tr>${pad(header)
      .map((cell) => `<th>${inline(cell)}</th>`)
      .join('')}</tr></thead><tbody>${rows
      .map((row) => `<tr>${pad(row).map((cell) => `<td>${inline(cell)}</td>`).join('')}</tr>`)
      .join('')}</tbody></table></div>`
  }
  const tabTableAt = (start) => {
    const rows = []
    let cursor = start
    while (cursor < lines.length && lines[cursor].includes('\t') && lines[cursor].trim()) {
      rows.push(splitTabRow(lines[cursor]))
      cursor += 1
    }
    if (!rows.length) return null
    let caption = ''
    if (rows.length > 1 && rows[0].filter((cell) => cell.trim()).length === 1) {
      caption = rows[0].find((cell) => cell.trim()) ?? ''
      rows.shift()
    }
    return { html: tableHtml(rows[0] ?? [], rows.slice(1), caption), cursor }
  }
  const blockStart = (line) => {
    if (!line.trim()) return true
    if (/^\s{0,3}(#{1,6})\s+/.test(line)) return true
    if (/^\s*[-*•]\s+/.test(line)) return true
    if (/^\s*\d+[.)]\s+/.test(line)) return true
    if (/^\s{0,3}>\s?/.test(line)) return true
    if (/^\[图片\]/.test(line)) return true
    if (line.includes('|')) return true
    return false
  }
  let index = 0
  while (index < lines.length) {
    const line = lines[index]
    if (!line.trim()) {
      index += 1
      continue
    }
    if (/^\[图片\]/.test(line)) {
      const caption = line.replace(/^\[图片\]\s*/, '').trim()
      output.push(
        `<div class="kb-flow-image-line"><span>图片</span><strong>${inline(caption || '文档内嵌图片')}</strong></div>`,
      )
      index += 1
      continue
    }
    const heading = /^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line)
    if (heading) {
      const level = Math.min(6, heading[1].length)
      output.push(`<h${level}>${inline(heading[2].trim())}</h${level}>`)
      index += 1
      continue
    }
    if (line.includes('\t')) {
      const tabTable = tabTableAt(index)
      if (tabTable) {
        output.push(tabTable.html)
        index = tabTable.cursor
        continue
      }
    }
    if (line.includes('|') && index + 1 < lines.length && isSeparator(lines[index + 1])) {
      const header = splitRow(line)
      const rows = []
      let cursor = index + 2
      while (cursor < lines.length && lines[cursor].includes('|') && lines[cursor].trim()) {
        rows.push(splitRow(lines[cursor]))
        cursor += 1
      }
      output.push(
        `<div class="kb-flow-table"><table><thead><tr>${header
          .map((cell) => `<th>${inline(cell)}</th>`)
          .join('')}</tr></thead><tbody>${rows
          .map((row) => `<tr>${row.map((cell) => `<td>${inline(cell)}</td>`).join('')}</tr>`)
          .join('')}</tbody></table></div>`,
      )
      index = cursor
      continue
    }
    if (line.includes('|')) {
      output.push(`<p class="kb-flow-raw-line">${inline(line)}</p>`)
      index += 1
      continue
    }
    if (/^\s{0,3}>\s?/.test(line)) {
      const quotes = []
      let cursor = index
      while (cursor < lines.length && /^\s{0,3}>\s?/.test(lines[cursor])) {
        quotes.push(inline(lines[cursor].replace(/^\s{0,3}>\s?/, '')))
        cursor += 1
      }
      output.push(`<blockquote>${quotes.join('<br>')}</blockquote>`)
      index = cursor
      continue
    }
    const bullet = /^\s{0,3}[-*•]\s+(.+)$/.exec(line)
    const ordered = /^\s{0,3}\d+[.)]\s+(.+)$/.exec(line)
    if (bullet || ordered) {
      const tag = bullet ? 'ul' : 'ol'
      const pattern = bullet ? /^\s{0,3}[-*•]\s+(.+)$/ : /^\s{0,3}\d+[.)]\s+(.+)$/
      const items = []
      let cursor = index
      while (cursor < lines.length) {
        const match = pattern.exec(lines[cursor])
        if (!match) break
        items.push(`<li>${inline(match[1])}</li>`)
        cursor += 1
      }
      output.push(`<${tag}>${items.join('')}</${tag}>`)
      index = cursor
      continue
    }
    const paragraph = []
    let cursor = index
    while (cursor < lines.length && !blockStart(lines[cursor])) {
      if (lines[cursor].trim()) paragraph.push(inline(lines[cursor]))
      cursor += 1
    }
    if (paragraph.length) output.push(`<p>${paragraph.join('<br>')}</p>`)
    index = cursor > index ? cursor : index + 1
  }
  return output.join('') || '<p class="kb-flow-rich-empty">（暂无内容）</p>'
}

/** 系统更新说明按 Markdown 文档展示，不直接把源码塞进 pre。 */
function renderUpdateNotesHtml(notes, latest) {
  const text = String(notes ?? '').trim()
  if (!text) return ''
  return `<details class="update-notes" style="margin-top:10px"><summary>查看 v${esc(
    latest ?? '',
  )} 更新说明</summary><div class="kb-flow-rich update-notes-md">${renderFlowRich(text)}</div></details>`
}

/** 把长说明收成小角标；完整文案挂在 data-tip，由统一浮层按需展示。 */
function hintBadge(label, tip, ariaLabel, extraClass = '', id = '') {
  const cls = extraClass ? `hint-badge ${extraClass}` : 'hint-badge'
  const idAttr = id ? ` id="${esc(id)}"` : ''
  return `<span class="${cls}"${idAttr} data-tip="${esc(tip)}" tabindex="0" aria-label="${esc(ariaLabel || label)}">${esc(label)}</span>`
}

/** 独立一行的角标：用于表单说明、弹窗提示等原本占一整段的文案。 */
function hintNote(label, tip, ariaLabel) {
  return `<div class="hint-note">${hintBadge(label, tip, ariaLabel)}</div>`
}

const TOP_TOAST_KEY = 'eab_top_toast'

/** 顶部浮动提示：成功类反馈不阻塞页面，自动消失。 */
function showTopToast(message, options = {}) {
  if (window.EABOverlay?.toast) return window.EABOverlay.toast(message, options)
  const tone = options.tone || 'success'
  const duration = Number(options.duration) > 0 ? Number(options.duration) : 4500
  let host = document.querySelector('.top-toast-host')
  if (!host) {
    host = document.createElement('div')
    host.className = 'top-toast-host'
    document.body.appendChild(host)
  }
  const item = document.createElement('div')
  item.className = `top-toast is-${tone}`
  item.setAttribute('role', 'status')
  item.setAttribute('aria-live', 'polite')

  const icon = document.createElement('span')
  icon.className = 'top-toast-icon'
  icon.setAttribute('aria-hidden', 'true')
  icon.innerHTML = '<svg viewBox="0 0 24 24" focusable="false"><path d="m5 12 4 4 10-10"/></svg>'

  const copy = document.createElement('span')
  copy.className = 'top-toast-copy'
  copy.textContent = String(message ?? '')

  const close = document.createElement('button')
  close.className = 'top-toast-close'
  close.type = 'button'
  close.setAttribute('aria-label', '关闭提示')
  close.textContent = '×'

  const action = options.action && options.action.label ? options.action : null
  const actionButton = action
    ? Object.assign(document.createElement('button'), {
        className: 'top-toast-action',
        type: 'button',
        textContent: String(action.label),
      })
    : null

  item.append(icon, copy)
  if (actionButton) item.append(actionButton)
  item.append(close)
  host.appendChild(item)

  let timer = 0
  const dismiss = () => {
    if (!item.isConnected) return
    item.classList.add('is-leaving')
    setTimeout(() => {
      item.remove()
      if (host && !host.childElementCount) host.remove()
    }, 180)
  }
  timer = setTimeout(dismiss, duration)
  close.addEventListener('click', () => {
    clearTimeout(timer)
    dismiss()
  })
  if (actionButton && action) {
    actionButton.addEventListener('click', () => {
      clearTimeout(timer)
      dismiss()
      try {
        action.onClick?.()
      } catch {
        /* 用户点击撤销后的异常不打断提示关闭 */
      }
    })
  }
  return { dismiss }
}

/** 跳页前把成功提示暂存，目标页 boot 后接着显示。 */
function queueTopToast(message, options = {}) {
  try {
    sessionStorage.setItem(TOP_TOAST_KEY, JSON.stringify({ message, options }))
  } catch {
    /* 私密模式 / 存储受限时忽略，不影响绑定结果 */
  }
}

/** 删除类确认统一成功反馈：只在确认且删除请求成功后提示，取消或失败时不误报。 */
const DELETE_ACTION_FEEDBACK = /删除|移除|清空/

/** 保存 / 删除按钮统一成功反馈：只在写请求成功后提示，失败时不误报。 */
const SAVE_TOAST_SKIP_IDS = new Set(['save-role', 'save-role-console', 'branding-save', 'pm-save', 'oo-save', 'web-search-save', 'browser-network-save'])
let pendingSaveFeedback = null

function clearPendingSaveFeedback() {
  if (!pendingSaveFeedback) return
  clearTimeout(pendingSaveFeedback.idleTimer)
  clearTimeout(pendingSaveFeedback.toastTimer)
  pendingSaveFeedback = null
}

function saveFeedbackMessage(button) {
  const label = String(button?.textContent || '').replace(/\s+/g, '')
  if (label.includes('角色')) return '角色已保存'
  if (label.includes('后台权限')) return '后台权限已保存'
  if (label.includes('并切换')) return '保存成功，正在切换'
  if (label.includes('并生效')) return '保存成功，已生效'
  if (label.includes('并绑定')) return '保存成功，已绑定'
  if (label.includes('密码')) return '密码已保存'
  if (label.includes('版本')) return '版本已保存'
  if (label.includes('用例')) return '用例已保存'
  if (label.includes('策略')) return '策略已保存'
  if (label.includes('模型')) return '模型已保存'
  if (label.includes('品牌')) return '品牌设置已保存'
  if (label.includes('配置')) return '配置已保存'
  if (label.includes('绑定')) return '绑定已保存'
  if (label.includes('权限')) return '权限已保存'
  return '保存成功'
}

function deleteFeedbackMessage(text) {
  const label = String(text || '').replace(/\s+/g, '').replace(/[?？!！。]/g, '')
  if (label.includes('清空')) {
    const noun = label.replace(/确认|清空/g, '').trim()
    return noun ? `${noun}已清空` : '已清空'
  }
  const removed = label.includes('移除')
  const noun = label.replace(/确认|删除|移除/g, '').trim()
  if (noun) return `${noun}已${removed ? '移除' : '删除'}`
  return removed ? '已移除' : '删除成功'
}

function armDeleteFeedback(text) {
  clearPendingSaveFeedback()
  pendingSaveFeedback = {
    message: deleteFeedbackMessage(text),
    started: false,
    idleTimer: setTimeout(clearPendingSaveFeedback, 2500),
    toastTimer: 0,
  }
}

function armSaveFeedback(button) {
  clearPendingSaveFeedback()
  pendingSaveFeedback = {
    message: saveFeedbackMessage(button),
    started: false,
    idleTimer: setTimeout(clearPendingSaveFeedback, 2500),
    toastTimer: 0,
  }
}

function saveFeedbackRequestStarted() {
  if (!pendingSaveFeedback) return
  clearTimeout(pendingSaveFeedback.idleTimer)
  clearTimeout(pendingSaveFeedback.toastTimer)
  pendingSaveFeedback.started = true
}

function saveFeedbackRequestFinished(ok) {
  if (!pendingSaveFeedback || !pendingSaveFeedback.started) return
  if (!ok) {
    clearPendingSaveFeedback()
    return
  }
  clearTimeout(pendingSaveFeedback.toastTimer)
  pendingSaveFeedback.toastTimer = setTimeout(() => {
    const message = pendingSaveFeedback.message
    clearPendingSaveFeedback()
    showTopToast(message)
  }, 300)
}

function trackSaveResponse(promise) {
  return promise.then(
    (value) => {
      saveFeedbackRequestFinished(true)
      return value
    },
    (err) => {
      saveFeedbackRequestFinished(false)
      throw err
    },
  )
}

document.addEventListener(
  'click',
  (event) => {
    const target = event.target instanceof Element ? event.target : null
    const button = target?.closest('button')
    if (!button || button.disabled || button.dataset.saveToast === 'off') return
    if (SAVE_TOAST_SKIP_IDS.has(button.id)) return
    const label = String(button.textContent || '').replace(/\s+/g, '')
    if (!label.includes('保存')) return
    armSaveFeedback(button)
  },
  true,
)

function flushQueuedTopToast() {
  try {
    const raw = sessionStorage.getItem(TOP_TOAST_KEY)
    if (!raw) return
    sessionStorage.removeItem(TOP_TOAST_KEY)
    const payload = JSON.parse(raw)
    if (payload && payload.message) showTopToast(payload.message, payload.options || {})
  } catch {
    /* 残留内容不合法时直接丢弃 */
  }
}

/** 模型表格的统一图标操作；图标本身不带文字，名称挂在浮层与 aria-label。 */
function modelActionIcon(name) {
  const paths = {
    test: '<path d="M9 7V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v3"/><path d="M7 7h10v3a5 5 0 0 1-10 0V7Z"/><path d="M12 15v5"/>',
    discover: '<circle cx="10.5" cy="10.5" r="4.5"/><path d="m14 14 4 4"/><path d="M10.5 8.5v4M8.5 10.5h4"/>',
    edit: '<path d="M4 20h4l10-10-4-4L4 16v4Z"/><path d="m13 5 4 4"/>',
    toggle: '<path d="M12 3v9"/><path d="M6.5 6.5a8 8 0 1 0 11 0"/>',
    delete: '<path d="M4 7h16"/><path d="M9 7V5h6v2"/><path d="M6 7l1 13h10l1-13"/><path d="M10 11v5M14 11v5"/>',
    stress: '<path d="M4 17a8 8 0 0 1 16 0"/><path d="m12 17 4-5"/><circle cx="12" cy="17" r="1.2"/>',
  }
  return `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">${paths[name] || ''}</svg>`
}

/** 控制台角标浮层：只绑定一次，后续页面重绘不需要重新挂监听。 */
function bindHintTips() {
  if (document.body.dataset.hintTipBound === '1') return
  document.body.dataset.hintTipBound = '1'
  const tip = document.createElement('div')
  tip.className = 'hint-tip'
  tip.id = 'admin-hint-tip'
  tip.setAttribute('role', 'tooltip')
  document.body.appendChild(tip)
  let current = null
  const hide = () => {
    if (current) current.removeAttribute('aria-describedby')
    current = null
    tip.classList.remove('is-visible')
  }
  const show = (target) => {
    const text = target?.dataset?.tip
    if (!text) return
    if (current && current !== target) current.removeAttribute('aria-describedby')
    current = target
    target.setAttribute('aria-describedby', tip.id)
    tip.textContent = text
    tip.style.left = '0px'
    tip.style.top = '0px'
    tip.classList.add('is-visible')
    const rect = target.getBoundingClientRect()
    const tipWidth = tip.offsetWidth
    const tipHeight = tip.offsetHeight
    let left = rect.left + rect.width / 2 - tipWidth / 2
    left = Math.max(8, Math.min(left, window.innerWidth - tipWidth - 8))
    let top = rect.bottom + 8
    if (top + tipHeight > window.innerHeight - 8) top = rect.top - tipHeight - 8
    tip.style.left = `${Math.round(left)}px`
    tip.style.top = `${Math.max(8, Math.round(top))}px`
  }
  const targetOf = (event) => event.target?.closest?.('[data-tip]')
  document.addEventListener('pointerover', (event) => {
    const target = targetOf(event)
    if (target) show(target)
  })
  document.addEventListener('pointerout', (event) => {
    const target = targetOf(event)
    if (target && !target.contains(event.relatedTarget)) hide()
  })
  document.addEventListener('focusin', (event) => {
    const target = targetOf(event)
    if (target) show(target)
  })
  document.addEventListener('focusout', (event) => {
    const target = targetOf(event)
    if (target && !target.contains(event.relatedTarget)) hide()
  })
  window.addEventListener('scroll', hide, true)
  window.addEventListener('resize', hide)
  // 页面重绘或弹窗关闭时，原角标可能已被移除；此时收起浮层，避免留下幽灵提示。
  new MutationObserver(() => {
    if (current && !current.isConnected) hide()
  }).observe(document.body, { childList: true, subtree: true })
}

function qs(path) {
  if (!state.company) return ''
  const sep = String(path ?? '').includes('?') ? '&' : '?'
  return `${sep}company=${encodeURIComponent(state.company)}`
}

let consoleAuthRedirecting = false

function redirectToConsoleLogin() {
  if (consoleAuthRedirecting) return
  consoleAuthRedirecting = true
  // 控制台未登录/会话过期时统一回到服务器侧管理员登录门，
  // 保留 company 等查询参数，登录成功后 gate 会原样带回。
  location.replace('/admin' + (location.search || ''))
}

async function parseResponse(res) {
  let body = null
  try {
    body = await res.json()
  } catch {
    body = null
  }
  if (!res.ok || !body || body.ok === false) {
    const err = body && body.ok === false ? body : { code: 'EAB_INTERNAL', message: `HTTP ${res.status}` }
    err.status = res.status
    // 控制台会话缺失或过期：不再把错误渲染到当前页/弹提示，直接跳登录门。
    // 返回一个永不结束的 Promise，让调用方的 catch/提示逻辑没有机会执行。
    if (res.status === 401) {
      redirectToConsoleLogin()
      return await new Promise(() => {})
    }
    throw err
  }
  return body.data
}

async function api(path) {
  const res = await fetch(path + qs(path), {
    headers: { accept: 'application/json', 'x-eab-console': '1' },
  })
  return parseResponse(res)
}

/** 显式指定公司读取（组织页需要同时拉多家公司） */
async function apiForCompany(path, companyId) {
  const sep = String(path ?? '').includes('?') ? '&' : '?'
  const url = `${path}${sep}company=${encodeURIComponent(companyId)}`
  const res = await fetch(url, { headers: { accept: 'application/json', 'x-eab-console': '1' } })
  return parseResponse(res)
}

async function apiPost(path, body) {
  saveFeedbackRequestStarted()
  try {
    const res = await fetch(path + qs(path), {
      method: 'POST',
      headers: { accept: 'application/json', 'content-type': 'application/json', 'x-eab-console': '1' },
      body: JSON.stringify(body ?? {}),
    })
    return await trackSaveResponse(parseResponse(res))
  } catch (err) {
    saveFeedbackRequestFinished(false)
    throw err
  }
}

async function apiSend(method, path, body) {
  saveFeedbackRequestStarted()
  try {
    const headers = { accept: 'application/json', 'x-eab-console': '1' }
    if (body !== undefined) headers['content-type'] = 'application/json'
    const res = await fetch(path + qs(path), {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    })
    return await trackSaveResponse(parseResponse(res))
  } catch (err) {
    saveFeedbackRequestFinished(false)
    throw err
  }
}

/** multipart 上传不设 content-type，浏览器会自动补 boundary。 */
async function apiUpload(path, formData) {
  saveFeedbackRequestStarted()
  try {
    const res = await fetch(path + qs(path), {
      method: 'POST',
      headers: { accept: 'application/json', 'x-eab-console': '1' },
      body: formData,
    })
    return await trackSaveResponse(parseResponse(res))
  } catch (err) {
    saveFeedbackRequestFinished(false)
    throw err
  }
}

function renderDenied(container, err) {
  container.innerHTML = `
    <div class="denied" role="alert">
      <h2>${esc(err.message || '请求被拒绝')}</h2>
      <span class="code">${esc(err.code || 'EAB_INTERNAL')}${err.status ? ` · HTTP ${err.status}` : ''}</span>
      <div class="muted">${esc(err.hint || '这是 PDP 的判定结果——当前身份不具备该动作所需的权限。')}</div>
      ${err.details ? `<div class="sql-box" style="margin-top:10px">${esc(JSON.stringify(err.details, null, 2))}</div>` : ''}
      ${err.traceId ? `<div class="muted" style="margin-top:8px;font-size:12px">traceId: <code>${esc(err.traceId)}</code></div>` : ''}
    </div>`
}

/** 统一的空/错误状态块；表格内用 compact，避免把行撑成整屏。 */
function stateBlockHtml({
  tone = 'neutral',
  title,
  body = '',
  actionLabel = '',
  action = '',
  compact = false,
} = {}) {
  const role = tone === 'error' ? 'alert' : 'status'
  const actionClass = compact ? 'link-btn' : 'btn sm ghost'
  return `<div class="${compact ? 'table-state' : 'state-block'} is-${tone}" role="${role}">
    <div class="state-copy">
      <strong>${esc(title || '')}</strong>
      ${body ? `<p>${esc(body)}</p>` : ''}
    </div>
    ${actionLabel ? `<button class="${actionClass}" type="button" data-state-action="${esc(action)}">${esc(actionLabel)}</button>` : ''}
  </div>`
}

function isPermissionError(err) {
  const status = Number(err?.status || 0)
  if (status === 401 || status === 403) return true
  return /pdp|permission|forbidden|denied|unauthorized/i.test(String(err?.code || ''))
}

/** 统一把网络类错误本地化，页面级错误块和详情弹层共用同一套文案。 */
function consoleErrorText(err) {
  const rawMessage = String(err?.message || '')
  if (/failed to fetch|networkerror|network error|network request failed/i.test(rawMessage)) {
    return '网络连接失败，请确认服务正在运行后重试。'
  }
  return rawMessage || '请求没有完成，请稍后重试。'
}

/** 权限拒绝保留 PDP 说明；网络/5xx 给“加载失败 + 重试”，不把两类错误混在一起。 */
function renderConsoleError(container, err, retry) {
  if (isPermissionError(err)) {
    renderDenied(container, err)
    return
  }
  const message = consoleErrorText(err)
  container.innerHTML = stateBlockHtml({
    tone: 'error',
    title: '加载失败',
    body: message,
    actionLabel: typeof retry === 'function' ? '重试' : '',
    action: 'state-retry',
  })
  container.querySelector('[data-state-action="state-retry"]')?.addEventListener('click', () => {
    if (typeof retry === 'function') retry()
  })
}

function renderLoading(container, text = '加载中…', options = {}) {
  if (options.skeleton) {
    const rows = Math.max(2, Math.min(8, Number(options.rows) || 5))
    container.innerHTML = `<div class="state-skeleton" role="status" aria-label="${esc(text)}" aria-live="polite">${Array.from(
      { length: rows },
      () => '<span class="state-skeleton-line" aria-hidden="true"></span>',
    ).join('')}</div>`
    return
  }
  container.innerHTML = `<div class="loading">${esc(text)}</div>`
}

/* ---------------- 管理范围（公司） ---------------- */

async function loadCompanies() {
  const data = await api('/api/console/companies')
  state.companies = data.companies
  if (!state.company || !state.companies.some((c) => c.id === state.company)) {
    state.company = data.defaultCompanyId || (state.companies[0] ? state.companies[0].id : null)
  }

  renderCompanyPicker()

  const url = new URL(location.href)
  if (state.company) url.searchParams.set('company', state.company)
  history.replaceState(null, '', url.toString())
}

function closeCompanyPicker() {
  const menu = $('#company-picker-menu')
  const button = $('#company-picker-btn')
  if (menu) menu.hidden = true
  if (button) button.setAttribute('aria-expanded', 'false')
}

/** 公司来源标识：同一家公司下钉钉 / 飞书 / 企业微信分别绑定，顶栏和公司选项都要能看出渠道来源 */
function companyChannelSources(company) {
  const rows = Array.isArray(company?.channels) ? company.channels : []
  const byProvider = new Map(rows.map((row) => [row.provider, row]))
  return ['dingtalk', 'feishu', 'wecom']
    .map((provider) => {
      const row = byProvider.get(provider)
      const label = CHANNEL_SOURCE_LABEL[provider] || provider
      const bound = row?.status === 'bound'
      const tenant = String(row?.tenantName ?? '').trim()
      const title = tenant ? `${label} · ${tenant}` : `${label} · ${bound ? '已绑定' : '未绑定'}`
      return `<span class="company-source${bound ? ' is-bound' : ''}" title="${esc(title)}">${esc(label)}</span>`
    })
    .join('')
}

function renderCompanyPicker() {
  const picker = $('#company-picker')
  if (!picker) return
  const current = companyMeta()

  /**
   * 单公司本地部署：没有“切换管理范围”。
   * 只显示这家公司本身，像一个身份牌，而不是一个可选多家公司的下拉。
   */
  if (state.companies.length <= 1) {
    const empty = state.companies.length === 0
    const only = state.companies[0] ?? current
    picker.innerHTML = `
      <div class="company-single${empty ? ' is-empty' : ''}" aria-label="当前公司">
        <span class="company-single-name">
          <strong>${esc(empty ? '未接入公司' : only?.name ?? '未接入公司')}</strong>
        </span>
      </div>`
    picker.onclick = null
    return
  }

  const options = state.companies
    .map((company) => {
      const users = Number(company.counts?.users ?? 0)
      const depts = Number(company.counts?.depts ?? 0)
      const active = company.id === state.company
      return `<button class="company-option${active ? ' is-active' : ''}" type="button" role="option" aria-selected="${active}" data-company="${esc(company.id)}">
        <span class="company-option-main"><strong>${esc(company.name)}</strong><code>${esc(company.id)}</code></span>
        <span class="company-option-meta">${users} 成员 · ${depts} 部门</span>
        <span class="company-sources" aria-label="渠道来源">${companyChannelSources(company)}</span>
        ${active ? '<span class="company-option-check">当前</span>' : ''}
      </button>`
    })
    .join('')

  picker.innerHTML = `
    <div class="company-picker-control">
      <button class="company-picker-btn" id="company-picker-btn" type="button" aria-haspopup="listbox" aria-expanded="false">
        <span class="company-picker-current">
          <strong>${esc(current?.name ?? '选择公司')}</strong>
          <code>${esc(current?.id ?? '')}</code>
        </span>
        <span class="company-picker-chevron">▾</span>
      </button>
      <div class="company-picker-menu" id="company-picker-menu" role="listbox" aria-label="切换管理公司" hidden>
        <div class="company-picker-menu-head">切换管理范围</div>
        ${options || '<div class="company-picker-empty">没有可选公司</div>'}
        ${hintBadge('切换说明', '切换后，当前页的权限、模型、知识库与设置都会按新公司重新加载。')}
      </div>
    </div>
    <span class="company-picker-hint">此页所有配置按这家公司隔离</span>`

  const pickerHandler = (event) => {
    const option = event.target.closest('[data-company]')
    if (option) {
      event.preventDefault()
      closeCompanyPicker()
      applyCompany(option.dataset.company)
      return
    }
    if (event.target.closest('#company-picker-btn')) {
      event.preventDefault()
      const menu = $('#company-picker-menu')
      const button = $('#company-picker-btn')
      if (!menu || !button) return
      const open = menu.hidden
      menu.hidden = !open
      button.setAttribute('aria-expanded', String(open))
      return
    }
    if (!event.target.closest('.company-picker-control')) closeCompanyPicker()
  }
  picker.onclick = pickerHandler
}

async function applyCompany(companyId) {
  if (!companyId || companyId === state.company) return
  switchCompany(companyId)
  state.selectedCollection = null
  state.kb = null
  state.collapsed.clear()
  renderCompanyPicker()
  try {
    await loadMe()
  } catch {
    /* 顶栏切公司不应被身份刷新失败挡住 */
  }
  await PAGES[state.page].render()
}

/**
 * 顶部账号头像：有钉钉头像时盖在姓名首字上；加载失败只摘掉图片，保留首字，
 * 避免防盗链或接口异常时出现破图。
 */
function setAccountAvatar(el, name, url) {
  if (!el) return
  const initial = String(name || '管').trim().charAt(0) || '管'
  el.textContent = initial
  el.classList.remove('has-photo')
  if (!url) return
  const img = document.createElement('img')
  img.className = 'account-avatar-img'
  img.alt = ''
  img.loading = 'eager'
  img.addEventListener(
    'error',
    () => {
      img.remove()
      el.classList.remove('has-photo')
      el.textContent = initial
    },
    { once: true },
  )
  img.src = url
  el.textContent = ''
  el.append(img)
  el.classList.add('has-photo')
}

async function loadMe() {
  const access = await api('/api/console/access')
  state.access = access
  state.allowedPages = Array.isArray(access.allowedPages) ? [...access.allowedPages] : []
  state.managePages = Array.isArray(access.managePages) ? [...access.managePages] : []
  state.pageActions = access.actionsByPage && typeof access.actionsByPage === 'object'
    ? { ...access.actionsByPage }
    : Object.fromEntries(
        (Array.isArray(access.pages) ? access.pages : []).map((item) => {
          const actions = []
          if (item.canCreate) actions.push('create')
          if (item.canEdit) actions.push('edit')
          if (item.canDelete) actions.push('delete')
          return [item.page, actions]
        }),
      )
  state.sectionPermissions = {}
  state.sectionConfigured = new Set()
  for (const item of Array.isArray(access.pages) ? access.pages : []) {
    if (!item?.section || !item?.parentPage) continue
    const key = `${item.parentPage}:${item.section}`
    state.sectionPermissions[key] = {
      canView: item.canView === true,
      canCreate: item.canCreate === true,
      canEdit: item.canEdit === true,
      canDelete: item.canDelete === true,
    }
    state.sectionConfigured.add(item.parentPage)
  }
  const me = await api('/api/me')
  state.me = me
  const name = access.kind === 'member'
    ? (access.name || me.person?.name || '公司成员')
    : me.company
      ? me.company.name
      : '管理范围'
  const nameEl = $('#account-name')
  if (nameEl) nameEl.textContent = name
  const popName = $('#account-name-pop')
  if (popName) popName.textContent = name
  const avatarUrl = access.kind === 'member' && me.person?.avatar
    ? `/api/me/avatar?v=${encodeURIComponent(`${me.person.id}:${me.person.avatar}`)}`
    : ''
  setAccountAvatar($('#account-avatar'), name, avatarUrl)
  setAccountAvatar($('#account-avatar-pop'), name, avatarUrl)
  const passwordAction = $('#account-password')
  if (passwordAction) passwordAction.hidden = access.kind === 'member'
  applyAccessToTopNav()

  const foot = $('#nav-tail')
  if (foot) foot.textContent = ''

  const caps = $('#caps')
  if (caps) {
    const shown = me.capabilities.slice(0, 10)
    const rest = me.capabilities.length - shown.length
    caps.innerHTML =
      shown.map((cap) => `<span class="chip" title="${esc(cap.scope)}">${esc(cap.label)}</span>`).join('') +
      (rest > 0 ? `<span class="chip accent" title="共 ${me.capabilities.length} 项能力">+${rest} 项</span>` : '')
  }
}

/* ---------------- 组织树 ---------------- */

function treePathsWithChildren(node, out = []) {
  if (!node) return out
  if (Array.isArray(node.children) && node.children.length > 0) out.push(node.path)
  for (const child of node.children || []) treePathsWithChildren(child, out)
  return out
}

function renderTree(node, depth, container, failed) {
  if (failed) {
    container.innerHTML = `<div class="banner danger" style="margin:0;flex-direction:column;align-items:flex-start;gap:4px">
      <strong>${esc(failed.message)}</strong>
      <span class="mono">${esc(failed.code)}</span>
    </div>`
    return
  }
  if (!node) {
    container.innerHTML = '<div class="empty">暂无部门</div>'
    return
  }
  const hasKids = Array.isArray(node.children) && node.children.length > 0
  const folded = state.collapsed.has(node.path)
  const total = Number(node.subtreeMemberCount ?? node.memberCount ?? 0)
  const currentCompany = depth === 0 && node.companyId === state.company
  const row = document.createElement('div')
  row.className = `tree-row dept-row${state.deptFilter === node.path ? ' is-active' : ''}${currentCompany ? ' is-current-company' : ''}`
  row.style.paddingLeft = `${10 + depth * 16}px`
  const childCount = node.children?.length ?? 0
  const manager = node.managerName ? `负责人 ${node.managerName}` : '未设置负责人'
  row.innerHTML = `
    <span class="caret ${hasKids ? '' : 'leaf'} ${folded ? 'folded' : ''}">${hasKids ? '▸' : '·'}</span>
    <span class="tree-avatar" aria-hidden="true">${esc(String(node.name || '部').slice(0, 1))}</span>
    <span class="tree-body">
      <span class="tree-name">${esc(node.name)}${currentCompany ? '<span class="tree-current">当前</span>' : ''}</span>
      <span class="tree-sub">${esc(manager)}${hasKids ? ` · ${childCount} 个下级` : ''}</span>
    </span>
    <span class="count" title="直属 ${node.memberCount} 人 · 含下级 ${total} 人"><strong>${total}</strong><span>人</span></span>`

  row.dataset.path = node.path
  row.addEventListener('click', (event) => {
    activateDept(node, { toggle: !event.target.closest('.count') })
  })
  row.addEventListener('contextmenu', (event) => {
    event.preventDefault()
    activateDept(node, { toggle: false })
    showDeptMenu(node, event.clientX, event.clientY)
  })

  container.appendChild(row)
  if (!folded) {
    for (const child of node.children) renderTree(child, depth + 1, container, null)
  }
}

let rootNodes = []

function repaintTree() {
  const container = $('#tree')
  if (!container) return
  container.innerHTML = ''
  for (const node of rootNodes) renderTree(node, 0, container, null)
}

function activateDept(node, { toggle = false } = {}) {
  // 多公司树：点到哪家公司，就把后续成员查询切到哪家
  if (node.companyId && node.companyId !== state.company) {
    switchCompany(node.companyId)
  }
  // 点什么都先筛这个部门：叶子部门也要有反应，否则点了像是"没坏但没生效"
  state.deptFilter = node.path
  // 有下级就顺带展开/收起（点人数只筛不折叠，避免"想看人却把树收没了"）
  if (toggle && Array.isArray(node.children) && node.children.length > 0) {
    if (state.collapsed.has(node.path)) state.collapsed.delete(node.path)
    else state.collapsed.add(node.path)
  }
  repaintTree()
  if (state.page === 'departments') {
    renderDeptDetail(node)
    return
  }
  const list = $('#org-members')
  if (list) loadMembers(list)
}

let deptMenu = null

function hideDeptMenu() {
  if (deptMenu) {
    deptMenu.remove()
    deptMenu = null
  }
}

function showDeptMenu(node, x, y) {
  hideDeptMenu()
  if (!node) return
  const isRoot = isRootDept(node)
  const el = document.createElement('div')
  el.className = 'ctx-menu dept-menu'
  el.id = 'dept-menu'
  el.innerHTML = `
    <div class="ctx-menu-head">${esc(node.name)}</div>
    <button type="button" data-dept-act="edit">编辑部门</button>
    ${isRoot ? '' : '<button type="button" data-dept-act="delete" class="danger">删除部门</button>'}`
  document.body.appendChild(el)
  const width = 188
  const height = isRoot ? 112 : 148
  el.style.left = `${Math.min(x, window.innerWidth - width - 8)}px`
  el.style.top = `${Math.min(y, window.innerHeight - height - 8)}px`
  deptMenu = el
  el.addEventListener('click', (event) => {
    const action = event.target.closest('[data-dept-act]')?.dataset.deptAct
    if (!action) return
    hideDeptMenu()
    if (action === 'edit') openDeptEdit(node)
    if (action === 'delete') deleteDept(node)
  })
}

async function refreshOrgRoots() {
  // 组织页同时展示所有公司：每家一个公司根节点，下面挂各自部门树
  const roots = []
  const names = {}
  let deptTotal = 0
  for (const company of state.companies) {
    const data = await apiForCompany('/api/org/tree', company.id)
    const node = data.root
    if (!node) continue
    node.companyId = company.id
    const walk = (item) => {
      if (!item) return
      item.companyId = company.id
      if (item.path) names[item.path] = item.name
      for (const child of item.children || []) walk(child)
    }
    walk(node)
    roots.push(node)
    deptTotal += Number(data.total ?? 0)
  }
  rootNodes = roots
  state.deptNames = names
  return { roots, deptTotal }
}

async function loadTree() {
  const container = $('#tree')
  if (!container) return
  container.innerHTML = ''
  try {
    const { roots, deptTotal } = await refreshOrgRoots()
    const count = $('#dept-count')
    if (count) {
      count.textContent = `${roots.length} 家公司 · ${deptTotal} 个业务部门`
      count.title = '业务部门数量不含公司根部门'
    }
    for (const node of roots) renderTree(node, 0, container, null)
  } catch (err) {
    const count = $('#dept-count')
    if (count) count.textContent = ''
    renderTree(null, 0, container, err)
  }
}

/* ---------------- 知识库 ---------------- */

function aclText(acl) {
  if (!acl.valid) return '配置无效（已按不可见处理）'
  if (acl.mode === 'all') return '全公司'
  if (acl.mode === 'roles') return (acl.roles || []).map((r) => ROLE_LABEL[r] || r).join('、') || '（空角色列表）'
  if (acl.mode === 'depts') return (acl.deptPaths || []).join('、') || '（空部门列表）'
  if (acl.mode === 'private') return acl.ownerUserId ? `所有者 ${acl.ownerUserId}` : '（缺所有者）'
  return acl.mode
}

async function loadKb() {
  const view = $('#view')
  renderLoading(view, '正在读取知识库', { skeleton: true, rows: 4 })
  setSide(`<div class="side-head">知识库</div><div class="side-note muted">加载中…</div>`)
  try {
    const data = await api('/api/kb/collections')
    let consoleData = null
    try {
      consoleData = await api('/api/console/kb/collections')
    } catch {
      consoleData = null
    }
    if (consoleData?.collections) {
      const meta = new Map(consoleData.collections.map((item) => [item.id, item]))
      data.collections = data.collections.map((item) => {
        const source = meta.get(item.id)
        return source
          ? {
              ...item,
              sourceKind: source.sourceKind,
              sourceLabel: source.sourceLabel,
              sourceConfig: source.sourceConfig,
              sourceSecretConfigured: source.sourceSecretConfigured,
            }
          : item
      })
    }
    state.kb = data
    renderKbSide(data)
    if (data.collections.length === 0) {
      view.innerHTML = `<div id="kb-docs">${stateBlockHtml({
        title: '还没有知识库',
        body: '新建一个知识库后，可以上传文件、接入外部来源，并在对话里引用。',
        actionLabel: '新建知识库',
        action: 'kb-empty-new',
      })}</div>`
      $('#kb-docs')?.querySelector('[data-state-action="kb-empty-new"]')?.addEventListener('click', () => openKbModal(null))
      return
    }
    view.innerHTML = `<div id="kb-docs"><section class="panel"><div class="empty">从左侧选择一个知识库，或新建一个</div></section></div>`

    const keep =
      state.selectedCollection && data.collections.some((c) => c.id === state.selectedCollection)
        ? state.selectedCollection
        : null
    if (keep) loadDocs(keep)
    else if (data.collections.length > 0) {
      state.selectedCollection = data.collections[0].id
      renderKbSide(data)
      loadDocs(data.collections[0].id)
    }
  } catch (err) {
    setSide('', true)
    renderConsoleError(view, err, () => loadKb())
  }
}

function renderKbSide(data) {
  const items = data.collections
    .map((item) => {
      const active = state.selectedCollection === item.id ? ' is-active' : ''
      const kind = item.sourceKind || 'local'
      const source = kind === 'local' ? '' : ` · 外部/${item.sourceLabel || kind}`
      return `<div class="side-item${active}" data-collection="${esc(item.id)}" data-kind="${esc(kind)}">
        <button class="side-item-main" type="button" data-kb-open>
          <strong>${esc(item.name)}</strong>
          <span class="side-item-sub">${esc(MODE_LABEL[item.acl.mode] || item.acl.mode)} · ${item.docCount} 篇文档${esc(source)}</span>
        </button>
        <button class="side-item-more" type="button" data-kb-more title="更多操作">⋯</button>
      </div>`
    })
    .join('')

  setSide(`
    <div class="side-head">知识库 <span class="muted">${data.collections.length}</span></div>
    <button class="btn primary side-add" type="button" id="kb-new">新建知识库</button>
    <div class="side-list">${items || '<div class="side-note">还没有知识库，点上方新建</div>'}</div>`)

  $('#kb-new')?.addEventListener('click', () => openKbModal(null))

  for (const item of document.querySelectorAll('.side-item[data-collection]')) {
    const select = () => {
      state.selectedCollection = item.dataset.collection
      for (const row of document.querySelectorAll('.side-item[data-collection]')) {
        row.classList.toggle('is-active', row.dataset.collection === state.selectedCollection)
      }
      loadDocs(state.selectedCollection)
    }
    item.querySelector('[data-kb-open]')?.addEventListener('click', select)
    item.querySelector('[data-kb-more]')?.addEventListener('click', (event) => {
      event.stopPropagation()
      const rect = event.currentTarget.getBoundingClientRect()
      showKbMenu(item.dataset.collection, rect.right, rect.bottom + 4)
    })
    item.addEventListener('contextmenu', (event) => {
      event.preventDefault()
      showKbMenu(item.dataset.collection, event.clientX, event.clientY)
    })
  }
}

function kbCollection(id) {
  return (state.kb?.collections ?? []).find((item) => item.id === id) || null
}

let kbMenu = null

function hideKbMenu() {
  if (kbMenu) {
    kbMenu.remove()
    kbMenu = null
  }
}

function showKbMenu(collectionId, x, y) {
  hideKbMenu()
  const collection = kbCollection(collectionId)
  if (!collection) return
  const el = document.createElement('div')
  el.className = 'ctx-menu kb-menu'
  el.id = 'kb-menu'
  el.innerHTML = `
    <div class="ctx-menu-head">${esc(collection.name)}</div>
    <button type="button" data-kb-act="edit">编辑 / 可见范围</button>
    <button type="button" data-kb-act="rename">重命名</button>
    <button type="button" data-kb-act="delete" class="danger">删除知识库</button>`
  document.body.appendChild(el)
  const width = 188
  const height = 148
  el.style.left = `${Math.min(x, window.innerWidth - width - 8)}px`
  el.style.top = `${Math.min(y, window.innerHeight - height - 8)}px`
  kbMenu = el
  el.addEventListener('click', (event) => {
    const action = event.target.closest('[data-kb-act]')?.dataset.kbAct
    if (!action) return
    hideKbMenu()
    if (action === 'edit') openKbModal(collection)
    if (action === 'rename') renameKb(collection)
    if (action === 'delete') removeKb(collection)
  })
}

async function renameKb(collection) {
  const next = prompt('重命名知识库', collection.name)
  if (next === null) return
  const name = next.trim()
  if (!name || name === collection.name) return
  try {
    await apiSend('PATCH', `/api/console/kb/collections/${encodeURIComponent(collection.id)}`, { name })
    await loadKb()
  } catch (err) {
    alert(err.message || '重命名失败')
  }
}

async function removeKb(collection) {
  const extra = collection.sourceKind && collection.sourceKind !== 'local' ? `外部来源：${collection.sourceLabel || collection.sourceKind}` : ''
  const ok = await confirmCard({
    title: '删除知识库？',
    message: `「${collection.name}」及其文档、切片会一并从检索中移除。`,
    detail: extra,
    confirmText: '删除知识库',
  })
  if (!ok) return
  try {
    await apiSend('DELETE', `/api/console/kb/collections/${encodeURIComponent(collection.id)}`)
    if (state.selectedCollection === collection.id) state.selectedCollection = null
    await loadKb()
  } catch (err) {
    alert(err.message || '删除失败')
  }
}

function flattenDepartments(node, out = []) {
  if (!node) return out
  for (const child of node.children ?? []) {
    out.push({ path: child.path, name: child.name, depth: child.depth ?? 1 })
    flattenDepartments(child, out)
  }
  return out
}

function kbSourceConfig(collection) {
  const raw = collection?.sourceConfig
  return raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}
}

function kbSourceFieldsHtml(kind, config, secretConfigured) {
  if (kind === 'dify') {
    return `<label class="field"><span>Dify API 地址</span><input id="kb-src-base" value="${esc(config.baseUrl || 'https://api.dify.ai/v1')}" placeholder="https://api.dify.ai/v1" /></label>
      <label class="field"><span>datasetId</span><input id="kb-src-dataset" value="${esc(config.datasetId || '')}" placeholder="Dify 知识库 ID" /></label>
      <label class="field"><span>API Key</span><input id="kb-src-secret" type="password" placeholder="${secretConfigured ? '已保存，留空不修改' : 'dataset 检索权限的 API Key'}" autocomplete="new-password" /></label>
      ${hintNote('来源说明', 'Dify 走在线检索；文档由 Dify 管理，EAB 内只读展示。')}`
  }
  if (kind === 'obsidian') {
    return `<label class="field"><span>Vault 目录（服务器本地路径）</span><input id="kb-src-vault" value="${esc(config.vaultPath || '')}" placeholder="例如 D:\\Notes\\MyVault" /></label>
      <label class="field"><span>导入密级</span><select id="kb-src-cls">
        <option value="public"${config.classification === 'public' ? ' selected' : ''}>公开</option>
        <option value="internal"${config.classification !== 'public' && config.classification !== 'confidential' ? ' selected' : ''}>内部</option>
        <option value="confidential"${config.classification === 'confidential' ? ' selected' : ''}>机密</option>
      </select></label>
      ${hintNote('同步说明', '保存后点“同步 Vault”把 Markdown 导入 EAB；导入后的文档可以点击编辑、删除，检索走本地切片。')}`
  }
  if (kind === 'generic') {
    return `<label class="field"><span>检索接口地址</span><input id="kb-src-endpoint" value="${esc(config.endpoint || '')}" placeholder="https://example.com/api/search" /></label>
      <label class="field"><span>请求方法</span><select id="kb-src-method">
        <option value="POST"${config.method !== 'GET' ? ' selected' : ''}>POST</option>
        <option value="GET"${config.method === 'GET' ? ' selected' : ''}>GET</option>
      </select></label>
      <label class="field"><span>Token / API Key（可选）</span><input id="kb-src-secret" type="password" placeholder="${secretConfigured ? '已保存，留空不修改' : '会以 Bearer 方式发送'}" autocomplete="new-password" /></label>
      <div class="source-grid">
        <label class="field"><span>入参字段</span><input id="kb-src-query-field" value="${esc(config.queryField || 'query')}" /></label>
        <label class="field"><span>条数字段</span><input id="kb-src-topk-field" value="${esc(config.topKField || 'top_k')}" /></label>
        <label class="field"><span>结果路径</span><input id="kb-src-results-path" value="${esc(config.resultsPath || 'results')}" placeholder="results 或 data.items" /></label>
        <label class="field"><span>标题字段</span><input id="kb-src-title-field" value="${esc(config.titleField || 'title')}" /></label>
        <label class="field"><span>正文字段</span><input id="kb-src-text-field" value="${esc(config.textField || 'text')}" /></label>
      </div>
      ${hintNote('接口说明', '适配 Confluence / Notion 代理、RAGFlow、火山知识库等自定义 REST 接口；返回数组元素至少包含正文字段。')}`
  }
  return hintNote('本地知识库', '文档在 EAB 内新增、编辑、删除，走本地切片检索。')
}

function bindKbSourceFields(overlay, collection) {
  const select = overlay.querySelector('#kb-source-kind')
  const host = overlay.querySelector('#kb-source-fields')
  const config = kbSourceConfig(collection)
  const render = () => {
    host.innerHTML = kbSourceFieldsHtml(select.value, config, Boolean(collection?.sourceSecretConfigured))
  }
  select.addEventListener('change', render)
  render()
}

function readKbSource(overlay) {
  const kind = overlay.querySelector('#kb-source-kind').value
  const value = (id) => overlay.querySelector(`#${id}`)?.value.trim() || ''
  if (kind === 'dify') {
    return {
      sourceKind: kind,
      sourceConfig: { baseUrl: value('kb-src-base'), datasetId: value('kb-src-dataset') },
      sourceSecret: value('kb-src-secret'),
    }
  }
  if (kind === 'obsidian') {
    return {
      sourceKind: kind,
      sourceConfig: { vaultPath: value('kb-src-vault'), classification: overlay.querySelector('#kb-src-cls').value },
      sourceSecret: '',
    }
  }
  if (kind === 'generic') {
    return {
      sourceKind: kind,
      sourceConfig: {
        endpoint: value('kb-src-endpoint'),
        method: overlay.querySelector('#kb-src-method').value,
        queryField: value('kb-src-query-field') || 'query',
        topKField: value('kb-src-topk-field') || 'top_k',
        resultsPath: value('kb-src-results-path') || 'results',
        titleField: value('kb-src-title-field') || 'title',
        textField: value('kb-src-text-field') || 'text',
      },
      sourceSecret: value('kb-src-secret'),
    }
  }
  return { sourceKind: 'local', sourceConfig: {}, sourceSecret: '' }
}

async function openKbModal(collection) {
  const roleData = await api('/api/console/roles')
  let depts = []
  try {
    depts = flattenDepartments((await api('/api/org/tree')).root)
  } catch {
    depts = []
  }
  const aclMode = collection?.acl.mode ?? 'all'
  const selectedRoles = new Set(collection?.acl.roles ?? [])
  const selectedDepts = new Set(collection?.acl.deptPaths ?? [])
  const overlay = modelModal(`
    <div class="modal-head"><h3>${collection ? '编辑知识库' : '新建知识库'}</h3><button class="modal-x" type="button">×</button></div>
    <div class="field-stack">
      <label class="field"><span>名称</span><input id="kb-name" value="${esc(collection?.name ?? '')}" placeholder="例如 公司制度、产品资料" /></label>
      <label class="field"><span>说明</span><textarea id="kb-desc" rows="2" placeholder="这个库放什么内容">${esc(collection?.description ?? '')}</textarea></label>
      <label class="field"><span>数据来源</span>
        <select id="kb-source-kind">
          <option value="local"${(collection?.sourceKind ?? 'local') === 'local' ? ' selected' : ''}>本地知识库（EAB 内维护）</option>
          <option value="dify"${collection?.sourceKind === 'dify' ? ' selected' : ''}>Dify 知识库（在线检索）</option>
          <option value="obsidian"${collection?.sourceKind === 'obsidian' ? ' selected' : ''}>Obsidian Vault（导入 Markdown）</option>
          <option value="generic"${collection?.sourceKind === 'generic' ? ' selected' : ''}>通用 HTTP 知识库（自定义 REST）</option>
        </select>
      </label>
      <div class="source-fields" id="kb-source-fields"></div>
      <div class="field"><span>可见范围</span>
        <div class="segmented" id="kb-mode">
          <button type="button" data-mode="all" class="${aclMode === 'all' ? 'active' : ''}">全公司</button>
          <button type="button" data-mode="roles" class="${aclMode === 'roles' ? 'active' : ''}">指定角色</button>
          <button type="button" data-mode="depts" class="${aclMode === 'depts' ? 'active' : ''}">指定部门</button>
        </div>
      </div>
      <div class="acl-block" id="kb-role-block">
        <div class="acl-title">可选角色</div>
        <div class="check-grid">
          ${roleData.roles
            .map(
              (role) => `<label class="check"><input type="checkbox" data-kb-role="${esc(role.code)}"${
                selectedRoles.has(role.code) ? ' checked' : ''
              } /><span>${esc(ROLE_LABEL[role.code] || role.name)}</span></label>`,
            )
            .join('')}
        </div>
      </div>
      <div class="acl-block" id="kb-dept-block">
        <div class="acl-title">可选部门（含下级）</div>
        <div class="check-grid dept-check-grid">
          ${
            depts
              .map(
                (dept) => `<label class="check dept-check"><input type="checkbox" data-kb-dept="${esc(dept.path)}"${
                  selectedDepts.has(dept.path) ? ' checked' : ''
                } /><span>${esc(dept.name)}</span></label>`,
              )
              .join('') || '<span class="muted">还没有部门</span>'
          }
        </div>
      </div>
    </div>
    <div class="modal-state" id="kb-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="kb-save">保存</button>
      <button class="btn ghost" type="button" id="kb-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#kb-cancel').addEventListener('click', close)
  bindKbSourceFields(overlay, collection)

  let mode = aclMode
  const syncMode = () => {
    for (const button of overlay.querySelectorAll('#kb-mode button')) {
      button.classList.toggle('active', button.dataset.mode === mode)
    }
    overlay.querySelector('#kb-role-block').classList.toggle('is-hidden', mode !== 'roles')
    overlay.querySelector('#kb-dept-block').classList.toggle('is-hidden', mode !== 'depts')
  }
  overlay.querySelectorAll('#kb-mode button').forEach((button) => {
    button.addEventListener('click', () => {
      mode = button.dataset.mode
      syncMode()
    })
  })
  syncMode()

  overlay.querySelector('#kb-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#kb-state')
    stateEl.textContent = '保存中…'
    const body = {
      name: overlay.querySelector('#kb-name').value.trim(),
      description: overlay.querySelector('#kb-desc').value.trim(),
      aclMode: mode,
      roles: [...overlay.querySelectorAll('[data-kb-role]:checked')].map((el) => el.dataset.kbRole),
      deptPaths: [...overlay.querySelectorAll('[data-kb-dept]:checked')].map((el) => el.dataset.kbDept),
      ...readKbSource(overlay),
    }
    try {
      if (collection) await apiSend('PATCH', `/api/console/kb/collections/${encodeURIComponent(collection.id)}`, body)
      else {
        const created = await apiPost('/api/console/kb/collections', body)
        state.selectedCollection = created.collection.id
      }
      close()
      loadKb()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
}

const kbFormatSize = (bytes) => {
  if (bytes >= 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`
  return `${Math.max(1, Math.round(bytes / 1024))} KB`
}

function openKbDocModal(collectionId, mode) {
  void mode
  const accept =
    '.pdf,.docx,.xlsx,.pptx,.txt,.md,.markdown,.csv,.json,.html,.htm,.png,.jpg,.jpeg,.webp'
  const overlay = modelModal(`
    <div class="modal-head kb-upload-head">
      <div class="kb-upload-title">
        <span class="kb-upload-eyebrow">知识库 / 入库流水线</span>
        <h3>上传并自动入库</h3>
        <p>多个文件会组成一个批次，依次完成解析、清洗、切片与索引；入库后可逐篇查看和手动修正。</p>
      </div>
      <button class="modal-x" type="button" aria-label="关闭">×</button>
    </div>
    <div class="field-stack kb-upload-body">
      <div class="kb-upload-flow" aria-hidden="true">
        <span class="is-on"><b>01</b>解析</span>
        <i></i>
        <span class="is-on"><b>02</b>清洗</span>
        <i></i>
        <span class="is-on"><b>03</b>切片</span>
        <i></i>
        <span class="is-on"><b>04</b>索引</span>
      </div>
      <div class="kb-drop" id="kb-drop" tabindex="0" role="button" aria-label="选择或拖入文件">
        <input id="doc-file" type="file" multiple accept="${accept}" hidden />
        <div class="kb-drop-icon">＋</div>
        <strong>把文件拖到这里，或点击选择</strong>
        <span>PDF / Word / Excel / PPT / TXT / Markdown / CSV / JSON / HTML / 图片</span>
        <em>单文件 ≤ 50MB，单次 ≤ 20 个、合计 ≤ 200MB</em>
        <div class="kb-drop-summary" id="doc-select-summary">尚未选择文件</div>
      </div>
      <div class="kb-file-list" id="doc-file-list"></div>
      <div class="kb-form-row kb-upload-config">
        <label class="field"><span>清洗策略</span>
          <select id="doc-clean-mode">
            <option value="auto" selected>智能清洗（推荐）</option>
            <option value="model">模型清洗</option>
            <option value="rules">规则清洗</option>
          </select>
        </label>
        <label class="field"><span>密级</span>
          <select id="doc-cls">
            <option value="public">公开</option>
            <option value="internal" selected>内部</option>
            <option value="confidential">机密</option>
          </select>
        </label>
      </div>
      <div class="kb-upload-strategy">
        <span class="kb-upload-strategy-icon">⌁</span>
        <div>
          <strong>智能策略</strong>
          <p>配置了清洗模型时自动走模型清洗，未配置或模型超时时回退规则清洗；全程记录每一步结果，可随时人工修正。</p>
        </div>
      </div>
      ${hintNote(
        '批量自动流程',
        '点击「上传并开始入库」后会自动进入批次进度页：可以同时看到整批进度和每个文件的解析、清洗、切片、索引状态。',
      )}
    </div>
    <div class="modal-state" id="doc-state"></div>
    <div class="modal-actions kb-upload-actions">
      <span class="kb-upload-tip">入库后可逐篇查看流程，清洗与切片结果支持手动编辑</span>
      <div class="kb-upload-action-buttons">
        <button class="btn primary" type="button" id="doc-save" disabled>上传并开始入库</button>
        <button class="btn ghost" type="button" id="doc-cancel">取消</button>
      </div>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal').classList.add('kb-upload-modal')
  const input = overlay.querySelector('#doc-file')
  const drop = overlay.querySelector('#kb-drop')
  const list = overlay.querySelector('#doc-file-list')
  const stateEl = overlay.querySelector('#doc-state')
  const save = overlay.querySelector('#doc-save')
  const summaryEl = overlay.querySelector('#doc-select-summary')
  const selected = []

  const render = () => {
    list.innerHTML = selected.length
      ? selected
          .map(
            (file, index) =>
              `<div class="kb-file-row"><span class="kb-file-name">${esc(file.name)}</span><span class="kb-file-size">${kbFormatSize(
                file.size,
              )}</span><button class="kb-file-x" type="button" data-file-index="${index}" aria-label="移除">×</button></div>`,
          )
          .join('')
      : '<div class="kb-file-empty">还没有选择文件，可一次选择多个文件</div>'
    const total = selected.reduce((sum, file) => sum + file.size, 0)
    summaryEl.textContent = selected.length
      ? `已选 ${selected.length} 个文件 · 合计 ${kbFormatSize(total)}`
      : '尚未选择文件'
    summaryEl.classList.toggle('has-files', selected.length > 0)
    save.disabled = selected.length === 0
  }
  const addFiles = (files) => {
    stateEl.className = 'modal-state'
    stateEl.textContent = ''
    for (const file of files) {
      if (selected.length >= 20) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '单次最多上传 20 个文件'
        break
      }
      if (file.size > 50 * 1024 * 1024) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = `${file.name} 超过 50MB`
        continue
      }
      const duplicate = selected.some((item) => item.name === file.name && item.size === file.size)
      if (!duplicate) selected.push(file)
    }
    render()
  }

  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#doc-cancel').addEventListener('click', close)
  drop.addEventListener('click', () => input.click())
  drop.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      input.click()
    }
  })
  drop.addEventListener('dragover', (event) => {
    event.preventDefault()
    drop.classList.add('is-over')
  })
  drop.addEventListener('dragleave', () => drop.classList.remove('is-over'))
  drop.addEventListener('drop', (event) => {
    event.preventDefault()
    drop.classList.remove('is-over')
    addFiles(event.dataTransfer?.files ?? [])
  })
  input.addEventListener('change', () => {
    addFiles(input.files ?? [])
    input.value = ''
  })
  list.addEventListener('click', (event) => {
    const button = event.target.closest('[data-file-index]')
    if (!button) return
    selected.splice(Number(button.dataset.fileIndex), 1)
    render()
  })
  save.addEventListener('click', async () => {
    if (selected.length === 0) return
    const form = new FormData()
    for (const file of selected) form.append('files', file, file.name)
    form.append('cleanMode', overlay.querySelector('#doc-clean-mode').value)
    form.append('classification', overlay.querySelector('#doc-cls').value)
    save.disabled = true
    stateEl.className = 'modal-state'
    stateEl.textContent = `正在上传 ${selected.length} 个文件，准备进入流水线…`
    try {
      const result = await apiUpload(
        `/api/console/kb/collections/${encodeURIComponent(collectionId)}/docs/upload`,
        form,
      )
      const files = Array.isArray(result.files) ? result.files : []
      const accepted = files.filter((item) => item.ok && item.docId)
      const failed = files.filter((item) => !item.ok)
      if (accepted.length) {
        close()
        await loadDocs(collectionId)
        openKbBatchPipeline(accepted, collectionId, failed)
        return
      }
      stateEl.className = 'modal-state bad'
      stateEl.innerHTML = [
        '<div>没有文件进入流水线。</div>',
        ...failed.map((item) => `<div class="kb-upload-error">${esc(item.filename)}：${esc(item.error || '上传失败')}</div>`),
      ].join('')
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '上传失败'
    } finally {
      save.disabled = selected.length === 0
    }
  })
  render()
}

async function openKbRetrievalTest(collectionId) {
  const overlay = modelModal(`
    <div class="modal-head kb-test-head">
      <div class="kb-test-title">
        <span class="kb-test-eyebrow">知识库 / 召回质量</span>
        <h3>召回测试</h3>
        <p>输入真实问题，检查命中片段、分数和召回模型表现。</p>
      </div>
      <button class="modal-x" type="button" aria-label="关闭召回测试">×</button>
    </div>
    <div class="kb-test-body">
      <div class="kb-test-main">
        <section class="kb-test-card kb-test-query-card">
          <div class="kb-test-card-head">
            <div><span class="kb-test-kicker">QUERY</span><h4>测试问题</h4></div>
            <span class="kb-test-hint">Ctrl + Enter 运行</span>
          </div>
          <label class="field kb-test-query-field"><span>测试问题</span>
            <textarea id="kbt-query" rows="3" placeholder="输入一个真实用户会问的问题，例如：交换机管理地址是多少？"></textarea>
          </label>
          <div class="kb-test-query-foot"><span>尽量使用用户原话，避免只输入关键词</span><span id="kbt-query-count">0 字</span></div>
          <div class="kb-test-grid kb-test-controls">
            <label class="field"><span>检索模式</span>
              <select id="kbt-mode">
                <option value="hybrid">混合检索（关键词 + 向量）</option>
                <option value="vector">仅向量</option>
                <option value="keyword">仅关键词</option>
              </select>
            </label>
            <label class="field"><span>TopK</span><input id="kbt-topk" type="number" min="1" max="20" value="5" /></label>
            <label class="field"><span>向量阈值</span><input id="kbt-threshold" type="number" min="0" max="1" step="0.01" value="0" /></label>
            <label class="kb-test-check"><input id="kbt-rerank" type="checkbox" /> 启用重排序</label>
          </div>
          <div class="kb-test-actions">
            <span class="modal-state" id="kbt-state"></span>
            <div class="kb-test-action-group">
              <button class="btn ghost" type="button" id="kbt-save">保存为用例</button>
              <button class="btn ghost" type="button" id="kbt-compare">对比向量模型</button>
              <button class="btn primary" type="button" id="kbt-run">运行测试</button>
            </div>
          </div>
        </section>
        <section class="kb-test-result-card">
          <div class="kb-test-card-head">
            <div><span class="kb-test-kicker">RESULT</span><h4>召回结果</h4></div>
            <span class="kb-test-hint">按 RRF 融合分排序</span>
          </div>
          <div id="kbt-result" class="kb-test-result">
            <div class="kb-test-empty-state">
              <span class="kb-test-empty-glyph">⌕</span>
              <strong>还没有召回结果</strong>
              <p>输入问题并运行测试，这里会显示命中片段、TopK 和分数。</p>
            </div>
          </div>
        </section>
      </div>
      <aside class="kb-test-side">
        <div class="kb-test-side-head">
          <h3>测试资产</h3>
          <p>用固定用例做回归，保留最近运行结果。</p>
        </div>
        <section class="kb-test-side-card">
          <div class="kb-test-section-head"><h4>测试用例</h4><span class="muted" id="kbt-case-count"></span></div>
          <div id="kbt-cases"></div>
        </section>
        <section class="kb-test-side-card">
          <div class="kb-test-section-head"><h4>最近记录</h4><button class="btn sm ghost" type="button" id="kbt-clear-runs">清空记录</button></div>
          <div id="kbt-runs"></div>
        </section>
      </aside>
    </div>`)
  overlay.querySelector('.modal').classList.add('kb-test-modal')
  const controller = new AbortController()
  const close = () => {
    controller.abort()
    overlay.remove()
  }
  overlay.querySelector('.modal-x')?.addEventListener('click', close)
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) close()
  })
  document.addEventListener(
    'keydown',
    (event) => {
      if (event.key === 'Escape' && !document.querySelector('.confirm-overlay')) close()
    },
    { signal: controller.signal },
  )
  const q = overlay.querySelector('#kbt-query')
  const stateEl = overlay.querySelector('#kbt-state')
  const resultEl = overlay.querySelector('#kbt-result')
  const casesEl = overlay.querySelector('#kbt-cases')
  const runsEl = overlay.querySelector('#kbt-runs')
  const queryCountEl = overlay.querySelector('#kbt-query-count')
  let embeddingModels = []
  const syncQueryCount = () => {
    queryCountEl.textContent = `${q.value.length} 字`
  }
  q.addEventListener('input', syncQueryCount)
  syncQueryCount()

  const setState = (text, kind = '') => {
    stateEl.className = `modal-state ${kind}`
    stateEl.textContent = text
  }
  const config = () => ({
    query: q.value.trim(),
    mode: overlay.querySelector('#kbt-mode').value,
    topK: Number(overlay.querySelector('#kbt-topk').value) || 5,
    vectorThreshold: Number(overlay.querySelector('#kbt-threshold').value) || 0,
    rerank: overlay.querySelector('#kbt-rerank').checked,
  })
  const renderResult = (data) => {
    if (!data) return
    const metrics = data.metrics || {}
    const diagnostics = data.diagnostics || {}
    const hits = Array.isArray(data.hits) ? data.hits : []
    const warnings = Array.isArray(diagnostics.warnings) ? diagnostics.warnings : []
    const hitHtml = hits.length
      ? hits
          .map(
            (hit, index) => `<div class="kb-test-hit">
              <div class="kb-test-hit-head">
                <label class="kb-test-pick"><input type="checkbox" data-hit-chunk="${esc(hit.chunkId)}" /> 期望</label>
                <span class="kb-test-rank">#${index + 1}</span>
                <span class="pill">${esc(hit.source)}</span>
                <span class="kb-test-doc">${esc(hit.docTitle)}</span>
                <span class="kb-test-score">RRF ${hit.rrfScore}${
                  hit.vectorScore ? ` · 向量 ${hit.vectorScore}` : ''
                }${hit.rerankScore !== null ? ` · 重排 ${hit.rerankScore}` : ''}</span>
              </div>
              <div class="kb-test-text">${esc(hit.text)}</div>
            </div>`,
          )
          .join('')
      : '<div class="kb-test-empty">没有命中。可以降低阈值、换关键词，或先重建索引。</div>'
    resultEl.innerHTML = `
      <div class="kb-test-summary">
        <div class="kb-test-metric"><strong>${metrics.top1Hit ? '命中' : '未命中'}</strong><span>Top1</span></div>
        <div class="kb-test-metric"><strong>${Number(metrics.recallAtK || 0).toFixed(2)}</strong><span>Recall@K</span></div>
        <div class="kb-test-metric"><strong>${Number(metrics.mrr || 0).toFixed(2)}</strong><span>MRR</span></div>
        <div class="kb-test-metric"><strong>${data.hits.length}</strong><span>命中条数</span></div>
      </div>
      <div class="kb-test-diag">
        关键词候选 ${diagnostics.keywordCandidates || 0} · 向量候选 ${diagnostics.vectorCandidates || 0} ·
        合并 ${diagnostics.mergedCandidates || 0} · 耗时 ${diagnostics.elapsedMs || 0}ms · ${esc(data.modelLabel || '')}
      </div>
      ${warnings.length ? `<div class="kb-doc-warn">${warnings.map((item) => esc(item)).join('<br />')}</div>` : ''}
      <div class="kb-test-hit-list">${hitHtml}</div>`
  }
  const renderCompare = (data) => {
    const results = Array.isArray(data.results) ? data.results : []
    resultEl.innerHTML = `<div class="kb-test-compare-title">模型对比 · ${esc(data.query)}</div>
      <table class="data kb-test-compare-table">
        <thead><tr><th>向量模型</th><th>Top1</th><th>Recall@K</th><th>MRR</th><th>命中</th><th>耗时</th></tr></thead>
        <tbody>${results
          .map((item) => {
            const metrics = item.metrics || {}
            return `<tr>
              <td><strong>${esc(item.modelName)}</strong><div class="desc mono">${esc(item.modelId)}</div></td>
              <td><span class="pill ${metrics.top1Hit ? 'ok' : ''}">${metrics.top1Hit ? '命中' : '未命中'}</span></td>
              <td>${Number(metrics.recallAtK || 0).toFixed(2)}</td>
              <td>${Number(metrics.mrr || 0).toFixed(2)}</td>
              <td>${item.hitCount}</td>
              <td>${item.elapsedMs}ms</td>
            </tr>`
          })
          .join('')}</tbody>
      </table>`
  }

  const renderCases = (data) => {
    const cases = Array.isArray(data.cases) ? data.cases : []
    overlay.querySelector('#kbt-case-count').textContent = `${cases.length} 个`
    casesEl.innerHTML = cases.length
      ? cases
          .map(
            (item) => `<div class="kb-test-list-row">
              <div class="kb-test-list-main"><strong>${esc(item.name)}</strong><span>${esc(item.query)}</span></div>
              <div class="kb-test-list-actions">
                <button class="btn sm" type="button" data-case-run="${esc(item.id)}">运行</button>
                <button class="btn sm danger" type="button" data-case-del="${esc(item.id)}">删除</button>
              </div>
            </div>`,
          )
          .join('')
      : '<div class="kb-test-empty">还没有用例。运行测试后可以把当前问题和选中的命中保存为用例。</div>'
  }
  const renderRuns = (data) => {
    const runs = Array.isArray(data.runs) ? data.runs : []
    runsEl.innerHTML = runs.length
      ? runs
          .slice(0, 8)
          .map(
            (item) => `<div class="kb-test-list-row">
              <div class="kb-test-list-main"><strong>${esc(item.query)}</strong><span>${fmtTime(item.createdAt)} · ${esc(
                item.modelLabel || '',
              )}</span></div>
              <div class="kb-test-list-meta"><span class="pill ${item.top1Hit ? 'ok' : ''}">${
                item.top1Hit ? 'Top1 命中' : '未命中'
              }</span><span class="muted">R@K ${Number(item.recallAtK || 0).toFixed(2)} · MRR ${Number(
                item.mrr || 0,
              ).toFixed(2)}${item.hitCount === 0 ? ' · 0 命中' : ''}</span>
                <button class="btn sm" type="button" data-run-query="${esc(item.query)}">再跑一次</button>
              </div>
            </div>`,
          )
          .join('')
      : '<div class="kb-test-empty">还没有测试记录。每次运行都会落一条记录，过期后自动清理。</div>'
  }
  const loadCases = async () => {
    const data = await api(`/api/console/kb/collections/${encodeURIComponent(collectionId)}/test-cases`)
    renderCases(data)
  }
  const loadRuns = async () => {
    const data = await api(`/api/console/kb/collections/${encodeURIComponent(collectionId)}/test-runs?limit=20`)
    renderRuns(data)
  }
  const loadEmbeddingModels = async () => {
    const data = await api(`/api/console/kb/collections/${encodeURIComponent(collectionId)}/embedding-models`)
    embeddingModels = Array.isArray(data.models) ? data.models : []
  }
  const run = async () => {
    const body = config()
    if (!body.query) {
      setState('请输入测试问题', 'bad')
      q.focus()
      return
    }
    const button = overlay.querySelector('#kbt-run')
    button.disabled = true
    setState('检索中…')
    try {
      const data = await apiPost(
        `/api/console/kb/collections/${encodeURIComponent(collectionId)}/test-runs`,
        body,
      )
      renderResult(data)
      setState(`完成：${data.hits.length} 条命中，${data.diagnostics.elapsedMs}ms`, 'good')
      await loadRuns()
    } catch (err) {
      setState(err.message || '测试失败', 'bad')
    } finally {
      button.disabled = false
    }
  }
  const compare = async () => {
    const body = config()
    if (!body.query) {
      setState('请输入对比测试的问题', 'bad')
      q.focus()
      return
    }
    if (embeddingModels.length === 0) {
      setState('该知识库还没有可对比的向量模型索引', 'bad')
      return
    }
    const button = overlay.querySelector('#kbt-compare')
    button.disabled = true
    setState(`对比 ${embeddingModels.length} 个向量模型…`)
    try {
      const picked = [...overlay.querySelectorAll('[data-hit-chunk]:checked')].map((item) => item.dataset.hitChunk)
      const data = await apiPost(
        `/api/console/kb/collections/${encodeURIComponent(collectionId)}/test-compare`,
        {
          ...body,
          embeddingModelIds: embeddingModels.map((item) => item.id),
          expectChunkIds: picked,
        },
      )
      renderCompare(data)
      setState(`完成：已对比 ${data.results.length} 个向量模型`, 'good')
      await loadRuns()
    } catch (err) {
      setState(err.message || '模型对比失败', 'bad')
    } finally {
      button.disabled = false
    }
  }

  overlay.addEventListener('click', async (event) => {
    const target = event.target
    if (target.closest('#kbt-run')) return void run()
    if (target.closest('#kbt-compare')) return void compare()
    if (target.closest('#kbt-clear-runs')) {
      const confirmed = await confirmCard({
        title: '清空测试记录？',
        message: '该知识库的召回测试历史会被删除，测试用例保留。',
        confirmText: '清空记录',
      })
      if (!confirmed) return
      try {
        await apiSend('DELETE', `/api/console/kb/collections/${encodeURIComponent(collectionId)}/test-runs`)
        setState('测试记录已清空', 'good')
        await loadRuns()
      } catch (err) {
        setState(err.message || '清空失败', 'bad')
      }
      return
    }
    if (target.closest('#kbt-save')) {
      const body = config()
      if (!body.query) {
        setState('先输入测试问题', 'bad')
        q.focus()
        return
      }
      const picked = [...overlay.querySelectorAll('[data-hit-chunk]:checked')].map((item) => item.dataset.hitChunk)
      const name = prompt('用例名称', body.query.slice(0, 32))
      if (name === null) return
      try {
        await apiPost(`/api/console/kb/collections/${encodeURIComponent(collectionId)}/test-cases`, {
          name: name.trim() || body.query.slice(0, 32),
          query: body.query,
          expectChunkIds: picked,
        })
        setState('用例已保存', 'good')
        await loadCases()
      } catch (err) {
        setState(err.message || '保存失败', 'bad')
      }
      return
    }
    const caseRun = target.closest('[data-case-run]')
    if (caseRun) {
      const button = caseRun
      button.disabled = true
      setState('运行用例…')
      try {
        const data = await apiPost(
          `/api/console/kb/test-cases/${encodeURIComponent(caseRun.dataset.caseRun)}/run`,
          {
            mode: overlay.querySelector('#kbt-mode').value,
            topK: Number(overlay.querySelector('#kbt-topk').value) || 5,
            vectorThreshold: Number(overlay.querySelector('#kbt-threshold').value) || 0,
            rerank: overlay.querySelector('#kbt-rerank').checked,
          },
        )
        renderResult(data)
        setState(`用例完成：${data.hits.length} 条命中`, 'good')
        await loadRuns()
      } catch (err) {
        setState(err.message || '用例运行失败', 'bad')
      } finally {
        button.disabled = false
      }
      return
    }
    const caseDel = target.closest('[data-case-del]')
    if (caseDel) {
      const confirmed = await confirmCard({
        title: '删除测试用例？',
        message: '只删除用例，不会影响测试记录与知识库文档。',
        confirmText: '删除用例',
      })
      if (!confirmed) return
      try {
        await apiSend('DELETE', `/api/console/kb/test-cases/${encodeURIComponent(caseDel.dataset.caseDel)}`)
        setState('用例已删除', 'good')
        await loadCases()
      } catch (err) {
        setState(err.message || '删除失败', 'bad')
      }
      return
    }
    const runAgain = target.closest('[data-run-query]')
    if (runAgain) {
      q.value = runAgain.dataset.runQuery
      syncQueryCount()
      return void run()
    }
  })
  q.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
      event.preventDefault()
      void run()
    }
  })
  try {
    await Promise.all([loadCases(), loadRuns(), loadEmbeddingModels()])
  } catch (err) {
    setState(err.message || '测试数据加载失败', 'bad')
  }
}
async function openKbUploadDocModal(docId, collectionId) {
  let status
  try {
    status = await api(`/api/console/kb/docs/${encodeURIComponent(docId)}/pipeline`)
  } catch (err) {
    alert(err.message || '文档状态读取失败')
    return
  }

  const STEPS = [
    {
      key: 'parse',
      label: '解析',
      apiStage: 'parse',
      retry: '重跑解析',
      desc: '读取原文件，保留页码、段落和表格结构。',
    },
    {
      key: 'clean',
      label: '清洗',
      apiStage: 'clean',
      retry: '重跑清洗',
      desc: '规则去噪；配置清洗模型时再做保事实改写。',
    },
    {
      key: 'chunk',
      label: '切片',
      apiStage: 'chunk',
      retry: '重跑切片',
      desc: '按知识库切片参数生成可召回片段。',
    },
    {
      key: 'index',
      label: '索引',
      apiStage: 'index',
      retry: '重建索引',
      desc: '写入关键词索引，并生成可选的向量索引。',
    },
  ]
  const ACTIVE_STEP = { parsing: 0, cleaning: 1, chunking: 2, indexing: 3 }
  const DONE_THROUGH = { uploaded: -1, parsing: -1, parsed: 0, cleaning: 0, cleaned: 1, chunking: 1, chunked: 2, indexing: 2, indexed: 3 }
  const MODE_LABEL = {
    rules: '规则清洗',
    model: '模型清洗',
    auto: '自动清洗',
    manual: '人工修正',
    null: '未清洗',
  }
  const formatDuration = (seconds) => {
    const raw = Math.max(0, Number(seconds) || 0)
    if (raw > 0 && raw < 1) return '不到 1 秒'
    const total = Math.round(raw)
    if (total > 0 && total < 60) return `${Math.max(1, total)} 秒`
    if (total === 0) return '0 秒'
    const minutes = Math.floor(total / 60)
    const rest = total % 60
    return rest ? `${minutes} 分 ${rest} 秒` : `${minutes} 分钟`
  }
  const stepKey = (index) => STEPS[index]?.key || 'parse'
  const stepEstimate = (index) => Number(status.estimates?.[stepKey(index)] ?? 0)
  const stepTiming = (index) => Number(status.timings?.[stepKey(index)] ?? 0)
  const stageElapsed = (index) => {
    if (status.activeStage !== stepKey(index) || !status.stageStartedAt) return 0
    return Math.max(0, (Date.now() - Number(status.stageStartedAt)) / 1000)
  }
  const stepEtaText = (index, state) => {
    const estimate = stepEstimate(index)
    const timing = stepTiming(index)
    if (state === 'done' || state === 'warn') {
      if (timing) return `实际 ${formatDuration(timing)}`
      return estimate ? `预计 ${formatDuration(estimate)}` : ''
    }
    if (state === 'error') return timing ? `已用 ${formatDuration(timing)}` : ''
    if (state === 'active') {
      const elapsed = stageElapsed(index)
      const progress = stepKey(index) === 'clean' ? Number(status.progress || 0) : 0
      const suffix = progress > 0.02 ? ` · 已清洗 ${Math.round(progress * 100)}%` : elapsed ? ` · 已用 ${formatDuration(elapsed)}` : ''
      return estimate ? `预计 ${formatDuration(estimate)}${suffix}` : suffix.replace(' · ', '')
    }
    return estimate ? `预计 ${formatDuration(estimate)}` : ''
  }
  const actualTotalSeconds = () =>
    ['parse', 'clean', 'chunk', 'index'].reduce((sum, key) => sum + Number(status.timings?.[key] ?? 0), 0)
  const isRunning = (value) =>
    ['parsing', 'cleaning', 'chunking', 'indexing'].includes(value.pipelineStage) ||
    ['pending', 'running'].includes(value.lastJob?.status)
  const initialStep = () => {
    if (status.pipelineWarning) return 1
    if (status.pipelineStage === 'failed') {
      const failed = STEPS.findIndex((item) => item.apiStage === status.lastJob?.stage)
      return failed >= 0 ? failed : 0
    }
    if (status.pipelineStage === 'needs_config') return 0
    if (status.pipelineStage === 'indexed') return 3
    const active = ACTIVE_STEP[status.pipelineStage]
    if (active !== undefined) return active
    const done = DONE_THROUGH[status.pipelineStage]
    if (done !== undefined) return Math.min(3, done + 1)
    return 0
  }
  const stageState = (index) => {
    if (status.pipelineStage === 'failed') {
      const failed = STEPS.findIndex((item) => item.apiStage === status.lastJob?.stage)
      if (failed >= 0) return index === failed ? 'error' : index < failed ? 'done' : 'pending'
      return index === 0 ? 'error' : 'pending'
    }
    if (status.pipelineStage === 'needs_config') return index === 0 ? 'error' : 'pending'
    const active = ACTIVE_STEP[status.pipelineStage]
    if (active === index) return 'active'
    if (status.pipelineStage === 'uploaded' && ['pending', 'running'].includes(status.lastJob?.status) && index === 0) {
      return 'active'
    }
    const done = DONE_THROUGH[status.pipelineStage] ?? -1
    if (index <= done) {
      if (index === 1 && status.pipelineWarning) return 'warn'
      if (index === 3 && status.indexError) return 'warn'
      return 'done'
    }
    return 'pending'
  }
  const stateLabel = (state) =>
    ({ done: '已完成', active: isRunning(status) ? '处理中' : '待处理', warn: '已完成 · 有降级', error: '失败', pending: '待处理' })[state] || '待处理'

  const overlay = modelModal(`
    <div class="kb-flow-head">
      <div class="kb-flow-title-wrap">
        <span class="kb-flow-kicker">知识库 · 文档处理流水线</span>
        <div class="kb-flow-titleline">
          <h3>${esc(status.title)}</h3>
          <span class="pill ${KB_STAGE_CLASS[status.pipelineStage] || ''}" id="kb-flow-status-pill">${esc(
            KB_STAGE_LABEL[status.pipelineStage] || status.pipelineStage || '未知',
          )}</span>
        </div>
        <div class="kb-flow-meta" id="kb-flow-meta"></div>
      </div>
      <button class="modal-x" type="button" id="kb-flow-x">×</button>
    </div>
    <div class="kb-flow-live" id="kb-flow-live" hidden>
      <span class="kb-flow-live-dot"></span>
      <span id="kb-flow-live-text"></span>
      <span class="kb-flow-live-eta" id="kb-flow-live-eta"></span>
      <span class="kb-flow-live-bar" id="kb-flow-live-bar" hidden><i></i></span>
      <button class="kb-flow-follow" type="button" id="kb-flow-follow" hidden>回到当前步骤</button>
    </div>
    <div class="kb-flow-rail" id="kb-flow-rail"></div>
    <div class="kb-flow-content" id="kb-flow-content"></div>
    <div class="kb-flow-footer">
      <div class="kb-flow-footer-left">
        <button class="btn" type="button" id="kb-flow-retry"></button>
        <span class="modal-state" id="kb-flow-msg"></span>
      </div>
      <div class="kb-flow-footer-right">
        <span class="kb-flow-counter" id="kb-flow-counter"></span>
        <button class="btn" type="button" id="kb-flow-prev">上一步</button>
        <button class="btn primary" type="button" id="kb-flow-next">下一步</button>
        <button class="btn ghost" type="button" id="kb-flow-close">关闭</button>
      </div>
    </div>`)
  overlay.querySelector('.modal').classList.add('kb-flow-modal')

  const railEl = overlay.querySelector('#kb-flow-rail')
  const contentEl = overlay.querySelector('#kb-flow-content')
  const metaEl = overlay.querySelector('#kb-flow-meta')
  const pillEl = overlay.querySelector('#kb-flow-status-pill')
  const liveEl = overlay.querySelector('#kb-flow-live')
  const liveTextEl = overlay.querySelector('#kb-flow-live-text')
  const liveEtaEl = overlay.querySelector('#kb-flow-live-eta')
  const liveBarEl = overlay.querySelector('#kb-flow-live-bar')
  const followBtn = overlay.querySelector('#kb-flow-follow')
  const retryBtn = overlay.querySelector('#kb-flow-retry')
  const msgEl = overlay.querySelector('#kb-flow-msg')
  const counterEl = overlay.querySelector('#kb-flow-counter')
  const prevBtn = overlay.querySelector('#kb-flow-prev')
  const nextBtn = overlay.querySelector('#kb-flow-next')
  const caches = { raw: null, clean: null, chunks: null }
  const loading = { raw: false, clean: false, chunks: false }
  const previewErrors = { raw: '', clean: '', chunks: '' }
  let assetsCache = null
  let assetsLoading = false
  let assetsError = ''
  let stepIndex = initialStep()
  let followProgress = isRunning(status)
  let closed = false
  let pollTimer = null
  let refreshBusy = false
  let editing = null

  const stopPolling = () => {
    if (pollTimer) clearInterval(pollTimer)
    pollTimer = null
  }
  const close = () => {
    closed = true
    stopPolling()
    overlay.remove()
  }
  const setMsg = (text, kind = '') => {
    msgEl.className = `modal-state ${kind}`
    msgEl.textContent = text || ''
  }
  const modeText = () => MODE_LABEL[status.cleanMode ?? 'null'] || status.cleanMode || '未清洗'
  const reduction = () => {
    if (!status.rawChars || !status.cleanChars) return '—'
    const value = (1 - status.cleanChars / status.rawChars) * 100
    return `${Math.max(0, value).toFixed(1)}%`
  }
  const previewStats = (kind) => {
    const data = caches[kind]
    if (!data) return ''
    return `${Number(data.totalLength ?? data.text?.length ?? 0).toLocaleString()} 字符`
  }

  const renderHeader = () => {
    pillEl.className = `pill ${KB_STAGE_CLASS[status.pipelineStage] || ''}`
    pillEl.textContent = KB_STAGE_LABEL[status.pipelineStage] || status.pipelineStage || '未知'
    const actualTotal = actualTotalSeconds()
    metaEl.innerHTML = [
      `<span>版本 v${status.version}</span>`,
      status.pageCount ? `<span>${status.pageCount} 页</span>` : '',
      `<span>${status.chunkCount} 个切片</span>`,
      status.imageCount ? `<span>${status.imageCount} 张图片</span>` : '',
      isRunning(status) && status.remainingSeconds != null
        ? `<span class="kb-flow-meta-eta">预计还需 ${formatDuration(status.remainingSeconds)}</span>`
        : status.pipelineStage === 'indexed' && actualTotal
          ? `<span class="kb-flow-meta-eta">全程耗时 ${formatDuration(actualTotal)}</span>`
          : status.estimates?.total
            ? `<span class="kb-flow-meta-eta">预计全程 ${formatDuration(status.estimates.total)}</span>`
            : '',
      `<span>最近更新 ${fmtTime(status.updatedAt)}</span>`,
      status.pipelineWarning ? '<span class="kb-flow-meta-warn">有降级项</span>' : '',
    ]
      .filter(Boolean)
      .join('<i></i>')
  }
  const renderLive = () => {
    if (!isRunning(status)) {
      liveEl.hidden = true
      return
    }
    liveEl.hidden = false
    const active = ACTIVE_STEP[status.pipelineStage]
    const progress = Math.max(0, Math.min(1, Number(status.progress || 0)))
    const progressCopy =
      active === 1 && progress > 0.02 ? ` · 已清洗 ${Math.round(progress * 100)}%` : ''
    liveTextEl.textContent =
      active === undefined
        ? '任务已排队，等待 worker 开始处理'
        : `正在${STEPS[active].label} · 第 ${active + 1} / 4 步${progressCopy}`
    liveEtaEl.textContent =
      status.remainingSeconds != null ? `预计还需 ${formatDuration(status.remainingSeconds)}` : ''
    const showBar = active === 1 && progress > 0.02
    liveBarEl.hidden = !showBar
    if (showBar) liveBarEl.querySelector('i').style.width = `${Math.max(2, Math.round(progress * 100))}%`
    followBtn.hidden = followProgress || active === undefined
  }
  const renderRail = () => {
    railEl.innerHTML = STEPS.map((item, index) => {
      const state = stageState(index)
      const active = index === stepIndex ? ' is-current' : ''
      const icon =
        state === 'done' ? '✓' : state === 'warn' ? '!' : state === 'error' ? '×' : state === 'active' ? '' : index + 1
      const eta = stepEtaText(index, state)
      return `<button class="kb-flow-step is-${state}${active}" type="button" data-flow-step="${index}" ${
        index === stepIndex ? 'aria-current="step"' : ''
      }>
        <span class="kb-flow-step-no">${state === 'active' ? '<i class="kb-flow-spinner"></i>' : icon}</span>
        <span class="kb-flow-step-copy"><strong>${item.label}</strong><small>${stateLabel(state)}${
          eta ? `<span class="kb-flow-step-eta is-${state}">${eta}</span>` : ''
        }</small></span>
      </button>${index < STEPS.length - 1 ? '<span class="kb-flow-connector"></span>' : ''}`
    }).join('')
    for (const button of railEl.querySelectorAll('[data-flow-step]')) {
      button.addEventListener('click', () => {
        stepIndex = Number(button.dataset.flowStep)
        followProgress = false
        setMsg('')
        renderAll()
      })
    }
  }
  const previewPane = (title, text, kind, options = {}) => {
    if (loading[kind]) {
      return `<section class="kb-flow-pane"><header><strong>${title}</strong></header><div class="kb-flow-pane-loading">加载中…</div></section>`
    }
    if (previewErrors[kind]) {
      return `<section class="kb-flow-pane"><header><strong>${title}</strong></header><div class="kb-flow-pane-loading is-bad">${esc(
        previewErrors[kind],
      )}</div></section>`
    }
    const body = text || '（暂无内容）'
    return `<section class="kb-flow-pane">
      <header><strong>${title}</strong><span>${previewStats(kind)}</span></header>
      ${options.plain ? `<pre>${esc(body)}</pre>` : `<div class="kb-flow-rich">${renderFlowRich(body)}</div>`}
    </section>`
  }
  const statCard = (label, value, hint = '') =>
    `<div class="kb-flow-stat"><span>${label}</span><strong>${value}</strong>${hint ? `<small>${hint}</small>` : ''}</div>`
  const alertCard = (kind, title, body) =>
    `<div class="kb-flow-alert is-${kind}"><strong>${esc(title)}</strong>${body ? `<p>${esc(body)}</p>` : ''}</div>`
  const imageKindLabel = (kind) =>
    ({ page_render: '扫描页', standalone: '独立图片', document_image: '文档内嵌图' })[kind] || '图片'
  const fmtAssetSize = (bytes) => {
    const value = Number(bytes || 0)
    if (!Number.isFinite(value) || value <= 0) return '0 B'
    if (value < 1024) return `${value} B`
    if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`
    return `${(value / 1024 / 1024).toFixed(1)} MB`
  }
  const assetGallery = () => {
    if (assetsLoading) {
      return `<section class="kb-flow-assets"><header><strong>文档图片</strong><span>读取中…</span></header><div class="kb-flow-pane-loading">加载图片资产…</div></section>`
    }
    if (assetsError) {
      return `<section class="kb-flow-assets"><header><strong>文档图片</strong><span>读取失败</span></header><div class="kb-flow-pane-loading is-bad">${esc(
        assetsError,
      )}</div></section>`
    }
    const assets = assetsCache || []
    if (!assets.length) return ''
    const withText = assets.filter((asset) => (asset.caption || asset.ocrText || '').trim()).length
    return `<section class="kb-flow-assets">
      <header><strong>文档图片</strong><span>${assets.length} 张${withText ? ` · ${withText} 张有说明/OCR` : ''}</span></header>
      <div class="kb-flow-asset-grid">${assets
        .map(
          (asset) => `<figure class="kb-flow-asset">
            <a href="${esc(asset.url)}" target="_blank" rel="noreferrer noopener"><img src="${esc(asset.url)}" alt="${esc(
              asset.caption || asset.sourceName || '文档图片',
            )}" loading="lazy"></a>
            <figcaption>
              <div class="kb-flow-asset-badges"><span>${imageKindLabel(asset.kind)}</span>${
                asset.pageNo ? `<span>第 ${Number(asset.pageNo)} 页</span>` : ''
              }<span>${fmtAssetSize(Number(asset.sizeBytes || 0))}</span></div>
              <strong>${esc(asset.caption || asset.sourceName || '未命名图片')}</strong>
              ${asset.ocrText ? `<p>${esc(asset.ocrText.slice(0, 150))}${asset.ocrText.length > 150 ? '…' : ''}</p>` : '<p class="is-empty">暂无 OCR 文本</p>'}
            </figcaption>
          </figure>`,
        )
        .join('')}</div>
    </section>`
  }
  const editorPane = (kind, title, note, value, ordinal = null) => {
    const action =
      kind === 'raw' ? '保存并重新清洗' : kind === 'clean' ? '保存并重新切片' : '保存并重建索引'
    const label = kind === 'raw' ? '解析文本' : kind === 'clean' ? '清洗文本' : `切片 #${ordinal + 1}`
    return `<section class="kb-flow-editor">
      <header>
        <div><strong>手动修正${label}</strong><span>${esc(note)}</span></div>
        <span class="kb-flow-editor-badge">人工编辑</span>
      </header>
      <textarea data-kb-editor rows="14" spellcheck="false">${esc(value || '')}</textarea>
      <footer>
        <span class="kb-flow-editor-count" data-kb-editor-count>${String(value || '').length.toLocaleString()} 字符</span>
        <div>
          <button class="btn" type="button" data-kb-cancel-edit>取消</button>
          <button class="btn primary" type="button" data-kb-save-edit="${kind}"${
            ordinal === null ? '' : ` data-kb-chunk-ordinal="${ordinal}"`
          }>${action}</button>
        </div>
      </footer>
    </section>`
  }
  const canManualEdit = (step) =>
    !isRunning(status) &&
    ['raw', 'clean', 'chunk'].includes(step.key) &&
    stageState(stepIndex) !== 'active' &&
    (step.key === 'chunk' ? Boolean(caches.chunks?.chunks?.length) : Boolean(caches[step.key]))

  const warningCopy = () => {
    const warning = status.pipelineWarning || ''
    if (!warning) return null
    if (/timeout|超时|aborted/i.test(warning)) {
      return {
        title: '模型清洗超时，已使用规则清洗结果',
        body: '模型在超时时间内没有返回。系统没有丢弃文档，已保留规则清洗结果并继续切片；可以只重跑「清洗」步骤。',
      }
    }
    if (/没有配置 kb\.clean/.test(warning)) {
      return {
        title: '未配置清洗模型，已使用规则清洗',
        body: '当前清洗方式要求模型，但知识库与文档都没有绑定 kb.clean 模型。绑定后可从清洗步骤重跑。',
      }
    }
    if (/缺少块标记/.test(warning)) {
      return {
        title: '模型输出缺少块标记，已使用规则结果',
        body: '模型没有按【块n】格式返回，系统保留了规则清洗结果。可重跑清洗，或换一个更稳定的清洗模型。',
      }
    }
    if (/未返回|保留规则/.test(warning)) {
      return {
        title: '部分块未返回，已保留规则结果',
        body: '模型只清洗了部分块，缺失部分已回退规则清洗。文档已经继续入库，不影响检索。',
      }
    }
    return { title: '流水线有降级项', body: warning }
  }

  const renderContent = () => {
    const step = STEPS[stepIndex]
    const state = stageState(stepIndex)
    const stepError =
      state === 'error'
        ? status.pipelineError || status.lastJob?.error || `${step.label}步骤失败`
        : ''
    const head = `<div class="kb-flow-step-head">
      <div><span class="kb-flow-step-eyebrow">STEP ${stepIndex + 1} / 4</span><h4>${step.label}</h4><p>${step.desc}</p></div>
      <div class="kb-flow-step-head-actions">
        ${
          stepEtaText(stepIndex, state)
            ? `<span class="kb-flow-step-time is-${state}">${stepEtaText(stepIndex, state)}</span>`
            : ''
        }
        <span class="kb-flow-state is-${state}">${stateLabel(state)}</span>
        ${
          !editing && canManualEdit(step) && step.key !== 'chunk'
            ? `<button class="btn kb-flow-edit-btn" type="button" data-kb-edit="${step.key}">✎ 手动修正</button>`
            : editing
              ? '<span class="kb-flow-editing-tag">手动修正中</span>'
              : ''
        }
      </div>
    </div>`
    let body = ''
    if (step.key === 'parse') {
      body = `<div class="kb-flow-stats">
          ${statCard('页数', status.pageCount || '—', status.pageCount ? '含扫描页' : '文本文件')}
          ${statCard('原始字符', status.rawChars ? status.rawChars.toLocaleString() : '—')}
          ${statCard('文档图片', status.imageCount || '—', status.imageTextCount ? `${status.imageTextCount} 张有 OCR/说明` : '未抽取到图片')}
          ${statCard(
            stepTiming(0) && ['done', 'warn'].includes(state) ? '本步耗时' : '预计耗时',
            stepTiming(0) && ['done', 'warn'].includes(state) ? formatDuration(stepTiming(0)) : formatDuration(stepEstimate(0)),
            ['done', 'warn'].includes(state) && stepEstimate(0) ? `预计 ${formatDuration(stepEstimate(0))}` : '实际计时',
          )}
        </div>
        ${stepError ? alertCard('bad', '解析失败', stepError) : ''}
        ${
          editing?.kind === 'raw'
            ? editorPane('raw', '解析文本', '修正 OCR 或版式解析误差；保存后从清洗步骤重新执行。', editing.text)
            : `${assetGallery()}${previewPane('解析后的原始文本', caches.raw?.text, 'raw')}`
        }`
    } else if (step.key === 'clean') {
      const copy = warningCopy()
      const modeHint =
        status.cleanModelName ||
        (status.cleanMode === 'manual'
          ? '人工修正结果'
          : status.pipelineWarning && /清洗/.test(status.pipelineWarning)
            ? '模型清洗已降级'
            : '')
      body = `<div class="kb-flow-stats">
          ${statCard('清洗方式', modeText(), modeHint)}
          ${statCard('原始字符', status.rawChars ? status.rawChars.toLocaleString() : '—')}
          ${statCard('清洗后字符', status.cleanChars ? status.cleanChars.toLocaleString() : '—', reduction())}
          ${statCard(
            stepTiming(1) && ['done', 'warn'].includes(state) ? '本步耗时' : '预计耗时',
            stepTiming(1) && ['done', 'warn'].includes(state) ? formatDuration(stepTiming(1)) : formatDuration(stepEstimate(1)),
            state === 'active' && Number(status.progress || 0) > 0.02
              ? `已清洗 ${Math.round(Number(status.progress) * 100)}%`
              : ['done', 'warn'].includes(state) && stepEstimate(1)
                ? `预计 ${formatDuration(stepEstimate(1))}`
                : '按块数与批次估算',
          )}
        </div>
        ${stepError ? alertCard('bad', '清洗失败', stepError) : ''}
        ${copy && !stepError ? alertCard('warn', copy.title, copy.body) : ''}
        ${
          editing?.kind === 'clean'
            ? editorPane('clean', '清洗文本', '人工修正清洗结果；保存后重新切片并重建索引。', editing.text)
            : `<div class="kb-flow-compare">
          ${previewPane('清洗前', caches.raw?.text, 'raw')}
          <span class="kb-flow-arrow">→</span>
          ${previewPane('清洗后', caches.clean?.text, 'clean')}
        </div>`
        }`
    } else if (step.key === 'chunk') {
      const chunks = caches.chunks?.chunks || []
      const average = chunks.length
        ? Math.round(chunks.reduce((sum, item) => sum + Number(item.tokenCount || 0), 0) / chunks.length)
        : 0
      body = `<div class="kb-flow-stats">
          ${statCard('切片数量', status.chunkCount || 0)}
          ${statCard('平均 tokens', average || '—', chunks.length ? `按前 ${chunks.length} 片计算` : '')}
          ${statCard('图片切片', chunks.filter((item) => item.imageUrl).length || '—', status.imageCount ? `文档共 ${status.imageCount} 张图片` : '无图片')}
          ${statCard(
            stepTiming(2) && ['done', 'warn'].includes(state) ? '本步耗时' : '预计耗时',
            stepTiming(2) && ['done', 'warn'].includes(state) ? formatDuration(stepTiming(2)) : formatDuration(stepEstimate(2)),
            ['done', 'warn'].includes(state) && stepEstimate(2) ? `预计 ${formatDuration(stepEstimate(2))}` : '按切片数估算',
          )}
        </div>
        ${stepError ? alertCard('bad', '切片失败', stepError) : ''}
        ${assetGallery()}
        ${
          chunks.length
            ? `<div class="kb-flow-chunk-list">${chunks
                .map((chunk) =>
                  editing?.kind === 'chunk' && editing.ordinal === chunk.ordinal
                    ? editorPane(
                        'chunk',
                        `切片 #${chunk.ordinal + 1}`,
                        '修正单个切片内容；保存后只重建索引，不重新切片。',
                        editing.text,
                        chunk.ordinal,
                      )
                    : `<div class="kb-chunk"><div class="kb-chunk-head"><span>#${chunk.ordinal + 1} · ${
                        chunk.tokenCount
                      } tokens${chunk.heading ? ` · ${esc(chunk.heading)}` : ''}${
                        chunk.pageNo ? ` · 第 ${chunk.pageNo} 页` : ''
                      }</span>${chunk.imageUrl ? '<span class="kb-chunk-image-badge">含图片</span>' : ''}${
                        !editing && !isRunning(status)
                          ? `<button class="kb-chunk-edit" type="button" data-kb-edit="chunk" data-kb-edit-ordinal="${chunk.ordinal}">编辑</button>`
                          : ''
                      }</div><div class="kb-chunk-body${chunk.imageUrl ? ' has-image' : ''}">${
                        chunk.imageUrl
                          ? `<a class="kb-chunk-image" href="${esc(chunk.imageUrl)}" target="_blank" rel="noreferrer noopener"><img src="${esc(
                              chunk.imageUrl,
                            )}" alt="${esc(chunk.meta?.imageCaption || '切片关联图片')}" loading="lazy"><span>${esc(
                              chunk.meta?.imageCaption || '查看原图',
                            )}</span></a>`
                          : ''
                      }<div class="kb-chunk-rich">${renderFlowRich(chunk.text)}</div></div></div>`,
                )
                .join('')}</div>`
            : loading.chunks
              ? '<div class="kb-flow-empty">加载切片…</div>'
              : `<div class="kb-flow-empty">${
                  previewErrors.chunks ? esc(previewErrors.chunks) : '还没有生成切片'
                }</div>`
        }`
    } else {
      body = `<div class="kb-flow-stats">
          ${statCard('关键词索引', status.chunkCount ? `${status.chunkCount} 个切片` : '未写入')}
          ${statCard('向量条数', status.embeddingCount || 0, status.embeddingModels ? `${status.embeddingModels} 个模型` : '')}
          ${statCard('文档版本', `v${status.version}`)}
          ${statCard(
            stepTiming(3) && ['done', 'warn'].includes(state) ? '本步耗时' : '预计耗时',
            stepTiming(3) && ['done', 'warn'].includes(state) ? formatDuration(stepTiming(3)) : formatDuration(stepEstimate(3)),
            ['done', 'warn'].includes(state) && stepEstimate(3) ? `预计 ${formatDuration(stepEstimate(3))}` : '含向量索引',
          )}
        </div>
        <div class="kb-flow-index-flow">
          <div><span>文本切片</span><strong>${status.chunkCount}</strong></div>
          <i>→</i>
          <div><span>关键词索引</span><strong>${status.chunkCount ? '已写入' : '未写入'}</strong></div>
          <i>→</i>
          <div><span>向量索引</span><strong>${status.embeddingCount ? '已生成' : '未生成'}</strong></div>
        </div>
        ${stepError ? alertCard('bad', '索引失败', stepError) : ''}
        ${
          status.indexError
            ? alertCard('warn', '向量索引未完成，当前仍可关键词检索', status.indexError)
            : status.embeddingCount === 0 && status.pipelineStage === 'indexed'
              ? alertCard('warn', '尚未生成向量索引', '文档已完成关键词切片的入库；绑定向量模型并重建索引后，才能使用混合检索。')
              : alertCard('ok', '索引结果', `关键词索引 ${status.chunkCount} 个切片，向量索引 ${status.embeddingCount} 条。`)
        }`
    }
    contentEl.innerHTML = head + body
  }
  const renderFooter = () => {
    const step = STEPS[stepIndex]
    retryBtn.textContent = step.retry
    retryBtn.disabled = Boolean(editing) || stageState(stepIndex) === 'active'
    prevBtn.disabled = stepIndex === 0
    nextBtn.textContent = stepIndex === STEPS.length - 1 ? '完成' : '下一步'
    counterEl.textContent = `${stepIndex + 1} / ${STEPS.length}`
  }
  const renderAll = () => {
    renderHeader()
    renderLive()
    renderRail()
    renderContent()
    renderFooter()
    void ensureStep(stepIndex)
  }

  const loadPreview = async (kind) => {
    if (caches[kind] || loading[kind]) return
    loading[kind] = true
    try {
      const limit = kind === 'chunks' ? 50 : 20000
      caches[kind] = await api(
        `/api/console/kb/docs/${encodeURIComponent(docId)}/preview?kind=${kind}&limit=${limit}`,
      )
      previewErrors[kind] = ''
    } catch (err) {
      previewErrors[kind] = err.message || '预览读取失败'
    } finally {
      loading[kind] = false
      if (!closed) renderContent()
    }
  }
  const loadAssets = async () => {
    if (assetsCache !== null || assetsLoading) return
    assetsLoading = true
    renderContent()
    try {
      const data = await api(`/api/console/kb/docs/${encodeURIComponent(docId)}/assets`)
      assetsCache = Array.isArray(data?.assets) ? data.assets : []
      assetsError = ''
    } catch (err) {
      assetsError = err.message || '图片资产读取失败'
    } finally {
      assetsLoading = false
      if (!closed) renderContent()
    }
  }
  const ensureStep = async (index) => {
    const key = STEPS[index]?.key
    if (key === 'parse') return Promise.all([loadPreview('raw'), loadAssets()])
    if (key === 'clean') return Promise.all([loadPreview('raw'), loadPreview('clean')])
    if (key === 'chunk') return Promise.all([loadPreview('chunks'), loadAssets()])
  }

  const refreshStatus = async (options = {}) => {
    if (closed || refreshBusy) return
    refreshBusy = true
    try {
      const next = await api(`/api/console/kb/docs/${encodeURIComponent(docId)}/pipeline`)
      const previousStage = status.pipelineStage
      const previousWarning = status.pipelineWarning
      status = next
      if (previousStage !== status.pipelineStage) {
        caches.raw = null
        caches.clean = null
        caches.chunks = null
        assetsCache = null
        assetsError = ''
        previewErrors.raw = ''
        previewErrors.clean = ''
        previewErrors.chunks = ''
      }
      if (options.follow !== false && followProgress && isRunning(status)) {
        const active = ACTIVE_STEP[status.pipelineStage]
        if (active !== undefined) stepIndex = active
      }
      if (followProgress && !previousWarning && status.pipelineWarning) {
        stepIndex = 1
        followProgress = false
      }
      if (status.pipelineStage === 'indexed' && followProgress) {
        // 用户是从某一步重跑时，完成后停在该步展示结果，不强行跳到索引。
        followProgress = false
      }
      if (!isRunning(status) && !status.pipelineWarning && status.status === 'ready') setMsg('')
      renderAll()
      if (isRunning(status)) {
        if (!pollTimer) pollTimer = setInterval(() => void refreshStatus(), 1800)
      } else {
        stopPolling()
        followBtn.hidden = true
      }
    } catch (err) {
      setMsg(err.message || '状态刷新失败', 'bad')
    } finally {
      refreshBusy = false
    }
  }

  overlay.querySelector('#kb-flow-x').addEventListener('click', close)
  overlay.querySelector('#kb-flow-close').addEventListener('click', close)
  prevBtn.addEventListener('click', () => {
    if (stepIndex === 0) return
    stepIndex -= 1
    followProgress = false
    setMsg('')
    renderAll()
  })
  nextBtn.addEventListener('click', () => {
    if (stepIndex === STEPS.length - 1) return close()
    stepIndex += 1
    followProgress = false
    setMsg('')
    renderAll()
  })
  followBtn.addEventListener('click', () => {
    const active = ACTIVE_STEP[status.pipelineStage]
    followProgress = true
    if (active !== undefined) stepIndex = active
    setMsg('')
    renderAll()
  })
  const beginEdit = async (kind, ordinal = null) => {
    if (editing) return
    if (isRunning(status)) {
      setMsg('流水线正在处理中，请等待当前任务结束后再手动修正。', 'bad')
      return
    }
    stopPolling()
    setMsg('手动修正中：自动刷新已暂停，保存后会继续执行。')
    if (kind === 'raw' || kind === 'clean') {
      if (!caches[kind]) await loadPreview(kind)
      editing = { kind, ordinal: null, text: caches[kind]?.text || '' }
    } else {
      if (!caches.chunks) await loadPreview('chunks')
      const chunk = (caches.chunks?.chunks || []).find((item) => item.ordinal === ordinal)
      if (!chunk) {
        setMsg('切片不存在，请刷新后重试。', 'bad')
        return
      }
      editing = { kind: 'chunk', ordinal, text: chunk.text || '' }
    }
    if (!closed) renderAll()
  }
  const cancelEdit = () => {
    editing = null
    setMsg('已取消手动修正。')
    renderAll()
    void refreshStatus()
  }
  const saveEdit = async (button) => {
    if (!editing) return
    const kind = button.dataset.kbSaveEdit
    const ordinal = button.dataset.kbChunkOrdinal === undefined ? null : Number(button.dataset.kbChunkOrdinal)
    const textarea = contentEl.querySelector('[data-kb-editor]')
    const text = textarea ? textarea.value : ''
    if (!text.trim()) {
      setMsg('内容不能为空。', 'bad')
      textarea?.focus()
      return
    }
    button.disabled = true
    setMsg('正在保存手动修正…')
    const savedKind = editing.kind
    try {
      if (kind === 'chunk') {
        await apiSend('PUT', `/api/console/kb/docs/${encodeURIComponent(docId)}/chunks/${ordinal}`, { text })
      } else {
        await apiSend('PUT', `/api/console/kb/docs/${encodeURIComponent(docId)}/pipeline/content`, {
          stage: kind,
          text,
        })
      }
    } catch (err) {
      button.disabled = false
      setMsg(err.message || '保存失败', 'bad')
      return
    }
    editing = null
    caches.raw = null
    caches.clean = null
    caches.chunks = null
    previewErrors.raw = ''
    previewErrors.clean = ''
    previewErrors.chunks = ''
    followProgress = true
    stepIndex = savedKind === 'raw' ? 1 : savedKind === 'clean' ? 2 : 3
    setMsg(
      savedKind === 'raw'
        ? '已保存解析文本，正在重新清洗…'
        : savedKind === 'clean'
          ? '已保存清洗文本，正在重新切片…'
          : '已保存切片，正在重建索引…',
      'good',
    )
    renderAll()
    try {
      await apiSend('POST', `/api/console/kb/docs/${encodeURIComponent(docId)}/pipeline/retry`, {
        stage: savedKind === 'raw' ? 'clean' : savedKind === 'clean' ? 'chunk' : 'index',
      })
      await loadDocs(collectionId)
      await refreshStatus({ follow: true })
    } catch (err) {
      setMsg(`内容已保存，但启动后续步骤失败：${err.message || '未知错误'}`, 'bad')
      await refreshStatus()
    }
  }
  contentEl.addEventListener('click', (event) => {
    const cancel = event.target.closest('[data-kb-cancel-edit]')
    if (cancel) {
      cancelEdit()
      return
    }
    const save = event.target.closest('[data-kb-save-edit]')
    if (save) {
      void saveEdit(save)
      return
    }
    const edit = event.target.closest('[data-kb-edit]')
    if (edit) {
      const kind = edit.dataset.kbEdit
      const ordinal = edit.dataset.kbEditOrdinal === undefined ? null : Number(edit.dataset.kbEditOrdinal)
      void beginEdit(kind, ordinal)
    }
  })
  contentEl.addEventListener('input', (event) => {
    if (!event.target.matches('[data-kb-editor]')) return
    const count = event.target.closest('.kb-flow-editor')?.querySelector('[data-kb-editor-count]')
    if (count) count.textContent = `${event.target.value.length.toLocaleString()} 字符`
  })
  contentEl.addEventListener('keydown', (event) => {
    if (!event.target.matches('[data-kb-editor]')) return
    if (event.key === 'Escape') {
      event.preventDefault()
      cancelEdit()
      return
    }
    if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
      event.preventDefault()
      contentEl.querySelector('[data-kb-save-edit]')?.click()
    }
  })
  retryBtn.addEventListener('click', async () => {
    const step = STEPS[stepIndex]
    const confirmed = await confirmCard({
      title: `${step.retry}？`,
      message: `将从「${step.label}」步骤重新执行；后续步骤会按最新结果重新生成，文档在完成前不可用于新增召回。`,
      confirmText: step.retry,
    })
    if (!confirmed) return
    retryBtn.disabled = true
    followProgress = true
    setMsg(`已提交${step.label}任务，等待 worker…`)
    try {
      await apiSend('POST', `/api/console/kb/docs/${encodeURIComponent(docId)}/pipeline/retry`, {
        stage: step.apiStage,
      })
      setMsg(`已排入队列，正在执行${step.label}。`, 'good')
      await loadDocs(collectionId)
      await refreshStatus({ follow: true })
    } catch (err) {
      retryBtn.disabled = false
      setMsg(err.message || '重跑失败', 'bad')
    }
  })

  renderAll()
  if (isRunning(status)) pollTimer = setInterval(() => void refreshStatus(), 1800)
}

/**
 * 批量入库进度台：上传成功后直接进入这里，整批与单文件状态同屏可见。
 * 单文件仍复用 openKbUploadDocModal 的四步详情和手动修正能力。
 */
function openKbBatchPipeline(files, collectionId, failed = []) {
  const STEPS = [
    { key: 'parse', label: '解析' },
    { key: 'clean', label: '清洗' },
    { key: 'chunk', label: '切片' },
    { key: 'index', label: '索引' },
  ]
  const ACTIVE_STEP = { parsing: 0, cleaning: 1, chunking: 2, indexing: 3 }
  const DONE_THROUGH = {
    uploaded: -1,
    parsing: -1,
    parsed: 0,
    cleaning: 0,
    cleaned: 1,
    chunking: 1,
    chunked: 2,
    indexing: 2,
    indexed: 3,
  }
  const items = files.map((item) => ({
    docId: String(item.docId),
    title: item.title || item.filename || '未命名文档',
    filename: item.filename || item.title || '未命名文档',
    sizeBytes: Number(item.sizeBytes) || 0,
    duplicate: Boolean(item.duplicate),
    status: null,
    statusError: '',
  }))
  const failedFiles = Array.isArray(failed) ? failed : []
  const overlay = modelModal(`
    <div class="kb-batch-head">
      <div class="kb-batch-title-wrap">
        <span class="kb-batch-kicker">知识库 / 智能入库批次</span>
        <div class="kb-batch-titleline">
          <h3 id="kb-batch-title">批次正在入库</h3>
          <span class="pill warn" id="kb-batch-pill">处理中</span>
        </div>
        <p id="kb-batch-subtitle"></p>
      </div>
      <button class="modal-x" type="button" id="kb-batch-x" aria-label="关闭">×</button>
    </div>
    <div class="kb-batch-notice" id="kb-batch-notice" hidden></div>
    <div class="kb-batch-overview">
      <div class="kb-batch-progress-head">
        <div><strong id="kb-batch-progress-text">正在读取处理进度…</strong><span>整批四步流水线进度</span></div>
        <span class="kb-batch-progress-percent" id="kb-batch-progress-percent">0%</span>
      </div>
      <div class="kb-batch-bar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0">
        <i id="kb-batch-bar"></i>
      </div>
      <div class="kb-batch-tabs" id="kb-batch-tabs"></div>
    </div>
    <div class="kb-batch-body">
      <div class="kb-batch-list" id="kb-batch-list">
        <div class="kb-batch-loading">正在读取 ${items.length} 个文件的流水线状态…</div>
      </div>
    </div>
    <div class="kb-batch-foot">
      <div class="kb-batch-live"><span class="kb-batch-live-dot"></span><span id="kb-batch-live">每 1.8 秒自动刷新</span></div>
      <div class="kb-batch-foot-actions">
        <button class="btn ghost" type="button" id="kb-batch-refresh">立即刷新</button>
        <button class="btn primary" type="button" id="kb-batch-close">关闭</button>
      </div>
    </div>`)
  overlay.querySelector('.modal').classList.add('kb-batch-modal')
  const listEl = overlay.querySelector('#kb-batch-list')
  const tabsEl = overlay.querySelector('#kb-batch-tabs')
  const titleEl = overlay.querySelector('#kb-batch-title')
  const pillEl = overlay.querySelector('#kb-batch-pill')
  const subtitleEl = overlay.querySelector('#kb-batch-subtitle')
  const noticeEl = overlay.querySelector('#kb-batch-notice')
  const progressTextEl = overlay.querySelector('#kb-batch-progress-text')
  const progressPercentEl = overlay.querySelector('#kb-batch-progress-percent')
  const barEl = overlay.querySelector('#kb-batch-bar')
  const liveEl = overlay.querySelector('#kb-batch-live')
  let filter = 'all'
  let closed = false
  let refreshBusy = false
  let batchDone = false
  let lastRefreshAt = 0
  let loadDocsDone = false
  let pollTimer = null
  const previousFocus = document.activeElement

  if (failedFiles.length) {
    noticeEl.hidden = false
    noticeEl.innerHTML = `<strong>${failedFiles.length} 个文件未进入流水线</strong><ul>${failedFiles
      .map((item) => `<li>${esc(item.filename || '未命名文件')}：${esc(item.error || '上传失败')}</li>`)
      .join('')}</ul>`
  }
  tabsEl.innerHTML = ''

  const fileExt = (name) => {
    const ext = String(name).split('.').pop()
    return ext && ext !== name ? ext.toUpperCase().slice(0, 5) : 'DOC'
  }
  const activeStepOf = (status) => ACTIVE_STEP[status?.pipelineStage]
  const isTerminal = (item) =>
    Boolean(item.statusError) ||
    (item.status && ['indexed', 'failed', 'needs_config'].includes(item.status.pipelineStage))
  const bucketOf = (item) => {
    if (item.statusError) return 'error'
    if (!item.status) return 'waiting'
    const stage = item.status.pipelineStage
    if (stage === 'indexed') return 'done'
    if (stage === 'failed' || stage === 'needs_config') return 'error'
    if (item.status.lastJob?.status === 'pending') return 'waiting'
    if (activeStepOf(item.status) !== undefined || item.status.lastJob?.status === 'running') return 'processing'
    return 'waiting'
  }
  const progressOf = (item) => {
    if (item.statusError) return 0
    const status = item.status
    if (!status) return 0
    if (status.pipelineStage === 'indexed') return 4
    if (status.pipelineStage === 'needs_config') return 0
    const done = DONE_THROUGH[status.pipelineStage] ?? -1
    const failedRaw = status.pipelineStage === 'failed' ? STEPS.findIndex((step) => step.key === status.lastJob?.stage) : -1
    const failed = failedRaw >= 0 ? failedRaw : status.pipelineStage === 'failed' ? 0 : -1
    if (failed >= 0) return Math.max(0, failed)
    const active = activeStepOf(status)
    if (active !== undefined) return Math.min(4, done + 1.5)
    return Math.max(0, done + 1)
  }
  const stepStateOf = (status, index) => {
    if (!status) return 'pending'
    if (status.pipelineStage === 'needs_config') return index === 0 ? 'error' : 'pending'
    if (status.pipelineStage === 'failed') {
      const raw = STEPS.findIndex((step) => step.key === status.lastJob?.stage)
      const failed = raw >= 0 ? raw : 0
      return index === failed ? 'error' : index < failed ? 'done' : 'pending'
    }
    const active = activeStepOf(status)
    if (active === index) return 'active'
    const done = DONE_THROUGH[status.pipelineStage] ?? -1
    if (index <= done) return index === 3 && status.indexError ? 'warn' : 'done'
    if (status.lastJob?.status === 'pending' && index === done + 1) return 'queued'
    return 'pending'
  }
  const stepIcon = (state, index) =>
    state === 'done' ? '✓' : state === 'warn' ? '!' : state === 'error' ? '×' : state === 'active' ? '' : index + 1
  const activeCopy = (status) => {
    if (!status) return '读取状态中…'
    if (status.pipelineStage === 'needs_config') return status.pipelineError || '缺少 OCR 或兼容解析组件，等待配置'
    if (status.pipelineStage === 'failed') return status.pipelineError || status.lastJob?.error || '流程执行失败'
    if (status.pipelineStage === 'indexed') {
      return status.indexError ? '已完成关键词索引，向量索引有异常' : '解析、清洗、切片、索引全部完成'
    }
    const active = activeStepOf(status)
    if (active !== undefined) {
      const desc =
        active === 1 && status.cleanMode
          ? ` · ${status.cleanMode === 'manual' ? '人工修正' : status.cleanModelName || status.cleanMode}`
          : ''
      return `正在${STEPS[active].label}${desc}`
    }
    if (status.lastJob?.status === 'pending') {
      const queuedStage = STEPS.find((step) => step.key === status.lastJob?.stage)
      return `排队中 · 等待${queuedStage?.label || '处理'}`
    }
    return '等待下一步'
  }
  const statusPill = (item) => {
    if (item.statusError) return '<span class="pill danger">读取失败</span>'
    if (!item.status) return '<span class="pill">查询中</span>'
    const stage = item.status.pipelineStage
    return `<span class="pill ${KB_STAGE_CLASS[stage] || ''}">${esc(KB_STAGE_LABEL[stage] || stage)}</span>`
  }

  const renderTabs = () => {
    const counts = { all: items.length, processing: 0, waiting: 0, done: 0, error: 0 }
    for (const item of items) counts[bucketOf(item)] += 1
    const tabs = [
      ['all', '全部'],
      ['processing', '处理中'],
      ['waiting', '排队中'],
      ['done', '已完成'],
      ['error', '异常'],
    ]
    tabsEl.innerHTML = tabs
      .map(
        ([key, label]) =>
          `<button class="kb-batch-tab${filter === key ? ' is-active' : ''}" type="button" data-batch-filter="${key}">
            <strong>${counts[key]}</strong><span>${label}</span>
          </button>`,
      )
      .join('')
  }
  const renderItem = (item) => {
    const bucket = bucketOf(item)
    const status = item.status
    const progress = progressOf(item)
    const steps = STEPS.map((step, index) => {
      const state = stepStateOf(status, index)
      return `<span class="kb-batch-step is-${state}"><i>${state === 'active' ? '<b class="kb-batch-spinner"></b>' : stepIcon(state, index)}</i><b>${step.label}</b></span>`
    }).join('<u></u>')
    const meta = status
      ? [
          status.chunkCount ? `${status.chunkCount} 个切片` : '尚未切片',
          status.rawChars || status.cleanChars
            ? `${Number(status.rawChars || 0).toLocaleString()} → ${Number(status.cleanChars || 0).toLocaleString()} 字符`
            : '',
          `v${status.version}`,
          status.cleanMode
            ? status.cleanMode === 'manual'
              ? '人工修正'
              : status.cleanModelName || (status.cleanMode === 'rules' ? '规则清洗' : '智能清洗')
            : '',
        ]
          .filter(Boolean)
          .join(' · ')
      : ''
    const warning =
      status?.pipelineWarning || status?.indexError
        ? `<div class="kb-batch-warning">${esc((status.pipelineWarning || status.indexError || '').slice(0, 180))}</div>`
        : ''
    return `<article class="kb-batch-item is-${bucket}" tabindex="0" role="button" data-batch-doc="${esc(
      item.docId,
    )}" aria-label="查看 ${esc(item.filename)} 的处理流程">
      <div class="kb-batch-item-body">
        <div class="kb-batch-item-head">
          <span class="kb-batch-ext">${esc(fileExt(item.filename))}</span>
          <div class="kb-batch-item-title">
            <strong>${esc(item.filename)}</strong>
            <span>${item.sizeBytes ? kbFormatSize(item.sizeBytes) : ''}${
              item.duplicate ? ' <em class="kb-batch-reuse">已存在 · 复用原文档</em>' : ''
            }</span>
          </div>
          <div class="kb-batch-item-side">${statusPill(item)}<span class="kb-batch-go">查看流程 →</span></div>
        </div>
        <div class="kb-batch-steps">${steps}</div>
        <div class="kb-batch-item-foot">
          <span class="kb-batch-active">${esc(item.statusError || activeCopy(status))}</span>
          <span class="kb-batch-meta">${esc(meta)}</span>
        </div>
        ${warning}
      </div>
      <div class="kb-batch-item-progress"><i style="width:${Math.round((progress / 4) * 100)}%"></i></div>
    </article>`
  }
  const renderList = () => {
    const visible = filter === 'all' ? items : items.filter((item) => bucketOf(item) === filter)
    listEl.innerHTML = visible.length
      ? visible.map(renderItem).join('')
      : `<div class="kb-batch-empty">当前筛选下没有文件；${batchDone ? '批次已全部处理完成。' : '可以切回「全部」查看整批进度。'}</div>`
  }
  const renderProgress = () => {
    const total = items.reduce((sum, item) => sum + progressOf(item), 0)
    const percent = Math.min(100, Math.round((total / Math.max(1, items.length * 4)) * 100))
    const done = items.filter((item) => item.status?.pipelineStage === 'indexed').length
    const counts = { processing: 0, waiting: 0, done: 0, error: 0 }
    for (const item of items) {
      const bucket = bucketOf(item)
      if (bucket in counts) counts[bucket] += 1
    }
    progressTextEl.textContent = batchDone
      ? `已处理 ${done} / ${items.length} 个文件`
      : `已完成 ${done} / ${items.length} 个文件 · ${counts.processing} 个处理中 · ${counts.waiting} 个排队`
    progressPercentEl.textContent = `${percent}%`
    barEl.style.width = `${percent}%`
    barEl.parentElement?.setAttribute('aria-valuenow', String(percent))
    titleEl.textContent = batchDone ? '批次入库已完成' : `批次正在入库 · ${items.length} 个文件`
    pillEl.className = `pill ${batchDone ? (counts.error ? 'warn' : 'ok') : 'warn'}`
    pillEl.textContent = batchDone ? (counts.error ? '完成 · 有异常' : '全部完成') : '处理中'
    subtitleEl.textContent = batchDone
      ? '已停止自动刷新；可点击任一文件查看完整四步结果。'
      : '解析、清洗、切片、索引自动执行；点击任一文件可查看流程并手动修正自动产物。'
    liveEl.textContent = batchDone
      ? '批次已结束，自动刷新已停止'
      : lastRefreshAt
        ? `每 1.8 秒自动刷新 · 最近 ${fmtTime(lastRefreshAt)}`
        : '正在连接流水线状态…'
  }
  const render = () => {
    renderProgress()
    renderTabs()
    renderList()
  }
  const finishIfDone = () => {
    if (!items.length || !items.every(isTerminal)) return
    batchDone = true
    if (pollTimer) clearInterval(pollTimer)
    pollTimer = null
    if (!loadDocsDone) {
      loadDocsDone = true
      void loadDocs(collectionId)
    }
  }
  const refresh = async () => {
    if (closed || refreshBusy) return
    refreshBusy = true
    try {
      const result = await apiSend('POST', '/api/console/kb/docs/pipeline/batch', {
        docIds: items.map((item) => item.docId),
      })
      const rows = Array.isArray(result.items) ? result.items : []
      const byId = new Map(rows.map((row) => [String(row.status?.docId || row.docId), row]))
      for (const item of items) {
        const row = byId.get(item.docId)
        if (!row) continue
        if (row.ok && row.status) {
          item.status = row.status
          item.statusError = ''
          if (row.status.title) item.title = row.status.title
        } else {
          item.statusError = row.error || '状态读取失败'
        }
      }
      lastRefreshAt = Date.now()
    } catch (err) {
      liveEl.textContent = `刷新失败：${err.message || '网络错误'}；将继续重试`
    } finally {
      refreshBusy = false
      finishIfDone()
      render()
    }
  }
  const close = () => {
    if (closed) return
    closed = true
    if (pollTimer) clearInterval(pollTimer)
    pollTimer = null
    document.removeEventListener('keydown', onKey)
    overlay.remove()
    if (previousFocus && typeof previousFocus.focus === 'function' && document.contains(previousFocus)) {
      previousFocus.focus()
    }
  }
  const onKey = (event) => {
    if (event.key !== 'Escape') return
    if (document.body.lastElementChild !== overlay) return
    event.preventDefault()
    close()
  }
  const openDetail = (docId) => {
    if (!docId) return
    void openKbUploadDocModal(docId, collectionId)
  }
  overlay.querySelector('#kb-batch-x').addEventListener('click', close)
  overlay.querySelector('#kb-batch-close').addEventListener('click', close)
  overlay.querySelector('#kb-batch-refresh').addEventListener('click', () => void refresh())
  tabsEl.addEventListener('click', (event) => {
    const button = event.target.closest('[data-batch-filter]')
    if (!button) return
    filter = button.dataset.batchFilter
    render()
  })
  listEl.addEventListener('click', (event) => {
    const row = event.target.closest('[data-batch-doc]')
    if (!row) return
    openDetail(row.dataset.batchDoc)
  })
  listEl.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' && event.key !== ' ') return
    const row = event.target.closest('[data-batch-doc]')
    if (!row) return
    event.preventDefault()
    openDetail(row.dataset.batchDoc)
  })
  document.addEventListener('keydown', onKey)
  render()
  void refresh()
  pollTimer = setInterval(() => void refresh(), 1800)
}

async function openKbDocEdit(docId) {
  let data
  try {
    data = await api(`/api/console/kb/docs/${encodeURIComponent(docId)}`)
  } catch (err) {
    alert(err.message || '文档读取失败')
    return
  }
  const doc = data.doc
  const overlay = modelModal(`
    <div class="modal-head"><h3>编辑文档</h3><button class="modal-x" type="button">×</button></div>
    <div class="field-stack">
      <label class="field"><span>标题</span><input id="doc-title" value="${esc(doc.title)}" /></label>
      <label class="field"><span>正文</span><textarea id="doc-content" rows="12">${esc(doc.content || '')}</textarea></label>
      <label class="field"><span>密级</span>
        <select id="doc-cls">
          <option value="public"${doc.classification === 'public' ? ' selected' : ''}>公开</option>
          <option value="internal"${doc.classification === 'internal' ? ' selected' : ''}>内部</option>
          <option value="confidential"${doc.classification === 'confidential' ? ' selected' : ''}>机密</option>
        </select>
      </label>
      ${hintNote('保存说明', '保存后会重新切片。')}
      <div class="hint">当前 ${doc.chunkCount} 个切片 · 来源：${esc(doc.sourceKind || 'local')}</div>
    </div>
    <div class="modal-state" id="doc-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="doc-save">保存修改</button>
      <button class="btn danger" type="button" id="doc-delete">删除文档</button>
      <button class="btn ghost" type="button" id="doc-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#doc-cancel').addEventListener('click', close)
  overlay.querySelector('#doc-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#doc-state')
    stateEl.textContent = '保存中…'
    try {
      await apiSend('PATCH', `/api/console/kb/docs/${encodeURIComponent(doc.id)}`, {
        title: overlay.querySelector('#doc-title').value.trim(),
        content: overlay.querySelector('#doc-content').value,
        classification: overlay.querySelector('#doc-cls').value,
      })
      close()
      loadDocs(doc.collectionId)
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
  overlay.querySelector('#doc-delete').addEventListener('click', async () => {
    const ok = await confirmCard({
      title: '删除文档？',
      message: `「${doc.title}」删除后不再参与检索。`,
      confirmText: '删除文档',
    })
    if (!ok) return
    try {
      await apiSend('DELETE', `/api/console/kb/docs/${encodeURIComponent(doc.id)}`)
      close()
      loadDocs(doc.collectionId)
    } catch (err) {
      alert(err.message || '删除失败')
    }
  })
}

function setKbPageSizeOpen(wrap, open) {
  const trigger = wrap.querySelector('#kb-doc-page-size')
  const menu = wrap.querySelector('.kb-page-size-menu')
  if (!trigger || !menu) return
  menu.hidden = !open
  wrap.classList.toggle('is-open', open)
  trigger.setAttribute('aria-expanded', String(open))
  if (open) {
    const selected = menu.querySelector('[role="option"][aria-selected="true"]')
    ;(selected || menu.querySelector('[role="option"]'))?.focus()
  }
}

document.addEventListener('click', (event) => {
  const wrap = document.querySelector('[data-kb-page-size].is-open')
  if (wrap && !wrap.contains(event.target)) setKbPageSizeOpen(wrap, false)
})

document.addEventListener('keydown', (event) => {
  if (event.key !== 'Escape') return
  const wrap = document.querySelector('[data-kb-page-size].is-open')
  if (!wrap) return
  event.preventDefault()
  event.stopPropagation()
  setKbPageSizeOpen(wrap, false)
  wrap.querySelector('#kb-doc-page-size')?.focus()
})

async function loadDocs(collectionId, options = {}) {
  const host = $('#kb-docs')
  if (!host) return
  if (state.kbDocCollection !== collectionId) {
    state.kbDocCollection = collectionId
    state.kbDocPage = 1
  }
  if (options.page) state.kbDocPage = Math.max(1, Number(options.page) || 1)
  if (options.pageSize) {
    state.kbDocPageSize = Number(options.pageSize) || 10
    state.kbDocPage = 1
  }
  const page = Math.max(1, Number(state.kbDocPage) || 1)
  const pageSize = [10, 20, 50].includes(Number(state.kbDocPageSize)) ? Number(state.kbDocPageSize) : 10
  renderLoading(host, '正在读取文档', { skeleton: true, rows: 4 })
  try {
    const data = await api(
      `/api/console/kb/collections/${encodeURIComponent(collectionId)}/docs?page=${page}&pageSize=${pageSize}`,
    )
    const collection = state.kb?.collections?.find((item) => item.id === collectionId)
    const sourceKind = data.collection.sourceKind || collection?.sourceKind || 'local'
    const sourceLabel = data.collection.sourceLabel || collection?.sourceLabel || sourceKind
    const external = Boolean(data.external)
    const pagination = data.pagination || {
      page,
      pageSize,
      total: data.docs.length,
      totalPages: 1,
    }
    state.kbDocPage = Number(pagination.page) || 1
    state.kbDocPageSize = Number(pagination.pageSize) || pageSize
    const totalChunks = Number(
      data.totalChunks ?? data.docs.reduce((sum, doc) => sum + Number(doc.chunkCount || 0), 0),
    )
    const vector = data.vector ?? { chunks: 0, vectors: 0, dim: 0, modelIds: [] }
    const indexCell = (doc) => {
      if (external) return `<span class="pill">外部托管</span>`
      const stage = doc.pipelineStage || (doc.sourceType === 'upload' ? 'uploaded' : 'indexed')
      const stageLabel = KB_STAGE_LABEL[stage] || stage
      if (stage === 'needs_config') {
        return `<span class="pill danger" title="${esc(doc.pipelineError || '')}">待配置</span>`
      }
      if (stage === 'failed') {
        return `<span class="pill danger" title="${esc(doc.pipelineError || doc.indexError || '')}">流水线失败</span>`
      }
      if (stage !== 'indexed') {
        return `<span class="pill warn" title="${esc(doc.pipelineError || '')}">${esc(stageLabel)}</span>`
      }
      if (doc.status === 'pending') return '<span class="pill warn">待索引</span>'
      if (doc.status === 'indexing') return '<span class="pill warn">向量化中…</span>'
      if (doc.status === 'failed') {
        return `<span class="pill danger" title="${esc(doc.indexError || '')}">索引失败</span>`
      }
      if (doc.status === 'indexed' || doc.status === 'completed') {
        if (doc.indexError) {
          return `<span class="pill warn" title="${esc(doc.indexError)}">已入库 · 仅关键词</span>`
        }
        return '<span class="pill ok">已索引</span>'
      }
      return `<span class="pill warn">${esc(doc.status)}</span>`
    }
    const docs = data.docs
      .map(
        (doc) => `<tr${external ? '' : ` class="click-row" data-doc="${esc(doc.id)}" data-doc-type="${esc(
          doc.sourceType || 'manual',
        )}"`}>
          <td class="name-cell"><strong>${esc(doc.title)}</strong><div class="desc">${doc.chunkCount} ${
            external ? '字' : '个切片'
          }${doc.sourceType === 'upload' && doc.pipelineStage !== 'indexed' ? ` · ${esc(KB_STAGE_LABEL[doc.pipelineStage] || doc.pipelineStage)}` : ''}</div></td>
          <td><span class="pill">${external ? '外部' : esc(CLS_LABEL[doc.classification] || doc.classification)}</span></td>
          <td>${indexCell(doc)}${
            (doc.pipelineError || doc.indexError) && !['failed', 'needs_config'].includes(doc.pipelineStage)
              ? `<div class="desc kb-index-error">${esc(doc.pipelineError || doc.indexError)}</div>`
              : ''
          }</td>
          <td class="kb-doc-actions">${
            external
              ? '<span class="muted">上游管理</span>'
              : `<button class="btn sm danger" type="button" data-doc-delete="${esc(doc.id)}" aria-label="删除 ${esc(doc.title)}">删除</button>`
          }</td>
        </tr>`,
      )
      .join('')

    const sourceBadge =
      sourceKind === 'local'
        ? ''
        : `<span class="pill source-pill">${esc(sourceLabel)}</span>`
    const docsHint = external
      ? `上游知识库返回的文档，EAB 内只读。文档由 ${sourceLabel} 上游管理；检索通过 kb.search 在线调用。${
          pagination.total === 0 ? '当前没有返回文档，请检查 API Key 是否有 dataset:read 权限。' : ''
        }`
      : sourceKind === 'obsidian'
        ? 'Obsidian 文档已导入为本地切片，可直接点击编辑；上游新增文件请点“同步 Vault”。'
        : '点击任意一行查看详情；上传文档会显示解析/清洗/切片/向量化阶段，手工文档可直接编辑。'

    const pageNumbers = []
    if (pagination.totalPages <= 7) {
      for (let index = 1; index <= pagination.totalPages; index += 1) pageNumbers.push(index)
    } else {
      pageNumbers.push(1)
      const start = Math.max(2, pagination.page - 1)
      const end = Math.min(pagination.totalPages - 1, pagination.page + 1)
      if (start > 2) pageNumbers.push('…')
      for (let index = start; index <= end; index += 1) pageNumbers.push(index)
      if (end < pagination.totalPages - 1) pageNumbers.push('…')
      pageNumbers.push(pagination.totalPages)
    }
    const emptyDocsState = stateBlockHtml({
      compact: true,
      title: external ? '上游还没有返回文档' : '还没有文档',
      body: external
        ? `当前没有从 ${sourceLabel} 返回文档。请检查 API Key 是否有 dataset:read 权限，或稍后重新读取。`
        : '上传 PDF、Word、Markdown 或纯文本；上传后会进入解析、清洗、切片和索引流水线。',
      actionLabel: external ? '重新读取' : '上传文件',
      action: external ? 'kb-docs-reload' : 'kb-docs-add',
    })
    const pager = `<div class="kb-doc-pager">
      <span class="kb-doc-pager-total">共 <strong>${pagination.total}</strong> 篇文档</span>
      <div class="kb-doc-pager-controls">
        <div class="kb-doc-page-size"><span>每页</span>
          <span class="kb-page-size-select" data-kb-page-size>
            <button class="kb-page-size-trigger" type="button" id="kb-doc-page-size"
              aria-label="每页文档数，当前 ${pagination.pageSize} 条"
              aria-haspopup="listbox" aria-expanded="false" aria-controls="kb-doc-page-size-menu">
              <span class="kb-page-size-value">${pagination.pageSize}</span>
              <span class="kb-page-size-caret" aria-hidden="true"></span>
            </button>
            <span class="kb-page-size-menu" id="kb-doc-page-size-menu" role="listbox" hidden>
              ${[10, 20, 50]
                .map(
                  (size) => `<button class="kb-page-size-option" type="button" role="option"
                    data-kb-page-size-option="${size}" aria-selected="${pagination.pageSize === size}">
                    <span>${size} 条</span><span class="kb-page-size-check" aria-hidden="true">${
                      pagination.pageSize === size ? '✓' : ''
                    }</span>
                  </button>`,
                )
                .join('')}
            </span>
          </span>
          条
        </div>
        <button class="kb-page-btn" type="button" data-kb-page="${pagination.page - 1}" ${
          pagination.page <= 1 ? 'disabled' : ''
        } aria-label="上一页">‹</button>
        ${pageNumbers
          .map((item) =>
            item === '…'
              ? '<span class="kb-page-ellipsis">…</span>'
              : `<button class="kb-page-btn${item === pagination.page ? ' is-active' : ''}" type="button" data-kb-page="${item}" ${
                  item === pagination.page ? 'aria-current="page"' : ''
                } aria-label="第 ${item} 页">${item}</button>`,
          )
          .join('')}
        <button class="kb-page-btn" type="button" data-kb-page="${pagination.page + 1}" ${
          pagination.page >= pagination.totalPages ? 'disabled' : ''
        } aria-label="下一页">›</button>
        <span class="kb-doc-page-jump">${pagination.page} / ${pagination.totalPages}</span>
      </div>
    </div>`

    host.innerHTML = `
      <section class="panel kb-summary-panel">
        <div class="panel-head kb-summary-head">
          <div class="kb-summary-copy">
            <h2>${esc(data.collection.name)} ${sourceBadge}</h2>
            <span class="hint">${esc(MODE_LABEL[data.collection.aclMode] || data.collection.aclMode)} · ${
              pagination.total
            } 篇文档${external ? '' : ` · ${totalChunks} 个切片`}</span>
          </div>
          <div class="head-actions kb-summary-actions">
            ${
              sourceKind !== 'local'
                ? '<button class="btn" type="button" id="kb-test">测试连接</button>'
                : ''
            }
            ${
              sourceKind === 'obsidian'
                ? '<button class="btn" type="button" id="kb-sync">同步 Vault</button>'
                : ''
            }
            <button class="btn" type="button" id="kb-edit">编辑 / 可见范围</button>
            ${external ? '' : '<button class="btn" type="button" id="kb-retrieval-test">召回测试</button>'}
            ${external ? '' : '<button class="btn" type="button" id="kb-reindex">重建索引</button>'}
            ${external ? '' : '<button class="btn primary" type="button" id="kb-add-doc">上传文件</button>'}
          </div>
        </div>
        <div class="modal-state" id="kb-source-state"></div>
        ${
          external
            ? ''
            : `<div class="kb-vector-bar ${vector.vectors ? 'is-on' : ''}">
                <div class="kb-vector-copy">
                  <strong>${vector.vectors ? '混合检索已启用' : '当前仅关键词检索'}</strong>
                  <span>${
                    vector.vectors
                      ? `${vector.vectors} 个切片已向量化 · ${vector.dim} 维${
                          vector.modelIds?.length ? ` · ${esc(vector.modelIds.join(' / '))}` : ''
                        }`
                      : '未配置向量模型或尚未索引；上传和问答仍可用，不会阻断。'
                  }</span>
                </div>
                <div class="kb-vector-stats">
                  <div><strong>${totalChunks}</strong><span>切片</span></div>
                  <div><strong>${vector.vectors || 0}</strong><span>向量</span></div>
                </div>
              </div>`
        }
      </section>

      <section class="panel kb-doc-panel">
        <div class="panel-head">
          <div class="kb-doc-title"><h2>文档</h2>${hintBadge(external ? '来源说明' : '文档说明', docsHint)}</div>
          <span class="pill">${pagination.total} 篇</span>
        </div>
        <table class="data">
          <thead><tr><th>文档</th><th>密级</th><th>索引状态</th><th>操作</th></tr></thead>
          <tbody>${docs || `<tr><td colspan="4">${emptyDocsState}</td></tr>`}</tbody>
        </table>
        ${pager}
      </section>`

    host.querySelector('#kb-edit')?.addEventListener('click', () => {
      if (collection) openKbModal(collection)
    })
    host.querySelector('[data-state-action="kb-docs-add"]')?.addEventListener('click', () => {
      openKbDocModal(collectionId, data.collection.aclMode)
    })
    host.querySelector('[data-state-action="kb-docs-reload"]')?.addEventListener('click', () => {
      loadDocs(collectionId)
    })
    host.querySelector('#kb-add-doc')?.addEventListener('click', () => openKbDocModal(collectionId, data.collection.aclMode))
    host.querySelector('#kb-retrieval-test')?.addEventListener('click', () => {
      openKbRetrievalTest(collectionId)
    })
    host.querySelector('#kb-test')?.addEventListener('click', async (event) => {
      const stateEl = host.querySelector('#kb-source-state')
      const button = event.currentTarget
      button.disabled = true
      stateEl.className = 'modal-state'
      stateEl.textContent = '测试连接中…'
      try {
        const result = await apiPost(`/api/console/kb/collections/${encodeURIComponent(collectionId)}/test`, {})
        stateEl.className = `modal-state ${result.ok ? 'good' : 'bad'}`
        stateEl.textContent = result.message || (result.ok ? '连接成功' : '连接失败')
      } catch (err) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = err.message || '测试失败'
      } finally {
        button.disabled = false
      }
    })
    host.querySelector('#kb-sync')?.addEventListener('click', async (event) => {
      const stateEl = host.querySelector('#kb-source-state')
      const button = event.currentTarget
      button.disabled = true
      stateEl.className = 'modal-state'
      stateEl.textContent = '同步 Vault 中…'
      try {
        const result = await apiPost(`/api/console/kb/collections/${encodeURIComponent(collectionId)}/sync`, {})
        stateEl.className = 'modal-state good'
        stateEl.textContent = `同步完成：${result.files} 个文件，新增 ${result.created}，更新 ${result.updated}，跳过 ${result.skipped}`
        await loadKb()
      } catch (err) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = err.message || '同步失败'
      } finally {
        button.disabled = false
      }
    })
    host.querySelector('#kb-reindex')?.addEventListener('click', async (event) => {
      const stateEl = host.querySelector('#kb-source-state')
      const button = event.currentTarget
      button.disabled = true
      stateEl.className = 'modal-state'
      stateEl.textContent = '提交索引任务…'
      try {
        await apiPost(`/api/console/kb/collections/${encodeURIComponent(collectionId)}/reindex`, {})
        for (let attempt = 0; attempt < 80; attempt += 1) {
          await new Promise((resolve) => setTimeout(resolve, 1500))
          const status = await api(
            `/api/console/kb/collections/${encodeURIComponent(collectionId)}/index-status`,
          )
          const job = status.job
          if (!job) break
          if (job.status === 'failed' || job.status === 'done') {
            stateEl.className = `modal-state ${job.status === 'failed' ? 'bad' : 'good'}`
            stateEl.textContent =
              job.status === 'failed'
                ? `索引失败：${job.done}/${job.total} 成功${job.error ? ` · ${job.error}` : ''}`
                : `索引完成：${job.done}/${job.total} 篇文档，${status.vector?.vectors ?? 0} 个向量`
            await loadDocs(collectionId)
            return
          }
          stateEl.textContent = `向量化中 ${job.done}/${job.total}…`
        }
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '索引任务超时，稍后可在索引状态里查看结果'
      } catch (err) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = err.message || '重建索引失败'
      } finally {
        button.disabled = false
      }
    })
    for (const row of host.querySelectorAll('[data-doc]')) {
      row.addEventListener('click', () => {
        if (row.dataset.docType === 'upload') openKbUploadDocModal(row.dataset.doc, collectionId)
        else openKbDocEdit(row.dataset.doc)
      })
    }
    for (const button of host.querySelectorAll('[data-kb-page]')) {
      button.addEventListener('click', async () => {
        const target = Number(button.dataset.kbPage)
        if (!target || target < 1 || target > pagination.totalPages || target === pagination.page) return
        await loadDocs(collectionId, { page: target })
      })
    }
    const pageSizeControl = host.querySelector('[data-kb-page-size]')
    const pageSizeTrigger = pageSizeControl?.querySelector('#kb-doc-page-size')
    pageSizeTrigger?.addEventListener('click', () => {
      for (const other of document.querySelectorAll('[data-kb-page-size].is-open')) {
        if (other !== pageSizeControl) setKbPageSizeOpen(other, false)
      }
      setKbPageSizeOpen(pageSizeControl, !pageSizeControl.classList.contains('is-open'))
    })
    for (const option of pageSizeControl?.querySelectorAll('[data-kb-page-size-option]') || []) {
      option.addEventListener('click', async (event) => {
        event.stopPropagation()
        const size = Number(option.dataset.kbPageSizeOption)
        setKbPageSizeOpen(pageSizeControl, false)
        if (![10, 20, 50].includes(size) || size === pagination.pageSize) return
        await loadDocs(collectionId, { pageSize: size })
      })
    }
    for (const button of host.querySelectorAll('[data-doc-delete]')) {
      button.addEventListener('click', async (event) => {
        event.preventDefault()
        event.stopPropagation()
        const doc = data.docs.find((item) => item.id === button.dataset.docDelete)
        if (!doc) return
        const confirmed = await confirmCard({
          title: '删除文档？',
          message: `「${doc.title}」删除后不再参与检索，切片会一并移除。`,
          confirmText: '删除文档',
        })
        if (!confirmed) return
        const label = button.textContent
        button.disabled = true
        button.textContent = '删除中…'
        try {
          await apiSend('DELETE', `/api/console/kb/docs/${encodeURIComponent(doc.id)}`)
          if (collection) collection.docCount = Math.max(0, pagination.total - 1)
          if (state.kb) renderKbSide(state.kb)
          await loadDocs(collectionId)
        } catch (err) {
          button.disabled = false
          button.textContent = label
          alert(err.message || '删除失败')
        }
      })
    }
    const activeStages = new Set([
      'uploaded',
      'parsing',
      'parsed',
      'cleaning',
      'cleaned',
      'chunking',
      'chunked',
      'indexing',
    ])
    if (state.kbPollTimer) clearTimeout(state.kbPollTimer)
    if (!external && data.docs.some((doc) => activeStages.has(doc.pipelineStage))) {
      state.kbPollTimer = setTimeout(() => loadDocs(collectionId), 2500)
    }
  } catch (err) {
    renderConsoleError(host, err, () => loadDocs(collectionId))
  }
}

/* ---------------- 组织页：成员管理 / 部门管理 ---------------- */

async function loadOrg() {
  const view = $('#view')
  setSide('', true)
  view.innerHTML = '<div id="org-members"></div>'
  renderLoading($('#org-members'), '正在读取成员', { skeleton: true, rows: 5 })
  try {
    await refreshOrgRoots()
    const currentRoot = currentCompanyRoot()
    const paths = new Set(deptNodes(currentRoot).map((node) => node.path))
    if (!state.deptFilter || !paths.has(state.deptFilter)) {
      state.deptFilter = currentRoot?.path ?? null
    }
    await loadMembers($('#org-members'))
  } catch (err) {
    renderConsoleError(view, err, () => loadOrg())
  }
}

async function loadDepartments() {
  const view = $('#view')
  setSide('', true)
  renderLoading(view)
  try {
    view.innerHTML = `
      <div class="dept-board">
        <section class="panel dept-tree-card">
          <div class="panel-head">
            <div><h2>部门结构</h2><span class="hint" id="dept-count">—</span></div>
            <div class="panel-actions">
              <button class="btn sm ghost" type="button" data-tree-expand>全部展开</button>
              <button class="btn sm ghost" type="button" data-tree-collapse>全部收起</button>
              <button class="btn sm primary" type="button" id="dept-new">＋ 新建部门</button>
            </div>
          </div>
          <div class="hint-note" style="margin:0 18px 12px">${hintBadge('人数口径', '点部门查看详情；右键可编辑或删除。人数口径为含下级部门的成员数，与成员管理页选「含下级」一致。')}</div>
          <div class="tree dept-tree" id="tree"></div>
        </section>
        <section class="dept-detail" id="dept-detail"></section>
      </div>`
    await loadTree()
    const currentRoot = currentCompanyRoot()
    const paths = new Set(deptNodes(currentRoot).map((node) => node.path))
    if (!state.deptFilter || !paths.has(state.deptFilter)) {
      state.deptFilter = currentRoot?.path ?? null
    }
    repaintTree()
    view.querySelector('#dept-new')?.addEventListener('click', () => openDeptCreate(state.deptFilter))
    renderDeptDetail(orgSelectedDept())
  } catch (err) {
    renderDenied(view, err)
  }
}

function renderDeptDetail(node) {
  const host = $('#dept-detail')
  if (!host) return
  if (!node) {
    host.innerHTML = `<section class="panel"><div class="empty">当前公司还没有部门数据</div></section>`
    return
  }
  const root = currentCompanyRoot()
  const all = deptNodes(root)
  const parent = all.find((item) => item.children?.some((child) => child.id === node.id))
  const children = node.children || []
  const isRoot = isRootDept(node)
  const direct = Number(node.memberCount ?? 0)
  const total = Number(node.subtreeMemberCount ?? direct)
  host.innerHTML = `
    <section class="panel dept-detail-card">
      <div class="panel-head">
        <div>
          <h2>${esc(node.name)}</h2>
          <span class="hint">${isRoot ? '公司根部门' : parent ? `上级 · ${esc(parent.name)}` : '部门'}</span>
        </div>
        <div class="panel-actions">
          <button class="btn sm ghost" type="button" data-dept-detail-manager>${node.managerName ? '更换负责人' : '设置负责人'}</button>
          <button class="btn sm" type="button" data-dept-detail-edit>编辑部门</button>
          ${isRoot ? '' : `<button class="btn sm danger" type="button" data-dept-detail-delete>删除</button>`}
        </div>
      </div>
      <div class="dept-detail-stats">
        <div><strong>${direct}</strong><span>直属成员</span></div>
        <div><strong>${total}</strong><span>含下级成员</span></div>
        <div><strong>${children.length}</strong><span>下级部门</span></div>
        <div><strong>${esc(node.managerName || '未设置')}</strong><span>负责人</span></div>
      </div>
      <div class="dept-detail-path mono">${esc(node.path)}</div>
      <div class="dept-detail-section">
        <div class="dept-detail-section-head">下级部门 <span class="muted">${children.length}</span></div>
        ${
          children.length
            ? `<div class="dept-child-list">${children
                .map(
                  (child) =>
                    `<button class="dept-child" type="button" data-dept-child="${esc(child.path)}">
                      <span class="dept-child-name">${esc(child.name)}</span>
                      <span class="dept-child-meta">${Number(child.subtreeMemberCount ?? child.memberCount ?? 0)} 人 · ${child.children?.length ?? 0} 个下级</span>
                    </button>`,
                )
                .join('')}</div>`
            : '<div class="muted dept-detail-empty">没有下级部门</div>'
        }
      </div>
      <div class="dept-detail-actions">
        <button class="btn sm ghost" type="button" data-dept-view-members>查看该部门成员</button>
      </div>
    </section>`
  host.querySelector('[data-dept-detail-edit]')?.addEventListener('click', () => openDeptEdit(node))
  host.querySelector('[data-dept-detail-manager]')?.addEventListener('click', () => openDeptEdit(node, { focusManager: true }))
  host.querySelector('[data-dept-detail-delete]')?.addEventListener('click', () => deleteDept(node))
  host.querySelector('[data-dept-view-members]')?.addEventListener('click', () => {
    state.deptFilter = node.path
    navigate('org')
  })
  host.querySelectorAll('[data-dept-child]').forEach((button) => {
    button.addEventListener('click', () => {
      const child = all.find((item) => item.path === button.dataset.deptChild)
      if (!child) return
      state.deptFilter = child.path
      repaintTree()
      renderDeptDetail(child)
    })
  })
}

/** 部门树增删改后，按当前页面刷新右侧内容 */
function refreshOrgAfterTreeChange() {
  if (state.page === 'departments') {
    renderDeptDetail(orgSelectedDept())
    return
  }
  const list = $('#org-members')
  if (list) loadMembers(list)
}

async function loadMembers(container) {
  const host = container || $('#view')
  if (!state.deptFilter) {
    host.innerHTML = `<section class="panel"><div class="panel-head"><h2>成员</h2></div>${stateBlockHtml({
      title: '这个公司还没有可显示的部门',
      body: '先在「部门管理」中创建部门，成员会按部门显示。',
      actionLabel: '去部门管理',
      action: 'member-goto-depts',
    })}</section>`
    host.querySelector('[data-state-action="member-goto-depts"]')?.addEventListener('click', () => navigate('departments'))
    return
  }
  renderLoading(host, '正在读取成员', { skeleton: true, rows: 5 })
  try {
    const data = await api('/api/org/members')
    const companyRoot = `/${state.company}/`
    const members = data.members.filter((m) => {
      if (state.deptFilter === companyRoot) return true
      // 部门成员默认包含所有下级部门成员，不再提供单独开关
      return m.deptPath.startsWith(state.deptFilter)
    })
    const searchTextOf = (m) =>
      [
        m.name,
        m.title,
        m.employeeNo,
        m.externalUserId,
        m.deptName,
        m.deptPath,
        STATUS_LABEL[m.status] || m.status,
        ...(m.roles || []).flatMap((r) => [r.code, r.name, ROLE_LABEL[r.code] || '']),
        ...(m.identities || []).flatMap((identity) => [
          identity.provider,
          CHANNEL_SOURCE_LABEL[identity.provider] || '',
          identity.externalUserId,
        ]),
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase()

    const rows = members
      .map((m) => {
        const identities = Array.isArray(m.identities) && m.identities.length
          ? m.identities
          : m.externalUserId
            ? [{ provider: 'dingtalk', externalUserId: m.externalUserId }]
            : []
        const identityRows = identities
          .map((identity) => {
            const label = CHANNEL_SOURCE_LABEL[identity.provider] || identity.provider
            return `<div class="desc mono member-identity-row"><span class="pill">${esc(label)}</span> ${esc(label)} ID：${esc(identity.externalUserId)}</div>`
          })
          .join('')
        const titleLine = m.title ? `<div class="desc">${esc(m.title)}</div>` : ''
        return `<tr data-member-search="${esc(searchTextOf(m))}">
        <td class="name-cell"><strong>${esc(m.name)}</strong>${titleLine}${identityRows}</td>
        <td>${esc(m.deptName)}<div class="desc mono member-dept-path">${esc(m.deptPath)}</div></td>
        <td>${(m.roles || []).map((r) => `<span class="chip accent">${esc(ROLE_LABEL[r.code] || r.code)}</span>`).join(' ')}</td>
        <td><span class="pill ${m.status === 'active' ? 'ok' : m.status === 'disabled' ? 'warn' : 'danger'}">${esc(
          STATUS_LABEL[m.status] || m.status,
        )}</span></td>
        <td><div class="row-actions member-actions">
          <button class="row-action primary" type="button" data-member-roles="${esc(m.id)}" title="角色权限">角色权限</button>
          <button class="row-action icon" type="button" data-member-more="${esc(m.id)}" title="更多操作" aria-label="更多成员操作" aria-haspopup="true">⋯</button>
        </div></td>
      </tr>`
      })
      .join('')

    const roleCounts = new Map()
    members.forEach((m) => {
      ;(m.roles || []).forEach((r) => {
        roleCounts.set(r.code, (roleCounts.get(r.code) || 0) + 1)
      })
    })
    const roleChips = [...roleCounts.entries()]
      .map(([code, count]) => `<span class="chip accent">${esc(ROLE_LABEL[code] || code)} · ${count} 人</span>`)
      .join(' ')
    const memberEmptyState = stateBlockHtml({
      compact: true,
      title: '该部门及下级还没有成员',
      body: '可以新建成员，或切换到其他部门查看。',
      actionLabel: '新建成员',
      action: 'member-new',
    })
    const memberSearchEmptyState = stateBlockHtml({
      compact: true,
      title: '没有匹配的成员',
      body: '调整搜索词，或清除搜索查看全部成员。',
      actionLabel: '清除搜索',
      action: 'member-clear-search',
    })

    const deptScopeLabel = deptLabel(state.deptFilter)
    const initialSearch = state.memberSearch.trim()

    host.innerHTML = `
      <section class="panel">
        <div class="panel-head table-panel-head">
          <div><h2>${esc(deptLabel(state.deptFilter))} · 成员</h2><span class="hint" id="member-count">${members.length} 人</span></div>
          <div class="panel-actions member-panel-actions">
            <label class="inline-field member-dept-field"><span>部门</span><select id="org-dept-filter">${deptSelectOptions(
              state.deptFilter,
            )}</select></label>
            <label class="inline-field member-search-field"><span>搜索</span><input id="member-search" type="search" placeholder="姓名 / 工号 / 部门 / 角色" value="${esc(
              state.memberSearch,
            )}" autocomplete="off" /></label>
            <div class="member-action-group">
              <button class="btn sm ghost" type="button" id="member-export">导出名单</button>
              <button class="btn sm ghost" type="button" id="member-bulk">批量授权</button>
              <button class="btn sm primary" type="button" id="member-new">＋ 新建成员</button>
            </div>
          </div>
        </div>
        <div class="table-summary" id="member-summary">
          <span class="summary-label">筛选</span>
          <span class="summary-chip"><span>部门</span><strong title="${esc(deptScopeLabel)}">${esc(deptScopeLabel)}</strong></span>
          <span class="summary-chip" id="member-search-chip"${initialSearch ? '' : ' hidden'}><span>搜索</span><strong id="member-search-value" title="${esc(initialSearch)}">${esc(initialSearch)}</strong></span>
          <button class="summary-reset" type="button" id="member-search-clear"${initialSearch ? '' : ' hidden'}>清除搜索</button>
        </div>
        <div class="table-scroll member-table-scroll" id="member-table-scroll">
          <table class="data member-table">
            <thead><tr><th>姓名</th><th>部门</th><th>角色</th><th>状态</th><th>操作</th></tr></thead>
            <tbody>${
              rows
                ? `${rows}<tr id="member-search-empty" hidden><td colspan="5">${memberSearchEmptyState}</td></tr>`
                : `<tr><td colspan="5">${memberEmptyState}</td></tr>`
            }</tbody>
          </table>
        </div>
        <div id="member-pager"></div>
      </section>
      <section class="panel" id="dept-policy">
        <div class="panel-head"><div><h2>部门权限概览</h2><span class="hint">${esc(deptLabel(state.deptFilter))}</span></div></div>
        <div class="mini-list">
          <div class="mini-row"><span>本部门角色分布</span><div>${roleChips || '<span class="muted">没有成员</span>'}</div></div>
          <div class="mini-row"><span>命中的知识库范围</span><div id="dept-acl" class="muted">加载中…</div></div>
        </div>
      </section>`

    api('/api/kb/collections')
      .then((kb) => {
        const box = host.querySelector('#dept-acl')
        if (!box) return
        const hit = (kb.collections || []).filter((c) =>
          (c.acl?.deptPaths || []).some((p) => p.startsWith(state.deptFilter)),
        )
        box.innerHTML = hit.length
          ? hit
              .map(
                (c) =>
                  `<div style="padding:4px 0">${esc(c.name)} <span class="desc mono">${esc(c.acl.mode)} · ${esc(
                    (c.acl.deptPaths || []).join(', '),
                  )}</span> <span class="chip accent">对该部门生效</span></div>`,
              )
              .join('')
          : '<span class="muted">这个部门没有被任何知识库的部门 ACL 命中</span>'
      })
      .catch((err) => {
        const box = host.querySelector('#dept-acl')
        if (box) box.textContent = `读取知识库失败：${err.message}`
      })

    const applyMemberSearch = () => {
      const query = state.memberSearch.trim().toLowerCase()
      const tokens = query.split(/\s+/).filter(Boolean)
      const dataRows = [...host.querySelectorAll('.member-table tbody tr[data-member-search]')]
      const matchedRows = []
      for (const row of dataRows) {
        const haystack = row.dataset.memberSearch || ''
        const matched = tokens.length === 0 || tokens.every((token) => haystack.includes(token))
        if (matched) matchedRows.push(row)
        else row.hidden = true
      }
      const totalMatched = matchedRows.length
      const pageSize = state.memberPageSize
      const totalPages = Math.max(1, Math.ceil(totalMatched / pageSize))
      state.memberPage = Math.min(Math.max(Number(state.memberPage) || 0, 0), totalPages - 1)
      const start = state.memberPage * pageSize
      const end = start + pageSize
      matchedRows.forEach((row, index) => {
        row.hidden = index < start || index >= end
      })
      const count = host.querySelector('#member-count')
      if (count) count.textContent = tokens.length ? `${totalMatched} / ${members.length} 人` : `${members.length} 人`
      const searchChip = host.querySelector('#member-search-chip')
      const searchValue = host.querySelector('#member-search-value')
      const searchClear = host.querySelector('#member-search-clear')
      if (searchChip && searchValue && searchClear) {
        searchChip.hidden = tokens.length === 0
        searchClear.hidden = tokens.length === 0
        searchValue.textContent = tokens.length ? state.memberSearch.trim() : ''
        searchValue.title = searchValue.textContent
      }
      const empty = host.querySelector('#member-search-empty')
      if (empty) empty.hidden = !tokens.length || totalMatched > 0
      const pager = host.querySelector('#member-pager')
      if (pager) {
        pager.innerHTML = totalMatched > 0 ? pagerHtml(totalMatched, state.memberPage, pageSize) : ''
        bindPager(pager, (next) => {
          state.memberPage = next
          applyMemberSearch()
          host.querySelector('#member-table-scroll')?.scrollTo({ top: 0 })
        })
      }
    }
    const searchInput = host.querySelector('#member-search')
    if (searchInput) {
      searchInput.addEventListener('input', () => {
        state.memberSearch = searchInput.value
        state.memberPage = 0
        applyMemberSearch()
      })
      applyMemberSearch()
    }
    host.querySelector('#member-search-clear')?.addEventListener('click', () => {
      state.memberSearch = ''
      state.memberPage = 0
      if (searchInput) searchInput.value = ''
      applyMemberSearch()
      searchInput?.focus()
    })

    const deptSelect = host.querySelector('#org-dept-filter')
    if (deptSelect) {
      deptSelect.addEventListener('change', () => {
        const option = deptSelect.selectedOptions[0]
        state.deptFilter = option?.dataset.path || null
        state.memberPage = 0
        loadMembers(host)
      })
    }
    host.querySelectorAll('[data-member-roles]').forEach((button) => {
      button.addEventListener('click', () => {
        const member = data.members.find((item) => item.id === button.dataset.memberRoles)
        if (member) openMemberRoles(member)
      })
    })
    host.querySelectorAll('[data-member-quota]').forEach((button) => {
      button.addEventListener('click', () => {
        const member = data.members.find((item) => item.id === button.dataset.memberQuota)
        if (member) openMemberQuota(member, host)
      })
    })
    host.querySelectorAll('[data-member-override]').forEach((button) => {
      button.addEventListener('click', () => {
        const member = data.members.find((item) => item.id === button.dataset.memberOverride)
        if (member) openOverrideModal(member)
      })
    })
    host.querySelectorAll('[data-member-password]').forEach((button) => {
      button.addEventListener('click', () => {
        const member = data.members.find((item) => item.id === button.dataset.memberPassword)
        if (member) openMemberPassword(member)
      })
    })
    host.querySelectorAll('[data-member-more]').forEach((button) => {
      button.addEventListener('click', (event) => {
        event.stopPropagation()
        const member = data.members.find((item) => item.id === button.dataset.memberMore)
        if (!member) return
        const rect = button.getBoundingClientRect()
        showMemberMenu(member, host, rect.right, rect.bottom + 4)
      })
    })
    host.querySelectorAll('[data-member-toggle]').forEach((button) => {
      button.addEventListener('click', async () => {
        const member = data.members.find((item) => item.id === button.dataset.memberToggle)
        if (member) await toggleMemberStatus(member, host)
      })
    })
    host.querySelectorAll('[data-member-delete]').forEach((button) => {
      button.addEventListener('click', async () => {
        const member = data.members.find((item) => item.id === button.dataset.memberDelete)
        if (member) await deleteMember(member, host)
      })
    })
    const newMember = host.querySelector('#member-new')
    if (newMember) newMember.addEventListener('click', () => openMemberCreate(state.deptFilter))
    host.querySelector('[data-state-action="member-new"]')?.addEventListener('click', () => newMember?.click())
    host.querySelector('[data-state-action="member-clear-search"]')?.addEventListener('click', () => {
      state.memberSearch = ''
      state.memberPage = 0
      if (searchInput) searchInput.value = ''
      applyMemberSearch()
      searchInput?.focus()
    })
    const bulk = host.querySelector('#member-bulk')
    if (bulk) bulk.addEventListener('click', () => openBulkGrant(members))
    const exportBtn = host.querySelector('#member-export')
    if (exportBtn) exportBtn.addEventListener('click', () => downloadConsoleFile('/api/console/members/export', '成员清单.csv'))
  } catch (err) {
    renderConsoleError(host, err, () => loadMembers(host))
  }
}

let memberMenu = null

function hideMemberMenu() {
  if (memberMenu) {
    memberMenu.remove()
    memberMenu = null
  }
}

function showMemberMenu(member, host, x, y) {
  hideMemberMenu()
  hideDeptMenu()
  hideKbMenu()
  if (!member) return
  const disabled = member.status === 'disabled'
  const el = document.createElement('div')
  el.className = 'ctx-menu member-menu'
  el.id = 'member-menu'
  el.innerHTML = `
    <div class="ctx-menu-head">${esc(member.name)} · 成员操作</div>
    <button type="button" data-member-act="edit">编辑资料</button>
    <button type="button" data-member-act="quota">存储配额</button>
    <button type="button" data-member-act="override">临时授权</button>
    <button type="button" data-member-act="password">重置密码</button>
    <button type="button" data-member-act="toggle" class="${disabled ? 'accent' : ''}">${disabled ? '启用成员' : '停用成员'}</button>
    <button type="button" data-member-act="delete" class="danger">删除成员</button>`
  document.body.appendChild(el)
  const width = 188
  const height = 274
  el.style.left = `${Math.min(x, window.innerWidth - width - 8)}px`
  el.style.top = `${Math.min(y, window.innerHeight - height - 8)}px`
  memberMenu = el
  el.addEventListener('click', (event) => {
    const action = event.target.closest('[data-member-act]')?.dataset.memberAct
    if (!action) return
    hideMemberMenu()
    if (action === 'edit') openMemberEdit(member)
    if (action === 'quota') openMemberQuota(member, host)
    if (action === 'override') openOverrideModal(member)
    if (action === 'password') openMemberPassword(member)
    if (action === 'toggle') toggleMemberStatus(member, host)
    if (action === 'delete') deleteMember(member, host)
  })
}

async function toggleMemberStatus(member, host) {
  const next = member.status === 'disabled' ? 'active' : 'disabled'
  if (next === 'disabled') {
    const ok = await confirmCard({
      title: '停用成员？',
      message: `停用「${member.name}」后，该成员的登录会话会立即失效。`,
      confirmText: '停用成员',
      tone: 'warning',
    })
    if (!ok) return
  }
  try {
    await apiSend('PATCH', `/api/console/members/${encodeURIComponent(member.id)}`, { status: next })
    loadMembers(host)
  } catch (err) {
    alert(err.message || '操作失败')
  }
}

async function deleteMember(member, host) {
  const ok = await confirmCard({
    title: '删除成员？',
    message: `删除「${member.name}」会做软删除（数据保留、可审计），登录会话立即失效。`,
    confirmText: '删除成员',
  })
  if (!ok) return
  try {
    await apiSend('DELETE', `/api/console/members/${encodeURIComponent(member.id)}`)
    loadMembers(host)
    loadTree()
  } catch (err) {
    alert(err.message || '删除失败')
  }
}

async function openMemberQuota(member, host) {  let data
  try {
    data = await api(`/api/console/workspace-quotas?userId=${encodeURIComponent(member.id)}`)
  } catch (err) {
    alert(err.message || '读取存储配额失败')
    return
  }
  const mb = 1024 * 1024
  const defaults = data.defaults || {}
  const policy = data.policy || null
  const effective = data.effective || {}
  const sourceLabel =
    effective.source === 'user' ? '单独配置' : effective.source === 'role' ? '角色配置' : '默认配置'
  const roleText = (effective.roleCodes || []).length ? `（${effective.roleCodes.join(' / ')}）` : ''
  const defaultLimitMb = Math.round((Number(defaults.limitBytes) || 0) / mb)
  const defaultFileMb = Math.round((Number(defaults.fileLimitBytes) || 0) / mb)
  const limitValue = policy ? String(Number(policy.limitBytes) / mb) : ''
  const fileValue = policy ? String(Number(policy.fileLimitBytes) / mb) : ''

  const overlay = modelModal(`
    <div class="modal-head"><h3>存储配额 · ${esc(member.name)}</h3><button class="modal-x" type="button">×</button></div>
    <div class="member-sum"><strong>${esc(member.deptName || '—')}</strong><span>${esc(member.title || '未设置职务')}</span></div>
    <div class="mini-list" style="margin-bottom:14px">
      <div class="mini-row"><span>当前生效</span><div><strong>${esc(formatStorageBytes(effective.limitBytes))}</strong> · 单文件 ${esc(
        formatStorageBytes(effective.fileLimitBytes),
      )}<span class="desc"> · ${esc(sourceLabel)}${esc(roleText)}</span></div></div>
    </div>
    <div class="modal-section-title">单独配置个人工作区 ${hintBadge('填写说明', '个人容量优先于角色配置；留空表示跟随角色 / 默认。保存后立即生效。容量和单文件上限要一起填；两项都留空等于恢复跟随角色 / 默认。')}</div>
    <div class="form-grid">
      <label><span>个人容量（MB）</span><input id="mq-limit" type="number" min="1" step="0.1" value="${esc(
        limitValue,
      )}" placeholder="默认 ${defaultLimitMb} MB" /></label>
      <label><span>单文件上限（MB）</span><input id="mq-file" type="number" min="1" step="0.1" value="${esc(
        fileValue,
      )}" placeholder="默认 ${defaultFileMb} MB" /></label>
    </div>
    <div class="modal-state" id="mq-state"></div>
    <div class="modal-actions">
      <button class="btn ghost" type="button" id="mq-reset">恢复默认</button>
      <button class="btn primary" type="button" id="mq-save">保存</button>
    </div>`)

  const close = () => overlay.remove()
  const stateEl = overlay.querySelector('#mq-state')
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#mq-reset').addEventListener('click', async () => {
    stateEl.className = 'modal-state muted'
    stateEl.textContent = '正在恢复…'
    try {
      await apiSend('DELETE', `/api/console/workspace-quotas/user/${encodeURIComponent(member.id)}`)
      close()
      loadMembers(host)
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '恢复失败'
    }
  })
  overlay.querySelector('#mq-save').addEventListener('click', async () => {
    const limitRaw = overlay.querySelector('#mq-limit').value.trim()
    const fileRaw = overlay.querySelector('#mq-file').value.trim()
    if (!limitRaw && !fileRaw) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '两项都为空时，请直接点「恢复默认」'
      return
    }
    if (!limitRaw || !fileRaw) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '容量和单文件上限要一起填'
      return
    }
    const limitMb = Number(limitRaw)
    const fileMb = Number(fileRaw)
    if (!Number.isFinite(limitMb) || !Number.isFinite(fileMb) || limitMb <= 0 || fileMb <= 0) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '请填写大于 0 的数字'
      return
    }
    if (fileMb > limitMb) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '单文件上限不能大于个人容量'
      return
    }
    stateEl.className = 'modal-state muted'
    stateEl.textContent = '正在保存…'
    try {
      await apiSend('PUT', '/api/console/workspace-quotas', {
        scopeType: 'user',
        scopeId: member.id,
        limitBytes: Math.round(limitMb * mb),
        fileLimitBytes: Math.round(fileMb * mb),
      })
      close()
      loadMembers(host)
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
}

function formatStorageBytes(bytes) {
  const value = Number(bytes)
  if (!Number.isFinite(value) || value <= 0) return '0 B'
  if (value >= 1024 * 1024 * 1024) return `${(value / 1024 / 1024 / 1024).toFixed(1)} GB`
  if (value >= 1024 * 1024) {
    const mb = value / 1024 / 1024
    return `${Number.isInteger(mb) ? mb : mb.toFixed(1)} MB`
  }
  if (value >= 1024) return `${(value / 1024).toFixed(1)} KB`
  return `${value} B`
}

async function openMemberRoles(member) {
  let roleData
  let accessData = null
  try {
    roleData = await api('/api/console/roles')
    if (state.access?.canConfigureAccess) {
      accessData = await api(`/api/console/member-console-permissions/${encodeURIComponent(member.id)}`)
    }
  } catch (err) {
    alert(err.message || '读取角色失败')
    return
  }
  const current = new Set((member.roles || []).map((role) => role.code))
  const canAssignMemberRoles = canPageAction('org', 'edit')
  const accessTree = accessData
    ? `
    <div class="modal-section-title">后台访问 ${hintBadge('页面权限', '每个页面只勾「可见」。页面可见即可使用该页全部功能，不再单独配置新增、编辑、删除或检查更新等动作。')}</div>
    <div class="muted role-console-summary">${
      (accessData.roleAllowedPages || []).length
        ? `角色已授予 ${(accessData.roleAllowedPages || []).length} 个页面；这里只配置个人额外权限，两者叠加生效。`
        : '这里配置的是个人额外权限；角色带来的后台权限请在角色详情「后台权限」中配置。'
    }</div>
    ${consolePermissionTreeHtml(accessData.catalog, accessData.pages || [], {
      rowAttr: 'data-page-row',
      viewAttr: 'data-page-view',
      domainAllAttr: 'data-page-domain-all',
    })}`
    : `
    <div class="modal-section-title">后台访问</div>
    <div class="muted role-console-summary">当前账号没有「成员管理」页面可见权限。成员管理页可见后才能配置成员后台访问；请联系平台管理员开通。</div>`
  const overlay = modelModal(`
    <div class="modal-head"><h3>配置成员权限 · ${esc(member.name)}</h3><button class="modal-x" type="button">×</button></div>
    <div class="member-access-shell">
      <aside class="member-access-side" aria-label="成员角色">
        <div class="member-sum"><strong>${esc(member.deptName)}</strong><span>${esc(member.title || '未设置职务')}</span></div>
        <div class="modal-section-title">授予角色 ${hintBadge('角色说明', '一个成员可以同时拥有多个角色；保存后立即生效。')}</div>
        ${
          canAssignMemberRoles
            ? ''
            : '<div class="muted role-console-summary">当前账号没有「成员管理」页面可见权限，角色分配只读；右侧「后台访问」权限仍可单独保存。</div>'
        }
        <div class="scope-groups">
          <div class="scope-group">
            ${roleData.roles
              .map(
                (role) => `<label class="scope-check"><input type="checkbox" data-assign="${esc(role.code)}"${
                  current.has(role.code) ? ' checked' : ''
                }${canAssignMemberRoles ? '' : ' disabled'} /> ${esc(ROLE_LABEL[role.code] || role.name)}
                  <span class="muted">（${esc(DATA_SCOPE_LABEL[role.dataScope] || role.dataScope)}）</span></label>`,
              )
              .join('')}
          </div>
        </div>
        <div class="member-access-tip">
          <strong>权限叠加</strong>
          <p>角色决定基础后台页面，个人权限只做额外补充；保存后立即生效。</p>
        </div>
      </aside>
      <main class="member-access-main" aria-label="后台访问权限">
        ${accessTree}
      </main>
    </div>
    <div class="modal-state" id="a-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="a-save">保存</button>
      <button class="btn ghost" type="button" id="a-cancel">取消</button>
    </div>`)
  if (accessData) {
    setupPermissionDomainSelectAll(overlay, {
      rowSelector: '[data-page-row]',
      viewSelector: 'input[data-page-view]',
      allSelector: 'input[data-page-domain-all]',
    })
  }
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#a-cancel').addEventListener('click', close)
  overlay.querySelector('#a-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#a-state')
    const roles = [...overlay.querySelectorAll('[data-assign]:checked')].map((el) => el.dataset.assign)
    if (canAssignMemberRoles && roles.length === 0) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '至少保留一个角色'
      return
    }
    if (!accessData && !canAssignMemberRoles) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '当前账号没有「成员管理」页面可见权限，无法保存'
      return
    }
    stateEl.textContent = '保存中…'
    let pageSaved = false
    try {
      if (accessData) {
        const pages = [...overlay.querySelectorAll('[data-page-row]')]
          .map((row) => ({
            page: row.dataset.pageRow,
            canView: row.querySelector('[data-page-view]')?.checked === true,
          }))
          .filter((item) => item.canView)
        await apiSend('PUT', `/api/console/member-console-permissions/${encodeURIComponent(member.id)}`, { pages })
        pageSaved = true
      }
      if (canAssignMemberRoles) {
        await apiPost(`/api/console/members/${encodeURIComponent(member.id)}/roles`, { roles })
      }
      close()
      loadMembers($('#org-members'))
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = pageSaved
        ? `后台访问权限已保存，但角色保存失败：${err.message || '保存失败'}`
        : (err.message || '保存失败')
      if (pageSaved) loadMembers($('#org-members'))
    }
  })
}

function deptNodes(node, list = []) {
  if (!node) return list
  list.push(node)
  for (const child of node.children || []) deptNodes(child, list)
  return list
}

function currentCompanyRoot() {
  return rootNodes.find((node) => node.companyId === state.company) ?? rootNodes[0] ?? null
}

function isRootDept(node) {
  if (!node) return false
  if (Number(node.depth ?? 0) === 0) return true
  return /^\/[^/]+\/?$/.test(String(node.path || ''))
}

function deptSelectOptions(selectedPath, root = currentCompanyRoot()) {
  return deptNodes(root)
    .map(
      (node) =>
        `<option value="${esc(node.id)}" data-path="${esc(node.path)}"${node.path === selectedPath ? ' selected' : ''}>${'　'.repeat(Math.max(0, Number(node.depth || 0)))}${esc(node.name)}</option>`,
    )
    .join('')
}

async function roleCheckboxes(current = []) {
  const roleData = await api('/api/console/roles')
  const set = new Set(current)
  return roleData.roles
    .map(
      (role) =>
        `<label class="scope-check"><input type="checkbox" data-role-code="${esc(role.code)}"${set.has(role.code) ? ' checked' : ''} /> ${esc(ROLE_LABEL[role.code] || role.name)}</label>`,
    )
    .join('')
}

function openDeptCreate(parentPath) {
  const root = currentCompanyRoot()
  const parent = deptNodes(root).find((node) => node.path === parentPath) || root
  const overlay = modelModal(`
    <div class="modal-head"><h3>新建部门</h3><button class="modal-x" type="button">×</button></div>
    <div class="form-grid">
      <label class="field"><span>部门名称</span><input id="d-name" placeholder="例如 财务部" /></label>
      <label class="field"><span>上级部门</span><select id="d-parent">${deptSelectOptions(parent.path)}</select></label>
    </div>
    <div class="modal-state" id="d-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="d-save">创建</button>
      <button class="btn ghost" type="button" id="d-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#d-cancel').addEventListener('click', close)
  overlay.querySelector('#d-save').addEventListener('click', async () => {
    const name = overlay.querySelector('#d-name').value.trim()
    const parentId = overlay.querySelector('#d-parent').value
    const stateEl = overlay.querySelector('#d-state')
    if (!name) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '部门名称不能为空'
      return
    }
    stateEl.textContent = '创建中…'
    try {
      await apiPost('/api/console/departments', { name, parentId })
      close()
      state.deptFilter = parent.path
      await loadTree()
      refreshOrgAfterTreeChange()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '创建失败'
    }
  })
}

/** 组织页的部门编辑 / 删除入口已收进树节点的右键菜单 */

function orgSelectedDept() {
  const root = currentCompanyRoot()
  return deptNodes(root).find((node) => node.path === state.deptFilter) ?? root
}

async function openDeptEdit(node, { focusManager = false } = {}) {
  if (!node) return
  let members = []
  try {
    const data = await api('/api/org/members')
    members = (data.members || []).filter((member) => String(member.deptPath || '').startsWith(node.path))
  } catch {
    members = []
  }
  const root = currentCompanyRoot()
  const isRoot = isRootDept(node)
  const segments = node.path.split('/').filter(Boolean)
  const parentPath = segments.length > 1 ? `/${segments.slice(0, -1).join('/')}/` : ''
  // 不能把部门挂到自己的下级：候选上级要排除自身及整棵子树
  const parentOptions = isRoot
    ? '<option value="">（根部门不能移动）</option>'
    : deptNodes(root)
        .filter((candidate) => !candidate.path.startsWith(node.path))
        .map(
          (candidate) =>
            `<option value="${esc(candidate.id)}"${candidate.path === parentPath ? ' selected' : ''}>${'　'.repeat(
              Math.max(0, Number(candidate.depth || 0)),
            )}${esc(candidate.name)}</option>`,
        )
        .join('')
  const managerCandidates = [
    { id: '', name: '不设负责人', title: '' },
    ...members.map((member) => ({ id: String(member.id), name: member.name, title: member.title || '' })),
  ]
  if (node.managerUserId && !managerCandidates.some((candidate) => candidate.id === String(node.managerUserId))) {
    managerCandidates.push({ id: String(node.managerUserId), name: node.managerName || '当前负责人', title: '' })
  }
  const selectedManager =
    managerCandidates.find((candidate) => candidate.id === String(node.managerUserId || '')) ?? managerCandidates[0]
  const overlay = modelModal(`
    <div class="modal-head"><h3>编辑部门</h3><button class="modal-x" type="button">×</button></div>
    <div class="form-grid">
      <label class="field"><span>部门名称</span><input id="de-name" value="${esc(node.name)}" /></label>
      <label class="field"><span>上级部门</span><select id="de-parent"${isRoot ? ' disabled' : ''}>${parentOptions}</select></label>
      <label class="field dept-manager-field"><span>部门负责人 ${hintBadge('负责人说明', '负责人从上一次同步（或手工建）的成员里选；移动部门会同时更新下级部门与成员路径。')}</span>
        <div class="search-select" data-manager-select>
          <input id="de-manager-search" class="search-select-input" type="text" role="combobox" aria-expanded="false" aria-controls="de-manager-list" aria-autocomplete="list" autocomplete="off" placeholder="搜索姓名或岗位" value="${esc(selectedManager.name)}" />
          <input type="hidden" id="de-manager" value="${esc(selectedManager.id)}" />
          <span class="search-select-caret" aria-hidden="true"></span>
          <div class="search-select-list" id="de-manager-list" role="listbox" hidden>
            ${managerCandidates
              .map(
                (candidate, index) =>
                  `<button type="button" class="search-select-option${candidate.id === selectedManager.id ? ' is-selected' : ''}" id="de-manager-opt-${index}" role="option" data-value="${esc(candidate.id)}" aria-selected="${candidate.id === selectedManager.id}"><span>${esc(candidate.name)}</span>${candidate.title ? `<small>${esc(candidate.title)}</small>` : ''}</button>`,
              )
              .join('')}
            <div class="search-select-empty" hidden>没有匹配的成员</div>
          </div>
        </div>
      </label>
    </div>
    <div class="modal-state" id="de-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="de-save">保存</button>
      <button class="btn ghost" type="button" id="de-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#de-cancel').addEventListener('click', close)

  const managerSelect = overlay.querySelector('[data-manager-select]')
  const managerSearch = overlay.querySelector('#de-manager-search')
  const managerList = overlay.querySelector('#de-manager-list')
  const managerValue = overlay.querySelector('#de-manager')
  const managerOptions = [...managerList.querySelectorAll('.search-select-option')]
  const managerEmpty = managerList.querySelector('.search-select-empty')
  let managerActive = -1
  const managerLabel = () =>
    managerOptions.find((option) => option.dataset.value === managerValue.value)?.querySelector('span')?.textContent ||
    '不设负责人'
  const paintManagerActive = () => {
    managerOptions.forEach((option, index) => option.classList.toggle('is-active', index === managerActive))
    if (managerActive >= 0) managerOptions[managerActive]?.scrollIntoView({ block: 'nearest' })
  }
  const filterManagerOptions = () => {
    const query = managerSearch.value.trim().toLowerCase()
    let visible = 0
    managerOptions.forEach((option) => {
      const matched = !query || option.textContent.toLowerCase().includes(query)
      option.hidden = !matched
      if (matched) visible += 1
    })
    managerEmpty.hidden = visible > 0
    managerActive =
      managerOptions.findIndex((option) => !option.hidden && option.classList.contains('is-selected'))
    if (managerActive < 0) managerActive = managerOptions.findIndex((option) => !option.hidden)
    paintManagerActive()
  }
  const openManager = (showAll = false) => {
    managerList.hidden = false
    managerSearch.setAttribute('aria-expanded', 'true')
    if (showAll) {
      managerOptions.forEach((option) => {
        option.hidden = false
      })
      managerEmpty.hidden = true
      managerActive = managerOptions.findIndex((option) => option.classList.contains('is-selected'))
      if (managerActive < 0) managerActive = 0
      paintManagerActive()
      return
    }
    filterManagerOptions()
  }
  const closeManager = (restore = true) => {
    managerList.hidden = true
    managerSearch.setAttribute('aria-expanded', 'false')
    if (restore) managerSearch.value = managerLabel()
    managerActive = -1
    paintManagerActive()
  }
  const chooseManager = (option) => {
    managerValue.value = option.dataset.value
    managerOptions.forEach((candidate) => {
      const selected = candidate === option
      candidate.classList.toggle('is-selected', selected)
      candidate.setAttribute('aria-selected', selected ? 'true' : 'false')
    })
    managerSearch.value = option.querySelector('span')?.textContent || ''
    closeManager(false)
    managerSearch.focus()
  }
  const moveManagerActive = (step) => {
    if (managerList.hidden) openManager(true)
    const visibleOptions = managerOptions.filter((option) => !option.hidden)
    if (!visibleOptions.length) return
    const currentVisible = visibleOptions.findIndex((option) => option === managerOptions[managerActive])
    const nextVisible = currentVisible < 0 ? 0 : (currentVisible + step + visibleOptions.length) % visibleOptions.length
    managerActive = managerOptions.indexOf(visibleOptions[nextVisible])
    paintManagerActive()
  }
  managerSearch.addEventListener('focus', () => {
    openManager(true)
    managerSearch.select()
  })
  managerSearch.addEventListener('click', () => {
    openManager(true)
    managerSearch.select()
  })
  managerSearch.addEventListener('input', () => openManager())
  managerList.addEventListener('pointerdown', (event) => event.preventDefault())
  managerOptions.forEach((option) => option.addEventListener('click', () => chooseManager(option)))
  managerSearch.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      moveManagerActive(event.key === 'ArrowDown' ? 1 : -1)
      return
    }
    if (event.key === 'Enter' && !managerList.hidden) {
      event.preventDefault()
      const option = managerOptions[managerActive]
      if (option && !option.hidden) chooseManager(option)
      return
    }
    if (event.key === 'Escape') {
      event.preventDefault()
      closeManager()
    }
  })
  managerSearch.addEventListener('blur', () => {
    setTimeout(() => {
      if (!managerSelect.contains(document.activeElement)) closeManager()
    }, 0)
  })
  overlay.addEventListener('pointerdown', (event) => {
    if (!managerSelect.contains(event.target)) closeManager()
  })
  if (focusManager) {
    managerSearch.focus()
    openManager(true)
  }
  overlay.querySelector('#de-save').addEventListener('click', async () => {
    const name = overlay.querySelector('#de-name').value.trim()
    const parentId = overlay.querySelector('#de-parent').value
    const managerSelect = overlay.querySelector('#de-manager')
    const managerUserId = managerSelect.value || null
    const stateEl = overlay.querySelector('#de-state')
    if (!name) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '部门名称不能为空'
      return
    }
    stateEl.className = 'modal-state'
    stateEl.textContent = '保存中…'
    try {
      await apiSend('PATCH', `/api/console/departments/${encodeURIComponent(node.id)}`, {
        name,
        ...(parentId ? { parentId } : {}),
        // 服务端把 undefined 当"清空负责人"，所以这里永远显式传值
        managerUserId,
      })
      close()
      await loadTree()
      enterDeptPathAfterMove(node, parentId)
      refreshOrgAfterTreeChange()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
}

/** 部门改名/移动后，路径变了；把选中项切到新路径，避免右栏还停在旧路径 */
function enterDeptPathAfterMove(node, parentId) {
  const root = currentCompanyRoot()
  const nodes = deptNodes(root)
  const moved = nodes.find((item) => item.id === node.id)
  if (moved) {
    state.deptFilter = moved.path
    repaintTree()
    return
  }
  const parent = nodes.find((item) => item.id === parentId)
  if (parent) {
    state.deptFilter = parent.path
    repaintTree()
  }
}

async function deleteDept(node) {
  if (!node) return
  const ok = await confirmCard({
    title: '删除部门？',
    message: `「${node.name}」下有成员或子部门时服务端会拒绝，需要先移走。`,
    confirmText: '删除部门',
  })
  if (!ok) return
  try {
    await apiSend('DELETE', `/api/console/departments/${encodeURIComponent(node.id)}`)
    const segments = node.path.split('/').filter(Boolean)
    const parentPath = segments.length > 1 ? `/${segments.slice(0, -1).join('/')}/` : node.path
    state.deptFilter = parentPath
    await loadTree()
    repaintTree()
    refreshOrgAfterTreeChange()
  } catch (err) {
    alert(err.message || '删除失败')
  }
}

