async function loadOverview() {
  if (state.access?.kind === 'member') return loadOverviewMember()
  const view = $('#view')
  const me = state.me
  const [health, org, kb, roles, providers, models, channels, plugins] = await Promise.all([
    api('/api/health').catch(() => null),
    api('/api/org/tree').catch(() => null),
    api('/api/kb/collections').catch(() => null),
    api('/api/console/roles').catch(() => null),
    api('/api/console/providers').catch(() => null),
    api('/api/console/models').catch(() => null),
    api('/api/console/channels').catch(() => null),
    api('/api/console/plugins').catch(() => null),
  ])

  const deptCount = org?.total ?? 0
  const memberCount = Number(org?.root?.subtreeMemberCount ?? org?.root?.memberCount ?? 0)
  const kbCount = kb?.collections?.length ?? 0
  const providerCount = providers?.providers?.length ?? 0
  const modelCount = models?.models?.length ?? 0
  const channelList = channels?.channels ?? []
  const channelMeta = channelMetaOf(channelList)
  const boundChannels = channelMeta.bound
  const channelTotal = channelMeta.total
  /* 填了凭证但没完成绑定的渠道：鼠标停在进度上能看到是谁，避免"待绑定"数对不上 */
  const channelPendingLabels = channelList
    .filter((item) => channelConfigured(item) && !channelBound(item))
    .map((item) => item.label || item.provider)
  const pluginCount = plugins?.stats?.installed ?? 0
  const roleCount = roles?.roles?.length ?? 0

  const tasks = [
    { key: 'org', title: '组织架构', meta: `${deptCount} 个部门 · ${memberCount} 名成员`, done: deptCount > 0, action: '管理组织' },
    { key: 'roles', title: '成员与角色权限', meta: `${roleCount} 个角色 · 在组织页给成员授权`, done: roleCount > 0, action: '检查权限' },
    { key: 'kb', title: '知识库', meta: `${kbCount} 个知识库 · 配置可见范围与文档`, done: kbCount > 0, action: '管理知识库' },
    { key: 'models', title: '模型接入', meta: `${providerCount} 个供应商 · ${modelCount} 个模型`, done: modelCount > 0, action: '接入模型' },
    { key: 'channels', title: '渠道接入', meta: channelMeta.text, hint: channelPendingLabels.length > 0 ? `${channelPendingLabels.join('、')} 已填凭证，但还没完成绑定` : '', done: boundChannels > 0, action: '配置渠道' },
    { key: 'extra', title: '插件', meta: `${pluginCount} 个已安装`, done: pluginCount > 0, action: '插件管理' },
  ]

  const orderedTasks = [...tasks].sort((a, b) => Number(a.done) - Number(b.done))
  const quickLinks = [
    { key: 'org', title: '组织与成员', meta: `${memberCount} 名成员` },
    { key: 'models', title: '模型接入', meta: `${modelCount} 个模型` },
    { key: 'kb', title: '知识库与 RAG', meta: `${kbCount} 个库` },
    { key: 'channels', title: '渠道绑定', meta: channelMeta.text },
  ]

  view.innerHTML = `
    <div class="stats overview-stats">
      <div class="stat"><div class="stat-label">服务状态</div><div class="stat-value">${health ? '运行中' : '异常'}<span class="stat-unit">${health ? `v${esc(health.version)}` : ''}</span></div></div>
      <div class="stat"><div class="stat-label">组织规模</div><div class="stat-value"><span data-motion="count" data-count-to="${memberCount}" data-count-duration="1100">${memberCount}</span><span class="stat-unit">成员 · ${deptCount} 部门</span></div></div>
      <div class="stat"><div class="stat-label">知识与模型</div><div class="stat-value"><span data-motion="count" data-count-to="${kbCount}" data-count-duration="1100">${kbCount}</span><span class="stat-unit">库 · ${modelCount} 模型</span></div></div>
      <div class="stat"><div class="stat-label">接入完成度</div><div class="stat-value"><span data-ov="channels-num">${boundChannels}</span><span class="stat-unit" data-ov="channels-unit">/ ${channelTotal} 渠道已绑定 · ${pluginCount} 插件</span></div></div>
    </div>

    <div class="overview-grid">
      <section class="panel overview-tasks">
        <div class="panel-head">
          <div><h2>配置进度</h2>${hintBadge('进度说明', '先处理未完成的项，已完成的会保持安静。')}</div>
          <span class="pill ${tasks.filter((task) => task.done).length === tasks.length ? 'ok' : 'warn'}">${
            tasks.filter((task) => task.done).length
          } / ${tasks.length} 已完成</span>
        </div>
        <div class="setup-list">
          ${orderedTasks
            .map(
              (task) => `<div class="setup-row${task.done ? ' is-done' : ''}">
                <span class="setup-state ${task.done ? 'done' : ''}">${task.done ? '已配置' : '待配置'}</span>
                <div class="setup-main"><strong>${esc(task.title)}</strong><span data-ov="${esc(task.key)}-meta"${task.hint ? ` title="${esc(task.hint)}"` : ''}>${esc(task.meta)}</span></div>
                <button class="btn sm${task.done ? '' : ' primary'}" type="button" data-go="${task.key}">${esc(task.action)}</button>
              </div>`,
            )
            .join('')}
        </div>
      </section>

      <aside class="overview-side">
        <section class="panel">
          <div class="panel-head">
            <div><h2>快捷入口</h2>${hintBadge('入口说明', '直接进入最常改的四块配置：组织与成员、模型、知识库、渠道。')}</div>
          </div>
          <div class="quick-grid">
            ${quickLinks
              .map(
                (item) => `<button class="quick-link" type="button" data-motion="lift" data-go="${item.key}">
                  <span>${esc(item.title)}</span>
                  <small data-ov="${esc(item.key)}-link">${esc(item.meta)}</small>
                  <i aria-hidden="true">→</i>
                </button>`,
              )
              .join('')}
          </div>
        </section>

        <section class="panel">
          <div class="panel-head"><div><h2>运行信息</h2>${hintBadge('范围说明', '展示当前服务版本与这个控制台的管理范围；数据范围固定为全公司。')}</div></div>
          <div class="kv-grid">
            <div><span>公司</span><strong>${esc(me?.company?.name ?? '—')}</strong></div>
            <div><span>公司 ID</span><strong class="mono">${esc(me?.company?.id ?? '—')}</strong></div>
            <div><span>控制台账号</span><strong>服务器超级管理员</strong></div>
            <div><span>数据范围</span><strong>全公司</strong></div>
            <div><span>健康检查</span><strong>${health ? `正常 · v${esc(health.version)}` : '不可用'}</strong></div>
            <div><span>已知能力项</span><strong>${me ? me.capabilities.length : 0} 项</strong></div>
          </div>
        </section>
      </aside>
    </div>`

  setSide('', true)
  setPageActions('')
  for (const button of document.querySelectorAll('[data-go]')) {
    button.addEventListener('click', () => navigate(button.dataset.go))
  }
}

/* ---------------- 权限矩阵（核对配置，不是员工查看） ---------------- */

/* ---------------- 角色与权限 ---------------- */

function companyMeta(id = state.company) {
  return state.companies.find((company) => company.id === id) ?? null
}

function switchCompany(companyId) {
  state.company = companyId
  state.selectedRole = null
  state.deptFilter = null
  const url = new URL(location.href)
  url.searchParams.set('company', companyId)
  history.replaceState(null, '', url.toString())
  renderCompanyPicker()
}

function openRoleCreateModal() {
  const overlay = modelModal(`
    <div class="modal-head"><h3>新建自定义角色</h3><button class="modal-x" type="button">×</button></div>
    <div class="field-stack">
      <label class="field"><span>角色名称</span><input id="nr-name" placeholder="例如 财务审核员" /></label>
      <label class="field"><span>角色标识</span><input id="nr-code" class="mono" placeholder="finance_reviewer（小写字母、数字、下划线）" /></label>
      <label class="field"><span>数据范围</span><select id="nr-scope">
        <option value="self">仅本人</option>
        <option value="dept" selected>本部门及下级</option>
        <option value="company">全公司</option>
      </select></label>
      ${hintNote('创建说明', '创建后立即进入权限编辑，勾选这个角色能做什么；成员授权在组织架构页完成。')}
    </div>
    <div class="modal-state" id="nr-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="nr-save">创建角色</button>
      <button class="btn ghost" type="button" id="nr-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#nr-cancel').addEventListener('click', close)
  overlay.querySelector('#nr-save').addEventListener('click', async () => {
    const name = overlay.querySelector('#nr-name').value.trim()
    const code = overlay.querySelector('#nr-code').value.trim().toLowerCase()
    const dataScope = overlay.querySelector('#nr-scope').value
    const msg = overlay.querySelector('#nr-state')
    if (!name || !code) {
      msg.textContent = '角色名称和标识都要填'
      msg.className = 'modal-state bad'
      return
    }
    try {
      const result = await apiPost('/api/console/roles', { code, name, dataScope, scopes: [] })
      close()
      state.selectedRole = result.code
      loadRoles()
    } catch (err) {
      msg.textContent = err.message || '创建失败'
      msg.className = 'modal-state bad'
    }
  })
}

async function deleteRoleCascade(role, messageHost) {
  if (!role) return
  const ok = await confirmCard({
    title: '删除角色？',
    message: `删除「${role.name}」后，该角色下所有成员的绑定会自动解除，操作不可撤销。`,
    detail: '删除后无法恢复，请确认该角色已不再需要。',
    confirmText: '删除角色',
  })
  if (!ok) return
  if (messageHost) messageHost.textContent = '删除中…'
  try {
    const result = await apiSend('DELETE', `/api/console/roles/${encodeURIComponent(role.code)}`)
    state.selectedRole = null
    await loadRoles()
    if (result?.unboundMembers) {
      // 让操作者知道这次删除实际解除了多少条授权
      setTimeout(() => {
        const host = $('#role-member-msg') || $('#role-msg')
        if (host) host.textContent = `已删除角色，解除 ${result.unboundMembers} 个成员绑定`
      }, 0)
    }
  } catch (err) {
    if (messageHost) messageHost.textContent = err.message || '删除失败'
    else window.alert(err.message || '删除失败')
  }
}

function setRoleMemberMessage(text) {
  const host = $('#role-member-msg')
  if (host) host.textContent = text
}

async function removeRoleMember(role, member, currentIds, messageHost, trigger) {
  const runRemove = async () => {
    if (messageHost) messageHost.textContent = '移除中…'
    const userIds = [...currentIds].filter((id) => id !== member.id)
    const result = await apiPost(`/api/console/roles/${encodeURIComponent(role.code)}/members`, { userIds })
    await loadRoles()
    setRoleMemberMessage(result.removed ? '已移除 1 人' : '没有变更')
    return result
  }

  if (window.EABOverlay?.popconfirm && trigger) {
    return window.EABOverlay.popconfirm(trigger, {
      title: '移除成员？',
      message: `将「${member.name}」从角色「${role.name}」中移除。`,
      detail: '该成员的其他角色不受影响；移除后仍可在角色成员页重新添加。',
      confirmText: '移除',
      tone: 'warning',
      loadingText: '移除中…',
      failureMessage: '移除失败，请重试',
      onConfirm: runRemove,
    })
  }

  const ok = await confirmCard({
    title: '移除成员？',
    message: `将「${member.name}」从角色「${role.name}」中移除。`,
    detail: '该成员的其他角色不受影响；移除后仍可在角色成员页重新添加。',
    confirmText: '移除成员',
    tone: 'warning',
  })
  if (!ok) return
  try {
    await runRemove()
  } catch (err) {
    if (messageHost) messageHost.textContent = err.message || '移除失败'
    else window.alert(err.message || '移除失败')
  }
}

async function removeRoleMembers(role, members, currentIds, messageHost) {
  if (!members.length) return false
  const names = members.map((member) => member.name).filter(Boolean)
  const preview = names.slice(0, 5).join('、') + (names.length > 5 ? ` 等 ${names.length} 人` : '')
  const ok = await confirmCard({
    title: `移除 ${members.length} 名成员？`,
    message: `将从角色「${role.name}」中移除：${preview}`,
    detail: '这些成员的其他角色不受影响；移除后仍可在角色成员页重新添加。',
    confirmText: '移除选中成员',
    tone: 'warning',
  })
  if (!ok) return false
  if (messageHost) messageHost.textContent = '移除中…'
  const selectedIds = new Set(members.map((member) => member.id))
  const userIds = [...currentIds].filter((id) => !selectedIds.has(id))
  try {
    const result = await apiPost(`/api/console/roles/${encodeURIComponent(role.code)}/members`, { userIds })
    await loadRoles()
    setRoleMemberMessage(result.removed ? `已移除 ${result.removed} 人` : '没有变更')
    return true
  } catch (err) {
    if (messageHost) messageHost.textContent = err.message || '移除失败'
    else window.alert(err.message || '移除失败')
    return false
  }
}

function memberPickerUnboundCount(node, membersByPath, boundIds) {
  const direct = (membersByPath.get(node.path) || []).filter((member) => !boundIds.has(member.id)).length
  return (node.children || []).reduce(
    (total, child) => total + memberPickerUnboundCount(child, membersByPath, boundIds),
    direct,
  )
}

function renderMemberPickerDept(node, membersByPath, boundIds) {
  const members = membersByPath.get(node.path) || []
  const children = node.children || []
  if (!members.length && !children.length) return ''
  const unboundCount = memberPickerUnboundCount(node, membersByPath, boundIds)
  const rows = members
    .map((member) => {
      const bound = boundIds.has(member.id)
      return `<label class="member-picker-member${bound ? ' is-bound' : ''}">
        <input type="checkbox" data-picker-member="${esc(member.id)}"${bound ? ' checked disabled' : ''} />
        <span class="member-picker-avatar">${esc(String(member.name || '?').slice(0, 1))}</span>
        <span class="member-picker-main">
          <strong>${esc(member.name)}</strong>
          <small>${esc(member.title || '成员')}</small>
        </span>
        ${bound ? '<span class="member-picker-tag">已在角色</span>' : ''}
      </label>`
    })
    .join('')
  return `<div class="member-picker-dept" data-picker-dept="${esc(node.path)}">
    <div class="member-picker-dept-head">
      <label>
        <input type="checkbox" data-picker-dept-check="${esc(node.path)}"${unboundCount ? '' : ' disabled'} />
        <span class="member-picker-dept-name">${esc(node.name)}</span>
      </label>
      <span class="member-picker-dept-meta">${
        unboundCount ? `可添加 ${unboundCount} 人` : '已全部绑定'
      }</span>
    </div>
    ${rows ? `<div class="member-picker-members">${rows}</div>` : ''}
    ${children.map((child) => renderMemberPickerDept(child, membersByPath, boundIds)).join('')}
  </div>`
}

async function openRoleMemberPicker(role, allMembers, boundIds) {
  let treeRoot
  try {
    treeRoot = (await api('/api/org/tree')).root
  } catch (err) {
    window.alert(err.message || '部门组织架构加载失败')
    return
  }
  const membersByPath = new Map()
  for (const member of allMembers) {
    const path = member.deptPath || '/c1/'
    if (!membersByPath.has(path)) membersByPath.set(path, [])
    membersByPath.get(path).push(member)
  }
  const overlay = modelModal(`
    <div class="modal-head">
      <div>
        <h3>添加成员 · ${esc(role.name)}</h3>
        ${hintBadge('多选说明', '按部门组织架构多选；部门行可全选该部门及下级成员。')}
      </div>
      <button class="modal-x" type="button">×</button>
    </div>
    <div class="member-picker-body" id="member-picker-body">
      ${renderMemberPickerDept(treeRoot, membersByPath, boundIds) || '<div class="empty">当前公司还没有成员</div>'}
    </div>
    <div class="modal-state" id="member-picker-state"></div>
    <div class="modal-actions member-picker-actions">
      <span class="member-picker-count" id="member-picker-count">已选 0 人</span>
      <button class="btn ghost" type="button" id="member-picker-cancel">取消</button>
      <button class="btn primary" type="button" id="member-picker-add" disabled>添加成员</button>
    </div>
  `)
  overlay.querySelector('.modal').classList.add('member-picker-modal')
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x')?.addEventListener('click', close)
  overlay.querySelector('#member-picker-cancel')?.addEventListener('click', close)

  const addButton = overlay.querySelector('#member-picker-add')
  const countLabel = overlay.querySelector('#member-picker-count')
  const stateLabel = overlay.querySelector('#member-picker-state')
  const deptChecks = [...overlay.querySelectorAll('[data-picker-dept-check]')]
  const memberChecks = [...overlay.querySelectorAll('[data-picker-member]:not(:disabled)')]

  const selectedIds = () => memberChecks.filter((input) => input.checked).map((input) => input.dataset.pickerMember)
  const syncDeptChecks = () => {
    for (const check of deptChecks) {
      const group = check.closest('.member-picker-dept')
      const members = [...group.querySelectorAll('[data-picker-member]:not(:disabled)')]
      if (!members.length) {
        check.checked = false
        check.indeterminate = false
        continue
      }
      const selected = members.filter((input) => input.checked).length
      check.checked = selected === members.length
      check.indeterminate = selected > 0 && selected < members.length
    }
  }
  const updateFooter = () => {
    const count = selectedIds().length
    if (countLabel) countLabel.textContent = `已选 ${count} 人`
    if (addButton) {
      addButton.disabled = count === 0
      addButton.textContent = count ? `添加 ${count} 人` : '添加成员'
    }
  }
  for (const check of deptChecks) {
    check.addEventListener('change', () => {
      const group = check.closest('.member-picker-dept')
      group.querySelectorAll('[data-picker-member]:not(:disabled)').forEach((input) => {
        input.checked = check.checked
      })
      syncDeptChecks()
      updateFooter()
    })
  }
  for (const input of memberChecks) {
    input.addEventListener('change', () => {
      syncDeptChecks()
      updateFooter()
    })
  }
  syncDeptChecks()
  updateFooter()

  addButton?.addEventListener('click', async () => {
    const ids = selectedIds()
    if (!ids.length) return
    addButton.disabled = true
    addButton.textContent = '添加中…'
    if (stateLabel) stateLabel.textContent = ''
    try {
      const userIds = [...new Set([...boundIds, ...ids])]
      const result = await apiPost(`/api/console/roles/${encodeURIComponent(role.code)}/members`, { userIds })
      close()
      await loadRoles()
      setRoleMemberMessage(`已添加 ${result.added} 人`)
    } catch (err) {
      if (stateLabel) stateLabel.textContent = err.message || '添加失败'
      addButton.disabled = false
      addButton.textContent = `添加 ${ids.length} 人`
    }
  })
}

function consolePermissionTreeHtml(catalog, pages, options = {}) {
  const rowAttr = options.rowAttr || 'data-role-page-row'
  const viewAttr = options.viewAttr || 'data-role-page-view'
  const domainAllAttr = options.domainAllAttr || 'data-perm-domain-all'
  const permissionMap = new Map((pages || []).map((item) => [item.page, item]))
  const pageMetaMap = new Map((catalog?.pages || []).map((item) => [item.page, item]))
  const actionsHtml = (perm, hideView = false) => `
    <span class="perm-page-actions">
      ${hideView ? '' : `<label class="scope-check"><input type="checkbox" ${viewAttr}${perm?.canView ? ' checked' : ''} /> 可见</label>`}
    </span>`
  const sectionRowHtml = (key, title, perm, hideView = false) => `
    <div class="perm-page-row is-section" ${rowAttr}="${esc(key)}">
      <strong>${esc(title)}</strong>
      ${actionsHtml(perm, hideView)}
    </div>`
  const pageBlockHtml = (page) => {
    const meta = pageMetaMap.get(page)
    const perm = permissionMap.get(page)
    const sections = Array.isArray(meta?.sections) ? meta.sections : []
    const pageTitle = meta?.title || page
    if (sections.length === 0) {
      return `<div class="perm-page-block is-single" ${rowAttr}="${esc(
        page,
      )}" aria-label="${esc(pageTitle)}页面权限">
        <div class="perm-page-name"><strong>${esc(pageTitle)}</strong></div>
        ${actionsHtml(perm)}
      </div>`
    }
    const hasSectionRows = sections.some((section) => permissionMap.has(`${page}:${section.key}`))
    return `<div class="perm-page-block has-sections">
      <div class="perm-page-content">
        ${sections
          .map((section) => {
            const key = `${page}:${section.key}`
            const childPerm = permissionMap.get(key) || (hasSectionRows ? undefined : perm)
            return sectionRowHtml(key, section.title, childPerm, section.hideView === true)
          })
          .join('')}
      </div>
    </div>`
  }
  return `
    <div class="perm-page-groups permission-tree-modern">
      ${(catalog?.domains || [])
        .map(
          (domain) => {
            const domainTitle = domain.title || domain.label || domain.id
            const domainPages = domain.pages || []
            const domainSections = domainPages.reduce(
              (total, page) => total + ((pageMetaMap.get(page)?.sections || []).length || 1),
              0,
            )
            return `<div class="perm-page-group">
            <div class="perm-page-domain">
              <div class="perm-page-domain-title">
                <span class="perm-domain-mark" aria-hidden="true"></span>
                <strong>${esc(domainTitle)}</strong>
                <span class="perm-domain-count">${domainSections} 个页面</span>
              </div>
              ${
                domainPages.length
                  ? `<label class="perm-page-all" title="全选本业务域后台权限">
                      <input type="checkbox" ${domainAllAttr} aria-label="全选${esc(domainTitle)}后台权限" />
                      <span>全选</span>
                    </label>`
                  : ''
              }
            </div>
            <div class="perm-page-list">${domainPages
              .map((page) => pageBlockHtml(page))
              .join('')}</div>
          </div>`
          },
        )
        .join('')}
    </div>`
}

function setupScopeGroupSelectAll(root) {
  for (const group of root.querySelectorAll('.scope-group')) {
    const head = group.querySelector('.scope-group-head')
    const items = [...group.querySelectorAll('input[data-scope]')]
    const allBox = head?.querySelector('input[data-scope-all]')
    if (!head || !allBox || items.length === 0) continue
    const label = allBox.parentElement?.querySelector('span')
    const sync = () => {
      const checked = items.filter((item) => item.checked).length
      allBox.checked = checked === items.length
      allBox.indeterminate = checked > 0 && checked < items.length
      if (label) label.textContent = checked === items.length ? '取消全选' : '全选'
    }
    allBox.addEventListener('change', () => {
      for (const item of items) item.checked = allBox.checked
      sync()
    })
    for (const item of items) item.addEventListener('change', sync)
    sync()
  }
}

function setupPermissionDomainSelectAll(
  root,
  {
    rowSelector = '[data-role-page-row]',
    viewSelector = 'input[data-role-page-view]',
    allSelector = 'input[data-perm-domain-all]',
  } = {},
) {
  for (const group of root.querySelectorAll('.perm-page-group')) {
    const allBox = group.querySelector(allSelector)
    const items = [...group.querySelectorAll(viewSelector)]
    if (!allBox || items.length === 0) continue
    const label = allBox.parentElement?.querySelector('span')
    const sync = () => {
      const checked = items.filter((item) => item.checked).length
      allBox.checked = checked === items.length
      allBox.indeterminate = checked > 0 && checked < items.length
      if (label) label.textContent = checked === items.length ? '取消全选' : '全选'
    }
    allBox.addEventListener('change', () => {
      const on = allBox.checked
      for (const row of group.querySelectorAll(rowSelector)) {
        const viewBox = row.querySelector(viewSelector)
        if (viewBox) viewBox.checked = on
      }
      sync()
    })
    for (const item of items) item.addEventListener('change', sync)
    sync()
  }
}

function setupConsoleDomainSelectAll(root) {
  setupPermissionDomainSelectAll(root)
}

function setupRoleMemberPanel(root, role, allMembers, currentIds) {
  const rows = [...root.querySelectorAll('[data-role-bound]')]
  const boxes = rows.map((row) => row.querySelector('[data-role-member-select]')).filter(Boolean)
  const searchInput = root.querySelector('#role-member-search')
  const allBox = root.querySelector('#role-member-select-all')
  const allLabel = root.querySelector('#role-member-select-all-label')
  const selectedHost = root.querySelector('#role-member-selected')
  const visibleHost = root.querySelector('#role-member-visible')
  const bulkButton = root.querySelector('#role-member-bulk-remove')
  const filterEmpty = root.querySelector('#role-member-filter-empty')
  const messageHost = root.querySelector('#role-member-msg')
  let query = ''

  const visibleRows = () => rows.filter((row) => !row.hidden)
  const selectedRows = () =>
    rows.filter((row) => row.querySelector('[data-role-member-select]')?.checked === true)

  const sync = () => {
    const visible = visibleRows()
    const selected = selectedRows()
    const visibleSelected = visible.filter(
      (row) => row.querySelector('[data-role-member-select]')?.checked === true,
    ).length
    if (allBox) {
      allBox.disabled = visible.length === 0
      allBox.checked = visible.length > 0 && visibleSelected === visible.length
      allBox.indeterminate = visibleSelected > 0 && visibleSelected < visible.length
    }
    if (allLabel) allLabel.textContent = allBox?.checked ? '取消全选' : '全选'
    if (selectedHost) selectedHost.textContent = `已选 ${selected.length} 人`
    if (bulkButton) {
      bulkButton.disabled = selected.length === 0
      bulkButton.textContent = selected.length ? `移除选中（${selected.length}）` : '移除选中'
    }
  }

  const applyFilter = () => {
    const terms = query.toLowerCase().split(/\s+/).filter(Boolean)
    let visible = 0
    for (const row of rows) {
      const matched = terms.every((term) => (row.dataset.search || '').toLowerCase().includes(term))
      row.hidden = !matched
      if (matched) visible += 1
    }
    if (visibleHost) visibleHost.textContent = terms.length ? ` · 显示 ${visible} 人` : ''
    if (filterEmpty) filterEmpty.hidden = !(terms.length > 0 && visible === 0)
    sync()
  }

  searchInput?.addEventListener('input', () => {
    query = searchInput.value.trim()
    for (const box of boxes) box.checked = false
    applyFilter()
  })

  allBox?.addEventListener('change', () => {
    const on = allBox.checked
    for (const row of visibleRows()) {
      const box = row.querySelector('[data-role-member-select]')
      if (box) box.checked = on
    }
    sync()
  })

  for (const box of boxes) box.addEventListener('change', sync)

  for (const row of rows) {
    row.addEventListener('click', (event) => {
      if (event.target.closest('button, input, label, a')) return
      const box = row.querySelector('[data-role-member-select]')
      if (!box) return
      box.checked = !box.checked
      box.dispatchEvent(new Event('change', { bubbles: true }))
    })
  }

  bulkButton?.addEventListener('click', async () => {
    const selected = selectedRows()
    if (!selected.length) return
    const members = selected
      .map((row) => allMembers.find((member) => member.id === row.dataset.roleBound))
      .filter(Boolean)
    if (!members.length) return
    const restText = bulkButton.textContent
    bulkButton.disabled = true
    bulkButton.textContent = '移除中…'
    const done = await removeRoleMembers(role, members, currentIds, messageHost)
    if (!done) {
      bulkButton.disabled = selectedRows().length === 0
      bulkButton.textContent = restText
      sync()
    }
  })

  applyFilter()
}

function roleDisplayName(role) {
  return ROLE_LABEL[role.code] || role.name || role.code
}

function roleRailHtml(roles, selectedCode = null) {
  const builtin = roles.filter((role) => role.builtin)
  const custom = roles.filter((role) => !role.builtin)
  const item = (role) => {
    const name = roleDisplayName(role)
    const active = role.code === selectedCode
    const searchText = [name, role.code, role.dataScope, role.builtin ? '内置角色' : '自定义角色'].join(' ').toLowerCase()
    return `<button class="role-rail-item${active ? ' is-active' : ''}" type="button" data-role-pick="${esc(
      role.code,
    )}" data-search="${esc(searchText)}" aria-current="${active ? 'true' : 'false'}">
      <span class="role-rail-avatar" aria-hidden="true">${esc(String(name).slice(0, 1))}</span>
      <span class="role-rail-main">
        <span class="role-rail-name"><span>${esc(name)}</span><em class="role-rail-tag">${role.builtin ? '内置' : '自定义'}</em></span>
        <small>${esc(DATA_SCOPE_LABEL[role.dataScope] || role.dataScope)} · ${role.scopes.length} 权限点 · ${
          role.members || 0
        } 人</small>
      </span>
    </button>`
  }
  const section = (title, list) =>
    list.length
      ? `<div class="role-rail-section" data-role-section>
          <div class="role-rail-section-head"><span>${title}</span><span>${list.length}</span></div>
          ${list.map(item).join('')}
        </div>`
      : ''
  return `<aside class="role-rail" aria-label="角色列表">
    <div class="role-rail-head">
      <div><span class="role-eyebrow">组织与权限</span><h2>角色</h2></div>
      <span class="pill">${roles.length} 个</span>
    </div>
    <label class="role-rail-search">
      <span class="role-rail-search-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4 4"></path></svg></span>
      <input id="role-rail-search" type="search" value="${esc(state.roleQuery || '')}" placeholder="搜索角色名或角色编码" aria-label="搜索角色" autocomplete="off" />
    </label>
    <div class="role-rail-list" id="role-rail-list">
      ${section('内置角色', builtin)}
      ${section('自定义角色', custom)}
      <div class="role-rail-empty" id="role-rail-empty" hidden>没有匹配的角色</div>
    </div>
    <div class="role-rail-foot">
      <button class="btn sm primary role-rail-add" type="button" id="role-rail-add">＋ 新建角色</button>
      <span class="muted" id="role-rail-count">共 ${roles.length} 个角色</span>
    </div>
  </aside>`
}

function setupRoleRail(root, roles) {
  const search = root.querySelector('#role-rail-search')
  const items = [...root.querySelectorAll('[data-role-pick]')]
  const sections = [...root.querySelectorAll('[data-role-section]')]
  const empty = root.querySelector('#role-rail-empty')
  const count = root.querySelector('#role-rail-count')
  const apply = () => {
    const tokens = String(search?.value || '')
      .trim()
      .toLowerCase()
      .split(/\s+/)
      .filter(Boolean)
    let shown = 0
    for (const item of items) {
      const hit = tokens.every((token) => String(item.dataset.search || '').includes(token))
      item.hidden = !hit
      if (hit) shown += 1
    }
    for (const section of sections) {
      const visible = [...section.querySelectorAll('[data-role-pick]')].some((item) => !item.hidden)
      section.hidden = !visible
    }
    if (empty) empty.hidden = shown > 0
    if (count) count.textContent = tokens.length ? `筛选出 ${shown} / ${roles.length} 个角色` : `共 ${roles.length} 个角色`
  }
  if (search) {
    search.addEventListener('input', () => {
      state.roleQuery = search.value
      apply()
    })
    search.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape' || !search.value) return
      event.stopPropagation()
      search.value = ''
      state.roleQuery = ''
      apply()
    })
  }
  for (const item of items) {
    item.addEventListener('click', () => {
      if (item.dataset.rolePick === state.selectedRole) return
      state.selectedRole = item.dataset.rolePick
      state.roleTab = 'permissions'
      window.scrollTo(0, 0)
      loadRoles()
    })
  }
  root.querySelector('#role-rail-add')?.addEventListener('click', () => openRoleCreateModal())
  apply()
}

