function approvalTimeText(value) {
  const ts = Number(value)
  if (!Number.isFinite(ts) || ts <= 0) return '—'
  const date = new Date(ts)
  const now = new Date()
  const pad = (n) => String(n).padStart(2, '0')
  const hm = `${pad(date.getHours())}:${pad(date.getMinutes())}`
  if (date.toDateString() === now.toDateString()) return `今天 ${hm}`
  const yesterday = new Date(now.getTime() - 24 * 3600 * 1000)
  if (date.toDateString() === yesterday.toDateString()) return `昨天 ${hm}`
  return `${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${hm}`
}

function approvalRecordsFromApi(requests) {
  if (!Array.isArray(requests)) return []
  return requests.map((item) => ({
    id: String(item.id ?? ''),
    requester: String(item.requesterName ?? ''),
    dept: String(item.requesterDept ?? ''),
    role: String(item.requesterTitle || (item.requestType === 'role' ? item.roleName : '权限点申请') || ''),
    scopes: Array.isArray(item.scopeLabels) && item.scopeLabels.length
      ? item.scopeLabels.map(String)
      : Array.isArray(item.scopes) ? item.scopes.map(String) : [],
    status: String(item.status ?? 'pending'),
    submittedAt: approvalTimeText(item.createdAt),
    createdAt: Number(item.createdAt) || 0,
    currentNode: String(item.currentNode ?? ''),
    progress: Number(item.currentStep) || 0,
    totalSteps: Number(item.totalSteps) || 0,
    todo: item.status === 'pending',
    mine: false,
    reason: String(item.reason ?? ''),
    requestType: item.requestType === 'role' ? 'role' : 'scope',
    roleName: String(item.roleName ?? ''),
    durationHours: Number(item.durationHours) || 0,
    requestDeadline: Number(item.requestDeadline) || 0,
    steps: Array.isArray(item.steps) ? item.steps : [],
  }))
}

function approvalRecordsOf() {
  return Array.isArray(state.approvalRecords) ? state.approvalRecords : []
}

function approvalRecordsHtml() {
  const records = approvalRecordsOf()
  const tabs = [
    { id: 'todo', label: '待处理', count: records.filter((item) => item.status === 'pending').length },
    { id: 'done', label: '已结束', count: records.filter((item) => item.status !== 'pending').length },
    { id: 'all', label: '全部记录', count: records.length },
  ]
  const tab = tabs.find((item) => item.id === state.approvalRecordTab) || tabs[0]
  const filtered = records.filter((item) => {
    if (tab.id === 'todo') return item.status === 'pending'
    if (tab.id === 'done') return item.status !== 'pending'
    return true
  })
  const selected = filtered.find((item) => item.id === state.approvalRecordId) || null
  const pendingCount = records.filter((item) => item.status === 'pending').length
  const approvedCount = records.filter((item) => item.status === 'approved').length
  const todayCount = records.filter((item) => approvalTimeText(item.createdAt).startsWith('今天')).length
  return `<div class="ap-records${selected ? ' has-detail' : ''}">
    <div class="ap-records-main">
      <div class="ap-stat-row">
        <div class="ap-stat"><span>今日申请</span><strong>${todayCount}</strong><small>创建于今天</small></div>
        <div class="ap-stat"><span>审批中</span><strong>${pendingCount}</strong><small>当前步骤待处理</small></div>
        <div class="ap-stat"><span>已通过</span><strong>${approvedCount}</strong><small>含历史通过</small></div>
        <div class="ap-stat"><span>超时</span><strong>${records.filter((item) => item.status === 'expired').length}</strong><small>系统自动关闭</small></div>
      </div>
      <div class="ap-filter-row">
        <div class="ap-tabs">${tabs.map((item) => `<button type="button" class="ap-tab${tab.id === item.id ? ' is-active' : ''}" data-ap-record-tab="${esc(item.id)}">${esc(item.label)}<span>${item.count}</span></button>`).join('')}</div>
        <div class="ap-search"><span aria-hidden="true">⌕</span><input data-ap-record-search placeholder="搜索申请人、权限点或单号" value="${esc(state.approvalRecordQuery)}"></div>
      </div>
      <div class="ap-table-wrap">
        <table class="ap-table">
          <thead><tr><th>申请单</th><th>申请人</th><th>申请权限</th><th>当前节点</th><th>状态</th><th>提交时间</th></tr></thead>
          <tbody>
            ${filtered.map((item) => `<tr data-ap-record-row="${esc(item.id)}" data-search="${esc(`${item.id} ${item.requester} ${item.dept} ${item.scopes.join(' ')} ${item.currentNode}`)}" class="${selected?.id === item.id ? 'is-selected' : ''}">
              <td><strong class="ap-mono">${esc(item.id)}</strong><small>${esc(item.role)}</small></td>
              <td><strong>${esc(item.requester)}</strong><small>${esc(item.dept)}</small></td>
              <td><div class="ap-scope-cell">${item.scopes.slice(0, 2).map((scope) => `<span>${esc(scope)}</span>`).join('')}${item.scopes.length > 2 ? `<em>+${item.scopes.length - 2}</em>` : ''}</div></td>
              <td>${esc(item.currentNode)}<div class="ap-progress"><span style="width:${item.status === 'approved' ? 100 : Math.min(100, (item.progress / Math.max(item.totalSteps, 1)) * 100)}%"></span></div></td>
              <td>${approvalStatusPill(item.status)}</td>
              <td><span class="ap-time">${esc(item.submittedAt)}</span></td>
            </tr>`).join('') || '<tr><td colspan="6" class="ap-empty-cell">当前筛选下没有审批记录</td></tr>'}
          </tbody>
        </table>
      </div>
      <div class="ap-table-foot"><span>展示 ${filtered.length} 条 · 共 ${records.length} 条真实审批记录</span><span>${pendingCount ? `${pendingCount} 条待处理` : '没有待处理申请'}</span></div>
    </div>
    ${selected ? approvalRecordDetailHtml(selected) : ''}
  </div>`
}

function approvalRecordDetailHtml(record) {
  const stepGroups = new Map()
  for (const step of Array.isArray(record.steps) ? record.steps : []) {
    const key = Number(step.stepNo) || 0
    const list = stepGroups.get(key) || []
    list.push(step)
    stepGroups.set(key, list)
  }
  const showSteps = [...stepGroups.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([stepNo, group]) => {
      const approved = group.filter((step) => step.status === 'approved').length
      const rejected = group.some((step) => step.status === 'rejected')
      const active = group.some((step) => step.status === 'active')
      const skipped = group.every((step) => step.status === 'skipped')
      const names = group.map((step) => step.approverName || '审批人').join('、')
      const title = group.length > 1 ? `第 ${stepNo} 步会签 · ${names}` : `第 ${stepNo} 步 · ${names}`
      const personState = group
        .map((step) => {
          const label =
            step.status === 'approved'
              ? '已同意'
              : step.status === 'rejected'
                ? '已拒绝'
                : step.status === 'skipped'
                  ? '已跳过'
                  : step.status === 'active'
                    ? '待审批'
                    : '等待中'
          return `${step.approverName || '审批人'} ${label}`
        })
        .join('；')
      let desc = personState
      if (rejected) desc = `已拒绝 · ${personState}`
      else if (approved === group.length) desc = `全部同意 · ${personState}`
      else if (active) desc = `会签中 · 已通过 ${approved}/${group.length} · ${personState}`
      else if (skipped) desc = `已跳过 · ${personState}`
      return {
        title,
        desc,
        done: approved === group.length && group.length > 0,
        active,
      }
    })
  const steps = [
    { title: '提交申请', desc: `${record.requester} · ${record.submittedAt}`, done: true, active: false },
    ...showSteps,
    {
      title: '个人权限生效',
      desc: record.status === 'approved' ? '已写入申请人权限' : '审批通过后写入',
      done: record.status === 'approved',
      active: false,
    },
  ]
  const lastComment = [...(record.steps || [])].reverse().find((step) => String(step.comment || '').trim())
  const opinion = lastComment
    ? String(lastComment.comment)
    : record.status === 'pending'
      ? '暂无审批意见，等待当前节点处理。'
      : record.status === 'rejected'
        ? '申请未通过，申请人可拆分权限后重新提交。'
        : record.status === 'expired'
          ? '审批超时，系统已关闭本次申请。'
          : record.reason || '审批已完成。'
  const busy = state.approvalRecordBusy === record.id
  return `<aside class="ap-detail">
    <div class="ap-detail-head">
      <div><span>申请详情</span><strong class="ap-mono">${esc(record.id)}</strong></div>
      <button type="button" class="wf-icon-btn" data-ap-record-close aria-label="关闭详情">×</button>
    </div>
    <div class="ap-detail-body">
      <div class="ap-detail-hero">
        <div><strong>${esc(record.requester)}</strong><span>${esc(record.dept || '未归属部门')} · ${esc(record.role || '公司成员')}</span></div>
        ${approvalStatusPill(record.status)}
      </div>
      <div class="ap-detail-section"><span>申请权限</span><div class="ap-detail-scopes">${record.scopes.map((scope) => `<span>${esc(scope)}</span>`).join('')}</div></div>
      <div class="ap-detail-section"><span>授权方式</span><div class="ap-detail-note">仅授予申请人本人，不改动角色；有效期 ${esc(String(record.durationHours || 0))} 小时。</div></div>
      <div class="ap-detail-section"><span>申请原因</span><div class="ap-detail-quote">${esc(record.reason || '未填写申请原因。')}</div></div>
      <div class="ap-detail-section"><span>审批进度</span>
        <div class="ap-timeline">${steps.map((step) => `<div class="ap-timeline-step${step.done ? ' is-done' : ''}${step.active ? ' is-active' : ''}"><i></i><div><strong>${esc(step.title)}</strong><small>${esc(step.desc)}</small></div></div>`).join('')}</div>
      </div>
      <div class="ap-detail-section"><span>审批意见</span><div class="ap-detail-quote">${esc(opinion)}</div></div>
    </div>
    <div class="ap-detail-foot">
      ${record.status === 'pending' && record.todo
        ? `<button type="button" class="btn" data-ap-record-reject${busy ? ' disabled' : ''}>${busy ? '处理中…' : '拒绝'}</button><button type="button" class="btn primary" data-ap-record-approve${busy ? ' disabled' : ''}>${busy ? '处理中…' : '同意'}</button>`
        : '<span class="muted">该记录已结束</span>'}
    </div>
  </aside>`
}

function approvalCatalogRows() {
  const data = state.approvalData || {}
  const scopes = data.scopes || []
  const policies = data.policies || []
  const query = String(state.approvalCatalogQuery || '').trim().toLowerCase()
  const filter = state.approvalCatalogFilter
  const groups = new Map()
  for (const item of scopes) {
    if (filter === 'danger' && !item.dangerous) continue
    if (filter === 'unconfigured' && policies.some((policy) => policy.targetType === 'scope' && policy.targetKey === item.scope)) continue
    if (query && !`${item.label} ${item.group} ${item.scope}`.toLowerCase().includes(query)) continue
    const group = item.group || '其他权限'
    const list = groups.get(group) || []
    list.push(item)
    groups.set(group, list)
  }
  if (!groups.size) return '<div class="ap-catalog-empty">没有匹配的权限点</div>'
  return [...groups.entries()].map(([group, items]) => {
    const configured = items.filter((item) => policies.some((policy) => policy.targetType === 'scope' && policy.targetKey === item.scope)).length
    return `<div class="ap-catalog-group">
      <div class="ap-catalog-group-head"><strong>${esc(group)}</strong><span>${items.length} 项 · ${configured} 项已配置策略</span></div>
      <div class="ap-catalog-list">
        ${items.map((item) => {
          const scoped = policies.some((policy) => policy.targetType === 'scope' && policy.targetKey === item.scope)
          return `<div class="ap-catalog-row">
          <div class="ap-catalog-main"><strong>${esc(item.label)}</strong><span class="ap-mono">${esc(item.scope)}</span></div>
          ${item.dangerous ? '<span class="ap-danger">高危</span>' : ''}
          <span class="ap-catalog-policy">${scoped ? '已配置审批策略' : '默认审批链'}</span>
          <button type="button" class="btn ghost ap-catalog-action" data-ap-catalog-flow="${esc(item.dangerous ? 'sensitive' : 'default')}">查看流程</button>
        </div>`}).join('')}
      </div>
    </div>`
  }).join('')
}

function approvalCatalogHtml() {
  const scopes = state.approvalData?.scopes || []
  const groups = new Set(scopes.map((item) => item.group || '其他权限')).size
  return `<div class="ap-catalog">
    <div class="ap-catalog-top">
      <div>
        <strong>全量权限目录</strong>
        <span>${scopes.length} 个权限点 · ${groups} 个分组 · 审批通过后只授予申请人本人</span>
      </div>
      <div class="ap-filter">
        <button type="button" class="ap-filter-btn${state.approvalCatalogFilter === 'all' ? ' is-active' : ''}" data-ap-catalog-filter="all">全部</button>
        <button type="button" class="ap-filter-btn${state.approvalCatalogFilter === 'danger' ? ' is-active' : ''}" data-ap-catalog-filter="danger">仅高危</button>
        <button type="button" class="ap-filter-btn${state.approvalCatalogFilter === 'unconfigured' ? ' is-active' : ''}" data-ap-catalog-filter="unconfigured">未单独配置</button>
        <div class="ap-search"><span aria-hidden="true">⌕</span><input data-ap-catalog-search placeholder="搜索权限名称或标识" value="${esc(state.approvalCatalogQuery)}"></div>
      </div>
    </div>
    <div class="ap-catalog-body">${approvalCatalogRows()}</div>
    <div class="ap-catalog-foot"><span>权限点来自 domain scope registry</span><span>流程模板与审批记录仍为前端示例数据</span></div>
  </div>`
}

function renderApprovalPage() {
  const view = $('#view')
  if (!view) return
  const tab = state.approvalTab || 'design'
  const tabs = [
    { id: 'design', label: '流程设计', count: '' },
    { id: 'records', label: '审批记录', count: (state.approvalRecords || approvalRecordsOf()).length },
    { id: 'catalog', label: '权限目录', count: (state.approvalData?.scopes || []).length },
  ]
  const actions = tab === 'design'
    ? `<button type="button" class="btn ghost" data-ap-default-policy>默认审批链</button><button type="button" class="btn ghost" data-ap-save>保存草稿</button><button type="button" class="btn primary" data-ap-publish>发布流程</button>`
    : tab === 'records'
      ? '<button type="button" class="btn ghost" data-ap-export>导出记录</button>'
      : `<button type="button" class="btn ghost" data-ap-catalog-refresh>同步权限目录</button>`
  view.innerHTML = `<section class="approval-shell${tab === 'records' ? ' is-records' : ''}">
    <div class="approval-top">
      <div class="ap-tabs is-main" role="tablist">
        ${tabs.map((item) => `<button type="button" class="ap-tab${tab === item.id ? ' is-active' : ''}" data-ap-tab="${esc(item.id)}" role="tab" aria-selected="${tab === item.id}">${esc(item.label)}${item.count ? `<span>${item.count}</span>` : ''}</button>`).join('')}
      </div>
      <div class="approval-top-actions">${actions}</div>
    </div>
    <div class="approval-body">${tab === 'design' ? approvalDesignHtml() : tab === 'records' ? approvalRecordsHtml() : approvalCatalogHtml()}</div>
  </section>`
  bindApprovalPage()
}

function approvalRerender() {
  approvalCloseCanvasMenu()
  renderApprovalPage()
}

function bindApprovalPage() {
  const shell = document.querySelector('.approval-shell')
  if (!shell) return
  approvalScheduleApproverPreview(30)
  const historyTemplate = approvalTemplateOf()
  if (historyTemplate) approvalEnsureHistory(historyTemplate)

  shell.addEventListener('click', async (event) => {
    const menuButton = event.target.closest('[data-wf-canvas-menu] button')
    if (menuButton) {
      const template = approvalTemplateOf()
      const menu = state.approvalCanvasMenu
      if (!template || !menu || menu.templateId !== template.id) {
        approvalCloseCanvasMenu()
        return
      }
      const addKind = menuButton.getAttribute('data-wf-menu-add')
      if (addKind) {
        const newNode = approvalNewFlowNode(addKind)
        approvalInsertFlowNode(template, newNode, menu.anchorId, menu.worldX, menu.worldY, {
          historyLabel: '新建节点',
          historyKey: `add:${newNode.id}`,
        })
        approvalCloseCanvasMenu()
        state.approvalNodeId = newNode.id
        state.approvalEdgeFrom = ''
        state.approvalEdgeTo = ''
        approvalRerender()
        showTopToast(
          addKind === 'condition'
            ? '已创建条件判断，拖动圆点继续连接分支'
            : addKind === 'cc'
              ? '已创建抄送节点，可从结束节点端口连接'
              : '已创建节点，拖动圆点连接上下游',
        )
        return
      }
      if (menuButton.closest('[data-wf-menu-edge-delete]')) {
        if (menu.edgeFrom && menu.edgeTo && approvalRemoveEdge(template, menu.edgeFrom, menu.edgeTo)) {
          state.approvalEdgeFrom = ''
          state.approvalEdgeTo = ''
          approvalCloseCanvasMenu()
          approvalRerender()
          showTopToast('连线已删除')
        }
        return
      }
      if (menuButton.closest('[data-wf-menu-delete]')) {
        const node = approvalFindNode(template.flow, menu.anchorId)
        if (!node || node.kind === 'start' || node.kind === 'end') return
        approvalDetachNodeWithLinks(template, node.id)
        approvalCloseCanvasMenu()
        state.approvalNodeId = template.flow[0]?.id || 'start'
        state.approvalEdgeFrom = ''
        state.approvalEdgeTo = ''
        approvalRerender()
        showTopToast('节点与关联连线已删除')
        return
      }
      const menuAction = menuButton.getAttribute('data-wf-menu-action')
      if (menuAction === 'layout') {
        approvalCloseCanvasMenu()
        approvalAutoLayoutGraph(template)
        approvalCanvasState().pendingFit = true
        approvalRerender()
        showTopToast('已按连线层级重新布局')
        return
      }
      if (menuAction === 'fit') {
        approvalCloseCanvasMenu()
        approvalFitCanvas()
        return
      }
      return
    }

    const zoomButton = event.target.closest('[data-wf-zoom]')
    if (zoomButton) {
      approvalCloseCanvasMenu()
      const action = zoomButton.getAttribute('data-wf-zoom')
      if (action === 'fit') approvalFitCanvas()
      else approvalZoomCanvas(action === 'out' ? .82 : 1.22)
      return
    }

    if (event.target.closest('[data-wf-layout]')) {
      const template = approvalTemplateOf()
      if (!template) return
      approvalAutoLayoutGraph(template)
      approvalCanvasState().pendingFit = true
      approvalRerender()
      showTopToast('已按连线层级重新布局')
      return
    }

    if (event.target.closest('[data-wf-focus]')) {
      state.approvalFocus = !state.approvalFocus
      approvalCanvasState().pendingFit = true
      approvalRerender()
      showTopToast(state.approvalFocus ? '已进入专注画布' : '已恢复三栏布局')
      return
    }

    const tabButton = event.target.closest('[data-ap-tab]')
    if (tabButton) {
      state.approvalTab = tabButton.getAttribute('data-ap-tab')
      state.approvalRecordId = ''
      approvalRerender()
      return
    }

    const templateButton = event.target.closest('[data-wf-template]')
    if (templateButton) {
      state.approvalTemplateId = templateButton.getAttribute('data-wf-template')
      const template = approvalTemplateOf()
      state.approvalNodeId = template?.flow?.[0]?.id || 'start'
      state.approvalEdgeFrom = ''
      state.approvalEdgeTo = ''
      approvalRerender()
      return
    }

    const deleteTemplateButton = event.target.closest('[data-wf-delete-template]')
    if (deleteTemplateButton) {
      const template = approvalTemplatesOf().find(
        (item) => item.id === deleteTemplateButton.getAttribute('data-wf-delete-template'),
      )
      openApprovalWorkflowDeleteModal(template)
      return
    }

    const edgeButton = event.target.closest('[data-wf-edge-from]')
    if (edgeButton && edgeButton.closest('[data-wf-edge-group]')) {
      state.approvalEdgeFrom = edgeButton.getAttribute('data-wf-edge-from')
      state.approvalEdgeTo = edgeButton.getAttribute('data-wf-edge-to')
      approvalRerender()
      return
    }

    const nodeButton = event.target.closest('[data-wf-node]')
    if (nodeButton) {
      state.approvalNodeId = nodeButton.getAttribute('data-wf-node')
      state.approvalEdgeFrom = ''
      state.approvalEdgeTo = ''
      approvalRerender()
      return
    }

    if (event.target.closest('[data-ap-default-policy]')) {
      openApprovalDefaultPolicyModal()
      return
    }

    if (event.target.closest('[data-ap-save]')) {
      const template = approvalTemplateOf()
      try {
        await approvalSaveTemplate(template, event.target.closest('button'))
      } catch (err) {
        showTopToast(err?.message || '保存失败')
      }
      return
    }

    if (event.target.closest('[data-ap-publish]')) {
      const template = approvalTemplateOf()
      try {
        await approvalPublishTemplate(template, event.target.closest('button'))
      } catch (err) {
        showTopToast(err?.message || '发布失败')
      }
      return
    }

    if (event.target.closest('[data-wf-check]')) {
      const template = approvalTemplateOf()
      if (!template) return
      try {
        const data = await apiSend('POST', `/api/console/approval-workflows/${encodeURIComponent(template.id)}/validate`, {
          flow: template.flow,
        })
        const errors = data.validation?.errors || []
        template.validation = errors
        if (data.validation?.valid) {
          approvalRerender()
          showTopToast('流程校验通过：节点完整，审批方式已配置')
        } else {
          approvalRerender()
          showTopToast(`校验未通过：${errors[0] || '请检查流程节点'}`)
        }
      } catch (err) {
        showTopToast(err?.message || '校验失败')
      }
      return
    }

    if (event.target.closest('[data-wf-new]')) {
      openApprovalWorkflowCreateModal()
      return
    }

    if (event.target.closest('[data-wf-add]')) {
      const kindSelect = shell.querySelector('[data-wf-add-kind]')
      const kind = kindSelect?.value || 'approval'
      const template = approvalTemplateOf()
      if (!template) return
      const newNode = approvalNewFlowNode(kind)
      approvalInsertFlowNode(template, newNode, state.approvalNodeId, undefined, undefined, {
        historyLabel: '新建节点',
        historyKey: `add:${newNode.id}`,
      })
      state.approvalNodeId = newNode.id
      approvalRerender()
      showTopToast(
        kind === 'condition'
          ? '已添加条件判断，可继续配置分支'
          : kind === 'cc'
            ? '已添加抄送节点，可作为流程末端'
            : '已添加节点，记得配置审批人',
      )
      return
    }

    const addBranchButton = event.target.closest('[data-wf-add-branch]')
    if (addBranchButton) {
      const template = approvalTemplateOf()
      const node = template ? approvalFindNode(template.flow, state.approvalNodeId) : null
      if (!template || node?.kind !== 'condition') return
      const branch = {
        id: approvalUid('br'),
        label: APPROVAL_BRANCH_RULES.risk_high.label,
        rule: { ...APPROVAL_BRANCH_RULES.risk_high },
        nodes: [approvalMakeApprovalNode('条件审批', 'dept_chain', '或签')],
      }
      const elseIndex = (node.branches || []).findIndex((item) => approvalBranchRuleKey(item) === 'else')
      node.branches.splice(elseIndex >= 0 ? elseIndex : node.branches.length, 0, branch)
      approvalTouchTemplate(template, { historyLabel: '新增条件分支' })
      approvalRerender()
      return
    }

    if (event.target.closest('[data-wf-add-else]')) {
      const template = approvalTemplateOf()
      const node = template ? approvalFindNode(template.flow, state.approvalNodeId) : null
      if (!template || node?.kind !== 'condition') return
      if ((node.branches || []).some((branch) => approvalBranchRuleKey(branch) === 'else')) {
        showTopToast('条件判断已有「否则」分支')
        return
      }
      node.branches = node.branches || []
      node.branches.push({
        id: approvalUid('br'),
        label: APPROVAL_BRANCH_RULES.else.label,
        rule: { ...APPROVAL_BRANCH_RULES.else },
        nodes: [approvalMakeApprovalNode('兜底审批', 'dept_chain', '或签')],
      })
      approvalTouchTemplate(template, { historyLabel: '新增否则分支' })
      approvalRerender()
      return
    }

    const deleteBranchButton = event.target.closest('[data-wf-branch-del]')
    if (deleteBranchButton) {
      const template = approvalTemplateOf()
      const node = template ? approvalFindNode(template.flow, state.approvalNodeId) : null
      if (!template || node?.kind !== 'condition') return
      if ((node.branches || []).length <= 1) {
        showTopToast('条件判断至少保留一个分支')
        return
      }
      const branchId = deleteBranchButton.getAttribute('data-wf-branch-del')
      node.branches = node.branches.filter((branch) => branch.id !== branchId)
      approvalTouchTemplate(template, { historyLabel: '删除条件分支' })
      approvalRerender()
      return
    }

    const addBranchNode = event.target.closest('[data-wf-branch-node]')
    if (addBranchNode) {
      const template = approvalTemplateOf()
      const branch = template ? approvalBranchOf(template, addBranchNode.getAttribute('data-wf-branch-node')) : null
      if (!template || !branch) return
      const newNode = approvalMakeApprovalNode('新增审批节点', 'dept_chain', '或签')
      branch.nodes = branch.nodes || []
      branch.nodes.push(newNode)
      approvalTouchTemplate(template, { historyLabel: '新增分支节点' })
      state.approvalNodeId = newNode.id
      approvalRerender()
      return
    }

    if (event.target.closest('[data-wf-pick-role]')) {
      await openApprovalRolePicker()
      return
    }

    if (event.target.closest('[data-wf-pick-members]')) {
      await openApprovalApproverPicker()
      return
    }

    const removeApprover = event.target.closest('[data-wf-approver-remove]')
    if (removeApprover) {
      const template = approvalTemplateOf()
      const node = template ? approvalFindNode(template.flow, state.approvalNodeId) : null
      if (!template || node?.kind !== 'approval') return
      const id = removeApprover.getAttribute('data-wf-approver-remove')
      node.approvers = approvalApproversOf(node).filter((item) => item.id !== id)
      node.desc = approvalNodeSummary(node)
      approvalTouchTemplate(template, { historyLabel: '移除审批人' })
      approvalRerender()
      return
    }

    if (event.target.closest('[data-wf-add-rule]')) {
      showTopToast('请在条件节点右侧面板编辑分支')
      return
    }

    if (event.target.closest('[data-wf-edge-close]')) {
      state.approvalEdgeFrom = ''
      state.approvalEdgeTo = ''
      approvalRerender()
      return
    }

    const edgeDelete = event.target.closest('[data-wf-edge-delete]')
    if (edgeDelete) {
      const template = approvalTemplateOf()
      if (!template) return
      const fromId = edgeDelete.getAttribute('data-wf-edge-from')
      const toId = edgeDelete.getAttribute('data-wf-edge-to')
      if (approvalRemoveEdge(template, fromId, toId)) {
        state.approvalEdgeFrom = ''
        state.approvalEdgeTo = ''
        approvalRerender()
        showTopToast('连线已删除')
      }
      return
    }

    if (event.target.closest('[data-wf-delete]')) {
      const template = approvalTemplateOf()
      if (!template) return
      const node = approvalFindNode(template.flow, state.approvalNodeId)
      if (!node || node.kind === 'start' || node.kind === 'end') return
      approvalDetachNodeWithLinks(template, node.id)
      state.approvalNodeId = template.flow[0]?.id || 'start'
      state.approvalEdgeFrom = ''
      state.approvalEdgeTo = ''
      approvalRerender()
      showTopToast('节点与关联连线已删除')
      return
    }

    const modeButton = event.target.closest('[data-wf-mode]')
    if (modeButton) {
      const template = approvalTemplateOf()
      if (!template) return
      const node = approvalFindNode(template.flow, state.approvalNodeId)
      if (node?.kind === 'approval') {
        const mode = modeButton.getAttribute('data-wf-mode')
        node.mode = mode
        node.meta = mode
        node.desc = approvalNodeSummary(node)
        approvalTouchTemplate(template, { historyLabel: '切换审批方式' })
        approvalRerender()
      }
      return
    }

    const recordTab = event.target.closest('[data-ap-record-tab]')
    if (recordTab) {
      state.approvalRecordTab = recordTab.getAttribute('data-ap-record-tab')
      state.approvalRecordId = ''
      approvalRerender()
      return
    }

    const recordRow = event.target.closest('[data-ap-record-row]')
    if (recordRow) {
      state.approvalRecordId = recordRow.getAttribute('data-ap-record-row')
      approvalRerender()
      return
    }

    if (event.target.closest('[data-ap-record-close]')) {
      state.approvalRecordId = ''
      approvalRerender()
      return
    }

    if (event.target.closest('[data-ap-record-approve]') || event.target.closest('[data-ap-record-reject]')) {
      const approve = Boolean(event.target.closest('[data-ap-record-approve]'))
      const record = approvalRecordsOf().find((item) => item.id === state.approvalRecordId)
      if (!record || state.approvalRecordBusy) return
      state.approvalRecordBusy = record.id
      approvalRerender()
      try {
        await apiPost(`/api/console/permission-requests/${encodeURIComponent(record.id)}/decide`, {
          decision: approve ? 'approve' : 'reject',
          stepNo: record.progress,
          comment: '',
        })
        await loadApprovalRecords()
        state.approvalRecordBusy = ''
        approvalRerender()
        showTopToast(approve ? '已同意申请，权限将授予申请人本人' : '已拒绝申请，申请人会收到通知')
      } catch (err) {
        state.approvalRecordBusy = ''
        approvalRerender()
        alert(err.message)
      }
      return
    }

    const catalogFilter = event.target.closest('[data-ap-catalog-filter]')
    if (catalogFilter) {
      state.approvalCatalogFilter = catalogFilter.getAttribute('data-ap-catalog-filter')
      approvalRerender()
      return
    }

    const catalogFlow = event.target.closest('[data-ap-catalog-flow]')
    if (catalogFlow) {
      state.approvalTab = 'design'
      state.approvalTemplateId = catalogFlow.getAttribute('data-ap-catalog-flow')
      const template = approvalTemplateOf()
      state.approvalNodeId = template?.flow?.[0]?.id || 'start'
      approvalRerender()
      return
    }

    if (event.target.closest('[data-ap-export]')) {
      showTopToast('审批记录导出将在后端接入后开放')
      return
    }

    if (event.target.closest('[data-ap-catalog-refresh]')) {
      showTopToast('权限目录已同步（原型）')
    }
  })

  const recordSearch = shell.querySelector('[data-ap-record-search]')
  if (recordSearch) {
    recordSearch.addEventListener('input', () => {
      state.approvalRecordQuery = recordSearch.value
      const query = recordSearch.value.trim().toLowerCase()
      for (const row of shell.querySelectorAll('[data-ap-record-row]')) {
        const haystack = (row.getAttribute('data-search') || '').toLowerCase()
        row.classList.toggle('is-hidden', Boolean(query) && !haystack.includes(query))
      }
    })
  }

  const catalogSearch = shell.querySelector('[data-ap-catalog-search]')
  if (catalogSearch) {
    catalogSearch.addEventListener('input', () => {
      state.approvalCatalogQuery = catalogSearch.value
      const body = shell.querySelector('.ap-catalog-body')
      if (body) body.innerHTML = approvalCatalogRows()
    })
  }

  const inspector = shell.querySelector('.wf-inspector')
  inspector?.addEventListener('input', (event) => {
    const template = approvalTemplateOf()
    if (!template) return
    const edgeLabelInput = event.target.closest('[data-wf-edge-label]')
    if (edgeLabelInput) {
      const fromId = edgeLabelInput.getAttribute('data-wf-edge-from')
      const toId = edgeLabelInput.getAttribute('data-wf-edge-to')
      const from = approvalFindNode(template.flow, fromId)
      if (!from || !toId) return
      if (!from.edgeLabels) from.edgeLabels = {}
      const value = edgeLabelInput.value
      if (value) from.edgeLabels[toId] = value
      else delete from.edgeLabels[toId]
      approvalTouchTemplate(template, {
        historyLabel: '修改连线名称',
        historyKey: `edge-label:${fromId}:${toId}`,
      })
      repaintApprovalEdges()
      return
    }
    const edgeValueInput = event.target.closest('[data-wf-edge-value]')
    if (edgeValueInput) {
      const prefix = edgeValueInput.getAttribute('data-wf-edge-value')
      const [fromId, toId] = prefix.split('|')
      const from = approvalFindNode(template.flow, fromId)
      if (!from || !toId) return
      if (!from.edgeRules) from.edgeRules = {}
      from.edgeRules[toId] = { ...(from.edgeRules[toId] || {}), value: edgeValueInput.value }
      approvalTouchTemplate(template, {
        historyLabel: '修改条件值',
        historyKey: `edge-value:${fromId}:${toId}`,
      })
      return
    }
    const branchLabel = event.target.closest('[data-wf-branch-label]')
    if (branchLabel) {
      const branch = approvalBranchOf(template, branchLabel.getAttribute('data-wf-branch-label'))
      if (!branch) return
      branch.label = branchLabel.value
      const tag = shell.querySelector(`[data-wf-branch-tag="${branch.id}"]`)
      if (tag) tag.textContent = branch.label
      approvalTouchTemplate(template, {
        historyLabel: '修改分支名称',
        historyKey: `branch-label:${branch.id}`,
      })
      return
    }
    const branchValue = event.target.closest('[data-wf-branch-value]')
    if (branchValue) {
      approvalApplyBranchValue(template, shell, branchValue)
      return
    }
    const field = event.target.closest('[data-wf-field]')
    if (!field) return
    const node = approvalFindNode(template.flow, state.approvalNodeId)
    if (!node) return
    const key = field.getAttribute('data-wf-field')
    if (key === 'maxLevels') {
      const limit = approvalOrgLevelLimit()
      const requested = Math.max(1, Math.trunc(Number(field.value) || 1))
      const levels = Math.min(limit, requested)
      if (requested !== levels) {
        field.value = String(levels)
        showTopToast(`审批级数不能超过本组织实际层级，最多 ${limit} 级`)
      }
      node.maxLevels = levels
      node.desc = approvalNodeSummary(node)
      approvalTouchTemplate(template, {
        historyLabel: '修改审批级数',
        historyKey: `levels:${node.id}`,
      })
      approvalScheduleApproverPreview(120)
      return
    }
    node[key] = key === 'timeoutHours' ? Number(field.value) || 72 : field.value
    approvalTouchTemplate(template, {
      historyLabel: key === 'title' ? '修改节点名称' : '修改节点信息',
      historyKey: `field:${node.id}:${key}`,
    })
    if (key === 'title') {
      const canvasNode = shell.querySelector(`[data-wf-node="${node.id}"] strong`)
      if (canvasNode) canvasNode.textContent = field.value
    }
  })

  inspector?.addEventListener('change', (event) => {
    const template = approvalTemplateOf()
    if (!template) return
    const previewApplicant = event.target.closest('[data-wf-preview-applicant]')
    if (previewApplicant) {
      state.approvalPreviewApplicantId = String(previewApplicant.value || '')
      approvalScheduleApproverPreview(0)
      return
    }
    const edgeRuleSelect = event.target.closest('[data-wf-edge-rule]')
    if (edgeRuleSelect) {
      const prefix = edgeRuleSelect.getAttribute('data-wf-edge-rule')
      const [fromId, toId] = prefix.split('|')
      const from = approvalFindNode(template.flow, fromId)
      if (!from || !toId) return
      const key = edgeRuleSelect.value
      const rule = { ...(APPROVAL_BRANCH_RULES[key] || APPROVAL_BRANCH_RULES.risk_high) }
      if (!from.edgeRules) from.edgeRules = {}
      from.edgeRules[toId] = rule
      if (!from.edgeLabels) from.edgeLabels = {}
      const current = String(from.edgeLabels[toId] || '')
      if (!current || /^分支\s+\d+$/.test(current) || current === '其他情况' || Object.values(APPROVAL_BRANCH_RULES).some((item) => current === item.label)) {
        from.edgeLabels[toId] = rule.label
      }
      approvalTouchTemplate(template, { historyLabel: '修改分支规则' })
      approvalRerender()
      return
    }
    const edgeValueInput = event.target.closest('[data-wf-edge-value]')
    if (edgeValueInput) {
      const prefix = edgeValueInput.getAttribute('data-wf-edge-value')
      const [fromId, toId] = prefix.split('|')
      const from = approvalFindNode(template.flow, fromId)
      if (!from || !toId) return
      if (!from.edgeRules) from.edgeRules = {}
      const rule = { ...(from.edgeRules[toId] || {}), value: edgeValueInput.value }
      from.edgeRules[toId] = rule
      const key = approvalEdgeRuleKey(rule)
      const base = APPROVAL_BRANCH_RULES[key]?.label || ''
      const current = String(from.edgeLabels?.[toId] || '')
      if (!current || current === base || current.startsWith(`${base} · `)) {
        if (!from.edgeLabels) from.edgeLabels = {}
        from.edgeLabels[toId] = edgeValueInput.value ? `${base} · ${edgeValueInput.value}` : base
      }
      approvalTouchTemplate(template, {
        historyLabel: '修改条件值',
        historyKey: `edge-value:${fromId}:${toId}`,
      })
      approvalRerender()
      return
    }
    const node = approvalFindNode(template.flow, state.approvalNodeId)
    if (!node) return
    const branchValue = event.target.closest('[data-wf-branch-value]')
    if (branchValue && node.kind === 'condition') {
      approvalApplyBranchValue(template, shell, branchValue)
      return
    }
    const branchRule = event.target.closest('[data-wf-branch-rule]')
    if (branchRule && node.kind === 'condition') {
      const branch = approvalBranchOf(template, branchRule.getAttribute('data-wf-branch-rule'))
      if (!branch) return
      const key = branchRule.value
      const rule = APPROVAL_BRANCH_RULES[key] || APPROVAL_BRANCH_RULES.risk_high
      branch.rule = { ...rule }
      branch.label = approvalBranchRuleLabel(key, branch.rule.value)
      approvalTouchTemplate(template, { historyLabel: '修改分支规则' })
      approvalRerender()
      return
    }
    const field = event.target.closest('[data-wf-field]')
    if (field) {
      const key = field.getAttribute('data-wf-field')
      if (key === 'source') {
        node.source = field.value
        if (node.source === 'role') {
          node.mode = '会签'
          node.meta = '会签'
          node.approvers = []
          node.desc = approvalNodeSummary(node)
          approvalTouchTemplate(template, { historyLabel: '切换审批来源' })
          approvalRerender()
          if (!String(node.roleCode || '').trim()) {
            showTopToast('请选择具体角色')
            void openApprovalRolePicker()
          }
          return
        }
        if (node.source === 'dept_chain' && !Number.isFinite(Number(node.maxLevels))) {
          node.maxLevels = approvalDefaultLevels()
        }
        node.desc = approvalNodeSummary(node)
        approvalTouchTemplate(template, { historyLabel: '切换审批来源' })
        approvalRerender()
        if (node.source === 'members' && !approvalApproversOf(node).length) showTopToast('请选择具体审批成员')
        return
      }
      if (key === 'timeoutHours') {
        const value = Math.min(720, Math.max(1, Math.trunc(Number(field.value) || 72)))
        node.timeoutHours = value
        node.desc = approvalNodeSummary(node)
        approvalTouchTemplate(template, {
          historyLabel: '修改处理时限',
          historyKey: `timeout:${node.id}`,
        })
        approvalRerender()
        return
      }
      if (key === 'maxLevels') {
        node.maxLevels = Math.min(10, Math.max(1, Math.trunc(Number(field.value) || 1)))
        node.desc = approvalNodeSummary(node)
        approvalTouchTemplate(template, {
          historyLabel: '修改审批级数',
          historyKey: `levels:${node.id}`,
        })
        approvalRerender()
        return
      }
      if (key === 'timeoutAction') {
        node.timeoutAction = field.value
        approvalTouchTemplate(template, { historyLabel: '修改超时处理' })
        return
      }
    }
    const toggle = event.target.closest('[data-wf-toggle]')
    if (toggle) {
      node[toggle.getAttribute('data-wf-toggle')] = Boolean(toggle.checked)
      approvalTouchTemplate(template, { historyLabel: '修改节点开关' })
    }
  })

  const approvalClientToWorld = (clientX, clientY) => {
    const canvasViewport = shell.querySelector('[data-wf-viewport]')
    const view = approvalCanvasState()
    if (!canvasViewport) return { x: 0, y: 0 }
    const rect = canvasViewport.getBoundingClientRect()
    return {
      x: (clientX - rect.left - view.x) / view.scale,
      y: (clientY - rect.top - view.y) / view.scale,
    }
  }

  const approvalWorldToClient = (point) => {
    const canvasViewport = shell.querySelector('[data-wf-viewport]')
    const view = approvalCanvasState()
    if (!canvasViewport) return { x: 0, y: 0 }
    const rect = canvasViewport.getBoundingClientRect()
    return { x: rect.left + view.x + point.x * view.scale, y: rect.top + view.y + point.y * view.scale }
  }

  const approvalDragIssue = (template, drag, targetId) => {
    if (drag.mode === 'link') return approvalConnectionIssue(template, drag.sourceId, targetId)
    if (drag.mode === 'edge-target') {
      return approvalConnectionIssue(template, drag.edgeFrom, targetId, { from: drag.edgeFrom, to: drag.edgeTo })
    }
    if (drag.mode === 'edge-source') {
      return approvalConnectionIssue(template, targetId, drag.edgeTo, { from: drag.edgeFrom, to: drag.edgeTo })
    }
    return ''
  }

  const approvalNearestPortSide = (node, worldPoint) => {
    let bestSide = 'bottom'
    let bestDistance = Infinity
    for (const side of APPROVAL_PORT_SIDES) {
      const point = approvalPortAnchor(node, side)
      const distance = Math.hypot(point.x - worldPoint.x, point.y - worldPoint.y)
      if (distance < bestDistance) {
        bestDistance = distance
        bestSide = side
      }
    }
    return bestSide
  }

  const approvalDragTargetAt = (clientX, clientY) => {
    const drag = state.approvalDrag
    const template = approvalTemplateOf()
    if (!drag || !template) return null
    const world = approvalClientToWorld(clientX, clientY)
    const exactElement = document.elementFromPoint(clientX, clientY)?.closest?.('[data-wf-node]')
    let targetElement = exactElement || null
    let targetNode = targetElement ? approvalFindNode(template.flow, targetElement.getAttribute('data-wf-node')) : null
    if (!targetNode) {
      const view = approvalCanvasState()
      const snapDistance = 34 / Math.max(view.scale, .2)
      let nearest = null
      for (const candidate of approvalGraphNodes(template.flow)) {
        const position = approvalGraphPosition(candidate)
        if (!position) continue
        const dx = Math.max(position.x - world.x, 0, world.x - (position.x + APPROVAL_GRAPH_NODE_W))
        const dy = Math.max(position.y - world.y, 0, world.y - (position.y + APPROVAL_GRAPH_NODE_H))
        const distance = Math.hypot(dx, dy)
        if (!nearest || distance < nearest.distance) nearest = { candidate, position, distance }
      }
      if (nearest && nearest.distance <= snapDistance) {
        targetElement = shell.querySelector(`[data-wf-node="${nearest.candidate.id}"]`)
        targetNode = nearest.candidate
      }
    }
    if (!targetNode || !targetElement) return null
    let side = ''
    const exactPort = document.elementFromPoint(clientX, clientY)?.closest?.('[data-wf-port-side]')
    if (exactPort && targetElement.contains(exactPort)) side = exactPort.getAttribute('data-wf-port-side') || ''
    if (!APPROVAL_PORT_SIDES.includes(side)) side = approvalNearestPortSide(targetNode, world)
    const issue = approvalDragIssue(template, drag, targetNode.id)
    return {
      id: targetNode.id,
      node: targetNode,
      element: targetElement,
      side,
      valid: !issue,
      reason: issue,
    }
  }

  const paintApprovalDragTarget = (target) => {
    shell.querySelectorAll('.wf-node').forEach((element) => {
      element.classList.remove('is-drop-target', 'is-drop-invalid')
    })
    shell.querySelectorAll('.wf-port').forEach((element) => {
      element.classList.remove('is-target-side', 'is-target-invalid')
    })
    if (!target) return
    target.element.classList.add(target.valid ? 'is-drop-target' : 'is-drop-invalid')
    const sidePort = target.element.querySelector(`.wf-port[data-wf-port-side="${target.side}"]`)
    sidePort?.classList.add(target.valid ? 'is-target-side' : 'is-target-invalid')
  }

  const repaintApprovalEdges = () => {
    const template = approvalTemplateOf()
    const layer = shell.querySelector('[data-wf-edge-layer]')
    const selected = state.approvalEdgeFrom
      ? { from: state.approvalEdgeFrom, to: state.approvalEdgeTo }
      : null
    const drag = state.approvalDrag
    const hidden = drag && (drag.mode === 'edge-target' || drag.mode === 'edge-source')
      ? { from: drag.edgeFrom, to: drag.edgeTo }
      : null
    if (template && layer) layer.innerHTML = approvalGraphEdgeSvg(template.flow, selected, hidden)
  }

  const clearApprovalDrag = () => {
    state.approvalDrag = null
    document.getElementById('wf-drag-guide')?.remove()
    shell.classList.remove('is-wf-linking', 'is-wf-edge-dragging')
    shell.querySelectorAll('.wf-node, .wf-port, .wf-viewport').forEach((element) => {
      element.classList.remove('is-drop-target', 'is-drop-invalid', 'is-dragging', 'is-panning', 'is-target-side', 'is-target-invalid')
    })
    repaintApprovalEdges()
  }

  const paintApprovalDragGuide = (drag, clientX, clientY) => {
    let guide = document.getElementById('wf-drag-guide')
    if (!guide) {
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
      svg.id = 'wf-drag-guide'
      svg.classList.add('wf-drag-guide')
      svg.setAttribute('aria-hidden', 'true')
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line')
      line.classList.add('wf-drag-guide-line')
      const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle')
      dot.classList.add('wf-drag-guide-dot')
      dot.setAttribute('r', '3')
      svg.append(line, dot)
      document.body.append(svg)
      guide = svg
    }
    const line = guide.querySelector('.wf-drag-guide-line')
    const dot = guide.querySelector('.wf-drag-guide-dot')
    line.setAttribute('x1', drag.originX)
    line.setAttribute('y1', drag.originY)
    line.setAttribute('x2', clientX)
    line.setAttribute('y2', clientY)
    dot.setAttribute('cx', clientX)
    dot.setAttribute('cy', clientY)
  }

  const showApprovalUndo = (template, snapshot, message) => {
    const templateId = template.id
    showTopToast(message, {
      tone: 'success',
      duration: 6500,
      action: {
        label: '撤销',
        onClick: () => {
          const current = approvalTemplatesOf().find((item) => item.id === templateId)
          if (!current) return
          const result = approvalStepHistory(current, 'undo')
          if (current.id === state.approvalTemplateId) approvalRerender()
          showTopToast(result.ok ? '已撤销删除' : result.message, result.ok ? { tone: 'success' } : {})
        },
      },
    })
  }

  const deleteApprovalEdgeWithUndo = (template, fromId, toId) => {
    const snapshot = JSON.parse(JSON.stringify(template.flow || []))
    if (!approvalRemoveEdge(template, fromId, toId)) return false
    state.approvalEdgeFrom = ''
    state.approvalEdgeTo = ''
    approvalRerender()
    showApprovalUndo(template, snapshot, '已删除连线，可撤销')
    return true
  }

  shell.addEventListener('pointerdown', (event) => {
    if (event.button !== 0) return
    const template = approvalTemplateOf()
    if (!template) return
    const activeElement = document.activeElement
    if (
      activeElement &&
      shell.contains(activeElement) &&
      activeElement.matches?.('input, textarea, select, [contenteditable="true"]') &&
      !event.target.closest?.('input, textarea, select, [contenteditable="true"]')
    ) {
      activeElement.blur()
    }
    if (state.approvalCanvasMenu && !event.target.closest('[data-wf-canvas-menu]')) approvalCloseCanvasMenu()
    if (event.target.closest('[data-wf-canvas-menu]')) return
    const edgeHandle = event.target.closest('[data-wf-edge-handle]')
    if (edgeHandle) {
      const endpoint = edgeHandle.getAttribute('data-wf-edge-handle')
      const edgeFrom = edgeHandle.getAttribute('data-wf-edge-from')
      const edgeTo = edgeHandle.getAttribute('data-wf-edge-to')
      const layout = approvalEdgeLayouts(template.flow).find((edge) => edge.from === edgeFrom && edge.to === edgeTo)
      if (!endpoint || !layout) return
      event.preventDefault()
      event.stopPropagation()
      try { edgeHandle.setPointerCapture?.(event.pointerId) } catch {}
      const opposite = endpoint === 'to' ? layout.fromPoint : layout.toPoint
      const screen = approvalWorldToClient(opposite)
      state.approvalDrag = {
        mode: endpoint === 'to' ? 'edge-target' : 'edge-source',
        edgeFrom,
        edgeTo,
        endpoint,
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        originX: screen.x,
        originY: screen.y,
        targetId: null,
        active: false,
      }
      shell.classList.add('is-wf-linking')
      return
    }
    const connector = event.target.closest('[data-wf-link-after]')
    if (connector) {
      const sourceId = connector.getAttribute('data-wf-link-after')
      if (!sourceId) return
      event.preventDefault()
      try { connector.setPointerCapture?.(event.pointerId) } catch {}
      const rect = connector.getBoundingClientRect()
      state.approvalDrag = {
        mode: 'link',
        sourceId,
        fromSide: connector.getAttribute('data-wf-port-side') || 'bottom',
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        originX: rect.left + rect.width / 2,
        originY: rect.top + rect.height / 2,
        targetId: null,
        active: false,
      }
      shell.classList.add('is-wf-linking')
      return
    }
    const nodeElement = event.target.closest('[data-wf-node]')
    if (nodeElement) {
      const sourceId = nodeElement.getAttribute('data-wf-node')
      const node = approvalFindNode(template.flow, sourceId)
      const position = approvalGraphPosition(node)
      if (!node || !position) return
      try { nodeElement.setPointerCapture?.(event.pointerId) } catch {}
      state.approvalDrag = {
        mode: 'node',
        sourceId,
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        originNodeX: position.x,
        originNodeY: position.y,
        originX: position.x,
        originY: position.y,
        targetId: null,
        active: false,
      }
      return
    }
    if (event.target.closest('[data-wf-edge-group]')) return
    const viewport = event.target.closest('[data-wf-viewport]')
    if (!viewport) return
    event.preventDefault()
    const view = approvalCanvasState()
    state.approvalPan = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      originX: view.x,
      originY: view.y,
    }
    viewport.classList.add('is-panning')
    try { viewport.setPointerCapture?.(event.pointerId) } catch {}
  })

  shell.addEventListener('pointermove', (event) => {
    const pan = state.approvalPan
    if (pan && event.pointerId === pan.pointerId) {
      const view = approvalCanvasState()
      view.x = pan.originX + event.clientX - pan.startX
      view.y = pan.originY + event.clientY - pan.startY
      approvalApplyCanvasView()
      return
    }
    const drag = state.approvalDrag
    if (!drag || event.pointerId !== drag.pointerId) return
    const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY)
    if (!drag.active && distance < 5) return
    if (!drag.active) {
      drag.active = true
      if (drag.mode === 'link') {
        shell.querySelector(`.wf-port[data-wf-link-after="${drag.sourceId}"]`)?.classList.add('is-dragging')
      } else if (drag.mode === 'edge-target' || drag.mode === 'edge-source') {
        shell.classList.add('is-wf-edge-dragging')
        repaintApprovalEdges()
        shell.querySelector('[data-wf-edge-handles]')?.remove()
      } else {
        shell.querySelector(`[data-wf-node="${drag.sourceId}"]`)?.classList.add('is-dragging')
      }
    }
    event.preventDefault()
    if (drag.mode === 'link' || drag.mode === 'edge-target' || drag.mode === 'edge-source') {
      paintApprovalDragGuide(drag, event.clientX, event.clientY)
      const target = approvalDragTargetAt(event.clientX, event.clientY)
      const key = target ? `${target.id}|${target.side}|${target.valid ? 1 : 0}` : ''
      if (key === drag.targetId) return
      drag.targetId = key
      paintApprovalDragTarget(target)
      return
    }
    const template = approvalTemplateOf()
    const node = template ? approvalFindNode(template.flow, drag.sourceId) : null
    if (!template || !node) return
    const view = approvalCanvasState()
    node.x = Math.max(0, drag.originNodeX + (event.clientX - drag.startX) / view.scale)
    node.y = Math.max(0, drag.originNodeY + (event.clientY - drag.startY) / view.scale)
    const element = shell.querySelector(`[data-wf-node="${drag.sourceId}"]`)
    if (element) {
      element.style.left = `${Math.round(node.x)}px`
      element.style.top = `${Math.round(node.y)}px`
    }
    const stage = shell.querySelector('[data-wf-stage]')
    if (stage) {
      stage.style.width = `${Math.max(parseFloat(stage.style.width) || 1200, node.x + APPROVAL_GRAPH_NODE_W + 280)}px`
      stage.style.height = `${Math.max(parseFloat(stage.style.height) || 760, node.y + APPROVAL_GRAPH_NODE_H + 240)}px`
    }
    repaintApprovalEdges()
  })

  const finishApprovalDrag = (event) => {
    const pan = state.approvalPan
    if (pan && event.pointerId === pan.pointerId) {
      state.approvalPan = null
      shell.querySelector('.wf-viewport.is-panning')?.classList.remove('is-panning')
      return
    }
    const drag = state.approvalDrag
    if (!drag || event.pointerId !== drag.pointerId) return
    if (!drag.active) {
      clearApprovalDrag()
      return
    }
    const template = approvalTemplateOf()
    const mode = drag.mode
    const sourceId = drag.sourceId
    if (mode === 'node') {
      clearApprovalDrag()
      if (!template) return
      const node = approvalFindNode(template.flow, sourceId)
      if (!node) return
      state.approvalNodeId = sourceId
      approvalTouchTemplate(template, { historyLabel: '移动节点' })
      approvalRerender()
      showTopToast('已移动节点位置')
      return
    }
    const target = approvalDragTargetAt(event.clientX, event.clientY)
    clearApprovalDrag()
    if (!template) return
    if (mode === 'edge-target' || mode === 'edge-source') {
      if (target && !target.valid) {
        showTopToast(target.reason || '这个位置不能连接')
        approvalRerender()
        return
      }
      if (!target) {
        deleteApprovalEdgeWithUndo(template, drag.edgeFrom, drag.edgeTo)
        return
      }
      const result = mode === 'edge-target'
        ? approvalReconnectEdgeTarget(template, drag.edgeFrom, drag.edgeTo, target.id, target.side)
        : approvalReconnectEdgeSource(template, drag.edgeFrom, drag.edgeTo, target.id, target.side)
      if (!result.ok) {
        showTopToast(result.message)
        approvalRerender()
        return
      }
      state.approvalEdgeFrom = mode === 'edge-target' ? drag.edgeFrom : target.id
      state.approvalEdgeTo = mode === 'edge-target' ? target.id : drag.edgeTo
      state.approvalNodeId = state.approvalEdgeTo
      approvalRerender()
      showTopToast(result.message)
      return
    }
    if (!target) return
    if (!target.valid) {
      showTopToast(target.reason || '这个位置不能连接')
      return
    }
    const result = approvalConnectNodes(template, sourceId, target.id, {
      fromSide: drag.fromSide,
      toSide: target.side,
    })
    if (!result.ok) {
      showTopToast(result.message)
      return
    }
    state.approvalNodeId = target.id
    state.approvalEdgeFrom = sourceId
    state.approvalEdgeTo = target.id
    approvalRerender()
    showTopToast(result.message)
  }

  shell.addEventListener('pointerup', finishApprovalDrag)
  shell.addEventListener('pointercancel', () => {
    state.approvalPan = null
    clearApprovalDrag()
    approvalRerender()
  })

  const cancelApprovalInteraction = () => {
    const pan = state.approvalPan
    if (pan) {
      const view = approvalCanvasState()
      view.x = pan.originX
      view.y = pan.originY
      state.approvalPan = null
      approvalApplyCanvasView()
    }
    const drag = state.approvalDrag
    if (drag?.mode === 'node') {
      const template = approvalTemplateOf()
      const node = template ? approvalFindNode(template.flow, drag.sourceId) : null
      if (node) {
        node.x = drag.originNodeX
        node.y = drag.originNodeY
      }
    }
    const hadInteraction = Boolean(drag || pan)
    clearApprovalDrag()
    if (hadInteraction) {
      approvalRerender()
      return true
    }
    return false
  }

  if (window.__eabApprovalKeyHandler) {
    document.removeEventListener('keydown', window.__eabApprovalKeyHandler)
  }
  if (window.__eabApprovalPointerHandler) {
    document.removeEventListener('pointerdown', window.__eabApprovalPointerHandler, true)
  }
  // 选中连线会触发重绘并再次 bind，这里只初始化一次，避免重绘时清掉画布焦点。
  if (typeof state.approvalCanvasFocus !== 'boolean') state.approvalCanvasFocus = false
  window.__eabApprovalPointerHandler = (event) => {
    if (!shell.isConnected) return
    state.approvalCanvasFocus = Boolean(event.target?.closest?.('[data-wf-viewport]'))
  }
  document.addEventListener('pointerdown', window.__eabApprovalPointerHandler, true)
  window.__eabApprovalKeyHandler = (event) => {
    if (!shell.isConnected) return
    const focused = document.activeElement
    if (focused && (focused.tagName === 'INPUT' || focused.tagName === 'TEXTAREA' || focused.tagName === 'SELECT' || focused.isContentEditable)) return
    const shortcutContext =
      state.approvalCanvasFocus ||
      Boolean(focused?.closest?.('[data-wf-viewport]')) ||
      Boolean(event.target?.closest?.('[data-wf-viewport]'))
    const commandKey = event.ctrlKey || event.metaKey
    const key = String(event.key || '').toLowerCase()
    if (commandKey && shortcutContext && ['z', 'y', 'c', 'v'].includes(key)) {
      const template = approvalTemplateOf()
      if (key === 'c' && template) {
        const result = approvalCopySelectedNode(template)
        if (result.ok) event.preventDefault()
        showTopToast(result.message)
        return
      }
      if (key === 'v' && template) {
        const result = approvalPasteNode(template)
        if (result.ok) event.preventDefault()
        showTopToast(result.message)
        return
      }
      if ((key === 'z' || key === 'y') && template) {
        event.preventDefault()
        const direction = key === 'y' || event.shiftKey ? 'redo' : 'undo'
        const result = approvalStepHistory(template, direction)
        showTopToast(result.message)
        return
      }
    }
    if (event.key === 'Escape') {
      if (state.approvalDrag || state.approvalPan) {
        event.preventDefault()
        cancelApprovalInteraction()
        return
      }
      if (state.approvalEdgeFrom) {
        state.approvalEdgeFrom = ''
        state.approvalEdgeTo = ''
        approvalRerender()
      }
      return
    }
    if (event.key === 'Delete' && state.approvalCanvasFocus && state.approvalEdgeFrom && state.approvalEdgeTo) {
      const template = approvalTemplateOf()
      if (!template) return
      event.preventDefault()
      deleteApprovalEdgeWithUndo(template, state.approvalEdgeFrom, state.approvalEdgeTo)
    }
  }
  document.addEventListener('keydown', window.__eabApprovalKeyHandler)

  const viewport = shell.querySelector('[data-wf-viewport]')
  if (viewport) {
    viewport.addEventListener('contextmenu', (event) => {
      const template = approvalTemplateOf()
      if (!template || !viewport.contains(event.target)) return
      event.preventDefault()
      approvalOpenCanvasMenu(template, shell, event)
    })
    viewport.addEventListener('wheel', (event) => {
      if (event.target.closest('[data-wf-canvas-menu]')) return
      event.preventDefault()
      if (!event.deltaY) return
      approvalZoomCanvas(Math.exp(-event.deltaY * .0015), event.clientX, event.clientY)
    }, { passive: false })
  }

  const template = approvalTemplateOf()
  if (template) approvalScheduleCanvasView(template)
}

async function loadApprovalRecords() {
  const data = await api('/api/console/permission-requests?mode=all')
  state.approvalRecords = approvalRecordsFromApi(data.requests)
}

/**
 * 管理端权限审批工作台：流程设计 / 审批记录 / 权限目录。
 *
 * 权限目录、角色、默认审批链、流程模板与版本都来自真实控制台接口；
 * 审批记录与同意/拒绝也走真实权限审批接口，不再填充示例数据。
 */
async function loadPermissionPolicies() {
  const view = $('#view')
  renderLoading(view)
  setSide('', true)
  try {
    const [data, workflowData, recordData, membersData, orgTreeData] = await Promise.all([
      api('/api/console/permission-policies'),
      api('/api/console/approval-workflows'),
      api('/api/console/permission-requests?mode=all'),
      api('/api/org/members').catch(() => ({ members: [] })),
      api('/api/org/tree').catch(() => null),
    ])
    if (Array.isArray(membersData.members)) state.approvalMembers = membersData.members
    if (orgTreeData?.root) state.approvalOrgMaxLevels = approvalOrgLevelsOfTree(orgTreeData.root)
    state.approvalData = {
      policies: data.policies ?? [],
      roles: data.roles ?? [],
      scopes: data.scopes ?? [],
      defaultPolicy: data.defaultPolicy ?? null,
    }
    state.approvalTemplates = workflowData.workflows ?? []
    for (const template of state.approvalTemplates) {
      approvalNormalizeLegacySources(template.flow)
      approvalClampLevels(template.flow)
    }
    state.approvalRecords = approvalRecordsFromApi(recordData.requests)
    if (!state.approvalTemplates.some((item) => item.id === state.approvalTemplateId)) {
      state.approvalTemplateId = state.approvalTemplates[0]?.id || ''
    }
    const active = state.approvalTemplates.find((item) => item.id === state.approvalTemplateId)
    if (!approvalFindNode(active?.flow, state.approvalNodeId)) {
      state.approvalNodeId = active?.flow?.[0]?.id || 'start'
    }
    renderApprovalPage()
  } catch (err) {
    renderDenied(view, err)
  }
}


/* ---------------- 模型接入 ---------------- */

const MODEL_CAPABILITY_OPTIONS = [
  { key: 'chat', label: '对话', hint: '通用文本问答' },
  { key: 'reasoning', label: '推理', hint: '多步推理、长思考' },
  { key: 'decision', label: '决策', hint: '路由、判定、选择' },
  { key: 'vision', label: '图片识别', hint: '读取图片内容' },
  { key: 'multimodal', label: '多模态', hint: '文本 + 图片联合输入' },
  { key: 'code', label: '代码', hint: '代码生成与审查' },
  { key: 'tool', label: '工具调用', hint: 'function calling' },
  { key: 'embedding', label: '向量', hint: 'embedding / 检索' },
  { key: 'rerank', label: '重排', hint: 'rerank / 检索结果重排' },
  { key: 'audio', label: '语音', hint: '转写、合成、语音问答' },
  { key: 'video', label: '视频', hint: '视频理解与抽帧' },
  { key: 'long_context', label: '长文本', hint: '超长上下文' },
  { key: 'fast', label: '快速', hint: '低延迟短任务' },
]

const MODEL_CAPABILITY_KEYS = new Set(MODEL_CAPABILITY_OPTIONS.map((item) => item.key))
const MODEL_CAPABILITY_ALIASES = {
  image: 'vision',
  visual: 'vision',
  reranker: 'rerank',
  reranking: 'rerank',
  'multi_modal': 'multimodal',
  multimodal_input: 'multimodal',
  think: 'reasoning',
  thinking: 'reasoning',
  r1: 'reasoning',
  function_calling: 'tool',
  tools: 'tool',
  embed: 'embedding',
  long_context: 'long_context',
  'long_context_window': 'long_context',
  longcontext: 'long_context',
  longtext: 'long_context',
  speech: 'audio',
  asr: 'audio',
  tts: 'audio',
  video_understanding: 'video',
  '图片': 'vision',
  '图片识别': 'vision',
  '视觉': 'vision',
  '多模态': 'multimodal',
  '推理': 'reasoning',
  '决策': 'decision',
  '对话': 'chat',
  '代码': 'code',
  '工具调用': 'tool',
  '向量': 'embedding',
  '语音': 'audio',
  '视频': 'video',
  '长文本': 'long_context',
  '快速': 'fast',
}

function normalizeModelTags(tags = []) {
  const keys = []
  const extras = []
  for (const raw of tags || []) {
    const value = String(raw || '').trim()
    if (!value) continue
    const normalized = value.toLowerCase().replace(/[-\s]+/g, '_')
    const key = MODEL_CAPABILITY_ALIASES[normalized] || normalized
    if (MODEL_CAPABILITY_KEYS.has(key)) {
      if (!keys.includes(key)) keys.push(key)
    } else if (!extras.includes(value)) {
      extras.push(value)
    }
  }
  return { keys, extras }
}

function modelCapabilitySummary(tags = []) {
  const { keys, extras } = normalizeModelTags(tags)
  const known = keys
    .map((key) => MODEL_CAPABILITY_OPTIONS.find((item) => item.key === key))
    .filter(Boolean)
  return {
    keys,
    extras,
    labels: [...known.map((item) => item.label), ...extras],
  }
}

function modelTypeOf(tags = []) {
  const caps = modelCapabilitySummary(tags)
  const keys = caps.keys
  const labels = []
  if (keys.includes('embedding')) labels.push('向量')
  if (keys.includes('rerank')) labels.push('重排')
  if (keys.includes('vision') || keys.includes('multimodal')) labels.push('多模态')
  if (keys.includes('decision')) labels.push('决策')
  else if (keys.includes('reasoning')) labels.push('推理')
  if (keys.includes('code')) labels.push('代码')
  if (keys.includes('audio')) labels.push('语音')
  if (keys.includes('video')) labels.push('视频')
  if (labels.length === 0 && keys.includes('chat')) labels.push('对话')
  if (labels.length === 0 && caps.extras.length) labels.push('自定义')
  if (labels.length === 0) return { label: '未标注', tone: 'is-muted' }
  const first = keys.includes('embedding') || keys.includes('rerank')
    ? 'is-embedding'
    : keys.includes('vision') || keys.includes('multimodal')
      ? 'is-vision'
      : keys.includes('decision') || keys.includes('reasoning')
        ? 'is-decision'
        : keys.includes('code')
          ? 'is-code'
          : keys.includes('audio') || keys.includes('video')
            ? 'is-audio'
            : 'is-chat'
  return { label: labels.slice(0, 2).join(' · '), tone: first }
}

function endpointKindLabel(kind) {
  const labels = {
    chat: '对话',
    systemone: 'SystemOne',
    embeddings: '向量',
    rerank: '重排',
    asr: '语音转写',
    tts: '语音合成',
    image: '图片生成',
    video: '视频理解',
    audio: '语音',
  }
  return labels[kind] || kind || ''
}

function modelSupportsRoutePurpose(model, purpose) {
  const capabilities = model?.capabilities?.length ? model.capabilities : model?.tags || []
  const endpointKind = model?.endpointKind || 'chat'
  if (purpose === 'chat.default') return capabilities.includes('chat') && endpointKind === 'chat'
  if (purpose === 'chat.vision') {
    return (capabilities.includes('vision') || capabilities.includes('multimodal')) && endpointKind === 'chat'
  }
  if (purpose === 'router.intent') {
    return (
      (capabilities.includes('decision') ||
        capabilities.includes('reasoning') ||
        capabilities.includes('chat')) &&
      endpointKind === 'chat'
    )
  }
  if (purpose === 'agent.model_choice') {
    return (
      (capabilities.includes('decision') ||
        capabilities.includes('reasoning') ||
        capabilities.includes('chat')) &&
      endpointKind === 'systemone'
    )
  }
  if (purpose === 'kb.embed') return capabilities.includes('embedding') || endpointKind === 'embeddings'
  if (purpose === 'kb.rerank') return endpointKind === 'rerank'
  if (purpose === 'asr.default') return endpointKind === 'asr'
  if (purpose === 'tts.default') return endpointKind === 'tts'
  if (purpose === 'image.default') return endpointKind === 'image'
  if (purpose === 'video.analyze') return endpointKind === 'video' || capabilities.includes('video')
  return false
}

function capabilityChipTone(key) {
  if (key === 'vision' || key === 'multimodal') return 'is-vision'
  if (key === 'decision' || key === 'reasoning') return 'is-decision'
  if (key === 'embedding' || key === 'rerank') return 'is-embedding'
  if (key === 'code') return 'is-code'
  if (key === 'audio' || key === 'video') return 'is-audio'
  return ''
}

function capabilityChipsHtml(tags = [], limit = 3) {
  const caps = modelCapabilitySummary(tags)
  if (caps.labels.length === 0) return '<span class="models-cap-empty">点击设置能力</span>'
  const shown = caps.labels.slice(0, limit)
  const knownItems = caps.keys
    .map((key) => MODEL_CAPABILITY_OPTIONS.find((item) => item.key === key))
    .filter(Boolean)
  return (
    shown
      .map((label, index) => {
        const tone = capabilityChipTone(knownItems[index]?.key)
        return `<span class="models-cap-chip ${tone}">${esc(label)}</span>`
      })
      .join('') + (caps.labels.length > limit ? `<span class="models-cap-more">+${caps.labels.length - limit}</span>` : '')
  )
}

function modelFormType(tags = [], endpointKind = '') {
  if (endpointKind === 'image') return 'image'
  const keys = modelCapabilitySummary(tags).keys
  if (keys.includes('rerank')) return 'rerank'
  if (keys.includes('embedding')) return 'embedding'
  if (keys.includes('vision') || keys.includes('multimodal')) return 'vision'
  if (keys.includes('video')) return 'video'
  if (keys.includes('audio')) return 'audio'
  if (keys.includes('decision') || keys.includes('reasoning')) return 'decision'
  if (keys.includes('chat')) return 'chat'
  return 'custom'
}

function capabilityOptionsHtml(tags = []) {
  const caps = normalizeModelTags(tags)
  return (
    MODEL_CAPABILITY_OPTIONS.map(
      (item) => `<label class="models-cap-option ${caps.keys.includes(item.key) ? 'is-on' : ''}">
        <input type="checkbox" data-cap-key="${item.key}"${caps.keys.includes(item.key) ? ' checked' : ''} />
        <span><strong>${esc(item.label)}</strong><small>${esc(item.hint)}</small></span>
      </label>`,
    ).join('') +
    caps.extras
      .map(
        (value) => `<label class="models-cap-option is-on">
          <input type="checkbox" data-cap-extra="${esc(value)}" checked />
          <span><strong>${esc(value)}</strong><small>自定义标签</small></span>
        </label>`,
      )
      .join('')
  )
}

function confirmCard({
  title = '确认操作',
  message = '',
  detail = '',
  confirmText = '确定',
  cancelText = '取消',
  tone = 'danger',
  requireText = '',
  requireHint = '',
} = {}) {
  return new Promise((resolve) => {
    const previousFocus = document.activeElement
    const overlay = document.createElement('div')
    overlay.className = 'modal-overlay confirm-overlay'
    const toneClass = tone === 'warning' ? ' is-warning' : tone === 'brand' ? ' is-brand' : ' is-danger'
    const icon =
      tone === 'warning'
        ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 9v4m0 3h.01M10.29 3.86 1.82 17a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/></svg>'
        : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2m-9 0 1 13h8l1-13M10 11v5m4-5v5"/></svg>'
    overlay.innerHTML = `<div class="confirm-card${toneClass}" data-eab-focus-owned="1" role="dialog" aria-modal="true" aria-labelledby="confirm-title">
      <div class="confirm-head">
        <span class="confirm-icon">${icon}</span>
        <div class="confirm-copy">
          <h3 id="confirm-title">${esc(title)}</h3>
          <p class="confirm-message">${esc(message)}</p>
          ${detail ? `<div class="confirm-detail">${esc(detail)}</div>` : ''}
          ${
            requireText
              ? `<label class="confirm-field"><span>${esc(requireHint || `请输入「${requireText}」确认`)}</span><input data-confirm-input autocomplete="off" placeholder="${esc(requireText)}" /></label>`
              : ''
          }
        </div>
      </div>
      <div class="confirm-actions">
        <button class="btn ghost" type="button" data-confirm-cancel>${esc(cancelText)}</button>
        <button class="btn ${tone === 'warning' ? 'confirm-warning' : tone === 'brand' ? 'primary' : 'danger'}" type="button" data-confirm-ok${requireText ? ' disabled' : ''}>${esc(confirmText)}</button>
      </div>
    </div>`
    document.body.appendChild(overlay)
    document.body.classList.add('eab-modal-open')
    const finish = (value) => {
      if (value) {
        const actionText = DELETE_ACTION_FEEDBACK.test(confirmText) ? confirmText : title
        if (DELETE_ACTION_FEEDBACK.test(actionText)) armDeleteFeedback(actionText)
      }
      document.removeEventListener('keydown', onKey)
      overlay.remove()
      document.body.classList.remove('eab-modal-open')
      if (previousFocus instanceof HTMLElement && previousFocus.isConnected && !previousFocus.closest('[hidden]')) {
        previousFocus.focus({ preventScroll: true })
      }
      resolve(value)
    }
    const onKey = (event) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        finish(false)
        return
      }
      if (event.key !== 'Tab') return
      const focusables = [...overlay.querySelectorAll('button:not([disabled]), input:not([disabled])')]
      if (!focusables.length) return
      const first = focusables[0]
      const last = focusables[focusables.length - 1]
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }
    overlay.addEventListener('click', (event) => {
      if (event.target === overlay && tone !== 'danger') finish(false)
    })
    overlay.querySelector('[data-confirm-cancel]').addEventListener('click', () => finish(false))
    const okButton = overlay.querySelector('[data-confirm-ok]')
    okButton.addEventListener('click', () => finish(true))
    const input = overlay.querySelector('[data-confirm-input]')
    if (input) {
      const sync = () => {
        okButton.disabled = input.value.trim() !== requireText
      }
      input.addEventListener('input', sync)
      input.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' && !okButton.disabled) {
          event.preventDefault()
          finish(true)
        }
      })
      sync()
    }
    document.addEventListener('keydown', onKey)
    ;(input || overlay.querySelector('[data-confirm-cancel]')).focus()
  })
}

function modelModal(html) {
  const overlay = document.createElement('div')
  overlay.className = 'modal-overlay'
  overlay.innerHTML = `<div class="modal">${html}</div>`
  const modal = overlay.querySelector('.modal')
  if (modal) {
    modal.setAttribute('role', 'dialog')
    modal.setAttribute('aria-modal', 'true')
    const title = modal.querySelector('.modal-head h3, .modal-head h2, h3, h2')?.textContent?.trim()
    modal.setAttribute('aria-label', title || '对话框')
  }
  document.body.appendChild(overlay)
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) overlay.remove()
  })
  overlay.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape') return
    if (document.querySelector('[role="dialog"][aria-modal="true"][data-eab-focus-owned="1"]')) return
    overlay.remove()
  })
  return overlay
}

function agentRunStatus(status) {
  return {
    succeeded: { text: '成功', className: 'ok' },
    failed: { text: '失败', className: 'warn' },
    cancelled: { text: '已取消', className: 'warn' },
    suspended: { text: '挂起 · 等后台工具', className: 'warn' },
  }[status] ?? { text: '运行中', className: 'warn' }
}

function agentDuration(ms) {
  const seconds = Math.max(0, Math.round((Number(ms) || 0) / 1000))
  if (seconds < 60) return `${seconds} 秒`
  const minutes = Math.floor(seconds / 60)
  const rest = seconds % 60
  if (minutes < 60) return rest ? `${minutes} 分 ${rest} 秒` : `${minutes} 分`
  const hours = Math.floor(minutes / 60)
  const minuteRest = minutes % 60
  return minuteRest ? `${hours} 小时 ${minuteRest} 分` : `${hours} 小时`
}

function agentRunDetailHtml(detail) {
  const runs = Array.isArray(detail?.runs) ? detail.runs : []
  const selected = runs.find((run) => run.selected) ?? runs[0] ?? null
  const stats = detail?.stats ?? {}
  const selectedStatus = selected ? agentRunStatus(selected.status) : { text: '—', className: '' }
  const nodes = runs.map((run) => {
    const status = agentRunStatus(run.status)
    const steps = Array.isArray(run.steps) ? run.steps : []
    const formation = run.formation && typeof run.formation === 'object' ? run.formation : null
    const formationLabel = formation
      ? formation.applied
        ? '已强制编队'
        : formation.force
          ? '判定可编队，但被运行时条件拦截'
          : '未强制编队'
      : ''
    const formationMeta = formation
      ? [
        formation.spawnedAgents === undefined ? '' : `实际派出 ${formation.spawnedAgents} 个`,
        formation.blockedBy?.length ? `拦截条件：${formation.blockedBy.join('、')}` : '',
      ].filter(Boolean).join(' · ')
      : ''
    const stepHtml = steps.length
      ? steps.map((step) => {
        const args = step.args === null || step.args === undefined
          ? ''
          : typeof step.args === 'string'
            ? step.args
            : JSON.stringify(step.args, null, 2)
        return `<div class="agent-run-step">
          <div class="agent-run-step-head">
            <span class="agent-run-step-index">${step.seq + 1}</span>
            <strong>${esc(step.name ?? step.toolId ?? step.kind)}</strong>
            <span class="pill ${step.status === 'done' ? 'ok' : step.status === 'error' ? 'warn' : ''}">${esc(step.status)}</span>
            <span class="desc">${esc(step.kind)}${step.toolId ? ` · ${esc(step.toolId)}` : ''} · ${agentDuration(step.durationMs)}</span>
          </div>
          ${args ? `<div class="agent-run-step-io"><span>参数</span><pre class="agent-run-code">${esc(args)}</pre></div>` : ''}
          ${step.resultSummary ? `<div class="agent-run-step-io"><span>结果</span><pre class="agent-run-code">${esc(step.resultSummary)}</pre></div>` : ''}
        </div>`
      }).join('')
      : '<div class="agent-run-empty">这个 Agent 还没有记录工具或模型步骤。</div>'
    return `<article class="agent-run-node${run.selected ? ' is-selected' : ''}" style="--agent-depth:${Math.max(0, Math.min(20, Number(run.depth) || 0))}">
      <div class="agent-run-node-main">
        <div class="agent-run-node-title">
          <span class="agent-run-branch">${run.depth ? '↳' : '●'}</span>
          <div>
            <strong>${esc(run.title ?? run.agentId)}</strong>
            <div class="desc">${esc(run.agentId)} · run ${esc(run.id)} · ${esc(run.modelId ?? '未记录模型')}</div>
          </div>
        </div>
        <div class="agent-run-node-meta">
          <span class="pill ${status.className}">${status.text}</span>
          <span>${agentDuration((run.endedAt ?? Date.now()) - run.startedAt)}</span>
          <span>${fmtNum(run.spentTokens ?? 0)}${run.budget ? ` / ${fmtNum(run.budget)}` : ''} token</span>
          <span>${steps.length} 步</span>
        </div>
      </div>
      ${run.error ? `<div class="agent-run-error"><strong>失败原因</strong><span>${esc(run.error)}</span></div>` : ''}
      ${formation ? `<div class="agent-run-formation${formation.applied ? ' is-on' : ''}">
        <div class="agent-run-formation-head"><strong>编队门禁 · ${esc(formationLabel)}</strong>${formationMeta ? `<span>${esc(formationMeta)}</span>` : ''}</div>
        <p>${esc(formation.detail || '未记录编队理由')}</p>
        ${formation.signals?.length ? `<div class="agent-run-formation-signals">${formation.signals.map((signal) => `<span>${esc(signal)}</span>`).join('')}</div>` : ''}
      </div>` : ''}
      <details class="agent-run-steps"${run.selected ? ' open' : ''}>
        <summary>${steps.length ? `${steps.length} 步工具 / 模型轨迹` : '暂无步骤'}</summary>
        ${stepHtml}
      </details>
    </article>`
  }).join('')

  return `<div class="agent-run-detail-head">
    <div>
      <span class="agent-run-detail-kicker">任务详情</span>
      <strong>${esc(selected?.title ?? '运行详情')}</strong>
      <div class="desc">根任务 ${esc(detail?.rootId ?? '—')}${detail?.truncated ? ' · 记录超过 200 条，只展示前 200 条' : ''}</div>
    </div>
    <div class="agent-run-detail-actions">
      <span class="pill ${selectedStatus.className}">${selectedStatus.text}</span>
      <button class="btn sm ghost" type="button" id="agent-run-detail-refresh">刷新</button>
    </div>
  </div>
  <div class="agent-run-summary">
    <div><span>父子运行</span><strong>${fmtNum(stats.totalRuns ?? runs.length)} 个</strong><span class="desc">运行中 ${fmtNum(stats.activeRuns ?? 0)} · 失败 ${fmtNum(stats.failedRuns ?? 0)}</span></div>
    <div><span>总墙钟</span><strong>${agentDuration(stats.wallMs ?? 0)}</strong><span class="desc">各 Agent 耗时合计 ${agentDuration(stats.totalDurationMs ?? 0)}</span></div>
    <div><span>总 Token</span><strong>${fmtNum(stats.totalTokens ?? 0)}</strong><span class="desc">父子树合计</span></div>
    <div><span>工具 / 模型步</span><strong>${fmtNum(stats.totalSteps ?? 0)} 步</strong><span class="desc">参数、结果摘要与耗时都在下面</span></div>
  </div>
  ${!runs.length ? '<div class="agent-run-empty">没有找到这棵运行树。</div>' : `<div class="agent-run-tree">${nodes}</div>`}`
}

async function openAgentRunDetail(runId) {
  if (!runId) return
  const trigger = document.activeElement
  document.querySelectorAll('.modal-overlay.agent-run-detail-overlay').forEach((node) => node.remove())
  const overlay = modelModal(`<div class="modal-head">
    <div><h3>运行详情</h3><div class="desc" id="agent-run-detail-sub">父任务 → 子 Agent → 工具轨迹</div></div>
    <button class="modal-x" type="button" aria-label="关闭运行详情">×</button>
  </div>
  <div class="agent-run-detail-body" id="agent-run-detail-body" aria-live="polite">
    <div class="agent-run-empty">正在读取运行详情…</div>
  </div>`)
  overlay.classList.add('agent-run-detail-overlay')
  overlay.querySelector('.modal').classList.add('agent-run-detail-modal')
  const body = overlay.querySelector('#agent-run-detail-body')
  let generation = 0

  const restoreFocus = () => {
    if (trigger && typeof trigger.focus === 'function' && trigger.isConnected) trigger.focus()
  }
  const close = () => {
    generation += 1
    overlay.remove()
    restoreFocus()
  }
  overlay.querySelector('.modal-x')?.addEventListener('click', close)
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) restoreFocus()
  })
  document.addEventListener('keydown', function onKey(event) {
    if (!overlay.isConnected) {
      document.removeEventListener('keydown', onKey)
      return
    }
    if (event.key === 'Escape') close()
  })

  async function load() {
    const current = ++generation
    try {
      const detail = await api(`/api/console/agent-runs/${encodeURIComponent(runId)}`)
      if (current !== generation || !overlay.isConnected) return
      body.innerHTML = agentRunDetailHtml(detail)
      body.querySelector('#agent-run-detail-refresh')?.addEventListener('click', () => {
        body.innerHTML = '<div class="agent-run-empty">正在刷新运行详情…</div>'
        void load()
      })
    } catch (error) {
      if (current !== generation || !overlay.isConnected) return
      renderConsoleError(body, error, () => {
        body.innerHTML = '<div class="agent-run-empty">正在重新读取运行详情…</div>'
        void load()
      })
    }
  }
  void load()
  overlay.querySelector('.modal-x')?.focus()
}

function fieldInfo(text) {
  return hintBadge('i', text, text, 'icon-only')
}

async function openProviderModal(provider) {
  const kinds = await api('/api/console/model-kinds')
  const cloudKinds = kinds.kinds.filter((item) => !['ollama', 'vllm', 'lmstudio', 'demo'].includes(item.kind))
  const localKinds = kinds.kinds.filter((item) => ['ollama', 'vllm', 'lmstudio'].includes(item.kind))
  const option = (item) =>
    `<option value="${item.kind}" data-base="${esc(item.defaultBaseUrl)}"${
      provider && provider.kind === item.kind ? ' selected' : ''
    }>${esc(item.label)}</option>`
  const overlay = modelModal(`
    <div class="modal-head"><h3>${provider ? '编辑供应商' : '添加供应商'}</h3><button class="modal-x" type="button">×</button></div>
    ${hintNote('接入说明', '任意 OpenAI 兼容、Anthropic、Gemini、Azure 或本地推理服务都能接入；保存后会尝试读取 /models，读不到也能手动添加模型。密钥只写入服务器 .eab-dev/secrets.json 或环境变量，不写数据库、不在页面回显；本地 Ollama / vLLM / LM Studio 一般不需要密钥。')}
    <div class="field-stack">
      <label class="field"><span>供应商类型</span><select id="p-kind">
        <optgroup label="云端厂商">${cloudKinds.map(option).join('')}</optgroup>
        <optgroup label="本地模型">${localKinds.map(option).join('')}</optgroup>
      </select></label>
      <label class="field"><span>显示名称</span><input id="p-name" value="${esc(provider?.name ?? '')}" placeholder="例如 DeepSeek 主力 / 本地 Qwen" /></label>
      <label class="field"><span>Base URL</span><input id="p-base" class="mono" value="${esc(provider?.baseUrl ?? '')}" placeholder="选择类型后自动填入，本地模型不要填公网地址" /></label>
      <label class="field"><span>API Key ${provider ? '（留空则不修改）' : ''}</span><input id="p-key" type="password" autocomplete="off" placeholder="直接粘贴密钥，保存到服务器本地密钥文件，不回显" /></label>
      <label class="field"><span>密钥引用名（可选）</span><input id="p-env" class="mono" value="${esc(provider?.apiKeyEnv ?? '')}" placeholder="例如 DEEPSEEK_API_KEY；留空自动生成" /></label>
    </div>
    <div class="modal-state" id="p-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="p-save">保存</button>
      <button class="btn ghost" type="button" id="p-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#p-cancel').addEventListener('click', close)
  const kind = overlay.querySelector('#p-kind')
  const base = overlay.querySelector('#p-base')
  kind.addEventListener('change', () => {
    const preset = kind.selectedOptions[0]?.dataset.base || ''
    if (preset) base.value = preset
  })
  overlay.querySelector('#p-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#p-state')
    stateEl.textContent = '保存中…'
    try {
      const body = {
        kind: kind.value,
        name: overlay.querySelector('#p-name').value.trim(),
        baseUrl: base.value.trim(),
        apiKey: overlay.querySelector('#p-key').value.trim(),
        apiKeyEnv: overlay.querySelector('#p-env').value.trim(),
      }
      const saved = provider
        ? await apiSend('PATCH', `/api/console/providers/${encodeURIComponent(provider.id)}`, body)
        : await apiPost('/api/console/providers', body)
      close()
      await loadModels()
      const savedProvider = saved?.provider ?? provider
      if (savedProvider && (savedProvider.kind !== 'demo' || savedProvider.baseUrl)) {
        await discoverProviderModels(savedProvider)
      }
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
}

async function discoverProviderModels(provider) {
  const msg = $('#provider-test-msg')
  if (msg) msg.textContent = `正在读取「${provider.name}」的模型清单…`
  try {
    const data = await api(`/api/console/providers/${encodeURIComponent(provider.id)}/models`)
    if (msg) msg.textContent = data.models.length ? data.message : `✗ ${data.message}`
    if (!data.models.length) return
    openModelImportModal(provider, data)
  } catch (err) {
    if (msg) msg.textContent = `✗ 模型清单检测失败：${err.message || '未知错误'}`
    else alert(`模型清单检测失败：${err.message || '未知错误'}`)
  }
}

function openModelImportModal(provider, data) {
  const importTypes = {
    chat: { label: '对话', caps: ['chat'], endpoint: 'chat', api: 'POST /chat/completions' },
    systemone: { label: '决策 / SystemOne', caps: ['chat', 'reasoning', 'decision'], endpoint: 'systemone', api: 'POST /systemone' },
    decision: { label: '决策 / 推理', caps: ['chat', 'reasoning', 'decision'], endpoint: 'chat', api: 'POST /chat/completions' },
    vision: { label: '多模态', caps: ['chat', 'vision', 'multimodal'], endpoint: 'chat', api: 'POST /chat/completions' },
    embedding: { label: '向量', caps: ['embedding'], endpoint: 'embeddings', api: 'POST /embeddings' },
    rerank: { label: '重排序', caps: ['rerank'], endpoint: 'rerank', api: 'POST /rerank' },
    asr: { label: '语音转写', caps: ['audio'], endpoint: 'asr', api: 'POST /audio/transcriptions' },
    tts: { label: '语音合成', caps: ['audio'], endpoint: 'tts', api: 'POST /audio/speech' },
    video: { label: '视频理解', caps: ['video'], endpoint: 'video', api: 'POST /video/analyze' },
  }
  const suggestionOf = (model) => {
    const suggested = model.suggested || {}
    const endpoint = suggested.endpointKind || 'chat'
    const type =
      endpoint === 'asr'
        ? 'asr'
        : endpoint === 'tts'
          ? 'tts'
          : endpoint === 'systemone'
            ? 'systemone'
            : importTypes[suggested.modelType]
              ? suggested.modelType
              : endpoint === 'embeddings'
              ? 'embedding'
              : endpoint === 'rerank'
                ? 'rerank'
                : endpoint === 'video'
                  ? 'video'
                  : 'chat'
    return {
      type,
      label: suggested.label || importTypes[type].label,
      endpoint,
      api: suggested.api?.path || importTypes[type].api.replace(/^POST /, ''),
      confidence: suggested.confidence || 'low',
      basis: suggested.basis || '按模型名推断',
    }
  }

  const overlay = modelModal(`
    <div class="modal-head">
      <div class="models-modal-title">
        <h3>发现 ${data.models.length} 个模型 ${hintBadge('导入说明', '类型是按模型名推断的，不是协议探测，可逐条修改；点保存后才会写入模型列表。', '模型导入说明')}</h3>
        <small class="model-import-source">来源 <span class="mono">${esc(data.baseUrl)}/models</span> · 勾选后加入「${esc(
      provider.name,
    )}」</small>
      </div>
      <button class="modal-x" type="button">×</button>
    </div>
    <div class="model-import-toolbar">
      <input class="model-import-search" id="imp-search" type="search" placeholder="搜索模型…（名称或类型）" aria-label="搜索待导入模型" autocomplete="off" />
      <span class="model-import-count" id="imp-count"></span>
      <button class="link-btn" type="button" id="imp-all">全选</button>
      <button class="link-btn" type="button" id="imp-none">全不选</button>
    </div>
    <div class="model-import-list">
      ${data.models
        .map((model, index) => {
          const suggested = suggestionOf(model)
          const search = [model.id, model.label, suggested.label].filter(Boolean).join(' ')
          return `<div class="model-import-row" data-import-item data-search="${esc(search)}">
            <input type="checkbox" id="imp-row-${index}" data-import-key="${esc(model.id)}" checked />
            <label class="model-import-main" for="imp-row-${index}">
              <strong class="mono">${esc(model.id)}</strong>
              <small>${model.label ? `${esc(model.label)} · ` : ''}${esc(suggested.label)} · ${esc(suggested.basis)}</small>
            </label>
            <div class="model-import-side">
              <select data-import-type="${index}" data-import-key="${esc(model.id)}" aria-label="${esc(model.id)} 的类型">
                ${Object.entries(importTypes)
                  .map(
                    ([value, meta]) =>
                      `<option value="${value}"${value === suggested.type ? ' selected' : ''}>${esc(meta.label)}</option>`,
                  )
                  .join('')}
              </select>
              <small class="mono" data-import-api="${index}">POST ${esc(suggested.api)}</small>
            </div>
          </div>`
        })
        .join('')}
      <div class="model-import-empty" id="imp-empty" hidden>没有匹配的模型，换个关键词试试</div>
    </div>
    <div class="modal-state" id="imp-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="imp-save">加入模型列表</button>
      <button class="btn ghost" type="button" id="imp-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#imp-cancel').addEventListener('click', close)

  const rows = [...overlay.querySelectorAll('[data-import-item]')]
  const checks = [...overlay.querySelectorAll('[data-import-key][type="checkbox"]')]
  const typeSelects = [...overlay.querySelectorAll('[data-import-type]')]
  const save = overlay.querySelector('#imp-save')
  const count = overlay.querySelector('#imp-count')
  const search = overlay.querySelector('#imp-search')
  const empty = overlay.querySelector('#imp-empty')
  const visibleChecks = () => checks.filter((input) => !input.closest('[data-import-item]').hidden)
  const update = () => {
    const selected = checks.filter((input) => input.checked).length
    const filtered = rows.filter((row) => !row.hidden).length
    count.textContent = search.value.trim()
      ? `已选 ${selected} / 共 ${checks.length} · 筛选出 ${filtered}`
      : `已选 ${selected} / 共 ${checks.length}`
    save.disabled = selected === 0
  }
  // 模糊搜索：忽略大小写、空格分词，全部命中才显示；只切 hidden，已勾选状态不受影响
  const applyFilter = () => {
    const tokens = search.value.trim().toLowerCase().split(/\s+/).filter(Boolean)
    let shown = 0
    for (const row of rows) {
      const hay = String(row.dataset.search || '').toLowerCase()
      const hit = tokens.every((token) => hay.includes(token))
      row.hidden = !hit
      if (hit) shown += 1
    }
    empty.hidden = !(rows.length > 0 && shown === 0)
    update()
  }
  search.addEventListener('input', applyFilter)
  search.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape' || !search.value) return
    event.stopPropagation()
    search.value = ''
    applyFilter()
  })
  for (const input of checks) input.addEventListener('change', update)
  for (const select of typeSelects) {
    select.addEventListener('change', () => {
      const index = select.dataset.importType
      const api = overlay.querySelector(`[data-import-api="${index}"]`)
      const meta = importTypes[select.value]
      if (api && meta) api.textContent = `POST ${meta.api.replace(/^POST /, '')}`
    })
  }
  overlay.querySelector('#imp-all').addEventListener('click', () => {
    for (const input of visibleChecks()) input.checked = true
    update()
  })
  overlay.querySelector('#imp-none').addEventListener('click', () => {
    for (const input of visibleChecks()) input.checked = false
    update()
  })
  update()

  save.addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#imp-state')
    const keys = checks.filter((input) => input.checked).map((input) => input.dataset.importKey)
    const models = keys.map((modelKey) => {
      const select = typeSelects.find((item) => item.dataset.importKey === modelKey)
      const meta = importTypes[select?.value] || importTypes.chat
      return { modelKey, capabilities: meta.caps, endpointKind: meta.endpoint }
    })
    stateEl.className = 'modal-state'
    stateEl.textContent = '写入中…'
    try {
      const result = await apiPost(`/api/console/providers/${encodeURIComponent(provider.id)}/models/import`, {
        models,
      })
      close()
      await loadModels()
      const msg = $('#provider-test-msg')
      if (msg) msg.textContent = `✓ ${result.message}`
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '写入失败'
    }
  })
}

async function openModelModal(model, providers, roles) {
  const activeProviders = providers.filter((item) => item.status === 'active')
  if (activeProviders.length === 0) {
    alert('先添加一个供应商，再添加模型')
    return
  }
  const initialTags = model?.tags || []
  const defaultRoleCodes = roles.some((role) => role.code === 'member')
    ? ['member']
    : roles.slice(0, 1).map((role) => role.code)
  const initialRoleCodes = model ? model.roles || [] : defaultRoleCodes
  const initialThinking =
    model?.thinking && model.thinking.enabled && Array.isArray(model.thinking.options)
      ? model.thinking
      : null
  const initialThinkOptions = initialThinking?.options?.length
    ? initialThinking.options.map((item) => ({
        id: String(item.id || ''),
        label: String(item.label || item.name || item.id || ''),
        hint: String(item.hint || item.description || ''),
        wire: String(item.wire || ''),
        budget: item.budget === null || item.budget === undefined ? null : Number(item.budget),
      }))
    : THINKING_LEVELS.map((item) => ({ ...item }))
  const initialThinkDefault = initialThinking?.defaultEffort || 'balanced'
  const initialThinkStrategy = initialThinking?.strategy === 'budget' ? 'budget' : 'effort'
  const initialThinkDefaultId = initialThinkOptions.some((item) => item.id === initialThinkDefault)
    ? initialThinkDefault
    : initialThinkOptions[0]?.id || ''
  const thinkRowHtml = (option, isDefault) => `<div class="models-think-row" data-think-row>
    <div class="models-think-row-main">
      <label class="field"><span>ID</span><input class="mono" data-think-field="id" value="${esc(option.id || '')}" placeholder="例如 low" maxlength="40" /></label>
      <label class="field"><span>显示名</span><input data-think-field="label" value="${esc(option.label || '')}" placeholder="例如 精简" maxlength="40" /></label>
      <label class="models-think-default-pick" title="员工打开对话时默认选中的档位">
        <input type="radio" name="m-think-default"${isDefault ? ' checked' : ''} />
        <span>默认</span>
      </label>
      <button class="btn ghost sm models-think-remove" type="button" data-think-remove>移除</button>
    </div>
    <div class="models-think-row-sub">
      <label class="field"><span>说明</span><input data-think-field="hint" value="${esc(option.hint || '')}" placeholder="展示给员工的说明" maxlength="120" /></label>
      <label class="field"><span>上游值</span><input class="mono" data-think-field="wire" value="${esc(option.wire || '')}" placeholder="low / medium / xhigh" maxlength="20" /></label>
      <label class="field"><span>输出预算</span><input data-think-field="budget" type="number" min="1" step="1" value="${option.budget ?? ''}" placeholder="留空不限" /></label>
    </div>
  </div>`
  const initialThinkRowsHtml = initialThinkOptions
    .map((option, index) => thinkRowHtml(option, option.id === initialThinkDefaultId || (index === 0 && !initialThinkDefaultId)))
    .join('')
  const overlay = modelModal(`
    <div class="modal-head">
      <div class="models-modal-title">
        <h3>${model ? '编辑模型' : '添加模型'}</h3>
      </div>
      <button class="modal-x" type="button">×</button>
    </div>
    <div class="models-modal-body">
      <section class="models-form-section">
        <div class="models-form-section-head">
          <strong>基础信息</strong>
          ${fieldInfo('模型在目录里怎么显示，以及由哪个供应商提供。')}
        </div>
        <div class="form-cols">
          <label class="field"><span>显示名</span><input id="m-name" value="${esc(model?.name ?? '')}" placeholder="例如 DeepSeek V3 / 本地 Qwen2.5" /></label>
          <label class="field"><span>供应商</span><select id="m-provider">
            ${activeProviders
              .map(
                (item) =>
                  `<option value="${item.id}"${model && model.providerId === item.id ? ' selected' : ''}>${esc(
                    item.name,
                  )} · ${esc(item.kindLabel)}</option>`,
              )
              .join('')}
          </select></label>
        </div>
        <div class="form-cols">
          <label class="field"><span>模型标识</span><input id="m-key" class="mono" value="${esc(model?.modelKey ?? '')}" placeholder="例如 deepseek-chat / qwen2.5:7b" /></label>
          <label class="field"><span>优先级 ${fieldInfo('仅在没有实测速度样本时兜底；数值越大越靠前。对话自动模式优先按真实回复速度选模。')}</span><input id="m-priority" type="number" value="${model?.priority ?? 10}" /></label>
        </div>
      </section>
      <section class="models-form-section">
        <div class="models-form-section-head">
          <strong>调用方式</strong>
          ${fieldInfo('类型决定默认能力，端点类型决定服务端用哪个协议调用；切换类型会自动带出推荐端点。')}
        </div>
        <div class="form-cols">
          <label class="field"><span>模型类型 <span class="hint-badge icon-only" id="m-type-hint" tabindex="0" data-tip="模型类型说明" aria-label="模型类型说明">i</span></span><select id="m-type">
            <option value="chat">对话模型</option>
            <option value="decision">决策 / 推理模型</option>
            <option value="vision">多模态 / 视觉模型</option>
            <option value="embedding">向量模型</option>
            <option value="rerank">重排序模型</option>
            <option value="audio">语音模型（ASR / TTS）</option>
            <option value="image">图片生成模型</option>
            <option value="video">视频理解模型</option>
            <option value="custom">自定义能力</option>
          </select></label>
          <label class="field"><span>端点类型 ${fieldInfo('决定服务端用哪个协议调用；SystemOne 只做结构化决策、不生成文本，语音要区分 ASR 与 TTS。')}</span><select id="m-endpoint">
            <option value="chat">对话 / chat completions</option>
            <option value="systemone">决策 / SystemOne（/v1/systemone）</option>
            <option value="embeddings">向量 / embeddings</option>
            <option value="rerank">重排 / rerank</option>
            <option value="asr">语音转写 / ASR</option>
            <option value="tts">语音合成 / TTS</option>
            <option value="image">图片生成 / images generations</option>
            <option value="video">视频理解 / video</option>
          </select></label>
        </div>
        <div class="models-type-preview-field">
          <span>列表里会显示为</span>
          <div class="models-type-preview">
            <span class="models-type-badge" id="m-type-preview"></span>
            <div class="models-preview-chips" id="m-preview-chips"></div>
          </div>
        </div>
        <label class="field" id="m-dim-field" hidden><span>向量维度 <em>仅向量模型</em> ${fieldInfo('用于核对入库与查询是否同一模型；留空由模型返回决定。')}</span><input id="m-dim" type="number" min="1" value="${model?.embeddingDim ?? ''}" placeholder="例如 1024" /></label>
      </section>
      <section class="models-form-section">
        <div class="models-form-section-head">
          <strong>上下文与输出</strong>
          ${fieldInfo('按模型真实窗口填写；留空按 32K / 4K 默认值。')}
        </div>
        <div class="form-cols">
          <label class="field"><span>上下文上限 <em>tokens</em> ${fieldInfo('模型的最大上下文窗口；留空按 32768（32K）处理。')}</span><input id="m-context" type="number" min="1" value="${model?.maxContext ?? ''}" placeholder="留空默认 32768（32K）" /></label>
          <label class="field"><span>输出上限 <em>tokens</em> ${fieldInfo('单次回答最多生成多少 token；留空按 4096 处理，且必须小于上下文上限。')}</span><input id="m-output" type="number" min="1" value="${model?.maxOutputTokens ?? ''}" placeholder="留空默认 4096" /></label>
        </div>
        <div class="field models-compress-field">
          <label class="check"><input id="m-compress" type="checkbox"${model ? (model.contextCompression !== false ? ' checked' : '') : ' checked'} /><span>上下文超限时自动压缩较早历史 ${fieldInfo('上下文上限留空时按 32768 生效；较早对话会压成摘要，最近消息保留原文，不会额外调用模型。')}</span></label>
        </div>
      </section>
      <section class="models-form-section">
        <div class="models-form-section-head">
          <strong>思考选项</strong>
          ${fieldInfo('开放后，员工可在对话输入框旁切换档位；每行对应模型真实支持的 reasoning_effort 或输出预算，不是提示词。')}
        </div>
        <label class="check models-think-switch">
          <input id="m-think-enabled" type="checkbox"${initialThinking ? ' checked' : ''} />
          <span>允许员工选择思考档位 ${fieldInfo('仅对话类模型生效；未开放时不显示选择器，也不会向上游发送思考参数。')}</span>
        </label>
        <div class="models-think-fields" id="m-think-fields"${initialThinking ? '' : ' hidden'}>
          <div class="models-think-toolbar">
            <label class="field models-think-preset-field"><span>常用预设</span><select id="m-think-preset">
              <option value="">选择后套用，仍可逐行修改</option>
              ${THINKING_PRESETS.map((preset) => `<option value="${preset.id}">${esc(preset.label)}</option>`).join('')}
            </select></label>
            <button class="btn ghost sm" type="button" id="m-think-preset-apply">套用预设</button>
            <button class="btn ghost sm" type="button" id="m-think-add">+ 添加档位</button>
          </div>
          <div class="models-think-rows" id="m-think-rows">${initialThinkRowsHtml}</div>
          <div class="form-cols">
            <label class="field"><span>生效方式 ${fieldInfo('原生思考参数适合直接支持 reasoning_effort / thinking 的供应商；输出预算适合会忽略思考参数的网关。')}</span><select id="m-think-strategy">
              <option value="effort"${initialThinkStrategy === 'effort' ? ' selected' : ''}>原生思考参数</option>
              <option value="budget"${initialThinkStrategy === 'budget' ? ' selected' : ''}>输出预算上限</option>
            </select></label>
            <div class="models-think-default-state" id="m-think-default-state"></div>
          </div>
          <div class="models-think-note" id="m-think-note"></div>
        </div>
      </section>
      <section class="models-form-section models-cap-section">
        <div class="models-cap-section-head">
          <div><span>能力 / 擅长场景 ${fieldInfo('可多选；勾选即决定顶部类型、筛选和图片可用性。')}</span></div>
          <div class="models-multi-actions">
            <label class="models-check-all"><input type="checkbox" id="m-cap-all" /><span>全选</span></label>
          </div>
        </div>
        <div class="models-cap-grid">${capabilityOptionsHtml(initialTags)}</div>
        <div class="models-cap-note" id="m-cap-note"></div>
      </section>
      <section class="models-form-section">
        <div class="models-form-section-head">
          <strong>可见角色</strong>
          ${fieldInfo('只勾选允许使用该模型的角色；全不选时任何成员都不能使用。')}
          <div class="models-multi-actions">
            <label class="models-check-all"><input type="checkbox" id="m-role-all" /><span>全选</span></label>
          </div>
        </div>
        <div class="check-grid models-role-grid">
          ${roles
            .map(
              (role) =>
                `<label class="check"><input type="checkbox" data-mrole="${esc(role.code)}"${
                  initialRoleCodes.includes(role.code) ? ' checked' : ''
                } /><span>${esc(ROLE_LABEL[role.code] || role.name)}</span></label>`,
            )
            .join('')}
        </div>
        <div class="models-role-state" id="m-role-state"></div>
      </section>
    </div>
    <div class="modal-state" id="m-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="m-save">保存模型</button>
      <button class="btn ghost" type="button" id="m-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  const type = overlay.querySelector('#m-type')
  const typeHint = overlay.querySelector('#m-type-hint')
  const endpoint = overlay.querySelector('#m-endpoint')
  type.value = modelFormType(initialTags, model?.endpointKind || '')
  const defaultEndpoint = (tags) => {
    if (tags.includes('rerank')) return 'rerank'
    if (tags.includes('embedding')) return 'embeddings'
    if (tags.includes('video')) return 'video'
    if (tags.includes('audio')) return model?.endpointKind === 'asr' || model?.endpointKind === 'tts' ? model.endpointKind : 'asr'
    return 'chat'
  }
  endpoint.value = model?.endpointKind && model.endpointKind !== 'audio' ? model.endpointKind : defaultEndpoint(initialTags)
  const dimField = overlay.querySelector('#m-dim-field')
  const roleInputs = [...overlay.querySelectorAll('[data-mrole]')]
  const roleAll = overlay.querySelector('#m-role-all')
  const roleState = overlay.querySelector('#m-role-state')
  const thinkEnabled = overlay.querySelector('#m-think-enabled')
  const thinkFields = overlay.querySelector('#m-think-fields')
  const thinkRowsEl = overlay.querySelector('#m-think-rows')
  const thinkAdd = overlay.querySelector('#m-think-add')
  const thinkPreset = overlay.querySelector('#m-think-preset')
  const thinkPresetApply = overlay.querySelector('#m-think-preset-apply')
  const thinkStrategy = overlay.querySelector('#m-think-strategy')
  const thinkDefaultState = overlay.querySelector('#m-think-default-state')
  const thinkNote = overlay.querySelector('#m-think-note')

  const readThinkRows = () =>
    [...thinkRowsEl.querySelectorAll('[data-think-row]')].map((row) => {
      const field = (name) => row.querySelector(`[data-think-field="${name}"]`)
      const budgetText = field('budget')?.value.trim() || ''
      const budgetNumber = budgetText ? Number(budgetText) : null
      return {
        row,
        id: field('id')?.value.trim() || '',
        label: field('label')?.value.trim() || '',
        hint: field('hint')?.value.trim() || '',
        wire: field('wire')?.value.trim().toLowerCase() || '',
        budget: Number.isFinite(budgetNumber) ? budgetNumber : null,
        isDefault: Boolean(row.querySelector('input[name="m-think-default"]')?.checked),
      }
    })

  const nextThinkId = (rows) => {
    let index = rows.length + 1
    while (rows.some((row) => row.id === `level${index}`)) index += 1
    return `level${index}`
  }

  const syncThinkState = () => {
    thinkFields.hidden = !thinkEnabled.checked
    let rows = readThinkRows()
    if (rows.length > 0 && !rows.some((row) => row.isDefault)) {
      rows[0].row.querySelector('input[name="m-think-default"]').checked = true
      rows = readThinkRows()
    }
    const budgetMode = thinkStrategy.value === 'budget'
    for (const row of rows) {
      const wire = row.row.querySelector('[data-think-field="wire"]')
      const budget = row.row.querySelector('[data-think-field="budget"]')
      if (wire) wire.disabled = budgetMode
      if (budget) budget.disabled = !budgetMode
      row.row.classList.toggle('is-budget', budgetMode)
    }
    thinkAdd.disabled = rows.length >= 8
    for (const button of thinkRowsEl.querySelectorAll('[data-think-remove]')) {
      button.disabled = rows.length <= 1
    }
    const defaultRow = rows.find((row) => row.isDefault)
    thinkDefaultState.textContent = defaultRow
      ? `默认档位：${defaultRow.label || defaultRow.id || '未命名'}`
      : '还没有默认档位'
    thinkDefaultState.classList.toggle('is-empty', !defaultRow)
    thinkNote.className = `models-think-note ${rows.length === 0 ? 'is-empty' : ''}`
    if (rows.length === 0) {
      thinkNote.innerHTML = '<strong>至少添加一个档位</strong><span>没有档位时无法保存；关闭开关可让该模型不显示思考选择器。</span>'
      return
    }
    thinkNote.innerHTML = budgetMode
      ? '<strong>输出预算方式</strong><span>每行填写的「输出预算」会作为该档位的 max_tokens 上限；留空表示不额外限制。适合忽略 reasoning_effort 的网关。</span>'
      : '<strong>原生思考参数</strong><span>每行的「上游值」会原样发给模型，例如 Qwen3.8 用 low / medium / xhigh，OpenAI 用 minimal / low / medium / high。留空时按档位 ID 兜底。</span>'
    thinkNote.classList.toggle('is-empty', false)
  }

  thinkEnabled.addEventListener('change', syncThinkState)
  thinkStrategy.addEventListener('change', syncThinkState)
  thinkRowsEl.addEventListener('input', syncThinkState)
  thinkRowsEl.addEventListener('change', syncThinkState)
  thinkRowsEl.addEventListener('click', (event) => {
    const remove = event.target.closest('[data-think-remove]')
    if (!remove) return
    const row = remove.closest('[data-think-row]')
    if (!row || readThinkRows().length <= 1) return
    row.remove()
    syncThinkState()
  })
  thinkAdd.addEventListener('click', () => {
    const rows = readThinkRows()
    if (rows.length >= 8) return
    thinkRowsEl.insertAdjacentHTML(
      'beforeend',
      thinkRowHtml({ id: nextThinkId(rows), label: '新档位', hint: '', wire: '', budget: null }, false),
    )
    syncThinkState()
  })
  thinkPresetApply.addEventListener('click', () => {
    const preset = THINKING_PRESETS.find((item) => item.id === thinkPreset.value)
    if (!preset) {
      thinkNote.className = 'models-think-note is-empty'
      thinkNote.innerHTML = '<strong>先选择一个预设</strong><span>套用后仍可逐行修改 ID、名称、上游值和预算。</span>'
      return
    }
    const defaultId = preset.options.some((option) => option.id === 'balanced')
      ? 'balanced'
      : preset.options[0]?.id || ''
    thinkRowsEl.innerHTML = preset.options
      .map((option) => thinkRowHtml(option, option.id === defaultId))
      .join('')
    syncThinkState()
  })
  const syncDimField = () => {
    dimField.hidden = endpoint.value !== 'embeddings'
  }
  const syncRoleState = () => {
    const count = roleInputs.filter((input) => input.checked).length
    roleAll.checked = roleInputs.length > 0 && count === roleInputs.length
    roleAll.indeterminate = count > 0 && count < roleInputs.length
    roleState.className = `models-role-state${count === 0 ? ' is-empty' : ''}`
    roleState.textContent =
      count === 0
        ? '未选择任何角色：保存后这个模型不会出现在任何成员的工作台。'
        : `已授权 ${count} 个角色：只有这些角色的成员能看到并使用这个模型。`
  }
  const typeHints = {
    chat: '通用文本问答，最基础的接入类型。',
    decision: '会自动勾选对话、推理、决策；普通推理仍用对话端点，只有把端点类型选成 SystemOne，才会参与子 Agent 的模型决策分配。',
    vision: '会自动勾选对话、图片识别、多模态；支持工作台图片输入。',
    embedding: '只做向量化，不参与对话生成；端点类型会自动切到 embeddings。',
    rerank: '重排序模型用于知识库检索后的二次排序；端点类型会自动切到 rerank，请求发往 POST /rerank。',
    audio: '语音链路：ASR 负责把语音转文字，TTS 负责把回答合成语音；务必在「端点类型」里选准。',
    image: '图片生成：独立内容工具，按文字生成图片并存入个人云空间，不进入对话主链路；端点必须是 OpenAI 兼容的 /images/generations。',
    video: '视频理解：异步抽帧、音轨转写与画面描述；端点类型会自动切到 video。',
    custom: '只按下面勾选的能力工作，不套用预设。',
  }
  const presetByType = {
    chat: ['chat'],
    decision: ['chat', 'reasoning', 'decision'],
    vision: ['chat', 'vision', 'multimodal'],
    embedding: ['embedding'],
    rerank: ['rerank'],
    audio: ['audio'],
    image: ['chat'],
    video: ['video'],
  }
  const capInputs = [...overlay.querySelectorAll('.models-cap-grid input')]
  const capAll = overlay.querySelector('#m-cap-all')
  const syncCapAll = () => {
    const total = capInputs.length
    const checkedCount = capInputs.filter((input) => input.checked).length
    capAll.checked = total > 0 && checkedCount === total
    capAll.indeterminate = checkedCount > 0 && checkedCount < total
  }
  const readTags = () => {
    const tags = [...overlay.querySelectorAll('[data-cap-key]:checked')].map((el) => el.dataset.capKey)
    const extras = [...overlay.querySelectorAll('[data-cap-extra]:checked')].map((el) => el.dataset.capExtra)
    return [...tags, ...extras]
  }
  const setChecked = (keys) => {
    for (const input of overlay.querySelectorAll('[data-cap-key]')) {
      input.checked = keys.includes(input.dataset.capKey)
      input.closest('.models-cap-option')?.classList.toggle('is-on', input.checked)
    }
    for (const input of overlay.querySelectorAll('[data-cap-extra]')) {
      input.checked = false
      input.closest('.models-cap-option')?.classList.remove('is-on')
    }
  }
  const syncPreview = () => {
    const tags = readTags()
    const info = modelTypeOf(tags)
    const preview = overlay.querySelector('#m-type-preview')
    preview.className = `models-type-badge ${info.tone}`
    preview.textContent = info.label
    overlay.querySelector('#m-preview-chips').innerHTML = capabilityChipsHtml(tags, 4)
    const hasVision = tags.includes('vision') || tags.includes('multimodal')
    const note = overlay.querySelector('#m-cap-note')
    note.className = `models-cap-note ${hasVision ? 'is-ready' : ''}`
    note.innerHTML = hasVision
      ? '<strong>图片识别已开启</strong><span>员工工作台可以直接上传或粘贴图片，服务端会按图片内容送入模型。</span>'
      : '<strong>未开启图片识别</strong><span>带图片的消息不会发给这个模型；需要图片能力时请勾选「图片识别 / 多模态」。</span>'
    const hintText = endpoint.value === 'systemone'
      ? 'SystemOne 是结构化决策端点：不生成文本，主 Agent 用它按子任务内容给子 Agent 选模型；Base URL 要能拼出 /v1/systemone。'
      : typeHints[type.value] || typeHints.custom
    typeHint.dataset.tip = hintText
    typeHint.setAttribute('aria-label', hintText)
    syncCapAll()
  }
  for (const input of overlay.querySelectorAll('.models-cap-grid input')) {
    input.addEventListener('change', () => {
      input.closest('.models-cap-option')?.classList.toggle('is-on', input.checked)
      syncPreview()
    })
  }
  type.addEventListener('change', () => {
    const preset = presetByType[type.value]
    if (preset) setChecked(preset)
    if (type.value === 'embedding') endpoint.value = 'embeddings'
    else if (type.value === 'rerank') endpoint.value = 'rerank'
    else if (type.value === 'video') endpoint.value = 'video'
    else if (type.value === 'image') endpoint.value = 'image'
    else if (type.value === 'audio') endpoint.value = endpoint.value === 'tts' ? 'tts' : 'asr'
    else if (type.value === 'decision') {
      // 决策模型既可能是普通推理，也可能是 SystemOne；切类型时不要粗暴覆盖用户已选的 SystemOne。
      if (endpoint.value !== 'systemone') endpoint.value = 'chat'
    } else if (['chat', 'vision'].includes(type.value)) endpoint.value = 'chat'
    syncPreview()
    syncDimField()
  })
  endpoint.addEventListener('change', () => {
    syncPreview()
    syncDimField()
  })
  for (const input of roleInputs) input.addEventListener('change', syncRoleState)
  roleAll.addEventListener('change', () => {
    for (const input of roleInputs) input.checked = roleAll.checked
    syncRoleState()
  })
  capAll.addEventListener('change', () => {
    for (const input of capInputs) {
      input.checked = capAll.checked
      input.closest('.models-cap-option')?.classList.toggle('is-on', input.checked)
    }
    syncPreview()
  })
  syncPreview()
  syncDimField()
  syncRoleState()
  syncThinkState()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#m-cancel').addEventListener('click', close)
  overlay.querySelector('#m-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#m-state')
    const thinkRows = readThinkRows()
    if (thinkEnabled.checked) {
      if (thinkRows.length === 0) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '思考选项至少添加一个档位，或关闭「允许员工选择思考档位」'
        return
      }
      if (thinkRows.length > 8) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '最多支持 8 个思考档位'
        return
      }
      const ids = thinkRows.map((row) => row.id)
      if (ids.some((id) => !id)) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '每个档位都要填写 ID'
        return
      }
      if (ids.some((id) => id.length > 40)) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '档位 ID 不能超过 40 个字符'
        return
      }
      if (new Set(ids).size !== ids.length) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '档位 ID 不能重复'
        return
      }
      if (thinkRows.some((row) => !row.label)) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '每个档位都要填写显示名'
        return
      }
      if (thinkStrategy.value === 'effort') {
        const invalidWire = thinkRows.find(
          (row) => row.wire && !['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max'].includes(row.wire),
        )
        if (invalidWire) {
          stateEl.className = 'modal-state bad'
          stateEl.textContent = `档位「${invalidWire.label || invalidWire.id}」的上游值不受支持，请填 none / minimal / low / medium / high / xhigh / max`
          return
        }
      }
    }
    const config = {
      ...(model?.config && typeof model.config === 'object' ? model.config : {}),
    }
    if (thinkEnabled.checked) {
      const defaultRow = thinkRows.find((row) => row.isDefault) || thinkRows[0]
      config.thinking = {
        enabled: true,
        options: thinkRows.map((row) => ({
          id: row.id,
          label: row.label,
          hint: row.hint,
          ...(row.wire ? { wire: row.wire } : {}),
          ...(row.budget !== null ? { budget: row.budget } : {}),
        })),
        defaultEffort: defaultRow.id,
        strategy: thinkStrategy.value === 'budget' ? 'budget' : 'effort',
      }
    } else {
      delete config.thinking
    }
    stateEl.textContent = '保存中…'
    const body = {
      name: overlay.querySelector('#m-name').value.trim(),
      providerId: overlay.querySelector('#m-provider').value,
      modelKey: overlay.querySelector('#m-key').value.trim(),
      priority: Number(overlay.querySelector('#m-priority').value),
      tags: readTags(),
      capabilities: readTags(),
      endpointKind: endpoint.value,
      embeddingDim: overlay.querySelector('#m-dim').value ? Number(overlay.querySelector('#m-dim').value) : null,
      maxContext: overlay.querySelector('#m-context').value ? Number(overlay.querySelector('#m-context').value) : null,
      maxOutputTokens: overlay.querySelector('#m-output').value ? Number(overlay.querySelector('#m-output').value) : null,
      contextCompression: overlay.querySelector('#m-compress').checked,
      config,
      roles: [...overlay.querySelectorAll('[data-mrole]:checked')].map((el) => el.dataset.mrole),
    }
    try {
      if (model) await apiSend('PATCH', `/api/console/models/${encodeURIComponent(model.id)}`, body)
      else await apiPost('/api/console/models', body)
      close()
      loadModels()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
}

function openPluginModelRoleModal(model, roles) {
  const initialRoleCodes = model.roles || []
  const overlay = modelModal(`
    <div class="modal-head">
      <div class="models-modal-title">
        <h3>配置插件模型</h3>
      </div>
      <button class="modal-x" type="button">×</button>
    </div>
    <div class="models-modal-body">
      <section class="models-form-section">
        <div class="models-form-section-head">
          <strong>${esc(model.name)}</strong>
          ${fieldInfo('这个模型由插件注入，能力随插件更新；这里只配置哪些角色能看到它。上下文与输出由插件的 resolveModel() 声明，不再由后台逐模型手填。')}
        </div>
        <div class="models-plugin-meta">
          <span class="models-provider-pill">${esc(model.providerName)}</span>
          <span class="mono">${esc(model.modelKey)}</span>
          <span class="muted">插件更新或停用后，模型会自动出现或消失。</span>
        </div>
      </section>
      <section class="models-form-section">
        <div class="models-form-section-head">
          <strong>可见角色</strong>
          ${fieldInfo('只勾选允许使用该模型的角色；默认只选普通员工。全不选时任何成员都不能使用。')}
          <div class="models-multi-actions">
            <button class="models-inline-btn" type="button" id="pm-role-all">全选</button>
            <button class="models-inline-btn is-muted" type="button" id="pm-role-clear">全不选</button>
          </div>
        </div>
        <div class="check-grid models-role-grid">
          ${roles
            .map(
              (role) =>
                `<label class="check"><input type="checkbox" data-pmrole="${esc(role.code)}"${
                  initialRoleCodes.includes(role.code) ? ' checked' : ''
                } /><span>${esc(ROLE_LABEL[role.code] || role.name)}</span></label>`,
            )
            .join('')}
        </div>
        <div class="models-role-state" id="pm-role-state"></div>
      </section>
    </div>
    <div class="modal-state" id="pm-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="pm-save">保存角色</button>
      <button class="btn ghost" type="button" id="pm-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  const roleInputs = [...overlay.querySelectorAll('[data-pmrole]')]
  const roleState = overlay.querySelector('#pm-role-state')
  const syncRoleState = () => {
    const count = roleInputs.filter((input) => input.checked).length
    roleState.className = `models-role-state${count === 0 ? ' is-empty' : ''}`
    roleState.textContent =
      count === 0
        ? '未选择任何角色：保存后这个插件模型不会出现在任何成员的工作台。'
        : `已授权 ${count} 个角色：只有这些角色的成员能看到并使用这个插件模型。`
  }
  for (const input of roleInputs) input.addEventListener('change', syncRoleState)
  const setAllRoles = (checked) => {
    for (const input of roleInputs) input.checked = checked
    syncRoleState()
  }
  overlay.querySelector('#pm-role-all').addEventListener('click', () => setAllRoles(true))
  overlay.querySelector('#pm-role-clear').addEventListener('click', () => setAllRoles(false))
  syncRoleState()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#pm-cancel').addEventListener('click', close)
  overlay.querySelector('#pm-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#pm-state')
    stateEl.className = 'modal-state'
    stateEl.textContent = '保存中…'
    try {
      await apiSend('PUT', `/api/console/models/${encodeURIComponent(model.id)}/plugin-settings`, {
        roles: [...overlay.querySelectorAll('[data-pmrole]:checked')].map((el) => el.dataset.pmrole),
      })
      close()
      showTopToast('插件模型可见角色已保存')
      loadModels()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
}

let modelCapabilityPopover = null
let toolRunPopover = null

function closeModelCapabilityPopover() {
  if (!modelCapabilityPopover) return
  modelCapabilityPopover.__cleanup?.()
  modelCapabilityPopover.remove()
  modelCapabilityPopover = null
}

function openModelCapabilityPopover(trigger, model, onSave) {
  closeModelCapabilityPopover()
  const popover = document.createElement('div')
  popover.className = 'models-cap-popover'
  popover.innerHTML = `
    <div class="models-cap-pop-head">
      <div><strong>能力 / 擅长场景</strong><span>${esc(model.name)}</span></div>
      <button class="models-cap-clear" type="button" id="cap-clear">清空</button>
    </div>
    <div class="models-cap-grid is-compact">${capabilityOptionsHtml(model.tags)}</div>
    <div class="models-cap-pop-foot">
      <span class="muted" id="cap-msg">勾选后保存，列表类型会立即更新</span>
      <div><button class="btn ghost" type="button" id="cap-cancel">取消</button><button class="btn primary" type="button" id="cap-save">保存</button></div>
    </div>`
  document.body.appendChild(popover)
  modelCapabilityPopover = popover
  const rect = trigger.getBoundingClientRect()
  const width = popover.offsetWidth
  const height = popover.offsetHeight
  const left = Math.max(12, Math.min(rect.left, window.innerWidth - width - 12))
  const top =
    rect.bottom + height + 8 <= window.innerHeight
      ? rect.bottom + 8
      : Math.max(12, rect.top - height - 8)
  popover.style.left = `${left}px`
  popover.style.top = `${top}px`
  const readTags = () => {
    const tags = [...popover.querySelectorAll('[data-cap-key]:checked')].map((el) => el.dataset.capKey)
    const extras = [...popover.querySelectorAll('[data-cap-extra]:checked')].map((el) => el.dataset.capExtra)
    return [...tags, ...extras]
  }
  const setChecked = (keys) => {
    for (const input of popover.querySelectorAll('[data-cap-key]')) {
      input.checked = keys.includes(input.dataset.capKey)
      input.closest('.models-cap-option')?.classList.toggle('is-on', input.checked)
    }
    for (const input of popover.querySelectorAll('[data-cap-extra]')) {
      input.checked = false
      input.closest('.models-cap-option')?.classList.remove('is-on')
    }
  }
  for (const input of popover.querySelectorAll('input')) {
    input.addEventListener('change', () => {
      input.closest('.models-cap-option')?.classList.toggle('is-on', input.checked)
    })
  }
  popover.querySelector('#cap-clear').addEventListener('click', () => setChecked([]))
  popover.querySelector('#cap-cancel').addEventListener('click', closeModelCapabilityPopover)
  popover.querySelector('#cap-save').addEventListener('click', async () => {
    const msg = popover.querySelector('#cap-msg')
    const save = popover.querySelector('#cap-save')
    const tags = readTags()
    save.disabled = true
    msg.textContent = '保存中…'
    try {
      await onSave(tags)
      closeModelCapabilityPopover()
    } catch (err) {
      msg.className = 'models-cap-error'
      msg.textContent = err.message || '保存失败'
      save.disabled = false
    }
  })
  const onOutside = (event) => {
    if (popover.contains(event.target) || trigger.contains(event.target)) return
    closeModelCapabilityPopover()
  }
  const onKey = (event) => {
    if (event.key === 'Escape') closeModelCapabilityPopover()
  }
  setTimeout(() => {
    document.addEventListener('mousedown', onOutside)
    document.addEventListener('keydown', onKey)
  }, 0)
  popover.__cleanup = () => {
    document.removeEventListener('mousedown', onOutside)
    document.removeEventListener('keydown', onKey)
  }
}

function toolInputFields(tool) {
  return tool.source === 'plugin' ? (tool.input?.properties ?? {}) : (tool.input ?? {})
}

function toolArgsPreview(tool) {
  const fields = toolInputFields(tool)
  const keys = Object.keys(fields || {})
  if (!keys.length) return '{}'
  const seed = {}
  for (const key of keys) {
    const spec = fields[key] || {}
    seed[key] = Object.prototype.hasOwnProperty.call(spec, 'default') ? spec.default : ''
  }
  return JSON.stringify(seed, null, 2)
}

function toolSchemaHint(tool) {
  const fields = toolInputFields(tool)
  const keys = Object.keys(fields || {})
  if (!keys.length) return '这个工具不需要参数，直接运行即可。'
  return `可用字段：${keys.map((key) => `${key}${fields[key]?.type ? ` · ${fields[key].type}` : ''}`).join('、')}`
}

function formatToolResult(value) {
  let text = ''
  if (typeof value === 'string') text = value
  else {
    try {
      text = JSON.stringify(value, null, 2) ?? ''
    } catch {
      text = String(value ?? '')
    }
  }
  if (!text) text = '（无返回值）'
  if (text.length > 10000) text = `${text.slice(0, 10000)}\n…结果已截断（共 ${text.length} 字符）`
  return text
}

function closeToolRunPopover() {
  if (!toolRunPopover) return
  toolRunPopover.__cleanup?.()
  toolRunPopover.remove()
  toolRunPopover = null
}

function openToolRunPopover(trigger, tool) {
  if (!tool) return
  closeToolRunPopover()
  const popover = document.createElement('div')
  popover.className = 'tool-run-popover'
  popover.setAttribute('role', 'dialog')
  popover.setAttribute('aria-label', `试运行 ${tool.name}`)
  const sourceLabel = tool.source === 'plugin' ? '插件工具' : '内置工具'
  popover.innerHTML = `
    <div class="tool-run-head">
      <div class="tool-run-title">
        <div class="tool-run-kicker"><span>工具试运行</span><span class="tool-run-tag">${sourceLabel}</span>${tool.dangerous ? '<span class="tool-run-tag is-risk">需审批</span>' : ''}</div>
        <strong>${esc(tool.name)}</strong>
        <span class="tool-run-id mono">${esc(tool.id)}</span>
        <span class="tool-run-desc">${esc(tool.description || '暂无说明')}</span>
      </div>
      <div class="tool-run-head-actions">
        <span class="tool-run-grip" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></span>
        <button class="tool-run-close" type="button" aria-label="关闭试运行">×</button>
      </div>
    </div>
    <div class="tool-run-body">
      <div class="tool-run-label"><strong>参数 JSON</strong><span>留空按 <code>{}</code> 处理</span></div>
      <textarea class="tool-run-args" id="tool-run-args" spellcheck="false" aria-label="参数 JSON">${esc(toolArgsPreview(tool))}</textarea>
      <div class="tool-run-schema">${esc(toolSchemaHint(tool))}</div>
      <div class="tool-run-msg" id="tool-run-msg" hidden></div>
      <div class="tool-run-result" id="tool-run-result" hidden>
        <div class="tool-run-result-head"><strong>运行结果</strong><button class="link-btn" type="button" id="tool-run-copy">复制</button></div>
        <pre id="tool-run-output"></pre>
      </div>
    </div>
    <div class="tool-run-foot">
      <span>拖动标题可移动 · 参数和结果都会写入审计</span>
      <div><button class="btn ghost" type="button" id="tool-run-cancel">关闭</button><button class="btn primary" type="button" id="tool-run-go">运行</button></div>
    </div>`
  document.body.appendChild(popover)
  toolRunPopover = popover

  const rect = trigger.getBoundingClientRect()
  const width = popover.offsetWidth
  const height = popover.offsetHeight
  const left = Math.max(12, Math.min(rect.right - width, window.innerWidth - width - 12))
  const top =
    rect.bottom + 8 + height <= window.innerHeight - 12
      ? rect.bottom + 8
      : Math.max(12, rect.top - height - 8)
  popover.style.left = `${left}px`
  popover.style.top = `${top}px`

  const argsEl = popover.querySelector('#tool-run-args')
  const msg = popover.querySelector('#tool-run-msg')
  const resultBox = popover.querySelector('#tool-run-result')
  const output = popover.querySelector('#tool-run-output')
  const runBtn = popover.querySelector('#tool-run-go')
  const copyBtn = popover.querySelector('#tool-run-copy')
  const head = popover.querySelector('.tool-run-head')
  let running = false
  let drag = null

  const onDragStart = (event) => {
    if (event.pointerType === 'mouse' && event.button !== 0) return
    if (event.target.closest('button, input, textarea, a')) return
    const current = popover.getBoundingClientRect()
    drag = {
      pointerId: event.pointerId,
      offsetX: event.clientX - current.left,
      offsetY: event.clientY - current.top,
    }
    popover.classList.add('is-dragging')
    try {
      head.setPointerCapture(event.pointerId)
    } catch {}
    event.preventDefault()
  }
  const onDragMove = (event) => {
    if (!drag || event.pointerId !== drag.pointerId) return
    const dragWidth = popover.offsetWidth
    const dragHeight = popover.offsetHeight
    const left = Math.max(8, Math.min(event.clientX - drag.offsetX, window.innerWidth - dragWidth - 8))
    const top = Math.max(8, Math.min(event.clientY - drag.offsetY, window.innerHeight - dragHeight - 8))
    popover.style.left = `${left}px`
    popover.style.top = `${top}px`
  }
  const onDragEnd = (event) => {
    if (!drag || (event && event.pointerId !== drag.pointerId)) return
    const pointerId = drag.pointerId
    drag = null
    popover.classList.remove('is-dragging')
    try {
      head.releasePointerCapture(pointerId)
    } catch {}
  }
  head.addEventListener('pointerdown', onDragStart)
  head.addEventListener('pointermove', onDragMove)
  head.addEventListener('pointerup', onDragEnd)
  head.addEventListener('pointercancel', onDragEnd)

  const setMessage = (text, tone = 'info') => {
    msg.hidden = !text
    msg.className = `tool-run-msg is-${tone}`
    msg.textContent = text || ''
  }

  const run = async () => {
    if (running) return
    let args
    try {
      const raw = argsEl.value.trim()
      args = raw ? JSON.parse(raw) : {}
      if (!args || typeof args !== 'object' || Array.isArray(args)) throw new Error('参数必须是 JSON 对象')
    } catch (err) {
      setMessage(`参数不合法：${err.message}`, 'bad')
      argsEl.focus()
      return
    }
    running = true
    runBtn.disabled = true
    runBtn.textContent = '运行中…'
    resultBox.hidden = true
    setMessage('正在调用工具…', 'info')
    const started = performance.now()
    try {
      const result = await apiPost(`/api/tools/${encodeURIComponent(tool.id)}/invoke`, { args })
      output.textContent = formatToolResult(result.result)
      resultBox.hidden = false
      setMessage(`运行成功 · ${Math.round(performance.now() - started)} ms`, 'ok')
    } catch (err) {
      if (err.code === 'EAB_APPROVAL_REQUIRED') {
        const approval = err.details?.approvalId ? `（审批单 ${err.details.approvalId}）` : ''
        setMessage(`需要审批：${err.message || '该工具需要管理员审批'}${approval}；到「审批」页通过后再运行。`, 'warn')
      } else {
        setMessage(`运行失败：${err.message || '未知错误'}`, 'bad')
      }
    } finally {
      running = false
      runBtn.disabled = false
      runBtn.textContent = '运行'
    }
  }

  popover.querySelector('.tool-run-close').addEventListener('click', closeToolRunPopover)
  popover.querySelector('#tool-run-cancel').addEventListener('click', closeToolRunPopover)
  runBtn.addEventListener('click', () => void run())
  argsEl.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
      event.preventDefault()
      void run()
    }
  })
  copyBtn.addEventListener('click', async () => {
    const text = output.textContent || ''
    if (!text) return
    try {
      await navigator.clipboard.writeText(text)
      copyBtn.textContent = '已复制'
      setTimeout(() => { copyBtn.textContent = '复制' }, 1200)
    } catch {
      setMessage('复制失败，请手动选择结果。', 'bad')
    }
  })
  const onOutside = (event) => {
    if (popover.contains(event.target) || trigger.contains(event.target)) return
    closeToolRunPopover()
  }
  const onKey = (event) => {
    if (event.key === 'Escape') closeToolRunPopover()
  }
  setTimeout(() => {
    document.addEventListener('mousedown', onOutside)
    document.addEventListener('keydown', onKey)
  }, 0)
  popover.__cleanup = () => {
    document.removeEventListener('mousedown', onOutside)
    document.removeEventListener('keydown', onKey)
  }
  setTimeout(() => {
    argsEl.focus()
    argsEl.setSelectionRange(argsEl.value.length, argsEl.value.length)
  }, 0)
}

function formatStressDuration(ms) {
  if (!Number.isFinite(ms) || ms <= 0) return '—'
  return ms < 1000 ? `${Math.round(ms)} ms` : `${(ms / 1000).toFixed(2)} s`
}

function openModelStressModal(model, trigger) {
  const canRun =
    model.enabled &&
    model.providerStatus === 'active' &&
    (model.endpointKind ?? 'chat') === 'chat' &&
    model.providerKind !== 'demo'
  let timer = null
  let jobId = ''
  let running = false
  const overlay = modelModal(`
    <div class="modal-head">
      <div class="models-modal-title">
        <h3>模型压测 ${fieldInfo('直接调用真实模型，不经过在线对话闸门；用来判断这个模型端点自己的并发能力。')}</h3>
        <p>只发测试请求，不写会话和消息；结果只保留在当前服务进程里。</p>
      </div>
      <button class="modal-x" type="button">×</button>
    </div>
    <div class="models-modal-body stress-modal-body">
      <div class="stress-model-card">
        <div class="stress-model-main">
          <span class="models-provider-pill">${esc(model.providerName)}</span>
          <strong>${esc(model.name)}</strong>
          <span class="mono">${esc(model.modelKey)}</span>
        </div>
        <span class="pill ${canRun ? 'ok' : 'warn'}">${canRun ? '可压测' : '当前不可压测'}</span>
      </div>
      ${
        canRun
          ? ''
          : `<p class="stress-blocked">这个模型需要先启用、供应商处于启用状态，且类型为对话模型；演示回声没有真实上游。</p>`
      }
      <div class="stress-form-grid">
        <label class="field"><span>并发数 ${fieldInfo('同时发出的请求数；越高越能压出模型吞吐上限，也越占用算力。')}</span><input id="st-concurrency" type="number" min="1" max="20" value="3" ${canRun ? '' : 'disabled'} /></label>
        <label class="field"><span>总请求数 ${fieldInfo('本次一共发多少条请求；单次压测上限 100 条。')}</span><input id="st-requests" type="number" min="1" max="100" value="10" ${canRun ? '' : 'disabled'} /></label>
      </div>
      <div class="stress-presets" aria-label="压测档位">
        <button class="stress-preset" type="button" data-stress-preset="2,6">轻量 2 × 6</button>
        <button class="stress-preset is-active" type="button" data-stress-preset="3,10">标准 3 × 10</button>
        <button class="stress-preset" type="button" data-stress-preset="8,24">高压 8 × 24</button>
      </div>
      <label class="field"><span>测试提示词 ${fieldInfo('每条请求都发同一句短提示词，避免提示词长度影响延迟对比。')}</span><input id="st-prompt" value="请只回复 OK。" maxlength="2000" ${canRun ? '' : 'disabled'} /></label>
      ${hintNote('压测说明', '压测会消耗真实 token 和模型算力，建议在低峰执行；关闭弹窗不会终止已经开始的压测。')}
      <div class="stress-run" id="st-run">
        <div class="stress-run-head">
          <strong id="st-status" aria-live="polite">尚未开始</strong>
          <span id="st-progress-text">0 / 0</span>
        </div>
        <div class="stress-progress-track" id="st-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" aria-label="压测进度"><div class="stress-progress-fill" id="st-progress-fill"></div></div>
        <div class="stress-metrics">
          <div class="stress-metric"><span>成功 / 失败</span><strong id="st-success">—</strong><small>按已完成请求统计</small></div>
          <div class="stress-metric"><span>成功率</span><strong id="st-rate">—</strong><small>成功数 ÷ 已请求数</small></div>
          <div class="stress-metric"><span>p50</span><strong id="st-p50">—</strong><small>一半请求快于此</small></div>
          <div class="stress-metric"><span>p95</span><strong id="st-p95">—</strong><small>95% 请求快于此</small></div>
          <div class="stress-metric"><span>吞吐</span><strong id="st-rps">—</strong><small>条 / 秒</small></div>
          <div class="stress-metric"><span>总耗时</span><strong id="st-total">—</strong><small>从开始到结束</small></div>
        </div>
        <div class="stress-error-list" id="st-errors"></div>
      </div>
      <div class="modal-state" id="st-state" aria-live="polite"></div>
    </div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="st-run-btn"${canRun ? '' : ' disabled'}>开始压测</button>
      <button class="btn ghost" type="button" id="st-close">关闭</button>
    </div>`)
  const close = () => {
    if (timer) clearTimeout(timer)
    document.removeEventListener('keydown', onKey)
    overlay.remove()
    trigger?.focus?.()
  }
  const setBusy = (busy) => {
    running = busy
    for (const input of overlay.querySelectorAll('#st-concurrency, #st-requests, #st-prompt')) {
      input.disabled = busy || !canRun
    }
    for (const preset of overlay.querySelectorAll('[data-stress-preset]')) preset.disabled = busy || !canRun
    const runButton = overlay.querySelector('#st-run-btn')
    if (runButton) {
      runButton.disabled = busy || !canRun
      runButton.textContent = busy ? '压测中…' : jobId ? '重新压测' : '开始压测'
    }
  }
  const syncPresetActive = () => {
    const concurrency = Number(overlay.querySelector('#st-concurrency')?.value)
    const requests = Number(overlay.querySelector('#st-requests')?.value)
    for (const preset of overlay.querySelectorAll('[data-stress-preset]')) {
      preset.classList.toggle('is-active', preset.dataset.stressPreset === `${concurrency},${requests}`)
    }
  }
  const fill = (concurrency, requests) => {
    const concurrencyInput = overlay.querySelector('#st-concurrency')
    const requestsInput = overlay.querySelector('#st-requests')
    if (concurrencyInput) concurrencyInput.value = String(concurrency)
    if (requestsInput) requestsInput.value = String(requests)
    syncPresetActive()
  }
  for (const input of overlay.querySelectorAll('#st-concurrency, #st-requests')) {
    input.addEventListener('input', syncPresetActive)
  }
  for (const preset of overlay.querySelectorAll('[data-stress-preset]')) {
    preset.addEventListener('click', () => {
      if (running) return
      const [concurrency, requests] = preset.dataset.stressPreset.split(',').map(Number)
      fill(concurrency, requests)
    })
  }
  const render = (data) => {
    const completed = Number(data.completed || 0)
    const total = Number(data.total || 0)
    const percent = total ? Math.min(100, Math.max(0, (completed / total) * 100)) : 0
    const status = overlay.querySelector('#st-status')
    const statusText = data.running
      ? '压测中'
      : data.failed === 0
        ? '检测通过'
        : data.success === 0
          ? '连接失败'
          : '部分失败'
    status.textContent = statusText
    status.className = data.running ? 'is-running' : data.failed === 0 ? 'is-ok' : 'is-bad'
    overlay.querySelector('#st-progress-text').textContent = `${completed} / ${total}`
    overlay.querySelector('#st-progress-fill').style.width = `${percent}%`
    overlay.querySelector('#st-progress').setAttribute('aria-valuenow', String(Math.round(percent)))
    overlay.querySelector('#st-success').textContent = `${data.success} / ${data.failed}`
    overlay.querySelector('#st-rate').textContent = `${(Number(data.successRate || 0) * 100).toFixed(1)}%`
    overlay.querySelector('#st-p50').textContent = formatStressDuration(Number(data.latencyMs?.p50 || 0))
    overlay.querySelector('#st-p95').textContent = formatStressDuration(Number(data.latencyMs?.p95 || 0))
    overlay.querySelector('#st-rps').textContent = Number(data.throughputRps || 0).toFixed(2)
    overlay.querySelector('#st-total').textContent = formatStressDuration(Number(data.elapsedMs || 0))
    const errors = Array.isArray(data.errors) ? data.errors : []
    const errorList = overlay.querySelector('#st-errors')
    if (errors.length) {
      errorList.innerHTML = errors
        .map(
          (item) =>
            `<div class="stress-error-item"><span>第 ${Number(item.index) + 1} 次</span><strong>${esc(item.code || 'ERROR')}</strong><p>${esc(item.message || '调用失败')}</p><small>${formatStressDuration(Number(item.durationMs || 0))}</small></div>`,
        )
        .join('')
    } else if (!data.running && data.failed === 0) {
      errorList.innerHTML = '<p class="stress-success-note">全部请求成功，端点响应正常。</p>'
    } else {
      errorList.innerHTML = ''
    }
    const runBox = overlay.querySelector('#st-run')
    runBox.classList.toggle('is-running', Boolean(data.running))
    runBox.classList.toggle('is-ok', !data.running && data.failed === 0)
    runBox.classList.toggle('is-bad', !data.running && data.failed > 0)
  }
  const poll = async () => {
    if (!jobId) return
    try {
      const data = await api(`/api/console/model-stress-tests/${encodeURIComponent(jobId)}`)
      render(data)
      if (data.running) {
        timer = setTimeout(poll, 900)
      } else {
        timer = null
        setBusy(false)
        overlay.querySelector('#st-state').textContent = ''
      }
    } catch (err) {
      timer = null
      setBusy(false)
      overlay.querySelector('#st-state').textContent = err.message || '读取压测进度失败'
    }
  }
  const start = async () => {
    if (!canRun || running) return
    const concurrency = Math.min(20, Math.max(1, Math.trunc(Number(overlay.querySelector('#st-concurrency').value) || 3)))
    const requests = Math.min(100, Math.max(1, Math.trunc(Number(overlay.querySelector('#st-requests').value) || 10)))
    const prompt = overlay.querySelector('#st-prompt').value.trim() || '请只回复 OK。'
    setBusy(true)
    jobId = ''
    overlay.querySelector('#st-state').textContent = ''
    overlay.querySelector('#st-status').textContent = '准备请求…'
    overlay.querySelector('#st-status').className = 'is-running'
    overlay.querySelector('#st-progress-text').textContent = `0 / ${requests}`
    overlay.querySelector('#st-progress-fill').style.width = '0%'
    overlay.querySelector('#st-progress').setAttribute('aria-valuenow', '0')
    try {
      const data = await apiPost(`/api/console/models/${encodeURIComponent(model.id)}/stress-test`, {
        concurrency,
        requests,
        prompt,
      })
      jobId = data.jobId
      overlay.querySelector('#st-status').textContent = `正在跑 ${data.concurrency} 并发 × ${data.total} 次…`
      timer = setTimeout(poll, 600)
    } catch (err) {
      setBusy(false)
      overlay.querySelector('#st-state').textContent = err.message || '压测启动失败'
      overlay.querySelector('#st-status').textContent = '未开始'
      overlay.querySelector('#st-status').className = ''
    }
  }
  overlay.querySelector('#st-run-btn')?.addEventListener('click', start)
  overlay.querySelector('#st-close')?.addEventListener('click', close)
  overlay.querySelector('.modal-x')?.addEventListener('click', close)
  const onKey = (event) => {
    if (event.key === 'Escape') close()
  }
  document.addEventListener('keydown', onKey)
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) close()
  })
  setTimeout(() => overlay.querySelector(canRun ? '#st-run-btn' : '#st-close')?.focus(), 0)
}

async function loadModels() {
  const view = $('#view')
  renderLoading(view)
  closeModelCapabilityPopover()
  setSide('', true)
  try {
    const [providerData, modelData, routeData] = await Promise.all([
      api('/api/console/providers'),
      api('/api/console/models'),
      api('/api/console/model-routes').catch(() => ({ routes: [] })),
    ])
    const providers = providerData.providers
    const writableProviders = providers.filter((provider) => provider.source !== 'plugin')
    const pluginProviderCount = providers.length - writableProviders.length
    const models = modelData.models
    const roles = modelData.roles || []
    const enabledModels = models.filter((model) => model.enabled)
    const visionModels = models.filter((model) => {
      const caps = modelCapabilitySummary(model.tags)
      return caps.keys.includes('vision') || caps.keys.includes('multimodal')
    })
    const autoModel = enabledModels[0] || models[0] || null
    state.modelsFilter = state.modelsFilter || 'all'
    state.modelsSearch = state.modelsSearch || ''
    // 页头不再放“添加供应商 / 添加模型”：两个动作分别落在对应的功能区里，避免同一页出现重复入口。
    setPageActions('')

    const providerRows =
      providers
        .map((provider) => {
          const pluginChannel = provider.source === 'plugin'
          const providerKeyText = provider.apiKeyEnv
            ? `${provider.apiKeyEnv} ${provider.keyPresent ? '已注入' : '未注入'}`
            : ''
          const providerKeyState = provider.apiKeyEnv ? (provider.keyPresent ? '已注入' : '未注入') : ''
          const providerKeyBrief = pluginChannel
            ? '密钥 · 插件托管'
            : provider.apiKeyEnv
              ? `密钥 · ${provider.keyPresent ? '已注入' : '未注入'}`
              : '密钥 · 不需要'
          return `<tr>
            <td class="col-provider-name">
              <div class="models-provider-cell">
                <span class="models-provider-mark">${esc((provider.name || '?').slice(0, 1).toUpperCase())}</span>
                <div><strong>${esc(provider.name)}</strong><div class="desc">${
                  pluginChannel
                    ? `插件 ${esc(provider.pluginId || '')}<br>${esc(provider.route || '')}`
                    : esc(provider.kindLabel)
                }</div><div class="desc models-key-brief">${esc(providerKeyBrief)}</div></div>
              </div>
            </td>
            <td class="mono models-endpoint col-provider-endpoint">${esc(pluginChannel ? '随插件宿主注入' : (provider.baseUrl || '—'))}</td>
            <td class="models-secret-cell col-provider-key">${
              pluginChannel
                ? '<span class="pill ok"><span class="models-secret-text">插件托管</span></span>'
                : provider.apiKeyEnv
                  ? `<span class="pill ${provider.keyPresent ? 'ok' : 'warn'}" title="${esc(providerKeyText)}"><span class="models-secret-text">${esc(
                      provider.apiKeyEnv,
                    )}</span><span class="models-secret-state">${providerKeyState}</span></span>`
                  : '<span class="muted">不需要</span>'
            }</td>
            <td class="col-provider-model"><span class="models-count">${provider.models}</span></td>
            <td class="col-provider-status"><span class="pill ${pluginChannel ? 'ok' : (provider.status === 'active' ? 'ok' : 'warn')}">${
              pluginChannel ? '已注入' : (provider.status === 'active' ? '启用' : '停用')
            }</span></td>
            <td class="model-actions col-provider-actions">
              ${
                pluginChannel
                  ? `<button class="btn sm model-action-btn" type="button" data-refresh-plugin-channel="${esc(provider.id)}" data-tip="让插件重新探测模型并刷新目录。" aria-label="刷新插件模型">${modelActionIcon('discover')}</button>`
                  : `<button class="btn sm model-action-btn" type="button" data-test="${esc(provider.id)}" data-tip="测试连接：用当前凭证请求一次供应商端点。" aria-label="测试连接">${modelActionIcon('test')}</button>
              ${
                provider.kind === 'demo' && !provider.baseUrl
                  ? ''
                  : `<button class="btn sm model-action-btn" type="button" data-discover-provider="${esc(provider.id)}" data-tip="检测模型：读取 /models 清单并导入。" aria-label="检测模型">${modelActionIcon('discover')}</button>`
              }
              <button class="btn sm model-action-btn" type="button" data-edit-provider="${esc(provider.id)}" data-tip="编辑供应商。" aria-label="编辑供应商">${modelActionIcon('edit')}</button>
              <button class="btn sm model-action-btn" type="button" data-toggle-provider="${esc(provider.id)}" data-tip="${provider.status === 'active' ? '停用供应商。' : '启用供应商。'}" aria-label="${provider.status === 'active' ? '停用供应商' : '启用供应商'}">${modelActionIcon('toggle')}</button>
              <button class="btn sm model-action-btn is-danger" type="button" data-del-provider="${esc(provider.id)}" data-tip="删除供应商及其下模型。" aria-label="删除供应商">${modelActionIcon('delete')}</button>`
              }
            </td>
          </tr>`
        })
        .join('') || '<tr><td colspan="6" class="empty">还没有供应商，先接入一个端点</td></tr>'

    const routeItems = routeData?.routes ?? []
    const pluginModelCount = models.filter((model) => model.source === 'plugin' || model.readonly === true).length
    const boundRouteCount = routeItems.filter((item) => item.boundModelId).length
    const routeRows = routeItems
      .map((item) => {
        const eligible = models.filter(
          (model) => model.readonly !== true && model.source !== 'plugin' && modelSupportsRoutePurpose(model, item.purpose),
        )
        if (item.boundModelId && !eligible.some((model) => model.id === item.boundModelId)) {
          const bound = models.find((model) => model.id === item.boundModelId)
          if (bound) eligible.push(bound)
        }
        const options = eligible.length
          ? eligible
              .map(
                (model) =>
                  `<option value="${esc(model.id)}"${item.boundModelId === model.id ? ' selected' : ''}>${esc(
                    model.name,
                  )}${model.endpointKind ? ` · ${esc(endpointKindLabel(model.endpointKind))}` : ''}</option>`,
              )
              .join('')
          : `<option value="" selected>${pluginModelCount ? '插件模型只读，未开放用途绑定' : '没有匹配该用途的模型'}</option>`
        const selectHtml = eligible.length
          ? `<select data-route-purpose="${esc(item.purpose)}">
            <option value="">自动选择</option>
            ${options}
          </select>`
          : `<select data-route-purpose="${esc(item.purpose)}" disabled>${options}</select>`
        const badgeText = item.boundModelId ? '已绑定' : item.effectiveModelId ? '自动' : '未配置'
        const badgeHint = item.boundModelId
          ? '已手动绑定模型，不会随优先级自动变化'
          : item.effectiveModelId
            ? '未手动绑定，自动模式选择'
            : '没有可用模型，该用途会降级'
        const tone = item.boundModelId ? 'is-bound' : item.effectiveModelId ? 'is-fallback' : 'is-empty'
        const effectiveName = (item.boundModelId ? item.boundModelName || item.effectiveModelName : item.effectiveModelName) || ''
        const subText = effectiveName ? `当前生效：${effectiveName}` : '没有可用模型，该用途会降级'
        return `<div class="models-route-row ${tone}" data-route-row="${esc(item.purpose)}">
          <div class="models-route-copy">
            <strong>${esc(item.label)}</strong>
            <span>${esc(item.hint)}</span>
            <code>${esc(item.purpose)}</code>
          </div>
          <div class="models-route-pick">
            ${selectHtml}
            <span class="models-route-sub" title="${esc(subText)}">${esc(subText)}</span>
          </div>
          <span class="models-route-badge" title="${esc(badgeHint)}">${esc(badgeText)}</span>
        </div>`
      })
      .join('')

    const providerPanel = `
      <section class="panel models-panel" data-section-panel="providers">
        <div class="models-panel-head">
          <div class="models-title-line">
            <h2>供应商与端点</h2>
            ${hintBadge('端点说明', '接入端点后会自动读取模型清单；读不到也可以手动添加模型。密钥只保存在服务端，不会回到浏览器。')}
          </div>
          <div class="models-panel-actions">
            <span class="models-panel-note">${writableProviders.length} 个端点 · ${pluginProviderCount} 个插件通道 · ${providers.filter((item) => item.status === 'active').length} 个启用</span>
            <button class="btn primary" type="button" id="add-provider">添加供应商</button>
          </div>
        </div>
        <div class="models-table-scroll">
          <table class="data models-provider-table">
            <thead><tr><th class="col-provider-name">供应商</th><th class="col-provider-endpoint">端点</th><th class="col-provider-key">密钥</th><th class="col-provider-model">模型</th><th class="col-provider-status">状态</th><th class="col-provider-actions">操作</th></tr></thead>
            <tbody>${providerRows}</tbody>
          </table>
        </div>
        <div class="models-test-line" id="provider-test-msg"></div>
      </section>`

    const routePanel = `
      <section class="panel models-panel models-route-panel" data-section-panel="routes">
        <div class="models-panel-head">
          <div class="models-title-line">
            <h2>用途路由 <span class="models-panel-count">${boundRouteCount}/${routeItems.length}</span></h2>
            ${hintBadge('路由说明', '把「这次要做什么」绑定到具体模型；对话自动模式按实测回复速度选，其他用途留空时按能力和优先级自动挑。变更立即生效，未配置的用途会降级但不阻断现有对话。插件模型只读，暂不参与显式用途绑定。')}
          </div>
          <span class="models-panel-note">${routeItems.length ? '绑定后立即生效' : '迁移后可用'}</span>
        </div>
        <div class="models-route-list">${routeRows || '<div class="empty">还没有可路由的用途</div>'}</div>
      </section>`

    const catalogPanel = `
      <section class="panel models-panel models-catalog-panel" data-section-panel="catalog">
        <div class="models-panel-head">
          <div class="models-title-line">
            <h2>模型目录 <span class="models-panel-count" id="model-count">${models.length}</span></h2>
            ${hintBadge('能力说明', '按能力管理模型：点击「能力」可直接勾选，保存后立即生效。插件模型要先真实探测通过才会出现在这里；插件停用或卸载后会自动消失。')}
          </div>
          <div class="models-tools">
            <label class="models-search"><span class="models-search-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4 4"></path></svg></span><input id="model-search" type="search" value="${esc(state.modelsSearch)}" placeholder="搜索模型、标识或供应商" autocomplete="off" /></label>
            ${writableProviders.length ? '<button class="btn primary" type="button" id="add-model">添加模型</button>' : ''}
          </div>
        </div>
        <div class="models-filter-bar" id="model-filter"></div>
        <div class="models-table-scroll models-catalog-scroll">
          <table class="data models-table">
            <thead><tr><th class="col-model-name">模型</th><th class="col-model-provider">供应商</th><th class="col-model-type">类型</th><th class="col-model-context">上下文 / 输出</th><th class="col-model-capabilities">能力 / 擅长场景</th><th class="col-model-roles">可见角色</th><th class="col-model-status">状态</th><th class="col-model-actions">操作</th></tr></thead>
            <tbody id="model-rows"></tbody>
          </table>
        </div>
      </section>`

    view.innerHTML = `
      <div class="models-overview">
        <div class="models-overview-copy">
          <span class="models-eyebrow">MODEL ROUTER</span>
          <strong>模型与路由，按任务分开管理 ${hintBadge('使用顺序', '先绑定供应商与端点，再确认模型目录，最后按任务绑定用途路由；密钥只保留在服务端。')}</strong>
        </div>
        <div class="models-summary">
          <div class="models-summary-card"><span>供应商</span><strong id="stat-providers">${providers.length}</strong><small>${writableProviders.length} 个端点 · ${pluginProviderCount} 个插件通道</small></div>
          <div class="models-summary-card"><span>可用模型</span><strong id="stat-enabled">${enabledModels.length}</strong><small>/ ${models.length} 个 · 自动选择 ${esc(autoModel?.name || '—')}</small></div>
          <div class="models-summary-card ${visionModels.length ? 'is-highlight' : ''}"><span>图片识别</span><strong id="stat-vision">${visionModels.length}</strong><small id="stat-vision-note">${visionModels.length ? '工作台可直接粘贴图片' : '尚未标记视觉模型'}</small></div>
          <div class="models-summary-card"><span>模型类型</span><strong id="stat-type">${new Set(models.map((model) => modelTypeOf(model.tags).label)).size}</strong><small>按能力自动归类</small></div>
        </div>
      </div>

      ${sectionNavHtml(
        [
          { key: 'providers', label: '供应商与端点', meta: `${providers.length} 个来源` },
          { key: 'catalog', label: '模型目录', meta: `${models.length} 个模型` },
          {
            key: 'routes',
            label: '用途路由',
            meta: `${boundRouteCount}/${routeItems.length} 已绑定`,
            attention: boundRouteCount < routeItems.length,
          },
        ],
        state.modelsSection || 'providers',
      )}
      <div class="section-panels">
        ${catalogPanel}
        ${routePanel}
        ${providerPanel}
      </div>`

    mountSectionNav(view, state.modelsSection, 'providers', (key) => {
      state.modelsSection = key
    })

    /* 路由行改绑后，页签计数 / 面板计数 / 未绑定高亮都按当前 DOM 重算，避免各算各的。 */
    const syncRouteCounts = () => {
      const routeRows = [...view.querySelectorAll('[data-route-row]')]
      const total = routeRows.length
      const bound = routeRows.filter((row) => row.classList.contains('is-bound')).length
      const counter = view.querySelector('.models-route-panel .models-panel-count')
      if (counter) counter.textContent = `${bound}/${total}`
      const tab = view.querySelector('[data-section-target="routes"]')
      const meta = tab?.querySelector('span')
      if (meta) meta.textContent = `${bound}/${total} 已绑定`
      if (tab) tab.classList.toggle('is-attention', bound < total)
    }

    const byId = new Map(providers.map((item) => [item.id, item]))
    const modelById = new Map(models.map((item) => [item.id, item]))
    const modelFilters = [
      { key: 'all', label: '全部' },
      { key: 'chat', label: '对话' },
      { key: 'decision', label: '决策 / 推理' },
      { key: 'vision', label: '多模态 / 视觉' },
      { key: 'embedding', label: '向量' },
      { key: 'code', label: '代码' },
      { key: 'audio', label: '语音' },
      { key: 'video', label: '视频' },
    ]
    const modelMatchesFilter = (model, filter) => {
      if (filter === 'all') return true
      const caps = modelCapabilitySummary(model.tags).keys
      if (filter === 'decision') return caps.includes('decision') || caps.includes('reasoning')
      if (filter === 'vision') return caps.includes('vision') || caps.includes('multimodal')
      return caps.includes(filter)
    }
    const tokenLimitLabel = (value) => {
      if (!value) return '—'
      return value >= 1024 ? `${Number((value / 1024).toFixed(1))}K` : String(value)
    }
    const modelRowHtml = (model) => {
      const caps = modelCapabilitySummary(model.tags)
      const type = modelTypeOf(model.tags)
      const readonly = model.readonly === true || model.source === 'plugin'
      const chatLike = model.endpointKind === 'chat' || model.endpointKind === 'systemone'
      const contextLabel = model.maxContext
        ? tokenLimitLabel(model.maxContext)
        : chatLike
          ? '默认 32K'
          : '—'
      const outputLabel = model.maxOutputTokens
        ? tokenLimitLabel(model.maxOutputTokens)
        : chatLike
          ? '默认 4K'
          : '—'
      const thinkTag = model.thinking?.enabled
        ? `<span class="models-source-tag is-think" title="员工可在对话页切换思考档位">可调思考</span>`
        : ''
      const roleChips = model.roles.length
        ? model.roles.length === roles.length
          ? '<span class="chip accent">全部角色</span>'
          : model.roles
              .slice(0, 2)
              .map((code) => `<span class="chip accent">${esc(ROLE_LABEL[code] || code)}</span>`)
              .join('') +
            (model.roles.length > 2 ? `<span class="models-role-more">+${model.roles.length - 2}</span>` : '')
        : '<span class="muted">未授权角色</span>'
      return `<tr data-model-row="${esc(model.id)}">
        <td class="col-model-name">
          <div class="models-model-cell">
            <strong>${esc(model.name)}${readonly ? '<span class="models-source-tag">插件</span>' : ''}${thinkTag}</strong>
            <span class="mono models-model-key">${esc(model.modelKey)}</span>
          </div>
        </td>
        <td class="col-model-provider">
          <span class="models-provider-pill">${esc(model.providerName)}</span>
          <div class="desc">${readonly ? '插件注入 · 角色可配置' : `${esc(model.providerKind)} · 优先级 ${model.priority}`}</div>
        </td>
        <td class="col-model-type"><span class="models-type-badge ${type.tone}">${esc(type.label)}</span>${
          model.endpointKind && model.endpointKind !== 'chat'
            ? `<div class="desc">${esc(endpointKindLabel(model.endpointKind))}端点</div>`
            : ''
        }</td>
        <td class="models-limits-cell col-model-context">
          <span class="mono">${contextLabel}</span>
          <div class="desc">输出 ${outputLabel}</div>
        </td>
        <td class="col-model-capabilities">
          ${
            readonly
              ? `<span class="models-caps-readonly" title="能力由插件定义，插件更新后自动变化">${capabilityChipsHtml(model.tags, 3)}</span>`
              : `<button class="models-cap-trigger" type="button" data-cap-model="${esc(model.id)}" title="点击设置能力 / 擅长场景">
            ${capabilityChipsHtml(model.tags, 3)}
          </button>`
          }
        </td>
        <td class="models-roles-cell col-model-roles">${roleChips}</td>
        <td class="col-model-status"><span class="pill ${model.enabled ? 'ok' : 'warn'}">${model.enabled ? '启用' : '停用'}</span></td>
        <td class="model-actions col-model-actions">
          ${
            readonly
              ? `<button class="btn sm model-action-btn" type="button" data-edit-plugin-model="${esc(model.id)}" data-tip="配置这个插件模型可见的角色；上下文与输出由插件声明。" aria-label="配置插件模型可见角色">${modelActionIcon('edit')}</button>`
              : `
          ${
            (model.endpointKind ?? 'chat') === 'chat'
              ? `<button class="btn sm model-action-btn" type="button" data-stress-model="${esc(model.id)}" data-tip="压测：直接调用真实模型，检查端点并发能力。" aria-label="压测">${modelActionIcon('stress')}</button>`
              : ''
          }
          <button class="btn sm model-action-btn" type="button" data-edit-model="${esc(model.id)}" data-tip="编辑模型。" aria-label="编辑模型">${modelActionIcon('edit')}</button>
          <button class="btn sm model-action-btn" type="button" data-toggle-model="${esc(model.id)}" data-tip="${model.enabled ? '停用模型。' : '启用模型。'}" aria-label="${model.enabled ? '停用模型' : '启用模型'}">${modelActionIcon('toggle')}</button>
          <button class="btn sm model-action-btn is-danger" type="button" data-del-model="${esc(model.id)}" data-tip="删除模型。" aria-label="删除模型">${modelActionIcon('delete')}</button>
          `
          }
        </td>
      </tr>`
    }
    const renderFilterChips = () => {
      const filterHtml = modelFilters
        .map((filter) => {
          const count = models.filter((model) => modelMatchesFilter(model, filter.key)).length
          return `<button class="models-filter ${state.modelsFilter === filter.key ? 'is-active' : ''}" type="button" data-model-filter="${filter.key}">
            ${filter.label}<span>${count}</span>
          </button>`
        })
        .join('')
      const filterBar = view.querySelector('#model-filter')
      if (filterBar) filterBar.innerHTML = filterHtml
    }
    const renderModelRows = () => {
      const rows = view.querySelector('#model-rows')
      if (!rows) return
      const query = String(state.modelsSearch || '').trim().toLowerCase()
      const visible = models.filter((model) => {
        if (!modelMatchesFilter(model, state.modelsFilter)) return false
        if (!query) return true
        const haystack = `${model.name} ${model.modelKey} ${model.providerName} ${modelCapabilitySummary(model.tags).labels.join(' ')}`.toLowerCase()
        return haystack.includes(query)
      })
      rows.innerHTML =
        visible.map(modelRowHtml).join('') ||
        `<tr><td colspan="8" class="empty models-empty">
          <strong>${query || state.modelsFilter !== 'all' ? '没有匹配的模型' : '还没有模型'}</strong>
          <span>${query || state.modelsFilter !== 'all' ? '换个关键词或筛选条件试试。' : '先添加一个模型；任意模型都可以接入，能力标签决定它能做什么。'}</span>
          ${
            query || state.modelsFilter !== 'all'
              ? '<button class="btn" type="button" data-clear-model-filter>清除筛选</button>'
              : writableProviders.length
                ? '<button class="btn primary" type="button" data-empty-add-model>添加模型</button>'
                : ''
          }
        </td></tr>`
      const count = view.querySelector('#model-count')
      if (count) count.textContent = `${visible.length} / ${models.length}`
    }
    const updateModelStats = () => {
      const enabled = models.filter((model) => model.enabled).length
      const visual = models.filter((model) => {
        const caps = modelCapabilitySummary(model.tags).keys
        return caps.includes('vision') || caps.includes('multimodal')
      }).length
      view.querySelector('#stat-enabled')?.replaceChildren(document.createTextNode(String(enabled)))
      view.querySelector('#stat-vision')?.replaceChildren(document.createTextNode(String(visual)))
      const visionNote = view.querySelector('#stat-vision-note')
      if (visionNote) visionNote.textContent = visual ? '工作台可直接粘贴图片' : '尚未标记视觉模型'
      view.querySelector('#stat-type')?.replaceChildren(
        document.createTextNode(String(new Set(models.map((model) => modelTypeOf(model.tags).label)).size)),
      )
      const visualCard = view.querySelector('#stat-vision')?.closest('.models-summary-card')
      visualCard?.classList.toggle('is-highlight', visual > 0)
    }
    renderFilterChips()
    renderModelRows()

    view.querySelector('#add-provider')?.addEventListener('click', () => openProviderModal(null))
    view.querySelector('#add-model')?.addEventListener('click', () => openModelModal(null, writableProviders, modelData.roles))
    view.querySelectorAll('[data-refresh-plugin-channel]').forEach((button) => {
      button.addEventListener('click', async () => {
        const channelId = button.dataset.refreshPluginChannel
        button.disabled = true
        try {
          const queued = await apiPost(`/api/console/plugin-channels/${encodeURIComponent(channelId)}/refresh`)
          if (queued.jobId) {
            showTopToast('已提交后台探测，完成后自动刷新列表')
            let job = null
            for (let attempt = 0; attempt < 150; attempt += 1) {
              await new Promise((resolve) => setTimeout(resolve, 1200))
              job = await api(`/api/console/jobs/${encodeURIComponent(queued.jobId)}`)
              if (['succeeded', 'failed', 'cancelled'].includes(job.status)) break
            }
            if (!job) throw new Error('作业状态读取超时')
            if (job.status === 'succeeded') {
              const result = job.result || {}
              showTopToast(
                result.checked
                  ? `插件模型已探测：${result.models}/${result.checked} 个可正常回复`
                  : '插件通道没有可探测的模型',
              )
            } else if (job.status === 'failed') {
              showTopToast(job.error || '插件模型刷新失败', { tone: 'warn' })
            } else {
              showTopToast('作业已取消或仍未完成，稍后重试', { tone: 'warn' })
            }
            loadModels()
            return
          }
          const result = queued
          showTopToast(
            result.checked
              ? `插件模型已探测：${result.models}/${result.checked} 个可正常回复`
              : '插件通道没有可探测的模型',
          )
          loadModels()
        } catch (err) {
          showTopToast(err.message || '插件模型刷新失败', { tone: 'warn' })
        } finally {
          button.disabled = false
        }
      })
    })
    for (const select of view.querySelectorAll('[data-route-purpose]')) {
      select.addEventListener('change', async () => {
        const row = select.closest('[data-route-row]')
        const badge = row?.querySelector('.models-route-badge')
        const sub = row?.querySelector('.models-route-sub')
        if (badge) badge.textContent = '保存中…'
        try {
          const result = await apiSend('PUT', `/api/console/model-routes/${encodeURIComponent(select.dataset.routePurpose)}`, {
            modelId: select.value || null,
          })
          const bound = Boolean(result.boundModelId)
          const name = result.effectiveModelName || ''
          const tone = bound ? 'is-bound' : name ? 'is-fallback' : 'is-empty'
          if (row) {
            row.classList.remove('is-bound', 'is-fallback', 'is-empty')
            row.classList.add(tone)
          }
          syncRouteCounts()
          if (badge) {
            badge.textContent = bound ? '已绑定' : name ? '自动' : '未配置'
            badge.title = bound
              ? '已手动绑定模型，不会随优先级自动变化'
              : name
                ? '未手动绑定，自动模式选择'
                : '没有可用模型，该用途会降级'
          }
          if (sub) {
            sub.textContent = name ? `当前生效：${name}` : '没有可用模型，该用途会降级'
            sub.title = sub.textContent
          }
        } catch (err) {
          if (badge) badge.textContent = '保存失败'
          alert(err.message || '用途路由保存失败')
        }
      })
    }
    view.querySelector('#model-search')?.addEventListener('input', (event) => {
      state.modelsSearch = event.target.value
      renderModelRows()
    })
    view.onclick = async (event) => {
      const filterButton = event.target.closest('[data-model-filter]')
      if (filterButton) {
        state.modelsFilter = filterButton.dataset.modelFilter
        renderFilterChips()
        renderModelRows()
        return
      }
      const clearFilter = event.target.closest('[data-clear-model-filter]')
      if (clearFilter) {
        state.modelsFilter = 'all'
        state.modelsSearch = ''
        const search = view.querySelector('#model-search')
        if (search) search.value = ''
        renderFilterChips()
        renderModelRows()
        return
      }
      if (event.target.closest('[data-empty-add-model]')) {
        openModelModal(null, writableProviders, modelData.roles)
        return
      }
      const capButton = event.target.closest('[data-cap-model]')
      if (capButton) {
        const model = modelById.get(capButton.dataset.capModel)
        if (!model) return
        openModelCapabilityPopover(capButton, model, async (tags) => {
          await apiSend('PATCH', `/api/console/models/${encodeURIComponent(model.id)}`, { tags })
          model.tags = tags
          renderFilterChips()
          renderModelRows()
          updateModelStats()
        })
        return
      }
      const stressButton = event.target.closest('[data-stress-model]')
      if (stressButton) {
        const model = modelById.get(stressButton.dataset.stressModel)
        if (model) openModelStressModal(model, stressButton)
        return
      }
      const pluginEditButton = event.target.closest('[data-edit-plugin-model]')
      if (pluginEditButton) {
        const model = modelById.get(pluginEditButton.dataset.editPluginModel)
        if (model) openPluginModelRoleModal(model, modelData.roles)
        return
      }
      const editButton = event.target.closest('[data-edit-model]')
      if (editButton) {
        openModelModal(modelById.get(editButton.dataset.editModel), writableProviders, modelData.roles)
        return
      }
      const toggleButton = event.target.closest('[data-toggle-model]')
      if (toggleButton) {
        const model = modelById.get(toggleButton.dataset.toggleModel)
        if (!model) return
        try {
          await apiSend('PATCH', `/api/console/models/${encodeURIComponent(model.id)}`, { enabled: !model.enabled })
          loadModels()
        } catch (err) {
          alert(err.message || '保存失败')
        }
        return
      }
      const deleteButton = event.target.closest('[data-del-model]')
      if (deleteButton) {
        const model = modelById.get(deleteButton.dataset.delModel)
        if (!model) return
        const ok = await confirmCard({
          title: '删除模型？',
          message: `删除后「${model.name}」将不能再用于对话。`,
          confirmText: '删除模型',
        })
        if (!ok) return
        try {
          await apiSend('DELETE', `/api/console/models/${encodeURIComponent(model.id)}`)
          loadModels()
        } catch (err) {
          alert(err.message || '删除失败')
        }
      }
    }

    view.querySelectorAll('[data-edit-provider]').forEach((button) => {
      button.addEventListener('click', () => openProviderModal(byId.get(button.dataset.editProvider)))
    })
    view.querySelectorAll('[data-test]').forEach((button) => {
      button.addEventListener('click', async () => {
        const msg = $('#provider-test-msg')
        if (msg) msg.textContent = '测试中…'
        try {
          const result = await apiPost(`/api/console/providers/${encodeURIComponent(button.dataset.test)}/test`)
          if (msg) msg.textContent = `${result.ok ? '✓' : '✗'} ${result.message}`
        } catch (err) {
          if (msg) msg.textContent = err.message || '测试失败'
        }
      })
    })
    view.querySelectorAll('[data-discover-provider]').forEach((button) => {
      button.addEventListener('click', () => discoverProviderModels(byId.get(button.dataset.discoverProvider)))
    })
    view.querySelectorAll('[data-toggle-provider]').forEach((button) => {
      button.addEventListener('click', async () => {
        const provider = byId.get(button.dataset.toggleProvider)
        await apiSend('PATCH', `/api/console/providers/${encodeURIComponent(provider.id)}`, {
          status: provider.status === 'active' ? 'disabled' : 'active',
        })
        loadModels()
      })
    })
    view.querySelectorAll('[data-del-provider]').forEach((button) => {
      button.addEventListener('click', async () => {
        const ok = await confirmCard({
          title: '删除供应商？',
          message: '如果这个供应商下面还有模型，服务端会拒绝删除。',
          confirmText: '删除供应商',
        })
        if (!ok) return
        try {
          await apiSend('DELETE', `/api/console/providers/${encodeURIComponent(button.dataset.delProvider)}`)
          loadModels()
        } catch (err) {
          alert(err.message || '删除失败')
        }
      })
    })
  } catch (err) {
    renderDenied(view, err)
  }
}

function matrixScopeGroups(scopeData) {
  const groups = new Map()
  for (const scope of scopeData.scopes || []) {
    const title = scopeData.groups?.[scope] || '其他'
    if (!groups.has(title)) groups.set(title, [])
    groups.get(title).push({ key: scope, label: scopeData.labels?.[scope] || scope })
  }
  return [...groups.entries()].map(([title, items]) => ({ key: title, title, items }))
}

function matrixConsoleDomains(catalog) {
  const pageMeta = new Map((catalog?.pages || []).map((page) => [page.page, page]))
  return (catalog?.domains || []).map((domain) => {
    const items = []
    for (const pageKey of domain.pages || []) {
      const meta = pageMeta.get(pageKey)
      const sections = Array.isArray(meta?.sections) ? meta.sections : []
      if (sections.length) {
        for (const section of sections) {
          items.push({
            key: `${pageKey}:${section.key}`,
            label: section.title || `${pageKey}:${section.key}`,
            page: pageKey,
          })
        }
      } else {
        items.push({ key: pageKey, label: meta?.title || pageKey, page: pageKey })
      }
    }
    return { key: domain.id || domain.title, title: domain.title || domain.label || domain.id || '后台页面', items }
  })
}

function matrixTooltip(title, grantedLabels) {
  if (!grantedLabels.length) return `${title}：未授予`
  const preview = grantedLabels.slice(0, 6).join('、')
  return `${title}：${preview}${grantedLabels.length > 6 ? ` 等 ${grantedLabels.length} 项` : ''}`
}

function matrixCellHtml(role, rowTitle, grantedLabels, total) {
  const granted = grantedLabels.length
  const ratio = total > 0 ? granted / total : 0
  const level = granted === 0 ? 'none' : granted === total ? 'full' : ratio >= 0.6 ? 'high' : 'partial'
  const label = `${roleDisplayName(role)} · ${rowTitle}：${granted} / ${total} 项`
  return `<td class="role-matrix-cell is-${level}" data-matrix-col="${esc(role.code)}" aria-label="${esc(label)}" title="${esc(
    matrixTooltip(label, grantedLabels),
  )}"><span>${granted ? `${granted}<em>/${total}</em>` : '—'}</span></td>`
}

function roleMatrixPageHtml(data) {
  const roles = data.roles || []
  const mode = state.matrixMode === 'pages' ? 'pages' : 'scopes'
  const filter = state.matrixFilter === 'builtin' || state.matrixFilter === 'custom' ? state.matrixFilter : 'all'
  const filteredRoles = roles.filter((role) =>
    filter === 'builtin' ? role.builtin : filter === 'custom' ? !role.builtin : true,
  )
  const scopeGroups = matrixScopeGroups(data.scopeData || {})
  const consoleDomains = matrixConsoleDomains(data.catalog)
  const scopeTotal = (data.scopeData?.scopes || []).length
  const pageTotal = consoleDomains.reduce((sum, domain) => sum + domain.items.length, 0)
  const rows = mode === 'pages' ? consoleDomains : scopeGroups
  const modeLabel = mode === 'pages' ? '后台页面' : '功能权限'
  const roleHeader = (role) => `<th class="role-matrix-role" data-matrix-col="${esc(role.code)}">
    <button class="role-matrix-role-btn" type="button" data-matrix-role="${esc(role.code)}" title="打开 ${esc(
      roleDisplayName(role),
    )} 的角色详情">
      <span class="role-matrix-avatar" aria-hidden="true">${esc(String(roleDisplayName(role)).slice(0, 1))}</span>
      <span class="role-matrix-role-main">
        <strong>${esc(roleDisplayName(role))}</strong>
        <small>${esc(DATA_SCOPE_LABEL[role.dataScope] || role.dataScope)} · ${role.members || 0} 人</small>
      </span>
      <em>${role.builtin ? '内置' : '自定义'}</em>
    </button>
  </th>`
  const roleScopes = new Map(filteredRoles.map((role) => [role.code, new Set(role.scopes || [])]))
  const consoleKeys = new Map(
    filteredRoles.map((role) => [
      role.code,
      new Set(
        (Array.isArray(role.consolePages) ? role.consolePages : [])
          .filter((page) => page.canView)
          .map((page) => page.page),
      ),
    ]),
  )
  const grantedLabelsFor = (item, role) =>
    mode === 'pages'
      ? item.items.filter((leaf) => consoleKeys.get(role.code)?.has(leaf.key)).map((leaf) => leaf.label)
      : item.items.filter((scope) => roleScopes.get(role.code)?.has(scope.key)).map((scope) => scope.label)
  const rowScore = (item) => filteredRoles.reduce((sum, role) => sum + grantedLabelsFor(item, role).length, 0)
  const orderedRows =
    mode === 'pages' ? [...rows].sort((a, b) => rowScore(b) - rowScore(a)) : rows
  const row = (item) => {
    return `<tr>
      <th class="role-matrix-row-head"><strong>${esc(item.title)}</strong><span>${item.items.length} 项</span></th>
      ${filteredRoles
        .map((role) => matrixCellHtml(role, item.title, grantedLabelsFor(item, role), item.items.length))
        .join('')}
    </tr>`
  }
  const table =
    filteredRoles.length === 0
      ? '<div class="empty role-matrix-empty">当前筛选没有角色。</div>'
      : `<div class="matrix-wrap role-matrix-wrap">
          <table class="data matrix role-matrix">
            <thead><tr><th class="role-matrix-corner">权限分组</th>${filteredRoles.map(roleHeader).join('')}</tr></thead>
            <tbody>${orderedRows.map(row).join('')}<tr id="role-matrix-no-hit" hidden><td class="role-matrix-no-hit" colspan="${
              filteredRoles.length + 1
            }">没有匹配的角色，换个关键词试试。</td></tr></tbody>
          </table>
        </div>`
  const matrixHint =
    mode === 'pages'
      ? '按业务域汇总每个角色可见的后台页面；只核对结果，具体勾选仍在角色详情的「后台权限」。'
      : '按权限分组汇总每个角色已获得的权限点；颜色越深表示该组覆盖越完整。'
  return `<section class="role-matrix-hero">
      <div class="role-matrix-copy">
        <span class="role-eyebrow">组织与权限 · 权限矩阵</span>
        <h2>角色 × ${modeLabel}${hintBadge('?', matrixHint, `${modeLabel}矩阵说明`, 'icon-only')}</h2>
        <div class="role-matrix-hero-actions">
          <button class="btn ghost" type="button" id="matrix-refresh">刷新</button>
          <button class="btn" type="button" id="matrix-to-roles">角色管理</button>
        </div>
      </div>
      <div class="role-matrix-stats">
        <div><span>角色</span><strong>${roles.length}</strong></div>
        <div><span>功能权限</span><strong>${scopeTotal}</strong></div>
        <div><span>后台页面</span><strong>${pageTotal}</strong></div>
      </div>
    </section>
    <div class="role-matrix-toolbar">
      <div class="role-matrix-modes" role="tablist" aria-label="矩阵维度">
        <button class="role-matrix-mode${mode === 'scopes' ? ' is-active' : ''}" type="button" role="tab" aria-selected="${
          mode === 'scopes'
        }" data-matrix-mode="scopes">功能权限</button>
        <button class="role-matrix-mode${mode === 'pages' ? ' is-active' : ''}" type="button" role="tab" aria-selected="${
          mode === 'pages'
        }" data-matrix-mode="pages">后台页面</button>
      </div>
      <div class="role-matrix-tools">
        <label class="role-matrix-search">
          <span aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4 4"></path></svg></span>
          <input id="role-matrix-search" type="search" value="${esc(state.matrixQuery || '')}" placeholder="搜索角色名或编码" aria-label="搜索矩阵中的角色" autocomplete="off" />
        </label>
        <select id="role-matrix-filter" aria-label="筛选角色类型">
          <option value="all"${filter === 'all' ? ' selected' : ''}>全部角色</option>
          <option value="builtin"${filter === 'builtin' ? ' selected' : ''}>只看内置</option>
          <option value="custom"${filter === 'custom' ? ' selected' : ''}>只看自定义</option>
        </select>
        <span class="role-matrix-visible-count" id="role-matrix-visible-count">显示 ${filteredRoles.length} / ${roles.length} 个角色</span>
      </div>
    </div>
    <section class="panel role-matrix-panel">
      <div class="panel-head">
        <div><h2>${modeLabel}矩阵${hintBadge('?', '行是权限分组，列是角色；数字表示该角色在该组已获得的项数 / 总项数', `${modeLabel}矩阵表格说明`, 'icon-only')}</h2></div>
        <span class="pill" id="role-matrix-mode-pill">${rows.length} 个分组 · ${filteredRoles.length} 个角色</span>
      </div>
      ${table}
      <div class="role-matrix-legend">
        <span><i class="role-matrix-dot is-none"></i>未授予</span>
        <span><i class="role-matrix-dot is-partial"></i>部分授予</span>
        <span><i class="role-matrix-dot is-high"></i>覆盖较高</span>
        <span><i class="role-matrix-dot is-full"></i>全部授予</span>
        <span class="muted">点击列头打开角色详情；矩阵只读，修改请进入角色详情。</span>
      </div>
    </section>`
}

function setupRoleMatrix(root, data) {
  const roles = data.roles || []
  const repaint = () => {
    root.innerHTML = roleMatrixPageHtml(data)
    setupRoleMatrix(root, data)
  }
  root.querySelector('#matrix-refresh')?.addEventListener('click', () => loadMatrix())
  root.querySelector('#matrix-to-roles')?.addEventListener('click', () => {
    state.selectedRole = null
    state.roleTab = 'permissions'
    navigate('roles')
  })
  root.querySelectorAll('[data-matrix-mode]').forEach((button) => {
    button.addEventListener('click', () => {
      if (button.dataset.matrixMode === state.matrixMode) return
      state.matrixMode = button.dataset.matrixMode === 'pages' ? 'pages' : 'scopes'
      window.scrollTo(0, 0)
      repaint()
    })
  })
  root.querySelector('#role-matrix-filter')?.addEventListener('change', (event) => {
    state.matrixFilter = event.target.value
    repaint()
  })
  root.querySelectorAll('[data-matrix-role]').forEach((button) => {
    button.addEventListener('click', () => {
      state.selectedRole = button.dataset.matrixRole
      state.roleTab = 'permissions'
      navigate('roles')
    })
  })
  const search = root.querySelector('#role-matrix-search')
  const visibleCount = root.querySelector('#role-matrix-visible-count')
  const noHit = root.querySelector('#role-matrix-no-hit')
  const applySearch = () => {
    const tokens = String(search?.value || '')
      .trim()
      .toLowerCase()
      .split(/\s+/)
      .filter(Boolean)
    const columnNodes = [...root.querySelectorAll('[data-matrix-col]')]
    let shown = 0
    for (const role of roles) {
      const text = [roleDisplayName(role), role.code, DATA_SCOPE_LABEL[role.dataScope] || role.dataScope]
        .join(' ')
        .toLowerCase()
      const hit = tokens.every((token) => text.includes(token))
      if (hit) shown += 1
      for (const node of columnNodes) {
        if (node.dataset.matrixCol !== role.code) continue
        node.hidden = !hit
      }
    }
    if (visibleCount) visibleCount.textContent = `显示 ${shown} / ${roles.length} 个角色`
    if (noHit) noHit.hidden = shown > 0
  }
  if (search) {
    search.addEventListener('input', () => {
      state.matrixQuery = search.value
      applySearch()
    })
    search.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape' || !search.value) return
      event.stopPropagation()
      search.value = ''
      state.matrixQuery = ''
      applySearch()
    })
  }
  applySearch()
}

async function loadMatrix() {
  const view = $('#view')
  renderLoading(view)
  setSide('', true)
  try {
    const [rolesData, scopeData, membersData] = await Promise.all([
      api('/api/console/roles'),
      api('/api/console/scopes'),
      api('/api/org/members').catch(() => ({ members: [] })),
    ])
    const allMembers = membersData?.members ?? []
    for (const role of rolesData.roles || []) {
      role.members = allMembers.filter((member) => (member.roles || []).some((item) => item.code === role.code)).length
    }
    const data = {
      roles: rolesData.roles || [],
      catalog: rolesData.catalog || state.access?.catalog || null,
      scopeData,
    }
    state.roles = data.roles
    renderNavRail()
    view.innerHTML = roleMatrixPageHtml(data)
    setupRoleMatrix(view, data)
    setPageActions('')
  } catch (err) {
    renderDenied(view, err)
  }
}

