            <input id="agent-team-max-workers" type="number" inputmode="numeric" min="${agentTeam.range.min}" max="${agentTeam.range.max}" step="1" value="${esc(String(agentTeam.configured ?? agentTeam.maxWorkers))}" autocomplete="off" />
