            showTopToast(result?.sync?.ok
              ? `同步完成：${result.sync.skillCount} 个技能可用`
              : `同步失败：${result?.sync?.error || 'Agent Card 不可用'}`, { tone: result?.sync?.ok ? 'ok' : 'warn' })
            await PAGES.system.render()
