const TASK_GRAPH_CATALOG_TTL = 5 * 60 * 1000
let taskGraphCatalogCache = null
let taskGraphCatalogPromise = null

function taskGraphCatalogDatalists(catalog) {
  const option = (value, label) => `<option value="${esc(value)}">${esc(label || value)}</option>`
  return `<datalist id="tg-tool-options">${(catalog.tools || [])
    .map((tool) => option(tool.id, tool.source === 'plugin' ? `${tool.name}（插件）` : tool.name))
    .join('')}</datalist>
    <datalist id="tg-model-options">${(catalog.models || [])
      .map((model) => option(model.id, `${model.name}${model.modelKey ? ` · ${model.modelKey}` : ''}`))
      .join('')}</datalist>
    <datalist id="tg-role-options">${(catalog.roles || [])
      .map((role) => option(role.code, role.name || role.code))
      .join('')}</datalist>`
}

function taskGraphCatalogStatus(catalog) {
  if (!catalog || !catalog.at) return '候选 ID 加载中；也可以手动填写。'
  if (!catalog.tools?.length && !catalog.models?.length && !catalog.roles?.length) {
    return '暂无可用候选，可手动填写或检查控制台权限。'
  }
  return `候选：${catalog.tools?.length || 0} 个工具 · ${catalog.models?.length || 0} 个模型 · ${catalog.roles?.length || 0} 个角色`
}

async function loadTaskGraphCatalog(force = false) {
  const now = Date.now()
  if (!force && taskGraphCatalogCache && now - taskGraphCatalogCache.at < TASK_GRAPH_CATALOG_TTL) {
    return taskGraphCatalogCache
  }
  if (taskGraphCatalogPromise) return taskGraphCatalogPromise
  taskGraphCatalogPromise = Promise.all([
    api('/api/console/tools/access').catch(() => null),
    api('/api/console/models').catch(() => null),
    api('/api/console/roles').catch(() => null),
  ])
    .then(([toolsData, modelsData, rolesData]) => {
      const tools = (toolsData?.tools || [])
        .filter((tool) => tool && tool.id && tool.available !== false)
        .map((tool) => ({ id: tool.id, name: tool.name || tool.id, source: tool.source || 'builtin' }))
      const models = (modelsData?.models || [])
        .filter((model) => model && model.id && model.enabled && (model.endpointKind === 'chat' || model.endpointKind === 'systemone'))
        .map((model) => ({ id: model.id, name: model.name || model.id, modelKey: model.modelKey || '' }))
      const roles = (rolesData?.roles || [])
        .filter((role) => role && role.code)
        .map((role) => ({ code: role.code, name: role.name || role.code }))
      taskGraphCatalogCache = { tools, models, roles, at: Date.now() }
      return taskGraphCatalogCache
    })
    .catch(() => {
      taskGraphCatalogCache = { tools: [], models: [], roles: [], at: Date.now() }
      return taskGraphCatalogCache
    })
    .finally(() => {
      taskGraphCatalogPromise = null
    })
  return taskGraphCatalogPromise
}

async function hydrateTaskGraphCatalog(host) {
  if (!host) return
  try {
    const catalog = await loadTaskGraphCatalog()
    if (!host.isConnected) return
    const status = host.querySelector('#tg-catalog-status')
    if (status) status.textContent = taskGraphCatalogStatus(catalog)
    for (const [id, items] of [
      ['tg-tool-options', catalog.tools],
      ['tg-model-options', catalog.models],
      ['tg-role-options', catalog.roles],
    ]) {
      const datalist = host.querySelector(`#${id}`)
      if (!datalist) continue
      datalist.innerHTML = (items || [])
        .map((item) => {
          const key = item.id || item.code
          const label = item.name || key
          return `<option value="${esc(key)}">${esc(id === 'tg-model-options' && item.modelKey ? `${label} · ${item.modelKey}` : label)}</option>`
        })
        .join('')
    }
  } catch {
    /* 自动补全失败不阻断表单编辑 */
  }
}

function taskGraphDefaultSelectedNode(definition) {
  return (
    definition?.nodes?.find((node) => node.id && node.kind !== 'start' && node.kind !== 'end')?.id ||
    definition?.nodes?.[0]?.id ||
    ''
  )
}

function taskGraphFieldOptions(definition) {
  const values = new Set([
    ['input.question', '运行输入 · 问题'],
    ['input.userId', '运行输入 · 用户 ID'],
    ['input.date', '运行输入 · 日期'],
  ])
  for (const node of definition?.nodes || []) {
    if (!node || !node.id) continue
    values.add([`nodes.${node.id}`, `节点输出 · ${node.title || node.id}`])
    if (node.kind === 'tool' || node.kind === 'agent') {
      values.add([`nodes.${node.id}.text`, `文本输出 · ${node.title || node.id}`])
      values.add([`nodes.${node.id}.count`, `计数输出 · ${node.title || node.id}`])
      values.add([`nodes.${node.id}.result`, `结果输出 · ${node.title || node.id}`])
    }
    if (node.kind === 'tool') {
      values.add([`nodes.${node.id}.hits.0.title`, `首条命中标题 · ${node.title || node.id}`])
    }
  }
  return [...values]
    .map(([value, label]) => `<option value="${esc(value)}">${esc(label)}</option>`)
    .join('')
}

function taskGraphRuleLabel(rule) {
  if (!rule || typeof rule !== 'object') return ''
  if (rule.else) return '否则'
  const opEntry = TASK_GRAPH_RULE_OPS.find(([id]) => id === (rule.op || 'truthy'))
  const opLabel = opEntry ? opEntry[1] : rule.op || '满足'
  const field = String(rule.field || '字段')
  const value = rule.value === undefined || rule.value === null || rule.value === '' ? '' : String(rule.value)
  const label = `${field} ${opLabel}${value ? ` ${value}` : ''}`
  return label.length > 34 ? `${label.slice(0, 32)}…` : label
}

function taskGraphFlowEdgeList(definition) {
  const byId = new Map((definition?.nodes || []).filter((node) => node?.id).map((node) => [node.id, node]))
  const edges = []
  for (const node of byId.values()) {
    for (const target of node.nextIds || []) {
      if (!byId.has(target) || target === node.id) continue
      edges.push({
        from: node.id,
        to: target,
        type: node.kind === 'condition' ? 'branch' : 'normal',
        label: node.kind === 'condition' ? taskGraphRuleLabel(node.edgeRules?.[target]) : '',
      })
    }
    if (node.kind === 'manual' && node.manual?.rejectNextId && byId.has(node.manual.rejectNextId)) {
      edges.push({ from: node.id, to: node.manual.rejectNextId, type: 'reject', label: '拒绝' })
    }
  }
  return edges
}

function taskGraphFlowLayout(definition) {
  const nodes = (definition?.nodes || []).filter((node) => node && node.id && node.kind)
  if (!nodes.length) return { nodes: [], edges: [], width: 0, height: 0 }
  const byId = new Map(nodes.map((node) => [node.id, node]))
  const edges = taskGraphFlowEdgeList(definition)
  const entryId = byId.has(definition.entry) ? definition.entry : nodes[0].id
  const depth = new Map([[entryId, 0]])

  // 有环时也能停下来，最多按节点数传播
  for (let pass = 0; pass < nodes.length; pass += 1) {
    let changed = false
    for (const edge of edges) {
      if (!depth.has(edge.from) || !byId.has(edge.to)) continue
      const next = depth.get(edge.from) + 1
      if (!depth.has(edge.to) || next > depth.get(edge.to)) {
        depth.set(edge.to, next)
        changed = true
      }
    }
    if (!changed) break
  }

  const order = new Map()
  let sequence = 0
  const visit = (id, stack) => {
    if (!id || order.has(id) || stack.has(id)) return
    order.set(id, sequence)
    sequence += 1
    stack.add(id)
    for (const edge of edges.filter((item) => item.from === id)) visit(edge.to, stack)
    stack.delete(id)
  }
  visit(entryId, new Set())
  for (const node of nodes) {
    if (!order.has(node.id)) {
      order.set(node.id, sequence)
      sequence += 1
    }
  }

  const knownDepths = [...depth.values()]
  const maxKnownDepth = knownDepths.length ? Math.max(...knownDepths) : 0
  for (const node of nodes) {
    if (!depth.has(node.id)) depth.set(node.id, maxKnownDepth + 1)
  }
  const maxDepth = Math.max(...nodes.map((node) => depth.get(node.id) || 0))

  const sorted = [...nodes].sort((a, b) => {
    const depthDiff = (depth.get(a.id) || 0) - (depth.get(b.id) || 0)
    return depthDiff || (order.get(a.id) || 0) - (order.get(b.id) || 0)
  })

  const metrics = { nodeW: 176, nodeH: 78, gapX: 34, gapY: 62, pad: 24 }
  const layers = []
  for (const node of sorted) {
    const d = depth.get(node.id) || 0
    if (!layers[d]) layers[d] = []
    layers[d].push(node)
  }
  let widest = 0
  for (const layer of layers) {
    if (!layer) continue
    widest = Math.max(widest, layer.length)
  }
  const width = Math.max(520, metrics.pad * 2 + widest * metrics.nodeW + Math.max(0, widest - 1) * metrics.gapX)
  const height = metrics.pad * 2 + (maxDepth + 1) * metrics.nodeH + maxDepth * metrics.gapY
  const positions = new Map()
  for (let d = 0; d <= maxDepth; d += 1) {
    const layer = layers[d] || []
    if (!layer.length) continue
    const layerWidth = layer.length * metrics.nodeW + (layer.length - 1) * metrics.gapX
    const startX = metrics.pad + Math.max(0, (width - metrics.pad * 2 - layerWidth) / 2)
    layer.forEach((node, index) => {
      positions.set(node.id, {
        x: startX + index * (metrics.nodeW + metrics.gapX),
        y: metrics.pad + d * (metrics.nodeH + metrics.gapY),
      })
    })
  }

  const edgeViews = edges
    .filter((edge) => positions.has(edge.from) && positions.has(edge.to))
    .map((edge, index) => {
      const from = positions.get(edge.from)
      const to = positions.get(edge.to)
      const x1 = from.x + metrics.nodeW / 2
      const y1 = from.y + metrics.nodeH
      const x2 = to.x + metrics.nodeW / 2
      const y2 = to.y
      let path
      if (y2 <= y1 + 2) {
        const bulge = 52 + (index % 3) * 12
        const direction = x2 >= x1 ? 1 : -1
        path = `M ${x1} ${y1} C ${x1 + direction * bulge} ${y1 + 24}, ${x2 + direction * bulge} ${y2 - 24}, ${x2} ${y2}`
      } else {
        const bend = Math.max(20, (y2 - y1) * 0.35)
        path = `M ${x1} ${y1} C ${x1} ${y1 + bend}, ${x2} ${y2 - bend}, ${x2} ${y2}`
      }
      return {
        ...edge,
        path,
        labelX: (x1 + x2) / 2 + ((index % 3) - 1) * 12,
        labelY: (y1 + y2) / 2,
      }
    })

  return { nodes: sorted, positions, edges: edgeViews, width, height, metrics }
}

function taskGraphFlowNodeMeta(node) {
  if (node.kind === 'tool') return node.tool || '未选择工具'
  if (node.kind === 'agent') return node.agent?.modelId || '未选择模型'
  if (node.kind === 'manual') return node.manual?.assigneeRole || '人工审批'
  if (node.kind === 'wait') {
    const parts = taskGraphWaitParts(node.wait?.durationSec ?? 60)
    const unit = (TASK_GRAPH_WAIT_UNITS.find(([sec]) => sec === parts.unit) || ['60', '分钟'])[1]
    return `等待 ${parts.value} ${unit}`
  }
  if (node.kind === 'condition') return `${node.nextIds?.length || 0} 条分支`
  return node.kind === 'end' ? '流程结束' : '流程开始'
}

function taskGraphFlowHtml(definition, selectedNodeId) {
  const layout = taskGraphFlowLayout(definition)
  if (!layout.nodes.length) return '<div class="task-graph-flow-card"><div class="empty">还没有节点，先从模板开始或添加一个节点。</div></div>'
  const { metrics } = layout
  const flowNodes = layout.nodes
    .map((node) => {
      const point = layout.positions.get(node.id)
      if (!point) return ''
      return `<button class="tg-flow-node ${node.id === selectedNodeId ? 'selected' : ''}" type="button" data-tg-flow-node="${esc(node.id)}" style="left:${point.x}px;top:${point.y}px;width:${metrics.nodeW}px;height:${metrics.nodeH}px">
        <span class="tg-flow-node-top"><span class="tg-flow-node-kind tg-flow-kind-${esc(node.kind)}">${esc(taskGraphKindLabel(node.kind))}</span><em>${esc(node.id)}</em></span>
        <strong>${esc(node.title || node.id)}</strong>
        <small>${esc(taskGraphFlowNodeMeta(node))}</small>
      </button>`
    })
    .join('')
  const paths = layout.edges
    .map((edge) => `<path class="tg-flow-edge tg-flow-edge-${edge.type}" d="${edge.path}" marker-end="url(#tg-flow-arrow)"></path>`)
    .join('')
  const labels = layout.edges
    .filter((edge) => edge.label)
    .map(
      (edge) =>
        `<span class="tg-flow-edge-label ${edge.type === 'reject' ? 'reject' : ''}" style="left:${edge.labelX}px;top:${edge.labelY}px">${esc(edge.label)}</span>`,
    )
    .join('')

  return `<div class="task-graph-flow-card">
    <div class="task-graph-flow-head">
      <div><strong>流程图预览</strong><span class="desc">点击节点可定位到下方表单；节点 ID 由系统生成。</span></div>
      <span class="desc">${layout.nodes.length} 个节点 · ${layout.edges.length} 条流转</span>
    </div>
    <div class="task-graph-flow-scroll">
      <div class="task-graph-flow-canvas" style="width:${layout.width}px;height:${layout.height}px">
        <svg class="task-graph-flow-svg" width="${layout.width}" height="${layout.height}" viewBox="0 0 ${layout.width} ${layout.height}" aria-hidden="true">
          <defs>
            <marker id="tg-flow-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="rgba(127,127,127,0.8)"></path></marker>
          </defs>
          ${paths}
        </svg>
        ${flowNodes}
        ${labels}
      </div>
    </div>
    <div class="task-graph-flow-legend"><span><i class="tg-flow-dot"></i>正常流转</span><span><i class="tg-flow-dot branch"></i>条件分支</span><span><i class="tg-flow-dot reject"></i>拒绝后跳转</span></div>
  </div>`
}

function taskGraphClone(value) {
  return JSON.parse(JSON.stringify(value))
}

function taskGraphKindLabel(kind) {
  return TASK_GRAPH_NODE_KIND_LABEL[kind] || kind || '节点'
}

function taskGraphEnsureDefinition(input) {
  const definition = input && typeof input === 'object' ? taskGraphClone(input) : taskGraphTemplate()
  if (!Array.isArray(definition.nodes)) definition.nodes = []
  if (!definition.entry) definition.entry = definition.nodes.find((node) => node.kind === 'start')?.id || ''
  for (const node of definition.nodes) {
    if (!node || typeof node !== 'object') continue
    if (!Array.isArray(node.nextIds)) node.nextIds = []
    if (!node.edgeRules || typeof node.edgeRules !== 'object' || Array.isArray(node.edgeRules)) node.edgeRules = {}
  }
  return definition
}

function taskGraphTargetOptions(nodes, currentId, excludeId) {
  return [
    '<option value="">— 选择节点 —</option>',
    ...nodes
      .filter((node) => node.id !== excludeId)
      .map(
        (node) =>
          `<option value="${esc(node.id)}" ${node.id === currentId ? 'selected' : ''}>${esc(node.title || node.id)}（${esc(node.id)}）</option>`,
      ),
  ].join('')
}

function taskGraphNextNodeId(kind, nodes) {
  const prefix = kind === 'condition' ? 'branch' : kind === 'agent' ? 'agent' : kind
  let index = 1
  while (nodes.some((node) => node.id === `${prefix}${index}`)) index += 1
  return `${prefix}${index}`
}

function taskGraphRuleDefault(hasElse) {
  return hasElse ? { field: 'input.question', op: 'exists' } : { else: true }
}

function taskGraphNewNode(kind, nodes, nextId) {
  const id = taskGraphNextNodeId(kind, nodes)
  const nextIds = nextId ? [nextId] : []
  if (kind === 'condition') {
    return {
      id,
      kind,
      title: '条件分支',
      nextIds,
      edgeRules: nextId ? { [nextId]: { field: 'input.question', op: 'exists' } } : {},
    }
  }
  if (kind === 'agent') {
    return {
      id,
      kind,
      title: '子 Agent 处理',
      nextIds,
      agent: { modelId: '', prompt: '{{input.question}}', maxRounds: 4 },
    }
  }
  if (kind === 'manual') {
    return {
      id,
      kind,
      title: '人工确认',
      nextIds,
      manual: { instructions: '请确认是否继续', assigneeRole: '' },
    }
  }
  if (kind === 'wait') {
    return { id, kind, title: '等待', nextIds, wait: { durationSec: 60 } }
  }
  if (kind === 'end') return { id, kind, title: '结束', nextIds: [] }
  return {
    id,
    kind: 'tool',
    title: '调用工具',
    nextIds,
    tool: 'kb.search',
    args: { query: '{{input.question}}' },
  }
}

function taskGraphReplaceEdge(node, fromId, toId) {
  const index = node.nextIds.indexOf(fromId)
  if (index >= 0) node.nextIds[index] = toId
  if (node.edgeRules && node.edgeRules[fromId]) {
    if (toId) node.edgeRules[toId] = node.edgeRules[fromId]
    delete node.edgeRules[fromId]
  }
}

function taskGraphInsertNode(definition, kind, afterId) {
  const nodes = definition.nodes
  const endNode = nodes.find((node) => node.kind === 'end')
  const fallbackEnd = endNode?.id || ''
  const source = nodes.find((node) => node.id === afterId) || null
  const node = taskGraphNewNode(kind, nodes, fallbackEnd)

  if (!source) {
    const beforeEnd = endNode ? nodes.indexOf(endNode) : nodes.length
    const predecessor = endNode ? nodes.find((item) => item !== endNode && item.nextIds.includes(endNode.id)) : null
    nodes.splice(Math.max(0, beforeEnd), 0, node)
    if (predecessor) taskGraphReplaceEdge(predecessor, endNode.id, node.id)
    return node
  }

  if (source.kind === 'condition') {
    const beforeEnd = endNode ? nodes.indexOf(endNode) : nodes.length
    nodes.splice(Math.max(0, beforeEnd), 0, node)
    source.nextIds.push(node.id)
    const hasElse = Object.values(source.edgeRules || {}).some((rule) => rule?.else)
    source.edgeRules[node.id] = taskGraphRuleDefault(hasElse)
    return node
  }

  if (source.kind === 'end') {
    const predecessor = nodes.find((item) => item !== source && item.nextIds.includes(source.id))
    const beforeEnd = nodes.indexOf(source)
    nodes.splice(beforeEnd, 0, node)
    if (predecessor) taskGraphReplaceEdge(predecessor, source.id, node.id)
    return node
  }

  const previousNext = source.nextIds[0] || fallbackEnd
  node.nextIds = previousNext ? [previousNext] : []
  source.nextIds = [node.id]
  nodes.splice(nodes.indexOf(source) + 1, 0, node)
  return node
}

function taskGraphRemoveNode(definition, nodeId) {
  const nodes = definition.nodes
  const node = nodes.find((item) => item.id === nodeId)
  if (!node) return false
  if (node.kind === 'start' || node.kind === 'end') return false
  const fallback = node.nextIds.find((id) => id && id !== nodeId) || nodes.find((item) => item.kind === 'end')?.id || ''
  for (const item of nodes) {
    if (item === node) continue
    const nextIds = []
    for (const id of item.nextIds) {
      if (id !== nodeId) nextIds.push(id)
      else if (fallback && !nextIds.includes(fallback)) nextIds.push(fallback)
    }
    item.nextIds = nextIds
    if (item.edgeRules?.[nodeId]) {
      if (fallback && fallback !== nodeId && !item.edgeRules[fallback]) {
        item.edgeRules[fallback] = item.edgeRules[nodeId]
      }
      delete item.edgeRules[nodeId]
    }
  }
  nodes.splice(nodes.indexOf(node), 1)
  return true
}

function taskGraphWaitParts(seconds) {
  const value = Number(seconds) || 60
  if (value % 86400 === 0) return { value: value / 86400, unit: '86400' }
  if (value % 3600 === 0) return { value: value / 3600, unit: '3600' }
  if (value % 60 === 0) return { value: value / 60, unit: '60' }
  return { value, unit: '1' }
}

function taskGraphArgsText(node, argsTexts) {
  if (argsTexts.has(node.id)) return argsTexts.get(node.id)
  return node.args === undefined ? '{}' : JSON.stringify(node.args, null, 2)
}

function taskGraphDefinitionFromDraft(definition, argsTexts) {
  const draft = taskGraphClone(definition)
  for (const node of draft.nodes) {
    if (node.kind !== 'tool') continue
    if (!argsTexts.has(node.id)) continue
    const text = String(argsTexts.get(node.id) || '').trim() || '{}'
    try {
      const args = JSON.parse(text)
      if (!args || typeof args !== 'object' || Array.isArray(args)) {
        throw new Error('参数必须是 JSON 对象')
      }
      node.args = args
    } catch (err) {
      throw new Error(`节点「${node.title || node.id}」参数 JSON 解析失败：${err.message}`)
    }
  }
  return draft
}

function taskGraphNodeCardHtml(node, nodes, index, selectedNodeId, argsTexts) {
  const selectable = node.id === selectedNodeId
  const canDelete = node.kind !== 'start' && node.kind !== 'end'
  const commonNext =
    node.kind === 'condition' || node.kind === 'end'
      ? ''
      : `<label class="tg-field tg-field-inline"><span>下一步</span><select data-tg-next="${esc(node.id)}" data-node-id="${esc(node.id)}">${taskGraphTargetOptions(nodes, node.nextIds[0] || '', node.id)}</select></label>`
  let body = ''

  if (node.kind === 'tool') {
    body = `
      <div class="tg-field-grid">
        <label class="tg-field"><span>工具 ID<span class="tg-field-hint">输入可搜索已有工具</span></span>
          <input data-tg-field="tool" data-node-id="${esc(node.id)}" value="${esc(node.tool || '')}" placeholder="例如 kb.search" list="tg-tool-options" autocomplete="off" spellcheck="false">
        </label>
      </div>
      <label class="tg-field"><span>参数 JSON<span class="tg-field-hint">字符串可用 {{input.question}} 引用运行输入</span></span>
        <textarea class="tg-json-input" data-tg-json="args" data-node-id="${esc(node.id)}" spellcheck="false">${esc(taskGraphArgsText(node, argsTexts))}</textarea>
      </label>`
  } else if (node.kind === 'agent') {
    body = `
      <div class="tg-field-grid">
        <label class="tg-field"><span>模型 ID<span class="tg-field-hint">输入可搜索已启用模型</span></span>
          <input data-tg-field="agent.modelId" data-node-id="${esc(node.id)}" value="${esc(node.agent?.modelId || '')}" placeholder="填写已配置的模型 ID" list="tg-model-options" autocomplete="off" spellcheck="false">
        </label>
        <label class="tg-field"><span>最大轮次</span>
          <input type="number" min="1" max="20" data-tg-number="agent.maxRounds" data-node-id="${esc(node.id)}" value="${esc(String(node.agent?.maxRounds ?? 4))}">
        </label>
      </div>
      <label class="tg-field"><span>子 Agent 指令<span class="tg-field-hint">支持 {{input.question}} 模板</span></span>
        <textarea data-tg-field="agent.prompt" data-node-id="${esc(node.id)}" spellcheck="false">${esc(node.agent?.prompt || '')}</textarea>
      </label>`
  } else if (node.kind === 'manual') {
    body = `
      <label class="tg-field"><span>处理说明</span>
        <textarea data-tg-field="manual.instructions" data-node-id="${esc(node.id)}">${esc(node.manual?.instructions || '')}</textarea>
      </label>
      <div class="tg-field-grid tg-field-grid-3">
        <label class="tg-field"><span>处理角色（可选）<span class="tg-field-hint">输入可搜索角色代码</span></span>
          <input data-tg-field="manual.assigneeRole" data-node-id="${esc(node.id)}" value="${esc(node.manual?.assigneeRole || '')}" placeholder="例如 company_admin" list="tg-role-options" autocomplete="off">
        </label>
        <label class="tg-field"><span>超时小时（展示用）</span>
          <input type="number" min="0" data-tg-number="manual.timeoutHours" data-node-id="${esc(node.id)}" value="${esc(String(node.manual?.timeoutHours ?? 0))}">
        </label>
        <label class="tg-field"><span>拒绝后转到</span>
          <select data-tg-reject="${esc(node.id)}" data-node-id="${esc(node.id)}">${taskGraphTargetOptions(nodes, node.manual?.rejectNextId || '', node.id).replace('<option value="">— 选择节点 —</option>', '<option value="">— 直接结束 —</option>')}</select>
        </label>
      </div>`
  } else if (node.kind === 'wait') {
    const wait = taskGraphWaitParts(node.wait?.durationSec ?? 60)
    body = `
      <div class="tg-field-grid">
        <label class="tg-field"><span>等待时长</span>
          <input type="number" min="1" data-tg-wait-value="${esc(node.id)}" data-node-id="${esc(node.id)}" value="${esc(String(wait.value))}">
        </label>
        <label class="tg-field"><span>单位</span>
          <select data-tg-wait-unit="${esc(node.id)}" data-node-id="${esc(node.id)}">${TASK_GRAPH_WAIT_UNITS.map(([sec, label]) => `<option value="${sec}" ${sec === wait.unit ? 'selected' : ''}>${label}</option>`).join('')}</select>
        </label>
      </div>`
  } else if (node.kind === 'condition') {
    const rows = node.nextIds.length
      ? node.nextIds
          .map((target, edgeIndex) => {
            const rule = node.edgeRules?.[target] || {}
            const isElse = Boolean(rule.else)
            const needsValue = !isElse && !['exists', 'empty', 'truthy'].includes(rule.op || 'truthy')
            return `<div class="tg-condition-row" data-tg-edge-row="${esc(node.id)}-${edgeIndex}">
              <label class="tg-field"><span>走到</span>
                <select data-tg-edge-target="${esc(node.id)}" data-edge-index="${edgeIndex}" data-old-target="${esc(target)}">${taskGraphTargetOptions(nodes, target, node.id)}</select>
              </label>
              <label class="tg-check"><input type="checkbox" data-tg-rule-else="${esc(node.id)}" data-edge-target="${esc(target)}" ${isElse ? 'checked' : ''}> 否则</label>
              <label class="tg-field"><span>字段</span>
                <input data-tg-rule-field="${esc(node.id)}" data-edge-target="${esc(target)}" value="${esc(rule.field || '')}" placeholder="input.question" list="tg-field-options" autocomplete="off" ${isElse ? 'disabled' : ''} spellcheck="false">
              </label>
              <label class="tg-field"><span>判断</span>
                <select data-tg-rule-op="${esc(node.id)}" data-edge-target="${esc(target)}" ${isElse ? 'disabled' : ''}>${TASK_GRAPH_RULE_OPS.map(([op, label]) => `<option value="${op}" ${op === (rule.op || 'truthy') ? 'selected' : ''}>${label}</option>`).join('')}</select>
              </label>
              <label class="tg-field"><span>值</span>
                <input data-tg-rule-value="${esc(node.id)}" data-edge-target="${esc(target)}" value="${esc(rule.value === undefined ? '' : String(rule.value))}" ${isElse || !needsValue ? 'disabled' : ''}>
              </label>
              <button class="link-btn danger-link" type="button" data-tg-edge-delete="${esc(node.id)}" data-edge-index="${edgeIndex}">删除出线</button>
            </div>`
          })
          .join('')
      : '<div class="empty">还没有出线，先在条件节点后添加一个节点。</div>'
    body = `
      <div class="tg-condition-head"><span class="desc">每条出线都要有规则，最多一个「否则」；执行时按顺序取第一个命中的非否则分支。</span>
        <button class="btn ghost" type="button" data-tg-edge-add="${esc(node.id)}">添加出线</button>
      </div>
      <div class="tg-condition-list">${rows}</div>`
  }

  return `<section class="tg-node-card ${selectable ? 'selected' : ''}" data-tg-node-card="${esc(node.id)}">
    <div class="tg-node-head">
      <span class="tg-node-index">${index + 1}</span>
      <span class="tg-kind tg-kind-${esc(node.kind)}">${esc(taskGraphKindLabel(node.kind))}</span>
      <input class="tg-node-title" data-tg-field="title" data-node-id="${esc(node.id)}" value="${esc(node.title || '')}" placeholder="节点标题">
      ${body || commonNext ? `<span class="tg-node-open">${selectable ? '编辑中' : '展开'}</span>` : ''}
      <span class="tg-node-id mono">${esc(node.id)}</span>
      ${canDelete ? `<button class="link-btn danger-link" type="button" data-tg-node-delete="${esc(node.id)}">删除</button>` : ''}
    </div>
    ${body ? `<div class="tg-node-body">${body}</div>` : ''}
    ${commonNext ? `<div class="tg-node-foot">${commonNext}</div>` : ''}
  </section>`
}

function taskGraphNodesHtml(definition, selectedNodeId, argsTexts) {
  return definition.nodes
    .map((node, index) => taskGraphNodeCardHtml(node, definition.nodes, index, selectedNodeId, argsTexts))
    .join('')
}

function taskGraphEditorShell(selected, definition, runs, creating, runsError = null) {
  const name = selected ? selected.name : '新任务图'
  const description = selected ? selected.description || '' : ''
  const initialNodeId = taskGraphDefaultSelectedNode(definition)
  const catalog = taskGraphCatalogCache || { tools: [], models: [], roles: [] }
  const status = selected
    ? `状态 ${taskGraphPill(selected.status)} · 当前版本 v${Number(selected.version) || 0}${selected.publishedVersion ? ` · 已发布 v${selected.publishedVersion}` : ''}`
    : '新建草稿：保存后生成第一个草稿版本。'
  const validation = selected?.validation?.length
    ? `<span class="danger-text">校验未通过：${esc(selected.validation.join('；'))}</span>`
    : '<span class="desc">表单修改后可点「校验」检查结构。</span>'
  const addChips = TASK_GRAPH_ADDABLE_KINDS.map(
    ([kind, label]) => `<button class="tg-add-chip" type="button" data-tg-add-kind="${kind}">+ ${label}</button>`,
  ).join('')
  const starterHtml = creating
    ? `<div class="task-graph-onboarding">
        <span><b>1</b> 选模板或直接插入节点</span>
        <span><b>2</b> 在节点卡片填工具 / 模型 / 规则</span>
        <span><b>3</b> 校验通过后保存草稿</span>
      </div>
      <div class="task-graph-starters">
        <div class="task-graph-starter-head"><strong>从模板开始</strong><span class="desc">套用模板会替换当前节点，名字和说明保留；之后仍可继续增删。</span></div>
        <div class="task-graph-starter-grid">${TASK_GRAPH_STARTERS.map(
          (template) => `<button class="tg-starter" type="button" data-tg-template="${esc(template.id)}">
            <strong>${esc(template.name)}</strong>
            <span>${esc(template.description)}</span>
          </button>`,
        ).join('')}</div>
      </div>`
    : ''
  const runsHtml = selected
    ? `<h3 class="task-graph-runs-title">运行记录 <span class="muted">${runs.length}</span></h3>${
        runsError
          ? stateBlockHtml({
              compact: true,
              tone: 'error',
              title: '运行记录读取失败',
              body: consoleErrorText(runsError),
              actionLabel: '重试',
              action: 'tg-runs-retry',
            })
          : taskGraphRunsTable(runs)
      }`
    : ''
  const actions = selected
    ? `<button class="btn ghost" type="button" id="tg-validate">校验</button>
       <button class="btn" type="button" id="tg-save">保存草稿</button>
       <button class="btn" type="button" id="tg-publish">发布</button>
       <button class="btn danger" type="button" id="tg-delete">停用</button>`
    : '<button class="btn ghost" type="button" id="tg-validate">校验</button><button class="btn" type="button" id="tg-save">保存草稿</button>'
  const runBox = selected
    ? `<div class="task-graph-run-box">
        <div class="task-graph-json-head"><strong>运行输入 JSON</strong><span class="desc">模板里用 {{input.question}} 引用</span></div>
        <textarea id="tg-run-input" spellcheck="false">${esc(JSON.stringify({ question: '测试任务图' }, null, 2))}</textarea>
        <button class="btn accent" type="button" id="tg-run">运行已发布版本</button>
      </div>`
    : ''

  return `<div class="task-graph-meta">
      <label>名称<input id="tg-name" value="${esc(name)}"></label>
      <label>说明<input id="tg-desc" value="${esc(description)}"></label>
      <div class="desc tg-meta-status">${status}</div>
    </div>
    ${starterHtml}
    <div id="tg-flow-preview">${taskGraphFlowHtml(definition, initialNodeId)}</div>
    <div class="task-graph-orchestration-head">
      <div><strong>节点编排</strong><span class="desc">点击流程图或节点卡片选中节点；只展开当前节点的表单，其余节点保持折叠。工具 ID、模型 ID、角色代码支持自动补全。</span></div>
      <span class="desc" id="tg-add-hint"></span>
    </div>
    <div class="task-graph-addbar">
      <div class="tg-add-kind-row"><span class="tg-add-label">插入节点</span>${addChips}</div>
      <span class="desc">工具=调接口 · 子 Agent=让模型处理 · 人工=暂停审批 · 等待=延时 · 条件=按规则分流</span>
      <span class="desc" id="tg-catalog-status">${esc(taskGraphCatalogStatus(catalog))}</span>
    </div>
    <div class="task-graph-node-editor is-single" id="tg-node-editor">${taskGraphNodesHtml(definition, initialNodeId, new Map())}</div>
    ${taskGraphCatalogDatalists(catalog)}
    <datalist id="tg-field-options">${taskGraphFieldOptions(definition)}</datalist>
    <div class="task-graph-validation" id="tg-validation">${validation}</div>
    <div class="row-actions task-graph-actions">${actions}</div>
    <details class="task-graph-advanced">
      <summary>高级 JSON（可修改后应用到表单）</summary>
      <div class="task-graph-json-head"><strong>定义 JSON</strong><span class="desc">表单变更会同步到这里；直接修改后点「应用 JSON」覆盖表单。</span></div>
      <textarea id="tg-definition" spellcheck="false">${esc(JSON.stringify(definition, null, 2))}</textarea>
      <div class="row-actions task-graph-actions"><button class="btn ghost" type="button" id="tg-apply-json">应用 JSON 到表单</button></div>
    </details>
    ${runBox}
    ${runsHtml}`
}

function taskGraphRunsTable(runs) {
  if (!runs.length) {
    return stateBlockHtml({
      compact: true,
      title: '还没有运行记录',
      body: '发布并运行任务图后，这里会显示每次 Trace、状态和当前节点。',
    })
  }
  return `<table class="data task-graph-runs">
      <thead><tr><th>Trace</th><th>状态</th><th>开始</th><th>当前节点</th><th>操作</th></tr></thead>
      <tbody>${runs
        .map(
          (run) => `<tr>
            <td><button class="link-btn mono" type="button" data-tg-run="${esc(run.id)}">${esc(run.traceId)}</button></td>
            <td>${taskGraphPill(run.status)}${run.error ? `<div class="desc danger-text">${esc(run.error)}</div>` : ''}</td>
            <td class="desc">${esc(new Date(run.startedAt).toLocaleString('zh-CN'))}</td>
            <td class="desc mono">${esc(run.currentNodeId || '—')}</td>
            <td>${
              run.status === 'waiting_manual'
                ? `<div class="row-actions"><button class="link-btn accent" type="button" data-tg-approve="${esc(run.id)}" data-decision="approved">通过</button><button class="link-btn danger-link" type="button" data-tg-approve="${esc(run.id)}" data-decision="rejected">拒绝</button></div>`
                : run.status === 'running' || run.status === 'waiting_wait'
                  ? `<button class="link-btn danger-link" type="button" data-tg-cancel="${esc(run.id)}">取消</button>`
                  : '—'
            }</td>
          </tr>`,
        )
        .join('')}</tbody>
    </table>`
}


async function loadTaskGraphPanel(graphId) {
  const host = document.getElementById('task-graph-panel')
  if (!host) return
  renderLoading(host, '正在读取任务图', { skeleton: true, rows: 5 })
  let graphs = []
  try {
    const data = await api('/api/console/task-graphs')
    graphs = data.graphs || []
  } catch (err) {
    renderConsoleError(host, err, () => loadTaskGraphPanel(graphId))
    return
  }
  const selectedId = graphId || state.taskGraphSelected || (graphs[0] && graphs[0].id) || ''
  const selected = graphs.find((item) => item.id === selectedId) || null
  let runs = []
  let runsError = null
  if (selected) {
    try {
      const data = await api(`/api/console/task-graphs/${encodeURIComponent(selected.id)}/runs?limit=20`)
      runs = data.runs || []
    } catch (err) {
      runs = []
      runsError = err
    }
  }
  state.taskGraphGraphs = graphs
  state.taskGraphSelected = selected ? selected.id : ''
  renderTaskGraphPanel(host, graphs, selected, runs, false, runsError)
}

function renderTaskGraphPanel(host, graphs, selected, runs, creating = false, runsError = null) {
  const showGraphList = graphs.length > 1
  const graphList = graphs.length
    ? graphs
        .map(
          (graph) => `<button class="task-graph-item ${selected && selected.id === graph.id ? 'active' : ''}" type="button" data-tg-open="${esc(graph.id)}">
            <strong>${esc(graph.name)}</strong>
            <div class="desc">${esc(graph.description || '无描述')}</div>
            <div class="desc">v${Number(graph.version) || 0} · ${taskGraphPill(graph.status)} ${graph.draftVersion ? `<span class="muted">草稿 v${graph.draftVersion}</span>` : ''}</div>
          </button>`,
        )
        .join('')
    : '<div class="empty">还没有任务图。</div>'

  host.innerHTML = `
    <section class="panel task-graph-panel">
      <div class="panel-head">
        <div>
          <h2>任务图 <span class="muted">多步骤流程编排</span></h2>
          <p class="desc task-graph-sub">把工具、模型、人工审批、等待和条件判断串成一条流程；发布后按版本运行，每一步都有记录。</p>
        </div>
        <div class="panel-actions"><button class="btn" type="button" id="task-graph-new">新建任务图</button></div>
      </div>
      <div class="task-graph-layout">
        ${showGraphList ? `<aside class="task-graph-list">${graphList}</aside>` : ''}
        <div class="task-graph-editor">${
          selected || creating
            ? taskGraphEditorShell(selected, selected ? selected.definition : taskGraphTemplate(), runs, creating, runsError)
            : stateBlockHtml({
                title: '还没有任务图',
                body: '点右上角「新建任务图」，从模板开始，或从开始节点手工编排工具、子 Agent、人工审批和条件分支。',
              })
        }</div>
      </div>
    </section>`

  for (const button of host.querySelectorAll('[data-tg-open]')) {
    button.addEventListener('click', async () => {
      if (!(await taskGraphCanLeave(host))) return
      await loadTaskGraphPanel(button.dataset.tgOpen)
    })
  }
  const newButton = host.querySelector('#task-graph-new')
  if (newButton) {
    newButton.addEventListener('click', async () => {
      if (!(await taskGraphCanLeave(host))) return
      state.taskGraphSelected = ''
      renderTaskGraphPanel(host, graphs, null, [], true)
    })
  }
  bindTaskGraphEditor(host, selected)
  host.querySelector('[data-state-action="tg-runs-retry"]')?.addEventListener('click', () => {
    loadTaskGraphPanel(selected ? selected.id : '')
  })
  void hydrateTaskGraphCatalog(host)
}

async function taskGraphCanLeave(host) {
  if (host.dataset.tgDirty !== '1') return true
  return confirmCard({
    title: '放弃未保存的修改？',
    message: '当前任务图有表单修改还没保存，切换后会丢失。',
    confirmText: '放弃修改',
  })
}

function bindTaskGraphEditor(host, selected) {
  let draft = taskGraphEnsureDefinition(selected ? selected.definition : taskGraphTemplate())
  let selectedNodeId = taskGraphDefaultSelectedNode(draft)
  const argsTexts = new Map()
  const nodeHost = host.querySelector('#tg-node-editor')
  const jsonArea = host.querySelector('#tg-definition')
  if (!nodeHost) return
  host.dataset.tgDirty = '0'

  const setPath = (target, path, value) => {
    const parts = path.split('.')
    let cursor = target
    for (const part of parts.slice(0, -1)) {
      if (!cursor[part] || typeof cursor[part] !== 'object') cursor[part] = {}
      cursor = cursor[part]
    }
    cursor[parts[parts.length - 1]] = value
  }

  const syncJson = () => {
    if (!jsonArea || document.activeElement === jsonArea) return
    jsonArea.value = JSON.stringify(draft, null, 2)
  }

  const updateAddHint = () => {
    const hint = host.querySelector('#tg-add-hint')
    if (!hint) return
    const node = draft.nodes.find((item) => item.id === selectedNodeId)
    hint.textContent = node
      ? node.kind === 'condition'
        ? `选中「${node.title}」，添加节点会作为一条新分支接到它后面。`
        : `选中「${node.title}」，添加节点会插在它后面。`
      : '未选中节点，添加节点会插在结束节点之前。'
  }

  const refreshFlowPreview = () => {
    const flowHost = host.querySelector('#tg-flow-preview')
    if (flowHost) {
      const scroller = flowHost.querySelector('.task-graph-flow-scroll')
      const scrollLeft = scroller?.scrollLeft || 0
      const scrollTop = scroller?.scrollTop || 0
      flowHost.innerHTML = taskGraphFlowHtml(draft, selectedNodeId)
      const nextScroller = flowHost.querySelector('.task-graph-flow-scroll')
      if (nextScroller) {
        nextScroller.scrollLeft = scrollLeft
        nextScroller.scrollTop = scrollTop
      }
    }
    const fieldOptions = host.querySelector('#tg-field-options')
    if (fieldOptions) fieldOptions.innerHTML = taskGraphFieldOptions(draft)
  }

  const markDirty = () => {
    host.dataset.tgDirty = '1'
    syncJson()
    refreshFlowPreview()
    const box = host.querySelector('#tg-validation')
    if (box) box.innerHTML = '<span class="desc">表单已修改，尚未校验。</span>'
  }

  const showEditorError = (message) => {
    const box = host.querySelector('#tg-validation')
    if (box) box.innerHTML = `<span class="err-text">${esc(message)}</span>`
  }

  const selectNode = (nodeId, scrollToForm = false) => {
    if (!nodeId) return
    selectedNodeId = nodeId
    for (const card of nodeHost.querySelectorAll('[data-tg-node-card]')) {
      const active = card.dataset.tgNodeCard === nodeId
      card.classList.toggle('selected', active)
      const open = card.querySelector('.tg-node-open')
      if (open) open.textContent = active ? '编辑中' : '展开'
    }
    for (const node of host.querySelectorAll('[data-tg-flow-node]')) {
      node.classList.toggle('selected', node.dataset.tgFlowNode === nodeId)
    }
    updateAddHint()
    if (scrollToForm) {
      const card = [...nodeHost.querySelectorAll('[data-tg-node-card]')].find((item) => item.dataset.tgNodeCard === nodeId)
      card?.scrollIntoView({ behavior: 'smooth', block: 'center' })
    }
  }

  const renderNodes = () => {
    nodeHost.innerHTML = taskGraphNodesHtml(draft, selectedNodeId, argsTexts)
    refreshFlowPreview()
    updateAddHint()
    syncJson()
  }

  const readDefinition = () => taskGraphDefinitionFromDraft(draft, argsTexts)

  const payload = (definition) => ({
    ...(selected ? { id: selected.id } : {}),
    name: host.querySelector('#tg-name')?.value || '',
    description: host.querySelector('#tg-desc')?.value || '',
    definition,
  })

  const showValidation = (validation) => {
    const box = host.querySelector('#tg-validation')
    if (!box) return
    box.innerHTML = validation.valid
      ? '<span class="ok-text">校验通过，可以保存或发布。</span>'
      : `<span class="danger-text">校验未通过：${esc((validation.errors || []).join('；'))}</span>`
  }

  const ensureJsonApplied = () => {
    if (host.dataset.tgJsonDirty !== '1') return true
    const box = host.querySelector('#tg-validation')
    if (box) box.innerHTML = '<span class="err-text">高级 JSON 已修改但还没应用到表单，请先点「应用 JSON 到表单」。</span>'
    return false
  }

  const save = async () => {
    if (!ensureJsonApplied()) return
    try {
      const definition = readDefinition()
      const data = await apiPost('/api/console/task-graphs', payload(definition))
      host.dataset.tgDirty = '0'
      await loadTaskGraphPanel(data.graph.id)
    } catch (err) {
      showEditorError(`保存失败：${err.message || '请求失败'}`)
    }
  }

  const addNode = (kind = 'tool') => {
    const node = taskGraphInsertNode(draft, kind, selectedNodeId)
    selectedNodeId = node.id
    host.dataset.tgDirty = '1'
    renderNodes()
    host.querySelector('#tg-validation').innerHTML = '<span class="desc">已添加节点，尚未校验。</span>'
  }

  for (const button of host.querySelectorAll('[data-tg-template]')) {
    button.addEventListener('click', async () => {
      const template = TASK_GRAPH_STARTERS.find((item) => item.id === button.dataset.tgTemplate)
      if (!template) return
      if (host.dataset.tgDirty === '1') {
        const confirmed = await confirmCard({
          title: `套用「${template.name}」模板？`,
          message: '当前节点和表单修改会被替换，任务图名称和说明保留。',
          confirmText: '套用模板',
        })
        if (!confirmed) return
      }
      draft = taskGraphEnsureDefinition(template.build(taskGraphCatalogCache))
      argsTexts.clear()
      selectedNodeId = taskGraphDefaultSelectedNode(draft)
      const starterNames = TASK_GRAPH_STARTERS.map((item) => item.name)
      const starterDescriptions = TASK_GRAPH_STARTERS.map((item) => item.description)
      const nameInput = host.querySelector('#tg-name')
      if (nameInput && (!nameInput.value.trim() || nameInput.value.trim() === '新任务图' || starterNames.includes(nameInput.value.trim()))) {
        nameInput.value = template.name
      }
      const descInput = host.querySelector('#tg-desc')
      if (descInput && (!descInput.value.trim() || starterDescriptions.includes(descInput.value.trim()))) descInput.value = template.description
      host.dataset.tgJsonDirty = '0'
      host.dataset.tgDirty = '1'
      renderNodes()
      host.querySelector('#tg-validation').innerHTML = `<span class="desc">已套用「${template.name}」模板，尚未校验。</span>`
    })
  }

  nodeHost.addEventListener('click', async (event) => {
    const target = event.target
    if (!(target instanceof Element)) return
    const addEdgeButton = target.closest('[data-tg-edge-add]')
    if (addEdgeButton) {
      const node = draft.nodes.find((item) => item.id === addEdgeButton.dataset.tgEdgeAdd)
      if (!node) return
      const used = new Set(node.nextIds)
      const candidates = draft.nodes.filter((item) => item.id !== node.id && item.kind !== 'start' && !used.has(item.id))
      if (!candidates.length) {
        alert('没有可用的出线目标。请先选中条件节点并添加一个新节点，或在表单里调整已有节点。')
        return
      }
      const targetNode = candidates.find((item) => item.kind === 'end') || candidates[0]
      node.nextIds.push(targetNode.id)
      const hasElse = Object.values(node.edgeRules || {}).some((rule) => rule?.else)
      node.edgeRules[targetNode.id] = taskGraphRuleDefault(hasElse)
      host.dataset.tgDirty = '1'
      renderNodes()
      host.querySelector('#tg-validation').innerHTML = '<span class="desc">已添加出线，尚未校验。</span>'
      return
    }

    const deleteEdgeButton = target.closest('[data-tg-edge-delete]')
    if (deleteEdgeButton) {
      const node = draft.nodes.find((item) => item.id === deleteEdgeButton.dataset.tgEdgeDelete)
      if (!node) return
      const index = Number(deleteEdgeButton.dataset.edgeIndex)
      const removed = node.nextIds[index]
      node.nextIds.splice(index, 1)
      if (removed && node.edgeRules) delete node.edgeRules[removed]
      host.dataset.tgDirty = '1'
      renderNodes()
      host.querySelector('#tg-validation').innerHTML = '<span class="desc">已删除出线，尚未校验。</span>'
      return
    }

    const deleteNodeButton = target.closest('[data-tg-node-delete]')
    if (deleteNodeButton) {
      const nodeId = deleteNodeButton.dataset.tgNodeDelete
      const node = draft.nodes.find((item) => item.id === nodeId)
      if (!node) return
      const confirmed = await confirmCard({
        title: `删除节点「${node.title || node.id}」？`,
        message: '出线会尽量接到它的下一个节点；保存前都可以继续修改。',
        confirmText: '删除节点',
      })
      if (!confirmed) return
      if (!taskGraphRemoveNode(draft, nodeId)) {
        alert('开始节点和结束节点不能删除。')
        return
      }
      argsTexts.delete(nodeId)
      if (selectedNodeId === nodeId) {
        selectedNodeId = draft.nodes.find((item) => item.kind !== 'start' && item.kind !== 'end')?.id || ''
      }
      host.dataset.tgDirty = '1'
      renderNodes()
      host.querySelector('#tg-validation').innerHTML = '<span class="desc">已删除节点，尚未校验。</span>'
      return
    }

    if (target.closest('input, select, textarea, button, label, a')) return
    const card = target.closest('[data-tg-node-card]')
    if (card) selectNode(card.dataset.tgNodeCard)
  })

  const handleFieldChange = (event) => {
    const target = event.target
    if (!(target instanceof HTMLElement)) return
    const nodeId = target.dataset.nodeId
    const node = nodeId ? draft.nodes.find((item) => item.id === nodeId) : null

    if (node && target.dataset.tgField) {
      setPath(node, target.dataset.tgField, target.value)
      markDirty()
      return
    }
    if (node && target.dataset.tgNumber) {
      const value = target.value === '' ? undefined : Number(target.value)
      setPath(node, target.dataset.tgNumber, value)
      markDirty()
      return
    }
    if (node && target.dataset.tgJson) {
      argsTexts.set(node.id, target.value)
      markDirty()
      return
    }
    if (node && target.dataset.tgNext) {
      node.nextIds = target.value ? [target.value] : []
      markDirty()
      return
    }
    if (node && target.dataset.tgReject) {
      if (target.value) node.manual = { ...(node.manual || {}), rejectNextId: target.value }
      else if (node.manual) delete node.manual.rejectNextId
      markDirty()
      return
    }
    if (node && target.dataset.tgWaitValue !== undefined) {
      const unitSelect = [...nodeHost.querySelectorAll('[data-tg-wait-unit]')].find(
        (item) => item.dataset.tgWaitUnit === node.id,
      )
      const unit = Number(unitSelect?.value) || 1
      node.wait = { ...(node.wait || {}), durationSec: Math.max(1, Number(target.value) || 1) * unit }
      markDirty()
      return
    }
    if (node && target.dataset.tgWaitUnit !== undefined) {
      const valueInput = [...nodeHost.querySelectorAll('[data-tg-wait-value]')].find(
        (item) => item.dataset.tgWaitValue === node.id,
      )
      const value = Number(valueInput?.value) || 1
      node.wait = { ...(node.wait || {}), durationSec: Math.max(1, value) * (Number(target.value) || 1) }
      markDirty()
      return
    }

    const ruleNode = target.dataset.tgRuleField || target.dataset.tgRuleOp || target.dataset.tgRuleValue || target.dataset.tgRuleElse
      ? draft.nodes.find((item) => item.id === (target.dataset.tgRuleField || target.dataset.tgRuleOp || target.dataset.tgRuleValue || target.dataset.tgRuleElse))
      : null
    if (ruleNode) {
      const edgeTarget = String(target.dataset.edgeTarget || '')
      if (!edgeTarget) return
      ruleNode.edgeRules = ruleNode.edgeRules || {}
      const rule = ruleNode.edgeRules[edgeTarget] || {}
      if (target.dataset.tgRuleElse !== undefined) {
        if (target.checked) ruleNode.edgeRules[edgeTarget] = { else: true }
        else ruleNode.edgeRules[edgeTarget] = { field: 'input.question', op: 'exists' }
        markDirty()
        renderNodes()
        return
      }
      if (target.dataset.tgRuleField !== undefined) rule.field = target.value
      if (target.dataset.tgRuleOp !== undefined) {
        rule.op = target.value
        if (!['eq', 'neq', 'contains', 'gt', 'gte', 'lt', 'lte'].includes(target.value)) delete rule.value
      }
      if (target.dataset.tgRuleValue !== undefined) rule.value = target.value
      ruleNode.edgeRules[edgeTarget] = rule
      markDirty()
      if (target.dataset.tgRuleOp !== undefined) renderNodes()
      return
    }

    const edgeSelect = target.closest('[data-tg-edge-target]')
    if (edgeSelect) {
      const node = draft.nodes.find((item) => item.id === edgeSelect.dataset.tgEdgeTarget)
      if (!node) return
      const index = Number(edgeSelect.dataset.edgeIndex)
      const oldTarget = edgeSelect.dataset.oldTarget || ''
      const newTarget = edgeSelect.value
      if (!newTarget) {
        edgeSelect.value = oldTarget
        alert('请选择一个存在的目标节点。')
        return
      }
      if (node.nextIds.some((id, itemIndex) => id === newTarget && itemIndex !== index)) {
        edgeSelect.value = oldTarget
        alert('同一个条件节点不能重复选择同一条出线。')
        return
      }
      node.nextIds[index] = newTarget
      if (oldTarget && node.edgeRules?.[oldTarget]) {
        node.edgeRules[newTarget] = node.edgeRules[oldTarget]
        delete node.edgeRules[oldTarget]
      }
      host.dataset.tgDirty = '1'
      renderNodes()
      host.querySelector('#tg-validation').innerHTML = '<span class="desc">出线已修改，尚未校验。</span>'
    }
  }

  nodeHost.addEventListener('input', handleFieldChange)
  nodeHost.addEventListener('change', handleFieldChange)
  nodeHost.addEventListener('focusin', (event) => {
    const target = event.target
    if (!(target instanceof Element)) return
    const card = target.closest('[data-tg-node-card]')
    const nodeId = card?.dataset.tgNodeCard
    if (nodeId && nodeId !== selectedNodeId) selectNode(nodeId)
  })
  host.querySelector('#tg-name')?.addEventListener('input', markDirty)
  host.querySelector('#tg-desc')?.addEventListener('input', markDirty)
  for (const button of host.querySelectorAll('[data-tg-add-kind]')) {
    button.addEventListener('click', () => addNode(button.dataset.tgAddKind || 'tool'))
  }
  host.querySelector('#tg-flow-preview')?.addEventListener('click', (event) => {
    const target = event.target
    if (!(target instanceof Element)) return
    const nodeButton = target.closest('[data-tg-flow-node]')
    if (nodeButton) selectNode(nodeButton.dataset.tgFlowNode, true)
  })

  jsonArea?.addEventListener('input', () => {
    host.dataset.tgDirty = '1'
    host.dataset.tgJsonDirty = '1'
    const box = host.querySelector('#tg-validation')
    if (box) box.innerHTML = '<span class="desc">JSON 已修改，点「应用 JSON 到表单」后才会生效。</span>'
  })
  host.querySelector('#tg-apply-json')?.addEventListener('click', () => {
    try {
      const parsed = JSON.parse(jsonArea.value)
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('顶层必须是对象')
      if (!Array.isArray(parsed.nodes)) throw new Error('nodes 必须是数组')
      if (!parsed.nodes.length) throw new Error('nodes 不能为空')
      parsed.nodes.forEach((node, index) => {
        if (!node || typeof node !== 'object' || Array.isArray(node)) throw new Error(`第 ${index + 1} 个节点必须是对象`)
        if (typeof node.id !== 'string' || !node.id.trim()) throw new Error(`第 ${index + 1} 个节点缺少 id`)
        if (typeof node.kind !== 'string' || !node.kind.trim()) throw new Error(`节点「${node.id}」缺少 kind`)
      })
      draft = taskGraphEnsureDefinition(parsed)
      argsTexts.clear()
      selectedNodeId =
        draft.nodes.find((node) => node.id === selectedNodeId)?.id ||
        draft.nodes.find((node) => node.kind !== 'start' && node.kind !== 'end')?.id ||
        draft.nodes[0]?.id ||
        ''
      host.dataset.tgDirty = '1'
      host.dataset.tgJsonDirty = '0'
      renderNodes()
      host.querySelector('#tg-validation').innerHTML = '<span class="desc">JSON 已应用到表单，尚未校验。</span>'
    } catch (err) {
      showEditorError(`定义 JSON 应用失败：${err.message}`)
    }
  })

  host.querySelector('#tg-validate')?.addEventListener('click', async () => {
    if (!ensureJsonApplied()) return
    try {
      const data = await apiPost('/api/console/task-graphs/validate', { definition: readDefinition() })
      showValidation(data.validation)
    } catch (err) {
      showEditorError(`校验失败：${err.message || '请求失败'}`)
    }
  })
  host.querySelector('#tg-save')?.addEventListener('click', save)
  host.querySelector('#tg-publish')?.addEventListener('click', async () => {
    if (!selected) return
    if (!ensureJsonApplied()) return
    try {
      const definition = readDefinition()
      const data = await apiPost(`/api/console/task-graphs/${encodeURIComponent(selected.id)}/publish`, { definition })
      host.dataset.tgDirty = '0'
      await loadTaskGraphPanel(data.graph.id)
    } catch (err) {
      showEditorError(`发布失败：${err.message || '请求失败'}`)
    }
  })
  host.querySelector('#tg-delete')?.addEventListener('click', async () => {
    if (!selected) return
    const okToDelete = await confirmCard({
      title: '停用任务图？',
      message: '停用后保留历史版本和运行记录，但不能再次运行。',
      confirmText: '停用',
    })
    if (!okToDelete) return
    try {
      await api(`/api/console/task-graphs/${encodeURIComponent(selected.id)}`, { method: 'DELETE' })
      host.dataset.tgDirty = '0'
      await loadTaskGraphPanel()
    } catch (err) {
      alert(err.message || '停用失败')
    }
  })
  host.querySelector('#tg-run')?.addEventListener('click', async () => {
    if (!selected) return
    if (host.dataset.tgDirty === '1') {
      const okToRun = await confirmCard({
        title: '运行已发布版本？',
        message: '当前表单还有未保存的修改，本次运行不会使用这些修改。',
        confirmText: '继续运行',
      })
      if (!okToRun) return
    }
    let input
    try {
      input = JSON.parse(host.querySelector('#tg-run-input')?.value || '{}')
    } catch (err) {
      alert(`运行输入 JSON 解析失败：${err.message}`)
      return
    }
    try {
      const data = await apiPost(`/api/console/task-graphs/${encodeURIComponent(selected.id)}/runs`, { input })
      host.dataset.tgDirty = '0'
      await loadTaskGraphPanel(selected.id)
      await openTaskGraphRun(data.run.id)
    } catch (err) {
      alert(err.message || '运行失败')
    }
  })
  for (const button of host.querySelectorAll('[data-tg-run]')) {
    button.addEventListener('click', () => openTaskGraphRun(button.dataset.tgRun))
  }
  for (const button of host.querySelectorAll('[data-tg-approve]')) {
    button.addEventListener('click', async () => {
      const decision = button.dataset.decision === 'rejected' ? 'rejected' : 'approved'
      let note = ''
      if (decision === 'rejected') {
        note = window.prompt('拒绝原因（可选）') || ''
      }
      try {
        await apiPost(`/api/console/task-graph-runs/${encodeURIComponent(button.dataset.tgApprove)}/approve`, { decision, note })
        await loadTaskGraphPanel(selected ? selected.id : '')
      } catch (err) {
        alert(err.message || '处理失败')
      }
    })
  }
  for (const button of host.querySelectorAll('[data-tg-cancel]')) {
    button.addEventListener('click', async () => {
      const okToCancel = await confirmCard({
        title: '取消这次运行？',
        message: '已完成的步骤会保留，运行状态变为已取消。',
        confirmText: '取消运行',
      })
      if (!okToCancel) return
      try {
        await apiPost(`/api/console/task-graph-runs/${encodeURIComponent(button.dataset.tgCancel)}/cancel`, {})
        await loadTaskGraphPanel(selected ? selected.id : '')
      } catch (err) {
        alert(err.message || '取消失败')
      }
    })
  }

  renderNodes()
}

async function openTaskGraphRun(runId) {
  const overlay = modelModal(`
    <div class="modal-head"><h3>任务图运行</h3><button class="modal-x" type="button">×</button></div>
    <div class="task-graph-run-detail" id="task-graph-run-detail"><div class="empty">加载中…</div></div>
    <div class="modal-actions"><button class="btn ghost" type="button" id="task-graph-run-close">关闭</button></div>`)
  let timer = null
  let closed = false
  let terminal = false
  const close = () => {
    closed = true
    if (timer) clearInterval(timer)
    overlay.remove()
  }
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#task-graph-run-close').addEventListener('click', close)
  const render = async () => {
    if (closed) return
    try {
      const data = await api(`/api/console/task-graph-runs/${encodeURIComponent(runId)}`)
      if (closed) return
      const run = data.run
      const steps = (run.steps || [])
        .map(
          (step) => `<li>
          <span class="task-event-dot"></span>
          <div>
            <strong>${esc(step.title)}</strong> ${taskGraphPill(step.status)}
            <span class="desc">${esc(TASK_GRAPH_NODE_KIND_LABEL[step.nodeKind] || step.nodeKind)} · ${esc(step.nodeId)} · ${Number(step.durationMs) || 0}ms</span>
            ${step.error ? `<div class="desc danger-text">${esc(step.error)}</div>` : ''}
            <div class="desc mono task-event-payload">${esc(JSON.stringify({ input: step.input, output: step.output }, null, 2).slice(0, 800))}</div>
          </div>
        </li>`,
        )
        .join('')
      overlay.querySelector('#task-graph-run-detail').innerHTML = `
      <div class="task-detail-grid">
        <div><span>任务图</span><strong>${esc(run.graphName)} · v${run.graphVersion}</strong></div>
        <div><span>状态</span><strong>${taskGraphPill(run.status)}</strong></div>
        <div><span>Trace</span><strong class="mono">${esc(run.traceId)}</strong></div>
        <div><span>当前节点</span><strong class="mono">${esc(run.currentNodeId || '—')}</strong></div>
        <div><span>开始</span><strong>${esc(new Date(run.startedAt).toLocaleString('zh-CN'))}</strong></div>
        <div><span>结束</span><strong>${run.finishedAt ? esc(new Date(run.finishedAt).toLocaleString('zh-CN')) : '—'}</strong></div>
      </div>
      ${run.waiting ? `<div class="task-graph-waiting"><strong>当前等待</strong><pre>${esc(JSON.stringify(run.waiting, null, 2))}</pre></div>` : ''}
      ${run.error ? `<div class="danger-text">${esc(run.error)}</div>` : ''}
      <h3>步骤 <span class="muted">${(run.steps || []).length}</span></h3>
      <ol class="task-timeline">${steps || '<li class="empty">还没有步骤。</li>'}</ol>`
      terminal = !['running', 'waiting_manual', 'waiting_wait'].includes(run.status)
      if (terminal && timer) {
        clearInterval(timer)
        timer = null
      }
    } catch (err) {
      if (closed) return
      const detail = overlay.querySelector('#task-graph-run-detail')
      if (!detail) return
      detail.innerHTML = stateBlockHtml({
        tone: 'error',
        title: '运行详情读取失败',
        body: consoleErrorText(err),
        actionLabel: '重试',
        action: 'tg-run-retry',
      })
      detail.querySelector('[data-state-action="tg-run-retry"]')?.addEventListener('click', () => {
        detail.innerHTML = '<div class="empty">正在重试…</div>'
        void render()
      })
    }
  }
  await render()
  if (!closed && !terminal && !timer) timer = setInterval(render, 2000)
}

/* 任务详情改成右侧抽屉：列表留在原位，抽屉里看概览、指令、执行记录和事件时间线，
   暂停/恢复/取消直接在抽屉底部操作，关闭后列表状态已刷新。 */
let taskDrawerOverlay = null
let closeTaskDrawer = null

function taskDrawerFacts(task) {
  const facts = [
    ['创建人', esc(task.userName || task.userId || '—')],
    ['规则', esc(taskRuleText(task))],
    ['下一次', esc(task.nextRunLocal || '—')],
    ['最近执行', esc(task.lastRunLocal || '—')],
    ['时区', esc(task.timezone || '—')],
    ['渠道', esc(task.channel || '—')],
  ]
  return `<dl class="task-drawer-facts">${facts
    .map(([label, value]) => `<div><dt>${label}</dt><dd>${value}</dd></div>`)
    .join('')}<div class="is-wide"><dt>会话</dt><dd class="mono">${esc(task.sessionId || '—')}</dd></div></dl>`
}

function taskDrawerBody(task) {
  const runs = (task.runs || [])
    .map(
      (run) => `<tr>
        <td class="desc">${esc(new Date(run.startedAt).toLocaleString('zh-CN'))}</td>
        <td>${taskRunPill(run.status)}</td>
        <td class="desc">${esc(run.resultText ? taskPromptBrief(run.resultText) : run.error || '—')}</td>
        <td class="desc">${esc(TASK_DELIVERY_LABEL[run.delivery] || run.delivery || '—')}${run.deliveryError ? `<div class="desc danger-text">${esc(run.deliveryError)}</div>` : ''}</td>
      </tr>`,
    )
    .join('')
  const events = (task.events || [])
    .slice()
    .reverse()
    .map(
      (event) => `<li>
        <span class="task-event-dot"></span>
        <div>
          <strong>${esc(TASK_EVENT_LABEL[event.type] || event.type)}</strong>
          <span class="desc">${esc(new Date(event.createdAt).toLocaleString('zh-CN'))}</span>
          <div class="desc mono task-event-payload">${esc(taskPayloadText(event.payload))}</div>
        </div>
      </li>`,
    )
    .join('')
  return `
    <section class="task-drawer-section">
      <h4>概览</h4>
      ${taskDrawerFacts(task)}
    </section>
    <section class="task-drawer-section">
      <h4>任务指令</h4>
      <pre class="task-drawer-prompt">${esc(task.prompt)}</pre>
    </section>
    <section class="task-drawer-section">
      <h4>最近执行 <span class="muted">${(task.runs || []).length}</span></h4>
      <table class="data task-drawer-runs">
        <thead><tr><th>开始时间</th><th>状态</th><th>结果 / 错误</th><th>投递</th></tr></thead>
        <tbody>${runs || '<tr><td colspan="4" class="empty">还没有执行记录。</td></tr>'}</tbody>
      </table>
    </section>
    <section class="task-drawer-section">
      <h4>事件时间线 <span class="muted">${(task.events || []).length}</span></h4>
      <ol class="task-timeline">${events || '<li class="empty">还没有事件。</li>'}</ol>
    </section>`
}

function taskDrawerActions(task) {
  const id = esc(task.id)
  const close = `<button class="btn ghost" type="button" data-drawer-close>关闭</button>`
  if (task.status === 'running' || task.status === 'done' || task.status === 'cancelled') return close
  const pause = task.status === 'active' ? `<button class="btn ghost" type="button" data-drawer-act="pause" data-drawer-task="${id}">暂停</button>` : ''
  const resume = task.status === 'paused' ? `<button class="btn primary" type="button" data-drawer-act="resume" data-drawer-task="${id}">恢复</button>` : ''
  return `${pause}${resume}<button class="btn ghost danger-text" type="button" data-drawer-act="cancel" data-drawer-task="${id}">取消任务</button>${close}`
}

function markTaskRowOpen(id) {
  for (const rowEl of document.querySelectorAll('#view [data-task-row]')) {
    rowEl.classList.toggle('is-open', Boolean(id) && rowEl.dataset.taskRow === id)
  }
}

async function openTaskDetail(id) {
  if (!id) return
  if (closeTaskDrawer) closeTaskDrawer()
  state.taskOpen = id
  markTaskRowOpen(id)
  const overlay = document.createElement('div')
  overlay.className = 'drawer-overlay task-drawer-overlay'
  overlay.innerHTML = `<aside class="drawer task-drawer" role="dialog" aria-modal="true" aria-label="任务详情">
    <header class="task-drawer-head">
      <div class="task-drawer-heading">
        <span class="task-drawer-kicker">任务详情</span>
        <h3 id="task-drawer-title">加载中…</h3>
        <div class="task-drawer-sub" id="task-drawer-sub"></div>
      </div>
      <button class="drawer-x" type="button" aria-label="关闭">×</button>
    </header>
    <div class="task-drawer-body" id="task-drawer-body"><div class="empty">加载中…</div></div>
    <footer class="task-drawer-foot" id="task-drawer-foot"></footer>
  </aside>`
  document.body.appendChild(overlay)
  taskDrawerOverlay = overlay
  const close = () => {
    document.removeEventListener('keydown', onKey)
    if (taskDrawerOverlay === overlay) taskDrawerOverlay = null
    if (closeTaskDrawer === close) closeTaskDrawer = null
    if (state.taskOpen === id) state.taskOpen = ''
    markTaskRowOpen('')
    overlay.remove()
  }
  closeTaskDrawer = close
  const onKey = (event) => {
    if (event.key === 'Escape') {
      event.stopPropagation()
      close()
    }
  }
  document.addEventListener('keydown', onKey)
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) close()
  })
  overlay.querySelector('.drawer-x').addEventListener('click', close)

  const load = async () => {
    try {
      const task = await api(`/api/console/schedules/${encodeURIComponent(id)}`)
      const title = overlay.querySelector('#task-drawer-title')
      const sub = overlay.querySelector('#task-drawer-sub')
      const body = overlay.querySelector('#task-drawer-body')
      const foot = overlay.querySelector('#task-drawer-foot')
      if (!overlay.isConnected) return
      title.textContent = task.title || '任务详情'
      sub.innerHTML = `${taskStatusPill(task.status)}<span class="muted">${esc(taskRuleText(task))}</span>`
      body.innerHTML = taskDrawerBody(task)
      foot.innerHTML = taskDrawerActions(task)
      for (const button of foot.querySelectorAll('[data-drawer-close]')) button.addEventListener('click', close)
      for (const button of foot.querySelectorAll('[data-drawer-act]')) {
        button.addEventListener('click', async () => {
          const action = button.dataset.drawerAct
          const taskId = button.dataset.drawerTask
          if (!action || !taskId) return
          if (action === 'cancel') {
            const okToCancel = await confirmCard({
              title: '取消定时任务？',
              message: '取消后不会再触发；历史执行记录和事件时间线会保留。',
              confirmText: '取消任务',
            })
            if (!okToCancel) return
          }
          button.disabled = true
          try {
            await apiPost(`/api/console/schedules/${encodeURIComponent(taskId)}/${action}`, {})
            await load()
            await loadTasks(state.taskStatus, 'schedules')
            markTaskRowOpen(state.taskOpen)
          } catch (err) {
            alert(err.message || '操作失败')
            button.disabled = false
          }
        })
      }
    } catch (err) {
      if (overlay.isConnected) overlay.querySelector('#task-drawer-body').innerHTML = `<div class="empty">${esc(err.message || '加载失败')}</div>`
    }
  }
  await load()
}

/* ---------------- 组织同步 ---------------- */

const STAT_LABEL = {
  deptsCreated: '新建部门',
  deptsRenamed: '部门改名',
  deptsMoved: '部门移动',
  deptsMissing: '部门缺失',
  deptsRecycled: '部门回收',
  deptsRestored: '部门恢复',
  usersCreated: '新建成员',
  usersUpdated: '成员变更',
  usersDeparted: '成员离职',
  usersMissing: '成员缺失',
  usersDisabled: '成员禁用',
  usersRestored: '成员恢复',
  identitiesCreated: '渠道身份(pending)',
  identitiesRestored: '渠道身份恢复',
  unchanged: '无变化',
  orphans: '孤儿部门',
  unassignedUsers: '无部门成员',
}

const ACTION_LABEL = {
  'dept.create': '新建部门',
  'dept.rename': '部门改名',
  'dept.move': '部门移动',
  'dept.restore': '部门恢复',
  'dept.missing': '部门缺失',
  'dept.recycle': '部门回收',
  'user.create': '新建成员',
  'user.update': '成员变更',
  'user.depart': '成员离职',
  'user.missing': '成员缺失',
  'user.disable': '成员禁用',
  'user.restore': '成员恢复',
  'identity.create': '生成渠道身份',
}

function statChips(stats) {
  if (!stats) return '<span class="muted">—</span>'
  const chips = Object.entries(STAT_LABEL)
    .filter(([key]) => Number(stats[key] ?? 0) > 0)
    .map(([key, label]) => `<span class="chip">${esc(label)} <strong>${Number(stats[key])}</strong></span>`)
  return chips.join(' ') || '<span class="muted">无变化</span>'
}

async function loadSync() {
  const view = $('#view')
  renderLoading(view)
  setSide('', true)
  try {
    const [channels, runs, bindings] = await Promise.all([
      api('/api/console/channels'),
      api('/api/org/sync-runs?limit=10&offset=0').catch(() => ({ runs: [], total: 0 })),
      api('/api/channel/bindings').catch(() => ({ bindings: [], devAuth: false })),
    ])
    renderSync(channels, runs, bindings)
    if (new URLSearchParams(location.search).get('open') === 'dingtalk') {
      openDingTalkOnboard()
      const url = new URL(location.href)
      url.searchParams.delete('open')
      url.searchParams.delete('goto')
      history.replaceState(null, '', url.toString())
    }
  } catch (err) {
    renderDenied(view, err)
  }
}

function channelConfigCard(item, options = {}) {
  const bound = Boolean(options.bound ?? item.bound)
  const secondary = Boolean(options.secondary)
  const hasCredentials = Boolean(item.appId && item.appSecretConfigured)
  const hasWebhook = Boolean(item.webhookUrl)
  const configured = hasCredentials || hasWebhook
  const missingSecret = bound && Boolean(item.appId) && !item.appSecretConfigured
  const topState = missingSecret
    ? '凭证缺失'
    : bound
      ? '已绑定'
      : hasCredentials
        ? '凭证已配置'
        : hasWebhook
          ? '仅配置了 Webhook'
          : '待配置'
  const stream = item.stream
  const isFeishu = item.provider === 'feishu'
  // 钉钉网关当前会正常推送消息，但部分版本不回传 REGISTERED 系统回执；
  // registered 只能作为诊断信息，不能作为“未连接”的判据，否则会出现
  // 手机端能收发、控制台却一直显示未连接。以 WebSocket connected 为准。
  const streamOk = Boolean(stream?.running && stream.connected)
  const streamBadge = stream
    ? streamOk
      ? `<span class="pill ok">${isFeishu ? '长连接已连接' : 'Stream 已连接'}</span>`
      : `<span class="pill warn">${isFeishu ? '长连接未连接' : 'Stream 未连接'}</span>`
    : ''
  const streamNote =
    stream && !streamOk
      ? `<div class="channel-stream-note">${esc(
          stream.error ||
            (stream.running
              ? isFeishu
                ? '飞书长连接正在建立；若持续未连接，请检查 App ID/App Secret、网络和飞书应用是否已发布。'
                : '钉钉 Stream 正在建立连接；若持续未连接，请检查网络或重新保存 AppSecret。'
              : isFeishu
                ? '飞书长连接未运行；手机消息暂时不会进入 EAB。'
                : '钉钉 Stream 未运行；手机消息暂时不会进入 EAB。'),
        )}</div>`
      : ''
  const feishuCheck = item.feishuCheck
  // 自检通过就按“健康渠道”收口：只保留状态角标，不铺开检查清单和通过说明。
  // 只有缺配置、连接异常或自检发现问题时，才展示事件订阅提醒和接入指引。
  const feishuHealthy = Boolean(isFeishu && feishuCheck?.ok)
  const feishuEventNote =
    isFeishu && !feishuHealthy && stream?.connected && !stream?.lastEventAt
      ? `<div class="inline-note" style="margin-top:8px">飞书长连接已连上，但 EAB 还没收到任何消息事件。请在飞书开放平台确认已订阅 <code>im.message.receive_v1</code>，并给应用开通机器人能力与发消息权限。</div>`
      : ''
  const feishuGuide = isFeishu && !feishuHealthy
    ? `<div class="inline-note" style="margin-top:8px">
        <strong>飞书接入检查清单</strong>
        <ul style="margin:6px 0 0 18px;padding:0">
          <li>应用能力：已开启「机器人」；应用版本已发布，可用范围包含你当前使用的账号。</li>
          <li>事件订阅：已订阅 <code>im.message.receive_v1</code>；事件接收方式选「长连接」（本机部署无需公网地址）。</li>
          <li>权限：<code>im:message</code>（获取与发送消息）或 <code>im:message:send_as_bot</code>（以机器人身份发消息）；图片/文件再加 <code>im:resource</code>。</li>
          <li>群聊：需要机器人被 @ 才会回复；单聊无需 @。</li>
        </ul>
      </div>`
    : ''
  const feishuCheckNote = isFeishu && feishuCheck && !feishuCheck.ok
    ? `<div class="inline-note" style="margin-top:8px;border-left:3px solid var(--warn, #b45309);padding-left:10px">
        <strong>飞书自检 · 发现问题</strong>
        ${
          feishuCheck.error
            ? `<div style="margin-top:4px">${esc(feishuCheck.error)}</div>`
            : feishuCheck.issues?.length
              ? `<ul style="margin:6px 0 0 18px;padding:0">${feishuCheck.issues
                  .map((issue) => `<li>${esc(issue)}</li>`)
                  .join('')}</ul>`
              : '<div style="margin-top:4px">请检查飞书应用的事件订阅、权限和发布状态。</div>'
        }
      </div>`
    : ''
  // 企业微信同样只在缺配置时给指引；凭证齐全后只保留状态和基础字段。
  const wecomReady = Boolean(item.provider === 'wecom' && item.appSecretConfigured && (item.appId || item.corpId))
  const wecomGuide = item.provider === 'wecom' && !wecomReady
    ? `<div class="inline-note" style="margin-top:8px">
        <strong>企业微信接入检查</strong>
        <ul style="margin:6px 0 0 18px;padding:0">
          <li>填写企业 CorpId 与应用 Secret；启用机器人消息时还需要 AgentId。</li>
          <li>保存后点「测试连接」；要同步通讯录时，再补通讯录 Secret。</li>
        </ul>
      </div>`
    : ''
  const badges = [
    item.appId
      ? `<span class="pill ok">应用凭证</span>`
      : `<span class="pill">应用凭证未配置</span>`,
    item.appSecretConfigured
      ? `<span class="pill ok">密钥已保存</span>`
      : `<span class="pill warn">密钥未配置</span>`,
    item.webhookUrl
      ? `<span class="pill ok">Webhook</span>`
      : `<span class="pill">Webhook 未配置</span>`,
    streamBadge,
  ].join('')
  const callback = item.callbackToken
    ? `<div class="callback-row"><span>回调地址</span><code>${esc(item.callbackPath)}?token=${esc(
        item.callbackToken.slice(0, 8),
      )}…</code><button class="link-btn" type="button" data-copy-callback="${esc(item.provider)}">复制完整地址</button></div>`
    : ''
  return `<div class="channel-config${bound ? ' is-bound' : ''}${secondary ? ' is-secondary' : ''}">
    <div class="channel-config-head">
      <div><strong>${esc(item.label)}</strong>${hintBadge(
        '接入说明',
        missingSecret
          ? '应用凭证还在，但密钥已经丢失；机器人无法连钉钉网关，请重新保存 AppSecret。'
          : bound
            ? '已完成企业绑定，机器人可以直接收发消息。'
            : hasCredentials
              ? '应用凭证已保存，可拉取真实通讯录并接收事件回调。'
              : '还没有填写应用凭证，无法拉取通讯录。',
      )}</div>
      <span class="pill ${missingSecret ? 'warn' : bound || configured ? 'ok' : 'warn'}">${topState}</span>
    </div>
    <div class="channel-flags">${badges}</div>
    ${streamNote}${feishuEventNote}${feishuCheckNote}${feishuGuide}${wecomGuide}
    <dl class="channel-fields">
      <div><dt>App ID</dt><dd>${esc(item.appId || '—')}</dd></div>
      <div><dt>Agent ID</dt><dd>${esc(item.agentId || '—')}</dd></div>
      <div><dt>企业 ID</dt><dd>${esc(item.corpId || item.tenantId || '—')}</dd></div>
      <div><dt>Webhook</dt><dd class="mono">${esc(item.webhookUrl ? `${item.webhookUrl.slice(0, 42)}…` : '—')}</dd></div>
    </dl>
    ${callback}
    <div class="channel-config-actions">
      <button class="btn" type="button" data-config-channel="${esc(item.provider)}">${configured ? '修改配置' : '配置接入'}</button>
      <button class="btn ghost" type="button" data-test-channel="${esc(item.provider)}">测试连接</button>
      <span class="channel-test" id="ch-test-${esc(item.provider)}"></span>
    </div>
  </div>`
}

function bindingCard(item, channel) {
  const demoBinding = item.bound && String(item.tenantName || item.tenantId || '').includes('演示')
  const ready = Boolean(channel?.appId && channel?.appSecretConfigured)
  const badge = demoBinding
    ? '<span class="badge warn">演示绑定</span>'
    : item.bound
      ? '<span class="badge ok">已绑定</span>'
      : '<span class="badge deny">未绑定</span>'
  const meta = item.bound
    ? `${esc(item.tenantName || item.tenantId)}<div class="desc">绑定时间 ${esc(
        new Date(item.boundAt).toLocaleString(),
      )}${item.lastSyncedAt ? ` · 上次同步 ${esc(new Date(item.lastSyncedAt).toLocaleString())}` : ''}${
        demoBinding
          ? item.provider === 'dingtalk'
            ? ' · 演示租户，绑定真实企业会被替换'
            : ' · 演示租户，可解除后重新绑定'
          : ''
      }</div>`
    : hintBadge('绑定方式', item.hint || '未绑定；完成企业授权后同步组织与成员。')
  let actions = ''
  if (item.bound && demoBinding) {
    actions =
      item.provider === 'dingtalk'
        ? `<button class="btn sm primary" data-bind-dingtalk>绑定钉钉机器人</button><button class="btn sm" data-unbind="${esc(
            item.provider,
          )}">解除演示绑定</button>`
        : `<button class="btn sm" data-unbind="${esc(item.provider)}">解除演示绑定</button>`
  } else if (item.bound) {
    actions = `${
      item.provider === 'dingtalk'
        ? `<button class="btn sm primary" data-bind-dingtalk>绑定钉钉机器人</button>`
        : `<button class="btn sm" data-onboard="${esc(item.provider)}" data-mode="manual">配置组织/凭据</button>`
    }<button class="btn sm" data-unbind="${esc(item.provider)}">解绑</button>`
  } else if (item.provider === 'dingtalk') {
    actions = `<button class="btn sm primary" data-bind-dingtalk>绑定钉钉机器人</button>`
  } else {
    actions = `<button class="btn sm primary" data-onboard="${esc(item.provider)}" data-mode="scan">扫码绑定</button><button class="btn sm" data-onboard="${esc(item.provider)}" data-mode="manual">手工绑定</button>`
  }

  return `<div class="channel-card${item.bound ? ' is-bound' : ''}${demoBinding ? ' is-demo' : ''}">
      <div class="channel-top"><strong>${esc(item.label)}</strong>${badge}</div>
      <div class="channel-meta muted">${meta}</div>
      <div class="channel-actions">${actions}</div>
    </div>`
}

function renderSync(channels, data, bindings) {
  const view = $('#view')
  const list = channels?.channels ?? []
  const channelByProvider = new Map(list.map((item) => [item.provider, item]))
  const bindingList = bindings?.bindings ?? []
  const boundChannels = list.filter((item) => Boolean(item.bound))
  const unboundChannels = list.filter((item) => !item.bound)
  const autoSync = channels?.autoSync
  const autoSyncIntervalMs = Number(autoSync?.intervalMs ?? 0)
  const autoSyncEvery = autoSyncIntervalMs >= 3_600_000
    ? `每 ${Number((autoSyncIntervalMs / 3_600_000).toFixed(1))} 小时`
    : autoSyncIntervalMs >= 60_000
      ? `每 ${Math.round(autoSyncIntervalMs / 60_000)} 分钟`
      : ''
  const autoSyncNote = `后台自动同步${autoSync?.enabled === false ? '未开启' : '已开启'}${
    autoSyncEvery ? `，${autoSyncEvery}` : ''
  }。只同步已绑定渠道；离职或连续两次未出现在通讯录的成员会被停用，原登录会话随之失效。`
  const bindingChannels = [...bindingList].sort((a, b) => Number(Boolean(b.bound)) - Number(Boolean(a.bound)))
  const primaryChannels = boundChannels.length ? boundChannels : list
  const secondaryChannels = boundChannels.length ? unboundChannels : []

  const SYNC_PAGE_SIZE = 10
  const syncVisible = () => list.some((item) => item.appSecretConfigured)
  const runRow = (run) => `<tr class="clickable" data-run="${esc(run.id)}">
        <td class="name-cell"><strong>${esc(fmtTime(run.startedAt))}</strong>
          <div class="desc mono">${esc(run.provider)} · ${esc(run.mode)}</div></td>
        <td><span class="badge ${run.status === 'ok' ? 'ok' : 'deny'}">${esc(run.status)}</span></td>
        <td>${statChips(run.stats)}</td>
        <td class="num">${run.diffCount} 条</td>
      </tr>`
  const runs = (data?.runs ?? []).filter(syncVisible).map(runRow).join('')
  const syncTotal = Number(data?.total ?? (data?.runs ?? []).length)

  const syncableChannels = boundChannels

  const paneBinding = `
    <section class="panel channel-pane" id="ch-binding" data-pane="binding">
      <div class="panel-head">
        <div class="panel-title-line"><h2>企业一键绑定</h2>${hintBadge('绑定说明', '钉钉、飞书、企业微信都支持扫码或手工绑定；飞书、企业微信不装 dsh-im 也能用，装了插件时机器人由插件接管。飞书通讯录复用应用凭据，企业微信通讯录另需 CorpId + CorpSecret。')}</div>
        ${hintBadge('租户规则', '一个租户只归一家公司；绑定关系与同步结果都会写审计。')}
      </div>
      ${
        bindingList.length
          ? `<div class="channel-binding-grid">${bindingChannels
              .map((item) => bindingCard(item, channelByProvider.get(item.provider)))
              .join('')}</div>`
          : '<div class="inline-note">没有读到绑定状态。点右上角「刷新状态」重试，或检查控制台会话。</div>'
      }
      <div class="inline-note" id="binding-state" style="margin-top:10px"></div>
    </section>`

  const paneConfig = `
    <section class="panel channel-pane" id="ch-config" data-pane="config" hidden>
      <div class="panel-head">
        <div class="panel-title-line"><h2>渠道接入</h2>${hintBadge('展示说明', '已绑定的企业优先显示；未绑定渠道收在下方，避免抢占视线。')}</div>
      </div>
      <div class="channel-tier-head">
        <div>
          <strong>${boundChannels.length ? '已绑定渠道' : '渠道配置'}</strong>
          <span>${
            boundChannels.length
              ? `当前有 ${boundChannels.length} 个渠道完成企业绑定，机器人可以直接收发消息。`
              : '还没有完成企业绑定的渠道，先配置凭证并完成绑定。'
          }</span>
        </div>
        <span class="pill ${boundChannels.length ? 'ok' : 'warn'}">${
          boundChannels.length ? `${boundChannels.length} 个已绑定` : '0 个已绑定'
        }</span>
      </div>
      <div class="channel-config-grid channel-config-grid-primary">${primaryChannels
        .map((item) => channelConfigCard(item, { bound: Boolean(item.bound) }))
        .join('')}</div>
      ${
        secondaryChannels.length
          ? `<details class="channel-secondary">
              <summary>
                <div class="panel-title-line"><strong>其他渠道</strong>${hintBadge('收纳说明', '未绑定渠道收在下方；配置凭证后可接入，不占用主视线。')}</div>
                <span class="channel-more-count">${secondaryChannels.length} 个待接入 <span class="channel-more-chevron" aria-hidden="true">⌄</span></span>
              </summary>
              <div class="channel-config-grid channel-config-grid-secondary">${secondaryChannels
                .map((item) => channelConfigCard(item, { bound: false, secondary: true }))
                .join('')}</div>
            </details>`
          : ''
      }
      <div class="inline-note" id="channel-state"></div>
    </section>`

  const paneSync = `
    <section class="panel channel-pane" id="ch-sync" data-pane="sync" hidden>
      <div class="panel-head">
        <div><h2>通讯录同步</h2>${hintBadge('同步说明', '从渠道 API 真实拉取部门与成员，按差异写回组织架构；不会删除外部系统里已有的数据。')}</div>
        <span class="pill">真实 API</span>
      </div>
      <div class="sync-actions">
        ${
          syncableChannels.length
            ? syncableChannels
                .map(
                  (item) =>
                    `<button class="btn primary" type="button" data-sync-channel="${esc(item.provider)}">同步${esc(item.label)}通讯录</button>`,
                )
                .join('')
            : '<span class="hint">还没有已绑定的渠道。先在「企业绑定」里完成绑定，绑定后这里才显示对应的同步按钮。</span>'
        }
      </div>
      <div class="inline-note">${esc(autoSyncNote)}</div>
      <div id="sync-result"></div>
    </section>`

  const paneHistory = `
    <section class="panel channel-pane" id="ch-history" data-pane="history" hidden>
      <div class="panel-head"><div><h2>同步记录</h2>${hintBadge('记录说明', '点一行查看差异；表格内滚动，翻页只换数据。')}</div>
        <span class="pill" id="sync-history-count">共 ${syncTotal} 条</span></div>
      <div class="table-scroll">
        <table class="data">
          <thead><tr><th>时间 / 渠道</th><th>状态</th><th>统计</th><th>差异</th></tr></thead>
          <tbody id="sync-history-body">${runs || '<tr><td colspan="4" class="empty">还没有同步记录</td></tr>'}</tbody>
        </table>
      </div>
      <div id="sync-history-pager">${pagerHtml(syncTotal, 0, SYNC_PAGE_SIZE)}</div>
      <div id="sync-detail"></div>
    </section>`

  const paneIdentity = `
    <section class="panel channel-pane" id="ch-identities" data-pane="identities" hidden>
      <div class="panel-head">
        <div><h2>外部账号绑定</h2>${hintBadge('身份说明', '飞书 open_id / 钉钉 staffId / 企微 UserId 绑定到 EAB 成员；未绑定不触发检索。钉钉私聊与网页共用同一份会话；解除绑定后两边都不再保留。')}</div>
        <button class="btn sm primary" type="button" id="ident-new">＋ 新增绑定</button>
      </div>
      <div id="ident-list"><span class="hint">加载中…</span></div>
    </section>`

  const pendingBindings = bindingList.filter((item) => !item.bound).length
  view.innerHTML = `
    <div class="channel-shell">
      <nav class="channel-tabs" role="tablist" aria-label="渠道分区">
        <button class="channel-tab is-active" type="button" role="tab" aria-selected="true" data-channel-tab="binding">
          <span>企业绑定</span>${pendingBindings ? `<em class="warn">${pendingBindings} 待绑</em>` : '<em class="ok">已就绪</em>'}
        </button>
        <button class="channel-tab" type="button" role="tab" aria-selected="false" data-channel-tab="config">
          <span>渠道接入</span><em>${boundChannels.length}/${list.length} 已绑</em>
        </button>
        <button class="channel-tab" type="button" role="tab" aria-selected="false" data-channel-tab="sync"><span>通讯录同步</span></button>
        <button class="channel-tab" type="button" role="tab" aria-selected="false" data-channel-tab="history">
          <span>同步记录</span><em>${syncTotal}</em>
        </button>
        <button class="channel-tab" type="button" role="tab" aria-selected="false" data-channel-tab="identities"><span>外部身份</span></button>
      </nav>
      <div class="channel-main">
        ${paneBinding}
        ${paneConfig}
        ${paneSync}
        ${paneHistory}
        ${paneIdentity}
      </div>
    </div>`


  const switchChannelTab = (tab) => {
    for (const button of view.querySelectorAll('[data-channel-tab]')) {
      const active = button.dataset.channelTab === tab
      button.classList.toggle('is-active', active)
      button.setAttribute('aria-selected', active ? 'true' : 'false')
    }
    for (const pane of view.querySelectorAll('.channel-pane')) {
      pane.hidden = pane.dataset.pane !== tab
    }
  }
  for (const button of view.querySelectorAll('[data-channel-tab]')) {
    button.addEventListener('click', () => switchChannelTab(button.dataset.channelTab))
  }

  const bindHistoryRows = () => {
    for (const tr of view.querySelectorAll('#sync-history-body tr.clickable')) {
      tr.addEventListener('click', () => loadSyncRun(tr.getAttribute('data-run')))
    }
  }
  const paintHistory = async (page) => {
    const body = view.querySelector('#sync-history-body')
    const pager = view.querySelector('#sync-history-pager')
    const count = view.querySelector('#sync-history-count')
    if (!body || !pager) return
    body.innerHTML = '<tr><td colspan="4" class="empty">加载中…</td></tr>'
    try {
      const data = await api(`/api/org/sync-runs?limit=${SYNC_PAGE_SIZE}&offset=${page * SYNC_PAGE_SIZE}`)
      const rows = (data.runs ?? []).filter(syncVisible)
      body.innerHTML = rows.length
        ? rows.map(runRow).join('')
        : '<tr><td colspan="4" class="empty">没有更多记录</td></tr>'
      if (count) count.textContent = `共 ${data.total ?? rows.length} 条`
      pager.innerHTML = pagerHtml(data.total ?? rows.length, page, SYNC_PAGE_SIZE)
      bindHistoryRows()
      bindPager(pager, (next) => paintHistory(next))
    } catch (err) {
      body.innerHTML = `<tr><td colspan="4" class="empty">${esc(err.message)}</td></tr>`
    }
  }
  bindHistoryRows()
  bindPager(view.querySelector('#sync-history-pager'), (next) => paintHistory(next))

  view.querySelector('#ident-new')?.addEventListener('click', () => openIdentityModal())
  loadIdentities(view)

  for (const button of view.querySelectorAll('[data-config-channel]')) {
    button.addEventListener('click', () => openChannelModal(list.find((item) => item.provider === button.dataset.configChannel)))
  }
  for (const button of view.querySelectorAll('[data-test-channel]')) {
    button.addEventListener('click', async () => {
      const box = view.querySelector(`#ch-test-${button.dataset.testChannel}`)
      button.disabled = true
      if (box) box.textContent = '发送中…'
      try {
        const result = await apiPost(`/api/console/channels/${button.dataset.testChannel}/test`, {
          text: `EAB 渠道测试 · ${new Date().toLocaleString('zh-CN')}`,
        })
        if (box) box.innerHTML = `<span class="${result.ok ? 'ok-text' : 'bad-text'}">${esc(result.message)}</span>`
      } catch (err) {
        if (box) box.innerHTML = `<span class="bad-text">${esc(err.message)}</span>`
      } finally {
        button.disabled = false
      }
    })
  }
  for (const button of view.querySelectorAll('[data-copy-callback]')) {
    button.addEventListener('click', async () => {
      const item = list.find((entry) => entry.provider === button.dataset.copyCallback)
      if (!item) return
      const url = `${location.origin}${item.callbackPath}?token=${item.callbackToken}`
      try {
        await navigator.clipboard.writeText(url)
        button.textContent = '已复制'
      } catch {
        prompt('复制回调地址', url)
      }
    })
  }

  for (const button of view.querySelectorAll('button[data-bind]')) {
    button.addEventListener('click', () => startBind(button.dataset.bind, bindings))
  }
  for (const button of view.querySelectorAll('button[data-onboard]')) {
    button.addEventListener('click', () =>
      openChannelOnboard(button.dataset.onboard, button.dataset.mode || 'scan', async () => {
        await loadCompanies().catch(() => {})
        await loadSync()
        switchChannelTab('binding')
      }),
    )
  }
  for (const button of view.querySelectorAll('button[data-bind-dingtalk]')) {
    button.addEventListener('click', () =>
      openDingTalkOnboard(async () => {
        await loadCompanies().catch(() => {})
        await loadSync()
        switchChannelTab('binding')
      }),
    )
  }
  for (const button of view.querySelectorAll('button[data-unbind]')) {
    button.addEventListener('click', () =>
      openUnbindConfirm(button.dataset.unbind, async () => {
        await loadCompanies().catch(() => {})
        await loadSync()
        switchChannelTab('binding')
      }),
    )
  }

  for (const button of view.querySelectorAll('button[data-sync-channel]')) {
    button.addEventListener('click', async () => {
      const channel = button.dataset.syncChannel
      const result = $('#sync-result')
      result.innerHTML = '<div class="loading">正在从渠道拉取通讯录…</div>'
      for (const other of view.querySelectorAll('button[data-sync-channel]')) other.disabled = true
      try {
        const outcome = await apiPost(`/api/console/channels/${channel}/sync`, {})
        const mobileHint =
          outcome.mobileCount === 0
            ? '<div class="inline-note is-warn">本次没有同步到手机号。若使用钉钉，请在开发者后台「权限管理 → 通讯录管理」勾选「企业员工手机号信息」并发布版本，然后再同步一次。</div>'
            : ''
        result.innerHTML = `
          <div class="panel" style="margin:0;box-shadow:none">
            <div class="panel-head"><div><h2>同步完成 · ${esc(outcome.provider)}</h2><span class="hint">${outcome.departments} 个部门 · ${outcome.members} 名成员 · ${outcome.mobileCount ?? 0} 个手机号 · ${outcome.diffCount} 条差异</span></div></div>
            <div class="chip-row">${statChips(outcome.stats)}</div>
            ${mobileHint}
            ${outcome.diffs.length ? syncDiffTable(outcome.diffs) : '<div class="inline-note">本次没有任何写入（幂等）</div>'}
          </div>`
      } catch (err) {
        result.innerHTML = ''
        renderDenied(result, err)
      } finally {
        for (const other of view.querySelectorAll('button[data-sync-channel]')) other.disabled = false
      }
    })
  }
  for (const anchor of view.querySelectorAll('[data-anchor]')) {
    anchor.addEventListener('click', () => {
      const target = document.getElementById(anchor.dataset.anchor)
      target?.scrollIntoView({ behavior: 'smooth', block: 'start' })
    })
  }
}

async function loadIdentities(view, page = 0) {
  const host = view.querySelector('#ident-list')
  if (!host) return
  const size = 10
  host.innerHTML = '<span class="hint">加载中…</span>'
  try {
    const data = await api(`/api/console/channel-identities?limit=${size}&offset=${page * size}`)
    const items = data.items || []
    const total = Number(data.total ?? items.length)
    if (!total) {
      host.innerHTML = '<span class="hint">还没有绑定。员工先在 /chat 登录，拿到自己的渠道账号 ID 后在这里绑定。</span>'
      return
    }
    if (!items.length && page > 0) return loadIdentities(view, page - 1)
    host.innerHTML = `
      <div class="table-scroll">
        <table class="data"><thead><tr><th>渠道</th><th>外部账号</th><th>成员</th><th>绑定时间</th><th>操作</th></tr></thead>
        <tbody>${items
          .map(
            (item) => `<tr>
              <td>${esc(item.provider)}</td>
              <td class="mono">${esc(item.external_id)}</td>
              <td>${esc(item.user_name)} <span class="desc mono">${esc(item.employee_no || item.user_id)}</span></td>
              <td>${esc(fmtTime(item.created_at))}</td>
              <td><button class="link-btn danger-link" type="button" data-unbind-ident="${esc(item.id)}">解除</button></td>
            </tr>`,
          )
          .join('')}</tbody></table>
      </div>
      ${pagerHtml(total, page, size)}`
    bindPager(host, (next) => loadIdentities(view, next))
    for (const button of host.querySelectorAll('[data-unbind-ident]')) {
      button.addEventListener('click', async () => {
        const ok = await confirmCard({
          title: '解除身份绑定？',
          message: '解除后，这个渠道账号发消息不会再以该成员身份处理。',
          confirmText: '解除绑定',
          tone: 'warning',
        })
        if (!ok) return
        button.disabled = true
        try {
          await api(`/api/console/channel-identities/${encodeURIComponent(button.dataset.unbindIdent)}${qs()}`, { method: 'DELETE' })
          await loadIdentities(view, page)
        } catch (err) {
          button.disabled = false
          alert(err.message || '解除失败')
        }
      })
    }
  } catch (err) {
    host.innerHTML = `<span class="bad-text">${esc(err.message)}</span>`
  }
}

async function openIdentityModal() {
  let members = []
  try {
    const data = await api('/api/org/members')
    members = data.members || []
  } catch (err) {
    alert(err.message || '读取成员失败')
    return
  }
  const overlay = modelModal(`
    <div class="modal-head"><h3>绑定渠道账号</h3><button class="modal-x" type="button">×</button></div>
    <div class="field-stack">
      <label class="field"><span>渠道</span><select id="ident-provider">
        <option value="feishu">飞书</option><option value="dingtalk">钉钉</option><option value="wecom">企业微信</option>
      </select></label>
      <label class="field"><span>外部账号 ID</span><input id="ident-external" class="mono" placeholder="飞书 open_id / 钉钉 staffId / 企微 UserId" /></label>
      <label class="field"><span>对应成员</span><select id="ident-user">${members
        .map((member) => `<option value="${esc(member.id)}">${esc(member.name)} · ${esc(member.deptName)}</option>`)
        .join('')}</select></label>
      ${hintNote('绑定规则', '一个外部账号只能绑定一个成员；重复绑定会报错，避免身份串号。')}
    </div>
    <div class="modal-state" id="ident-state"></div>
    <div class="modal-actions"><button class="btn primary" type="button" id="ident-save">保存绑定</button><button class="btn ghost" type="button" id="ident-cancel">取消</button></div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#ident-cancel').addEventListener('click', close)
  overlay.querySelector('#ident-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#ident-state')
    const provider = overlay.querySelector('#ident-provider').value
    const externalId = overlay.querySelector('#ident-external').value.trim()
    const userId = overlay.querySelector('#ident-user').value
    if (!externalId) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = '外部账号 ID 不能为空'
      return
    }
    stateEl.textContent = '保存中…'
    try {
      await apiPost('/api/console/channel-identities', { provider, externalId, userId })
      close()
      loadSync()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '绑定失败'
    }
  })
}

async function openChannelModal(item) {
  if (!item) return
  const copyMap = {
    feishu: { app: 'App ID', secret: 'App Secret', agent: '机器人 App ID（可选）', corp: '企业自定义 ID（可选）' },
    dingtalk: { app: 'App Key / Client ID', secret: 'App Secret', agent: '机器人编码 AgentId', corp: '企业 CorpId' },
    wecom: { app: '企业 ID（CorpId）', secret: '应用 Secret', agent: '应用 AgentId', corp: '通讯录 Secret 所属 CorpId（可选）' },
  }
  const labels = copyMap[item.provider] ?? copyMap.feishu
  const overlay = modelModal(`
    <div class="modal-head"><h3>配置 ${esc(item.label)}</h3><button class="modal-x" type="button">×</button></div>
    <div class="field-stack">
      <div class="form-cols">
        <label class="field"><span>${esc(labels.app)}</span><input id="ch-app" value="${esc(item.appId)}" placeholder="企业应用后台复制" /></label>
        <label class="field"><span>${esc(labels.agent)}</span><input id="ch-agent" value="${esc(item.agentId)}" placeholder="可选" /></label>
      </div>
      <label class="field"><span>${esc(labels.secret)}</span><input id="ch-secret" type="password" autocomplete="off" placeholder="${
        item.appSecretConfigured ? '已保存，留空不修改' : '粘贴应用密钥'
      }" /></label>
      <label class="field"><span>${esc(labels.corp)}</span><input id="ch-corp" value="${esc(item.corpId)}" placeholder="可选" /></label>
      <div class="field-divider"><span>群机器人 Webhook（用于连通性测试与通知）</span></div>
      <label class="field"><span>Webhook 地址</span><input id="ch-webhook" class="mono" value="${esc(item.webhookUrl)}" placeholder="https://…（在群机器人设置里复制）" /></label>
      <label class="field"><span>Webhook 签名密钥</span><input id="ch-webhook-secret" type="password" autocomplete="off" placeholder="${
        item.webhookSecretConfigured ? '已保存，留空不修改' : '飞书/钉钉机器人开启了签名才需要'
      }" /></label>
      <label class="switch"><input type="checkbox" id="ch-enabled"${item.enabled ? ' checked' : ''} /><span>启用该渠道</span></label>
      ${
        item.callbackToken
          ? `<div class="hint">回调地址：<code>${esc(location.origin + item.callbackPath)}?token=${esc(
              item.callbackToken,
            )}</code></div>`
          : hintNote('回调说明', '保存后生成回调地址与回调 token。')
      }
      ${hintNote('凭证说明', '应用凭证用于后续通讯录同步与事件回调；Webhook 用于群通知和立即验证连通性。密钥保存到服务器本地，不写数据库。')}
    </div>
    <div class="modal-state" id="ch-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="ch-save">保存配置</button>
      <button class="btn ghost" type="button" id="ch-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#ch-cancel').addEventListener('click', close)
  overlay.querySelector('#ch-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#ch-state')
    stateEl.textContent = '保存中…'
    try {
      await apiPost(`/api/console/channels/${item.provider}`, {
        appId: overlay.querySelector('#ch-app').value.trim(),
        agentId: overlay.querySelector('#ch-agent').value.trim(),
        corpId: overlay.querySelector('#ch-corp').value.trim(),
        appSecret: overlay.querySelector('#ch-secret').value.trim(),
        webhookUrl: overlay.querySelector('#ch-webhook').value.trim(),
        webhookSecret: overlay.querySelector('#ch-webhook-secret').value.trim(),
        enabled: overlay.querySelector('#ch-enabled').checked,
      })
      close()
      loadSync()
      refreshOverviewChannels()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '保存失败'
    }
  })
}

function syncDiffTable(diffs) {
  const rows = diffs
    .map((diff) => {
      const before = diff.before ? JSON.stringify(diff.before) : '—'
      const after = diff.after ? JSON.stringify(diff.after) : '—'
      return `<tr>
        <td><span class="chip">${esc(ACTION_LABEL[diff.action] || diff.action)}</span></td>
        <td class="mono">${esc(diff.entityId || '—')}</td>
        <td class="mono desc">${esc(before)}</td>
        <td class="mono desc">${esc(after)}</td>
      </tr>`
    })
    .join('')
  return `<table class="data docs-table diff-table">
      <thead><tr><th>动作</th><th>对象</th><th>之前</th><th>之后</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>`
}

async function loadSyncRun(runId) {
  const detail = $('#sync-detail')
  if (!detail) return
  renderLoading(detail, '加载差异…')
  try {
    const data = await api(`/api/org/sync-runs/${encodeURIComponent(runId)}`)
    detail.innerHTML = `
      <div class="panel">
        <div class="panel-head">
          <h2>同步差异</h2>
          <span class="hint">${esc(data.run.provider)} · ${esc(data.run.mode)} · ${data.diffs.length} 条</span>
        </div>
        ${data.diffs.length ? syncDiffTable(data.diffs) : '<div class="inline-note">这次同步没有产生写入差异。</div>'}
      </div>`
  } catch (err) {
    renderDenied(detail, err)
  }
}

/* ---------------- 渠道扫码绑定（模态） ---------------- */

let bindPollTimer = null

function closeBindModal() {
  if (bindPollTimer) {
    clearInterval(bindPollTimer)
    bindPollTimer = null
  }
  const overlay = document.querySelector('.modal-overlay')
  if (overlay) overlay.remove()
}

async function openUnbindConfirm(provider, onDone) {
  let preview
  try {
    preview = await api(`/api/channel/unbind/preview?provider=${encodeURIComponent(provider)}`)
  } catch (err) {
    showTopToast(err.message || '解绑预览失败', { tone: 'bad' })
    return
  }

  const rows = [
    ['删除部门', preview.departments],
    ['删除成员', preview.users],
    ['删除角色授权', preview.roles],
    ['删除权限覆盖', preview.overrides],
    ['撤销网页会话', preview.sessions],
    ['归档工作区', preview.workspaces],
    ['清理渠道身份', preview.identities],
  ]
  const warnings = (preview.warnings || [])
    .map((item) => `<p>${esc(item)}</p>`)
    .join('')

  const overlay = modelModal(`
    <div class="modal-head"><h3>解绑${esc(preview.label)}</h3><button class="modal-x" type="button">×</button></div>
    <div class="field-stack">
      <p class="muted">解绑会停止同步，并删除该渠道同步进来的组织与人员。EAB 自己创建、没有该渠道身份的成员不会被删除；如果他们在该渠道部门下，会先移到公司根部门。</p>
      <div class="kv">
        ${rows.map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('')}
      </div>
      <div class="banner warn">
        <strong>不可逆：</strong>角色授权会被物理删除，重新绑定后需要重新授权；聊天历史保留，个人工作区文件只归档不删除。
        ${warnings}
      </div>
    </div>
    <div class="modal-state" id="unbind-state"></div>
    <div class="modal-actions">
      <button class="btn" id="unbind-cancel" type="button">取消</button>
      <button class="btn danger" id="unbind-confirm" type="button">确认解绑并清理</button>
    </div>
  `)

  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#unbind-cancel').addEventListener('click', close)
  const confirmButton = overlay.querySelector('#unbind-confirm')
  confirmButton.addEventListener('click', async () => {
    confirmButton.disabled = true
    const stateEl = overlay.querySelector('#unbind-state')
    stateEl.className = 'modal-state'
    stateEl.textContent = '正在清理渠道数据…'
    try {
      const result = await apiPost('/api/channel/unbind', { provider, confirm: true })
      close()
      showTopToast(
        `已解绑${preview.label}：删除 ${result.removed?.departments ?? 0} 个部门、${result.removed?.users ?? 0} 名成员、${result.removed?.roles ?? 0} 条角色授权`,
      )
      await onDone?.()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '解绑失败'
      confirmButton.disabled = false
    }
  })
}

async function startBind(provider, bindings) {
  try {
    const session = await apiPost('/api/channel/bind/start', { provider })
    openBindModal(session, bindings)
  } catch (err) {
    const target = $('#sync-result') || $('#view')
    renderDenied(target, err)
  }
}

function openChannelOnboard(provider, initialMode, onDone) {
  const label = provider === 'feishu' ? '飞书' : '企业微信'
  const manualCopy =
    provider === 'feishu'
      ? '填飞书开放平台的 App ID 与 App Secret；保存后会校验并同步通讯录。未装 dsh-im 也能保存，装了会同时交给插件接管消息。'
      : '机器人用 Bot ID + Secret；同步组织架构还需要企业 CorpId + CorpSecret。未装 dsh-im 也能先保存绑定。'
  const manualFields =
    provider === 'feishu'
      ? `<label class="field"><span>App ID</span><input id="co-appid" class="mono" placeholder="cli_xxxxxxxx" autocomplete="off" /></label>
         <label class="field"><span>App Secret ${fieldInfo('只保存引用，不回显到页面。')}</span><input id="co-secret" class="mono" type="password" placeholder="粘贴 App Secret" /></label>
         <label class="field"><span>部署区域</span><select id="co-domain"><option value="feishu">飞书（open.feishu.cn）</option><option value="lark">Lark 国际版</option></select></label>`
      : `<label class="field"><span>Bot ID</span><input id="co-botid" class="mono" placeholder="企业微信智能机器人 Bot ID" autocomplete="off" /></label>
         <label class="field"><span>Bot Secret ${fieldInfo('只保存引用，不回显到页面。')}</span><input id="co-botsecret" class="mono" type="password" placeholder="粘贴机器人 Secret" /></label>
         <label class="field"><span>CorpId ${fieldInfo('可选；要同步组织架构时必填。')}</span><input id="co-corp" class="mono" placeholder="企业微信 CorpId" autocomplete="off" /></label>
         <label class="field"><span>通讯录 Secret ${fieldInfo('可选；企业应用的通讯录 Secret。')}</span><input id="co-corpsecret" class="mono" type="password" placeholder="粘贴通讯录 Secret" /></label>`
  const overlay = modelModal(`
    <div class="modal-head"><h3>${label} · 企业一键绑定</h3><button class="modal-x" type="button">×</button></div>
    <div class="dingtalk-bind-modal">
      <div class="dingtalk-bind-modes">
        <button class="dingtalk-bind-mode" type="button" data-mode="scan"><span class="dingtalk-bind-mode-dot"></span><span class="dingtalk-bind-mode-copy"><strong>扫码绑定</strong><span>扫码授权后自动写入机器人凭据</span></span></button>
        <button class="dingtalk-bind-mode" type="button" data-mode="manual"><span class="dingtalk-bind-mode-dot"></span><span class="dingtalk-bind-mode-copy"><strong>手工绑定</strong><span>已有应用时直接填凭据</span></span></button>
      </div>
      <section class="dingtalk-bind-section" data-panel="scan">
        <div class="onboard-qr">
          <div class="onboard-qr-visual">
            <div class="onboard-qr-frame"><img id="co-qr" alt="${label}扫码绑定二维码" /></div>
            <div class="onboard-qr-status" id="co-scan-status">正在生成二维码…</div>
          </div>
          <div class="onboard-steps">
            <strong>扫码后发生什么</strong>
            <ol>
              <li>用${label}扫描二维码并确认授权。</li>
              <li>平台会创建/连接机器人，EAB 保存应用/机器人凭据；装了 dsh-im 时同时交给插件接管消息。</li>
              <li>${provider === 'feishu' ? '通讯录同步使用同一套应用凭据。' : '机器人凭据不能拉通讯录，组织架构需要另填 CorpId + CorpSecret。'}</li>
            </ol>
          </div>
        </div>
        <div class="onboard-qr-actions">
          <button class="btn sm" type="button" id="co-refresh">重新生成</button>
        </div>
      </section>
      <section class="dingtalk-bind-section" data-panel="manual" hidden>
        <div class="bind-guide"><strong>手工绑定</strong><span>${manualCopy}</span></div>
        <div class="form-grid dingtalk-bind-grid">${manualFields}</div>
      </section>
      <div class="onboard-qr-status" id="ch-onboard-state" hidden></div>
      <div class="modal-actions dingtalk-bind-actions">
        <button class="btn ghost" type="button" id="co-cancel">取消</button>
        <button class="btn primary" type="button" id="co-save">保存并绑定</button>
      </div>
    </div>`)
  const stateEl = overlay.querySelector('#ch-onboard-state')
  const scanStatus = overlay.querySelector('#co-scan-status')
  const qrImg = overlay.querySelector('#co-qr')
  const scanPanel = overlay.querySelector('[data-panel="scan"]')
  const manualPanel = overlay.querySelector('[data-panel="manual"]')
  const tabs = [...overlay.querySelectorAll('.dingtalk-bind-mode')]
  const refreshBtn = overlay.querySelector('#co-refresh')
  const saveBtn = overlay.querySelector('#co-save')
  let sessionId = ''
  let timer = 0
  let pollInterval = 2000
  let stopped = false
  let mode = initialMode === 'manual' ? 'manual' : 'scan'
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) {
      if (timer) clearTimeout(timer)
      timer = 0
      stopped = true
    }
  })

  const stop = () => {
    stopped = true
    if (timer) clearTimeout(timer)
    timer = 0
  }
  const close = () => {
    stop()
    overlay.remove()
  }
  const setMode = (next) => {
    mode = next
    tabs.forEach((tab) => tab.classList.toggle('is-active', tab.dataset.mode === next))
    scanPanel.hidden = next !== 'scan'
    manualPanel.hidden = next !== 'manual'
    saveBtn.hidden = next !== 'manual'
    if (next === 'scan' && !sessionId) startScan()
  }
  const showState = (text, kind = '') => {
    stateEl.hidden = false
    stateEl.className = `onboard-qr-status${kind ? ` ${kind}` : ''}`
    stateEl.textContent = text
  }
  const finish = (result) => {
    close()
    if (typeof onDone === 'function') onDone(result)
  }
  const poll = async () => {
    if (!sessionId || stopped) return
    try {
      const status = await api(`/api/console/channels/${provider}/onboard/${sessionId}`)
      if (status.status === 'success') {
        stop()
        finish(status)
        return
      }
      if (status.status === 'expired' || status.status === 'failed' || status.status === 'error') {
        stop()
        scanStatus.className = 'onboard-qr-status bad'
        scanStatus.textContent = status.message || '扫码失败，请重新生成二维码'
        return
      }
      if (status.pollIntervalMs) {
        pollInterval = Math.max(1500, Number(status.pollIntervalMs))
      }
      scanStatus.className = 'onboard-qr-status'
      scanStatus.textContent = status.message || '已生成二维码，等待扫码授权…'
      if (!stopped) timer = setTimeout(poll, pollInterval)
    } catch (error) {
      stop()
      scanStatus.className = 'onboard-qr-status bad'
      scanStatus.textContent = error.message || '轮询扫码状态失败'
    }
  }
  async function startScan() {
    stop()
    stopped = false
    sessionId = ''
    scanStatus.className = 'onboard-qr-status'
    scanStatus.textContent = '正在生成二维码…'
    qrImg.removeAttribute('src')
    refreshBtn.disabled = true
    try {
      const started = await apiPost(`/api/console/channels/${provider}/onboard/start`, {})
      sessionId = started.sessionId
      qrImg.src = started.qrImageUrl
      scanStatus.textContent = '请用' + label + '扫码并确认授权'
      const interval = Math.max(1500, Number(started.pollIntervalMs || 2000))
      pollInterval = interval
      timer = setTimeout(poll, pollInterval)
    } catch (error) {
      scanStatus.className = 'onboard-qr-status bad'
      scanStatus.textContent = error.message || '二维码生成失败'
    } finally {
      refreshBtn.disabled = false
    }
  }

  for (const tab of tabs) tab.addEventListener('click', () => setMode(tab.dataset.mode))
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#co-cancel').addEventListener('click', close)
  refreshBtn.addEventListener('click', startScan)
  saveBtn.addEventListener('click', async () => {
    const body =
      provider === 'feishu'
        ? {
            appId: overlay.querySelector('#co-appid').value.trim(),
            appSecret: overlay.querySelector('#co-secret').value.trim(),
            domain: overlay.querySelector('#co-domain').value,
          }
        : {
            botId: overlay.querySelector('#co-botid').value.trim(),
            botSecret: overlay.querySelector('#co-botsecret').value.trim(),
            corpId: overlay.querySelector('#co-corp').value.trim(),
            corpSecret: overlay.querySelector('#co-corpsecret').value.trim(),
          }
    if (provider === 'feishu' && (!body.appId || !body.appSecret)) {
      showState('App ID 和 App Secret 都要填', 'bad')
      return
    }
    if (provider === 'wecom' && (!body.botId || !body.botSecret)) {
      if (body.corpId && body.corpSecret) {
        saveBtn.disabled = true
        showState('正在用企业通讯录凭据同步组织…')
        try {
          const result = await apiPost(`/api/console/channels/${provider}/org`, body)
          finish(result)
        } catch (error) {
          showState(error.message || '同步失败', 'bad')
          saveBtn.disabled = false
        }
        return
      }
      showState('Bot ID 和 Bot Secret 都要填；只同步组织请填 CorpId + 通讯录 Secret', 'bad')
      return
    }
    saveBtn.disabled = true
    showState('正在校验凭证并绑定…')
    try {
      const result = await apiPost(`/api/console/channels/${provider}/onboard/manual`, body)
      if (result.syncError) {
        showState(`已绑定，但通讯录同步失败：${result.syncError}`, 'warn')
        saveBtn.disabled = false
        return
      }
      if (result.needsOrgCredentials) {
        showState('机器人已绑定；同步组织架构还需要补充企业通讯录凭据。', 'warn')
        saveBtn.disabled = false
        return
      }
      if (result.pluginBound === false) {
        showState('已绑定到 EAB；当前没有 dsh-im 插件，机器人消息不会由插件接管。装好插件后再保存一次即可交给插件。', 'warn')
        saveBtn.disabled = false
        return
      }
      finish(result)
    } catch (error) {
      showState(error.message || '绑定失败', 'bad')
      saveBtn.disabled = false
    }
  })

  setMode(mode)
}

function openDingTalkBind(channel, bindings, organization = null) {
  const demoChannel = Boolean(
    channel?.tenantId &&
      (String(channel.tenantId).startsWith('demo-') || String(channel.tenantName ?? '').includes('演示')),
  )
  const replaceable =
    demoChannel ||
    (Number(organization?.dingtalkDepartments ?? 0) === 0 &&
      (Number(organization?.departments ?? 0) > 1 || Number(organization?.members ?? 0) > 0))
  const replaceDefault = replaceable ? ' checked' : ''
  const overlay = modelModal(`
    <div class="modal-head"><h3>钉钉 · 一键绑定并同步</h3><button class="modal-x" type="button">×</button></div>
    <div class="bind-guide">
      <strong>绑定前确认</strong>
      <span>已在钉钉开发者后台创建「企业内部应用」，并开通「通讯录部门信息读权限 qyapi_get_department_list」与「通讯录成员信息读权限 qyapi_get_member」；只开 qyapi_manage_addresslist 不够。</span>
      <span>EAB 只读取部门树与成员，不会向钉钉写入或修改任何组织数据。</span>
      ${
        demoChannel
          ? '<span style="color:#8a5a00">当前是演示绑定；填真实企业三项后会替换演示租户，并立即同步真实通讯录。</span>'
          : ''
      }
    </div>
    <div class="field-stack" style="margin-top:14px">
      <label class="field"><span>AppKey <em>企业内部应用 Client ID</em></span><input id="dt-app" value="${esc(
        demoChannel ? '' : channel?.appId || '',
      )}" placeholder="dingxxxxxx" autocomplete="off" /></label>
      <label class="field"><span>AppSecret <em>只保存引用，不回显</em></span><input id="dt-secret" type="password" autocomplete="off" placeholder="${
        channel?.appSecretConfigured && !demoChannel ? '已保存，留空不修改' : '粘贴真实 AppSecret'
      }" /></label>
      <label class="field"><span>企业 CorpId <em>用于确认租户归属</em></span><input id="dt-corp" value="${esc(
        demoChannel ? '' : channel?.corpId || '',
      )}" placeholder="dingxxxxxxxx" autocomplete="off" /></label>
    </div>
    ${
      replaceable
        ? `<label class="install-check bind-check" style="margin:12px 20px 0">
            <input id="dt-replace" type="checkbox"${replaceDefault} />
            <span><strong>${demoChannel ? '用钉钉通讯录替换演示组织' : '用钉钉通讯录替换现有组织'}</strong><small>替换会归档现有部门与成员（不物理删除，保留根部门）；不勾选则只追加钉钉组织</small></span>
          </label>`
        : ''
    }
    <div class="hint-note" style="margin:10px 20px 0">${hintBadge('同步说明', '绑定成功后会立即拉取一次通讯录，并把结果写进当前公司的组织架构；已存在的数据只做差异更新，不会重复创建。')}</div>
    <div class="modal-state" id="dt-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="dt-submit">${demoChannel ? '替换演示租户并同步' : '绑定并同步'}</button>
      <button class="btn ghost" type="button" id="dt-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#dt-cancel').addEventListener('click', close)
  const submit = overlay.querySelector('#dt-submit')
  submit.addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#dt-state')
    const appId = overlay.querySelector('#dt-app').value.trim()
    const appSecret = overlay.querySelector('#dt-secret').value.trim()
    const corpId = overlay.querySelector('#dt-corp').value.trim()
    if (!appId || !corpId) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = 'AppKey 和 CorpId 都要填'
      return
    }
    if (!appSecret && (!channel?.appSecretConfigured || demoChannel)) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = demoChannel ? '替换演示绑定需要填真实 AppSecret' : '第一次绑定需要填 AppSecret'
      return
    }
    submit.disabled = true
    stateEl.className = 'modal-state'
    stateEl.textContent = '正在验证钉钉应用、读取企业通讯录…'
    try {
      const result = await apiPost('/api/console/channels/dingtalk/bind', {
        appId,
        appSecret,
        corpId,
        replaceDemo: replaceable ? overlay.querySelector('#dt-replace')?.checked === true : false,
      })
      stateEl.className = 'modal-state ok'
      stateEl.textContent = `绑定成功：${result.binding.tenantName} · ${result.sync.departments} 个部门 / ${result.sync.members} 名成员${
        result.sync.archived?.departments || result.sync.archived?.members
          ? ` · 已归档演示数据 ${result.sync.archived.departments} 个部门 / ${result.sync.archived.members} 人`
          : ''
      }`
      setTimeout(() => {
        close()
        loadSync()
      }, 1200)
    } catch (err) {
      stateEl.className = 'modal-state bad'
      const urls = err?.details?.applyUrls ?? {}
      const labels = {
        qyapi_get_department_list: '开通「部门信息读」权限',
        qyapi_get_member: '开通「成员信息读」权限',
        qyapi_get_department_member: '开通「部门成员读」权限',
      }
      const versionUrl = err?.details?.versionUrl
      const versionLink = versionUrl
        ? `<a class="btn" href="${esc(versionUrl)}" target="_blank" rel="noopener">去发布新版本</a>`
        : ''
      const links = Object.entries(urls)
        .map(
          ([key, url]) =>
            `<a class="btn ghost" href="${esc(url)}" target="_blank" rel="noopener">${esc(
              labels[key] ?? `开通「${key}」权限`,
            )}</a>`,
        )
        .join('')
      stateEl.innerHTML =
        `<div>${esc(err.message || '绑定失败')}</div>` +
        (err.hint ? `<div class="bind-error-hint">${esc(err.hint)}</div>` : '') +
        (versionLink || links ? `<div class="bind-error-actions">${versionLink}${links}</div>` : '')
      submit.disabled = false
    }
  })
}

function openBindModal(session, bindings) {
  closeBindModal()
  const overlay = document.createElement('div')
  overlay.className = 'modal-overlay'
  overlay.innerHTML = `
    <div class="modal">
      <div class="modal-head">
        <h3>${esc(session.providerLabel)} · 扫码绑定企业</h3>
        <button class="modal-x" type="button" aria-label="关闭">×</button>
      </div>
      <div class="qr-box">
        ${
          session.qr && session.qr.imageUrl
            ? `<img src="${esc(session.qr.imageUrl)}" alt="二维码" />`
            : `<div class="qr-placeholder">
                 <span class="qr-brand">${esc(session.providerLabel)}</span>
                 <span class="muted">模拟渠道：真实接入后这里显示渠道返回的二维码图片</span>
                 <code class="qr-content">${esc(session.qr ? session.qr.content : '')}</code>
               </div>`
        }
      </div>
      <div class="modal-state" id="bind-state">等待管理员用${esc(session.providerLabel)}扫码授权…（5 分钟内有效）</div>
      <div class="modal-actions">
        ${
          bindings && bindings.devAuth
            ? '<button class="btn primary" type="button" id="mock-scan">模拟扫码（开发预览）</button>'
            : ''
        }
        <button class="btn" type="button" id="bind-cancel">取消</button>
      </div>
    </div>`
  document.body.appendChild(overlay)

  const setState = (text, tone) => {
    const el = overlay.querySelector('#bind-state')
    if (!el) return
    el.textContent = text
    el.className = `modal-state${tone ? ` ${tone}` : ''}`
  }

  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) closeBindModal()
  })
  overlay.querySelector('.modal-x').addEventListener('click', closeBindModal)
  overlay.querySelector('#bind-cancel').addEventListener('click', async () => {
    try {
      await apiPost(`/api/channel/bind/${session.sessionId}/cancel`, {})
    } catch {
      /* 取消失败也让用户关掉弹窗 */
    }
    closeBindModal()
    loadSync()
  })

  const scan = overlay.querySelector('#mock-scan')
  if (scan) {
    scan.addEventListener('click', async () => {
      scan.disabled = true
      setState('已扫码，正在换租户凭证…')
      try {
        const res = await apiPost(`/api/channel/bind/${session.sessionId}/mock-scan`, {})
        setState(`绑定成功：${res.session.tenantName}`, 'ok')
        setTimeout(() => {
          closeBindModal()
          loadSync()
        }, 900)
      } catch (err) {
        setState(err.message || '绑定失败', 'bad')
        scan.disabled = false
      }
    })
  }

  bindPollTimer = setInterval(async () => {
    try {
      const current = await api(`/api/channel/bind/${session.sessionId}`)
      if (current.status === 'authorized') {
        setState(`绑定成功：${current.tenantName || current.tenantId}`, 'ok')
        closeBindModal()
        loadSync()
      } else if (current.status === 'expired') {
        setState('二维码已过期，请关掉重试', 'bad')
        clearInterval(bindPollTimer)
        bindPollTimer = null
      } else if (current.status === 'cancelled') {
        closeBindModal()
      }
    } catch {
      /* 轮询失败不打断，下一轮再试 */
    }
  }, 1500)
}

/* ---------------- 插件（服务器侧生命周期管理器，对齐 DSH 的安装/列表/启用/更新/卸载） ---------------- */

const PLUGIN_STAGE_LABEL = {
  discovered: '已发现（部署侧放置）',
  installed: '已安装',
  disabled: '已安装 · 当前公司停用',
  enabled: '已安装 · 当前公司启用',
  invalid: '清单不合法',
  removed: '已卸载',
}

const PLUGIN_EVENT_LABEL = {
  install: '安装',
  update: '更新',
  enable: '启用',
  disable: '停用',
  uninstall: '卸载',
}

const PLUGIN_SOURCE_LABEL = {
  'browser-dir': '本机文件夹',
  'local-dir': '本地目录',
  npm: 'npm · 镜像',
  github: 'GitHub',
  disk: '磁盘发现',
}

function parseNpmSourceRef(ref) {
  if (!ref || !String(ref).startsWith('npm:')) return null
  const rest = String(ref).slice(4)
  const queryAt = rest.indexOf('?')
  const base = queryAt >= 0 ? rest.slice(0, queryAt) : rest
  const params = new URLSearchParams(queryAt >= 0 ? rest.slice(queryAt + 1) : '')
  const at = base.lastIndexOf('@')
  const packageName = at > 0 ? base.slice(0, at) : base
  const version = at > 0 ? base.slice(at + 1) : ''
  return { packageName, version, registry: params.get('registry') || '' }
}

function parseGithubSourceRef(ref) {
  if (!ref || !String(ref).startsWith('github:')) return null
  const rest = String(ref).slice(7)
  const queryAt = rest.indexOf('?')
  const base = queryAt >= 0 ? rest.slice(0, queryAt) : rest
  const params = new URLSearchParams(queryAt >= 0 ? rest.slice(queryAt + 1) : '')
  const hashAt = base.indexOf('#')
  return {
    repo: hashAt >= 0 ? base.slice(0, hashAt) : base,
    ref: hashAt >= 0 ? base.slice(hashAt + 1) : '',
    subdir: params.get('dir') || '',
  }
}

function fmtPluginTime(ms) {
  if (!ms) return '—'
  const date = new Date(ms)
  const pad = (value) => String(value).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`
}

function pluginPill(plugin) {
  if (!plugin.valid) return '<span class="pill danger">清单不合法</span>'
  if (!plugin.install) return `<span class="pill">${plugin.enabled ? '已发现 · 启用' : '已发现 · 停用'}</span>`
  if (plugin.enabled) return '<span class="pill ok">已安装 · 启用</span>'
  return '<span class="pill warn">已安装 · 停用</span>'
}

function pluginCard(plugin) {
  const keywords = plugin.keywords?.length
    ? plugin.keywords.map((item) => `<span class="chip">${esc(item)}</span>`).join('')
    : '<span class="muted">没有标签</span>'
  const scopes = plugin.scopes.length
    ? plugin.scopes.map((scope) => `<span class="chip" title="${esc(scope)}">${esc(scope)}</span>`).join('')
    : '<span class="muted">未声明权限</span>'
  const pages = plugin.pages
    .map(
      (page) =>
        `<button class="btn sm" type="button" data-plugin="${esc(plugin.id)}" data-page-file="${esc(page.file)}" data-page-title="${esc(page.title)}"${plugin.valid && plugin.enabled ? '' : ' disabled'}>打开「${esc(page.title)}」</button>`,
    )
    .join(' ')
  const toggle = plugin.valid
    ? `<button class="btn sm ${plugin.enabled ? '' : 'primary'}" type="button" data-toggle-plugin="${esc(plugin.id)}" data-next="${plugin.enabled ? 'false' : 'true'}">${plugin.enabled ? '停用（本司）' : '启用（本司）'}</button>`
    : ''
  const update = plugin.install
    ? `<button class="btn sm" type="button" data-plugin-update="${esc(plugin.id)}">更新…</button>`
    : ''
  const uninstall = plugin.valid
    ? `<button class="btn sm danger" type="button" data-plugin-uninstall="${esc(plugin.id)}">卸载…</button>`
    : ''
  const source = plugin.install
    ? `<div class="plugin-source-ref"><span class="plugin-source-label">${esc(PLUGIN_SOURCE_LABEL[plugin.install.source] || plugin.install.source)}</span><span class="mono" title="${esc(plugin.install.sourceRef || plugin.install.source)}">${esc(plugin.install.sourceRef || plugin.install.source)}</span></div>`
    : '<strong class="muted">部署侧放进 plugins/，尚未登记安装</strong>'
  const origin = plugin.install
    ? `${esc(fmtPluginTime(plugin.install.installedAt))} · ${esc(plugin.install.installedBy || '未知操作人')}`
    : '—'
  const initial = (plugin.name || plugin.id || '?').trim().slice(0, 1).toUpperCase()

  return `<section class="panel plugin-card" id="plugin-${esc(plugin.id)}">
    <div class="panel-head plugin-card-head">
      <div class="plugin-title">
        <div class="plugin-avatar">${esc(initial)}</div>
        <div class="plugin-title-text">
          <h2>${esc(plugin.name)}</h2>
          <div class="plugin-subline">
            <span class="mono">${esc(plugin.id)}@${esc(plugin.version)}</span>
          </div>
        </div>
      </div>
      ${pluginPill(plugin)}
    </div>
    <div class="legend" style="margin-top:0">${esc(plugin.description || '（没有写描述）')}</div>
    <div class="plugin-actions" style="margin-top:8px">${keywords}</div>
    <div class="kv" style="margin-top:10px">
      <div><span>作者 / 许可</span><strong>${esc(plugin.author || '未填写')}${plugin.license ? ` · ${esc(plugin.license)}` : ''}</strong></div>
      <div><span>安装来源</span>${source}</div>
      <div><span>安装记录</span><strong>${origin}</strong></div>
      <div><span>清单指纹</span><strong class="mono">${esc(plugin.checksum || '—')}</strong></div>
      <div><span>声明权限</span><strong class="caps-inline">${scopes}</strong></div>
      <div><span>贡献页面</span><strong>${plugin.pages.length ? pages : '无'}</strong></div>
    </div>
    ${plugin.valid ? '' : `<div class="banner danger" style="margin-top:10px"><strong>${esc(plugin.error || '清单不合法')}</strong><span>修好 plugin.json 后点「更新…」重新安装</span></div>`}
    <div class="plugin-actions">${toggle}${update}${uninstall}</div>
  </section>`
}

function pluginEventDetail(event) {
  const raw = event.detail
  let detail = null
  if (typeof raw === 'string' && raw.trim().startsWith('{')) {
    try {
      detail = JSON.parse(raw)
    } catch {
      detail = null
    }
  }
  if (!detail) return esc((raw || '—').slice(0, 120))
  const bits = []
  if (detail.from && detail.to && detail.from === detail.to) {
    bits.push(`<span class="mono">${esc(detail.from)}</span>`, '同版本重装')
  } else if (detail.from) {
    bits.push(`<span class="mono">${esc(detail.from)} → ${esc(detail.to || '—')}</span>`)
  } else if (detail.to) {
    bits.push('安装', `<span class="mono">${esc(detail.to)}</span>`)
  }
  if (detail.version) bits.push(`<span class="mono">v${esc(detail.version)}</span>`)
  if (detail.source) {
    const source = String(detail.source)
    const label = PLUGIN_SOURCE_LABEL[source]
    bits.push(esc(label || (/^[A-Za-z]:[\\/]/.test(source) || source.startsWith('/') ? '本地目录' : source)))
  } else if (detail.sourceRef) {
    const ref = String(detail.sourceRef)
    bits.push(ref.startsWith('npm:') ? 'npm' : ref.startsWith('github:') ? 'GitHub' : '本地目录')
  }
  if (detail.shared) bits.push('共享目录保留')
  if (!bits.length && detail.reason) bits.push(esc(detail.reason))
  return bits.length ? `<div class="plugin-event-detail">${bits.join('<span class="muted">·</span>')}</div>` : '<span class="muted">—</span>'
}

function pluginEventRows(events) {
  if (!events.length) return '<tr><td colspan="5" class="muted">还没有生命周期操作记录</td></tr>'
  return events
    .map(
      (event) => `<tr>
        <td class="mono">${esc(fmtPluginTime(event.at))}</td>
        <td class="mono">${esc(event.pluginId)}</td>
        <td><span class="pill">${esc(PLUGIN_EVENT_LABEL[event.event] || event.event)}</span></td>
        <td>${esc(event.actorId || '—')}${event.companyId ? ` <span class="muted">· ${event.companyId === state.pluginData?.companyId ? '本司' : esc(event.companyId)}</span>` : ''}</td>
        <td>${pluginEventDetail(event)}</td>
      </tr>`,
    )
    .join('')
}

async function openPluginInstall(prefill = {}) {
  const data = state.pluginData
  if (!data) return
  const existing = prefill.id ? data.plugins.find((plugin) => plugin.id === prefill.id) : null
  const npmPrefill = parseNpmSourceRef(existing?.install?.sourceRef)
  const githubPrefill = parseGithubSourceRef(existing?.install?.sourceRef)
  const registries = data.installer.registries?.length
    ? data.installer.registries
    : [{ id: 'npm', label: 'npm 官方', url: 'https://registry.npmjs.org', hint: '海外直连' }]
  const defaultRegistry = registries.find((item) => item.id === 'npmmirror')?.url || registries[0].url
  const prefillRegistry = npmPrefill?.registry || defaultRegistry
  const registryIsPreset = registries.some((item) => item.url === prefillRegistry)
  let source = prefill.source
    || (existing?.install?.source === 'npm' ? 'npm' : existing?.install?.source === 'github' ? 'github' : 'local-dir')
  const localPrefill = prefill.sourcePath || (existing?.install?.source === 'local-dir' ? existing.install.sourceRef : '') || ''

  const registryOptions = registries
    .map(
      (item) =>
        `<option value="${esc(item.url)}" data-hint="${esc(item.hint)}"${item.url === prefillRegistry ? ' selected' : ''}>${esc(item.label)} · ${esc(item.url)}</option>`,
    )
    .join('')

  const companyName = state.companies?.find((item) => item.id === data.companyId)?.name || data.companyId || '当前公司'
  const overlay = modelModal(`
    <div class="modal-head install-modal-head">
      <div>
        <span class="install-eyebrow">PLUGIN INSTALLER</span>
        <h3>${existing ? '更新插件' : '安装插件'} ${hintBadge('当前公司', `安装到「${companyName}」 · 本地目录 / npm 国内镜像 / GitHub 三种来源；只记当前公司名下，其他公司看不到，也不共用启停状态。`, '安装范围说明')}</h3>
      </div>
      <button class="modal-x" type="button">×</button>
    </div>

    <div class="install-source-tabs" role="tablist" aria-label="安装来源">
      <button class="install-source-tab" type="button" data-install-source="local-dir">
        <span class="install-source-icon">⌂</span>
        <span><strong>本地目录</strong><small>服务器上已有包</small></span>
      </button>
      <button class="install-source-tab" type="button" data-install-source="npm">
        <span class="install-source-icon">◈</span>
        <span><strong>npm / 镜像</strong><small>registry + 国内镜像</small></span>
      </button>
      <button class="install-source-tab" type="button" data-install-source="github">
        <span class="install-source-icon">◐</span>
        <span><strong>GitHub</strong><small>仓库 + 分支 / 标签</small></span>
      </button>
    </div>

    <div class="install-panel" data-install-panel="local-dir">
      <label class="install-field"><span class="install-label">插件包目录（服务器绝对路径） ${hintBadge('包格式', '支持 EAB 插件（plugin.json）和 DSH 插件（package.json 带 dsh 段，含 bundle.patch / client 入口）。目录名不必等于插件 id。', '支持的插件包格式')}</span>
        <input id="pg-local-src" value="${esc(localPrefill)}" placeholder="例如 D:/dsh/dsh-mrrp 或 D:/AI kaifa/EAB/plugins/eab-plugin-oncall" />
      </label>
    </div>

    <div class="install-panel" data-install-panel="npm">
      <label class="install-field"><span class="install-label">npm 包名 ${hintBadge('包要求', '包里必须带 plugin.json；只取内容，不执行 npm install、prepare 或生命周期脚本。默认取 registry 的最新版本。', 'npm 包要求')}</span>
        <input id="pg-npm-name" value="${esc(npmPrefill?.packageName || '')}" placeholder="eab-plugin-oncall 或 @scope/eab-plugin-x" />
      </label>
      <label class="install-field"><span class="install-label">镜像源 ${hintBadge('镜像说明', '按需选择 npm registry；国内镜像同步更快。', '镜像源说明', '', 'pg-registry-hint')}</span>
        <select id="pg-npm-registry">
          ${registryOptions}
          <option value="custom"${registryIsPreset ? '' : ' selected'}>自定义 registry…</option>
        </select>
      </label>
      <label class="install-field is-hidden" id="pg-custom-registry-wrap">自定义 registry 地址
        <input id="pg-custom-registry" value="${esc(registryIsPreset ? '' : prefillRegistry)}" placeholder="https://registry.example.com" />
      </label>
    </div>

    <div class="install-panel" data-install-panel="github">
      <div class="install-grid">
        <label class="install-field install-span-2"><span class="install-label">GitHub 仓库 ${hintBadge('访问范围', '公开仓库可直接装；私有仓库暂不支持匿名下载。', 'GitHub 仓库访问范围')}</span>
          <input id="pg-github-repo" value="${esc(githubPrefill?.repo || '')}" placeholder="owner/repo，例如 xmanrui/dsh-im" />
        </label>
        <label class="install-field">分支 / 标签
          <input id="pg-github-ref" value="${esc(githubPrefill?.ref || '')}" placeholder="留空 = 默认分支；也可填 v1.0.0" />
        </label>
        <label class="install-field">仓库内子目录
          <input id="pg-github-subdir" value="${esc(githubPrefill?.subdir || '')}" placeholder="可选，例如 packages/my-plugin" />
        </label>
      </div>
    </div>

    ${existing ? `<div class="install-existing">
      <span class="pill ok">已装 ${esc(existing.id)}@${esc(existing.version)}</span>
      <span>更新会保留首次安装时间，只改版本 / 来源 / 指纹；旧版本目录在替换成功后直接删除。</span>
    </div>` : ''}

    <div class="install-options">
      <label class="install-check">
        <input type="checkbox" id="pg-overwrite"${existing ? ' checked' : ''} />
        <span><strong>覆盖更新</strong><small>仅本司已安装且没有其他公司在用时才能覆盖；旧目录替换成功即删除，失败时自动回滚</small></span>
      </label>
      <label class="install-check">
        <input type="checkbox" id="pg-enable" checked />
        <span><strong>安装后对当前公司启用</strong><small>只影响当前公司，可随时停用</small></span>
      </label>
    </div>

    <div class="install-flow">
      <span>① 取包</span><i>→</i><span>② 解包并校验</span><i>→</i><span>③ 落盘登记</span>
      <div class="install-note" id="pg-note"></div>
    </div>
    <div class="install-progress" id="pg-progress" hidden aria-live="polite">
      <div class="install-progress-track"><span class="install-progress-bar"></span></div>
      <div class="install-progress-meta">
        <span id="pg-progress-text">正在安装…</span>
        <span id="pg-progress-time" class="mono">0s</span>
      </div>
    </div>
    <div class="modal-state" id="pg-state"></div>
    <div class="modal-actions">
      <button class="btn primary" type="button" id="pg-save">${existing ? '更新' : '安装'}</button>
      <button class="btn ghost" type="button" id="pg-cancel">取消</button>
    </div>`)

  overlay.querySelector('.modal').classList.add('plugin-install-modal')
  const close = () => {
    if (progressTimer) clearInterval(progressTimer)
    overlay.remove()
  }
  const tabs = Array.from(overlay.querySelectorAll('[data-install-source]'))
  const panels = Array.from(overlay.querySelectorAll('[data-install-panel]'))
  const noteEl = overlay.querySelector('#pg-note')
  const stateEl = overlay.querySelector('#pg-state')
  const saveBtn = overlay.querySelector('#pg-save')
  const progressEl = overlay.querySelector('#pg-progress')
  const progressText = overlay.querySelector('#pg-progress-text')
  const progressTime = overlay.querySelector('#pg-progress-time')
  let progressTimer = null
  let progressStartedAt = 0

  const stopProgressClock = () => {
    if (progressTimer) clearInterval(progressTimer)
    progressTimer = null
  }
  const setInstalling = (busy) => {
    overlay.querySelector('.modal').classList.toggle('is-installing', busy)
    for (const control of overlay.querySelectorAll('.install-source-tab, .install-field input, .install-field select, .install-check input')) {
      control.disabled = busy
    }
  }
  const startProgress = (text) => {
    stopProgressClock()
    progressStartedAt = Date.now()
    progressEl.hidden = false
    progressEl.classList.remove('is-done')
    progressText.textContent = text
    progressTime.textContent = '0s'
    stateEl.className = 'modal-state'
    stateEl.textContent = ''
    setInstalling(true)
    progressTimer = setInterval(() => {
      const seconds = Math.max(0, Math.floor((Date.now() - progressStartedAt) / 1000))
      progressTime.textContent = `${seconds}s`
    }, 500)
  }
  const updateProgress = (text) => {
    progressText.textContent = text
  }
  const completeProgress = (text) => {
    stopProgressClock()
    progressEl.hidden = false
    progressEl.classList.add('is-done')
    progressText.textContent = text
    progressTime.textContent = '完成'
  }
  const failProgress = () => {
    stopProgressClock()
    progressEl.hidden = true
    setInstalling(false)
  }
  const registrySelect = overlay.querySelector('#pg-npm-registry')
  const customWrap = overlay.querySelector('#pg-custom-registry-wrap')
  const customInput = overlay.querySelector('#pg-custom-registry')
  const registryHint = overlay.querySelector('#pg-registry-hint')

  const sourceNotes = {
    'local-dir': '本地目录：直接复制到 plugins/<id>，先落暂存区二次校验；适合离线或内网部署。',
    npm: 'npm / 镜像：从 registry 拉 tarball 后解包校验；不执行 npm install、prepare 或任何生命周期脚本。',
    github: 'GitHub：下载仓库 tarball 后解包；仓库里必须有 plugin.json，源码构建产物需随仓库一起提交。',
  }

  const syncRegistryHint = () => {
    const selected = registrySelect.value
    const preset = registries.find((item) => item.url === selected)
    customWrap.classList.toggle('is-hidden', selected !== 'custom')
    const tip = selected === 'custom'
      ? '自定义 registry 需兼容 npm registry API（GET /<package> 返回 dist.tarball）。'
      : `${preset?.label || 'registry'}：${preset?.hint || ''}`
    registryHint.dataset.tip = tip
    registryHint.setAttribute('aria-label', `${preset?.label || '自定义 registry'}镜像源说明`)
  }

  const syncSource = (next) => {
    source = next
    for (const tab of tabs) {
      const active = tab.dataset.installSource === next
      tab.classList.toggle('is-active', active)
      tab.setAttribute('aria-selected', active ? 'true' : 'false')
    }
    for (const panel of panels) panel.classList.toggle('is-hidden', panel.dataset.installPanel !== next)
    noteEl.innerHTML = hintBadge('安装方式', sourceNotes[next] || '', '安装方式说明')
    stateEl.className = 'modal-state'
    stateEl.textContent = ''
  }

  registrySelect.addEventListener('change', syncRegistryHint)
  for (const tab of tabs) tab.addEventListener('click', () => syncSource(tab.dataset.installSource))
  syncRegistryHint()
  syncSource(source)

  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#pg-cancel').addEventListener('click', close)
  saveBtn.addEventListener('click', async () => {
    const body = {
      source,
      overwrite: overlay.querySelector('#pg-overwrite').checked,
      enable: overlay.querySelector('#pg-enable').checked,
    }
    if (source === 'local-dir') {
      body.sourcePath = overlay.querySelector('#pg-local-src').value.trim()
      if (!body.sourcePath) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '请填服务器上的插件包目录'
        return
      }
    } else if (source === 'npm') {
      body.packageName = overlay.querySelector('#pg-npm-name').value.trim()
      body.registry = registrySelect.value === 'custom' ? customInput.value.trim() : registrySelect.value
      if (!body.packageName) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '请填 npm 包名'
        return
      }
      if (registrySelect.value === 'custom' && !body.registry) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '请填自定义 registry 地址'
        return
      }
    } else {
      body.repo = overlay.querySelector('#pg-github-repo').value.trim()
      body.ref = overlay.querySelector('#pg-github-ref').value.trim()
      body.subdir = overlay.querySelector('#pg-github-subdir').value.trim()
      if (!body.repo) {
        stateEl.className = 'modal-state bad'
        stateEl.textContent = '请填 GitHub 仓库（owner/repo）'
        return
      }
    }

    const originText = source === 'npm'
      ? '正在从 npm 拉取 tarball 并解包（不执行安装脚本）…'
      : source === 'github'
        ? '正在从 GitHub 下载仓库 tarball 并解包…'
        : '正在安装：复制 → 校验 → 登记…'
    startProgress(originText)
    saveBtn.disabled = true
    saveBtn.textContent = existing ? '更新中…' : '安装中…'
    try {
      await apiPost('/api/console/plugins/install', body)
      completeProgress('安装完成，正在刷新插件列表…')
      try {
        await loadPlugins()
      } catch {
        // 安装已经成功，列表刷新失败不改变安装结果，也不阻止自动关闭。
      }
      await new Promise((resolve) => setTimeout(resolve, 900))
      close()
    } catch (err) {
      failProgress()
      saveBtn.disabled = false
      saveBtn.textContent = existing ? '更新' : '安装'
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '安装失败'
    }
  })
}

function openPluginUninstall(plugin) {
  const companyName = state.companies?.find((item) => item.id === state.pluginData?.companyId)?.name || state.pluginData?.companyId || '当前公司'
  const overlay = modelModal(`
    <div class="modal-head"><h3>从「${esc(companyName)}」卸载 ${esc(plugin.name)}</h3><button class="modal-x" type="button">×</button></div>
    <div class="plugin-uninstall-note" role="note" aria-label="卸载影响说明">
      <div class="plugin-uninstall-head">
        <span class="plugin-uninstall-icon" aria-hidden="true">!</span>
        <strong>卸载影响</strong>
        <span class="plugin-uninstall-scope">仅当前公司</span>
      </div>
      <div class="plugin-uninstall-grid">
        <div class="plugin-uninstall-row">
          <span class="plugin-uninstall-key">公司范围</span>
          <p class="plugin-uninstall-copy">只解除 <strong>当前公司</strong> 的安装与启停记录，不影响其他公司。</p>
        </div>
        <div class="plugin-uninstall-row">
          <span class="plugin-uninstall-key">共享目录</span>
          <p class="plugin-uninstall-copy">如果当前公司是最后一家使用它的公司，<code>plugins/${esc(plugin.id)}</code> 会被 <strong class="plugin-uninstall-danger">直接删除</strong>（不保留回收站副本）；否则共享目录保留。</p>
        </div>
      </div>
    </div>
    <div class="modal-state" id="pu-state"></div>
    <div class="modal-actions">
      <button class="btn danger" type="button" id="pu-save">确认卸载</button>
      <button class="btn ghost" type="button" id="pu-cancel">取消</button>
    </div>`)
  const close = () => overlay.remove()
  overlay.querySelector('.modal-x').addEventListener('click', close)
  overlay.querySelector('#pu-cancel').addEventListener('click', close)
  overlay.querySelector('#pu-save').addEventListener('click', async () => {
    const stateEl = overlay.querySelector('#pu-state')
    stateEl.textContent = '卸载中…'
    try {
      await apiPost(`/api/console/plugins/${encodeURIComponent(plugin.id)}/uninstall`, {})
      close()
      await loadPlugins()
    } catch (err) {
      stateEl.className = 'modal-state bad'
      stateEl.textContent = err.message || '卸载失败'
    }
  })
}

function pluginHostOf(data, id) {
  return (data.hosts || []).find((host) => host.id === id) || null
}

function pluginPageUrl(data, plugin, page) {
  const version = encodeURIComponent(plugin.version || '')
  const checksum = encodeURIComponent(plugin.checksum || '')
  const company = encodeURIComponent(data.companyId || '')
  if ((page.kind || 'html') === 'dsh-client') {
    const inject = encodeURIComponent((plugin.dsh?.clientInject || []).join(','))
    return `/plugin-kernel.html?id=${encodeURIComponent(plugin.id)}&entry=${encodeURIComponent(page.file)}&company=${company}&version=${version}&h=${checksum}&title=${encodeURIComponent(page.title)}&inject=${inject}`
  }
  return `/plugins/assets/${encodeURIComponent(plugin.id)}/${page.file}${qs()}`
}

/** 插件 client bundle 的稳定 URL；v= 版本、h= 校验和，同版本覆盖更新也能失效。 */
function pluginClientAssetUrl(plugin, page) {
  const path = String(page.file || '')
    .split('/')
    .map((part) => encodeURIComponent(part))
    .join('/')
  const version = encodeURIComponent(plugin.version || '')
  const checksum = encodeURIComponent(plugin.checksum || '')
  const versionKey = version ? `&v=${version}` : ''
  const checksumKey = checksum ? `&h=${checksum}` : ''
  return `/plugins/assets/${encodeURIComponent(plugin.id)}/${path}?scope=console${versionKey}${checksumKey}`
}

let pluginKernelWarmStarted = false
const prefetchedPluginAssets = new Set()

/** 只拉进 HTTP 缓存，不解析、不执行插件代码；同一 URL 在一次页面会话里只发一次。 */
function prefetchPluginClientBundles(plugins) {
  for (const plugin of plugins || []) {
    if (!plugin.valid || !plugin.enabled) continue
    for (const page of plugin.pages || []) {
      if ((page.kind || 'html') !== 'dsh-client') continue
      const url = pluginClientAssetUrl(plugin, page)
      if (prefetchedPluginAssets.has(url)) continue
      prefetchedPluginAssets.add(url)
      fetch(url, { credentials: 'include', cache: 'force-cache' }).catch(() => {})
    }
  }
}
/**
 * 控制台打开插件页时先把共享内核预热，并把各插件的 client bundle 拉进 HTTP 缓存。
 * 预热页只执行 Cordis/slots/primitives/renderer，不执行任何插件代码，避免为了“快”
 * 把多个插件的副作用一起启动；真正的插件仍在用户点击时按 iframe 隔离启动。
 */
function warmPluginKernel(data) {
  if (!data || !data.companyId) return
  const run = () => {
    // 共享内核只启动一次；每轮插件列表刷新只补拉新增/升级的 bundle。
    if (!pluginKernelWarmStarted) {
      pluginKernelWarmStarted = true
      const frame = document.createElement('iframe')
      frame.src = `/plugin-kernel.html?warm=1&scope=console&company=${encodeURIComponent(data.companyId)}`
      frame.title = 'DSH 插件内核预热'
      frame.tabIndex = -1
      frame.setAttribute('aria-hidden', 'true')
      frame.style.cssText = 'position:absolute;width:1px;height:1px;left:-10px;top:-10px;opacity:0;pointer-events:none;border:0'
      let cleaned = false
      const cleanup = () => {
        if (cleaned) return
        cleaned = true
        frame.remove()
        window.removeEventListener('message', onMessage)
      }
      const onMessage = (event) => {
        if (event.origin !== location.origin) return
        if (event.source !== frame.contentWindow) return
        if (event.data && event.data.type === 'eab-plugin-kernel-warm') cleanup()
      }
      window.addEventListener('message', onMessage)
      frame.addEventListener('load', () => {
        // 页面 load 不代表异步内核加载完成；正常由 postMessage 清理，这里只做兜底。
        setTimeout(cleanup, 8000)
      }, { once: true })
      document.body.appendChild(frame)
    }

    prefetchPluginClientBundles(data.plugins || [])
  }
  if (typeof window.requestIdleCallback === 'function') {
    window.requestIdleCallback(run, { timeout: 2000 })
  } else {
    setTimeout(run, 800)
  }
}

function pluginFormatBadge(plugin) {
  return plugin.format === 'dsh'
    ? '<span class="plugin-format-badge dsh">DSH</span>'
    : '<span class="plugin-format-badge">EAB</span>'
}

function pluginStatusPill(plugin, host) {
  if (!plugin.valid) return '<span class="pill danger">清单不合法</span>'
  if (!plugin.enabled) return '<span class="pill warn">已停用</span>'
  if (host && host.error) return '<span class="pill warn">启用 · host 异常</span>'
  if (host && Array.isArray(host.hostGaps) && host.hostGaps.length) {
    return `<span class="pill warn" title="${esc(host.hostGaps.map((gap) => gap.message).join('\n'))}">启用 · 能力缺口</span>`
  }
  if (host) return '<span class="pill ok">运行中</span>'
  if (plugin.install && plugin.install.removedAt) return '<span class="pill">已卸载</span>'
  if (!plugin.install) return '<span class="pill">已发现</span>'
  return '<span class="pill ok">已启用</span>'
}

/** 插件侧栏的搜索词：重新渲染侧栏后仍然保留，避免边搜边被刷掉 */
const pluginRailSearch = { company: '', personal: '' }

/** 模糊过滤插件列表：忽略大小写、空格分词，所有词都命中才显示（只切 hidden，不重绘 DOM） */
function filterPluginRail(kind) {
  const list = document.querySelector(`[data-plugin-list="${kind}"]`)
  if (!list) return
  const tokens = String(pluginRailSearch[kind] || '').trim().toLowerCase().split(/\s+/).filter(Boolean)
  const items = Array.from(list.querySelectorAll('[data-plugin-item]'))
  let shown = 0
  for (const item of items) {
    const hay = String(item.dataset.search || item.textContent || '').toLowerCase()
    const hit = tokens.every((token) => hay.includes(token))
    item.hidden = !hit
    if (hit) shown += 1
  }
  const empty = list.querySelector('[data-plugin-search-empty]')
  if (empty) empty.hidden = !(items.length > 0 && shown === 0)
}

/** 绑定两个搜索框（用 oninput 赋值，重复绑定不会叠加监听） */
function bindPluginRailSearch() {
  for (const input of document.querySelectorAll('[data-plugin-search]')) {
    const kind = input.dataset.pluginSearch
    if (!kind) continue
    input.value = pluginRailSearch[kind] || ''
    input.oninput = () => {
      pluginRailSearch[kind] = input.value
      filterPluginRail(kind)
    }
    input.onkeydown = (event) => {
      if (event.key !== 'Escape' || !input.value) return
      event.stopPropagation()
      input.value = ''
      pluginRailSearch[kind] = ''
      filterPluginRail(kind)
    }
  }
  filterPluginRail('company')
  filterPluginRail('personal')
}

function pluginRailItem(plugin, selected) {
  const initial = (plugin.name || plugin.id || '?').trim().slice(0, 1).toUpperCase()
  const sub = plugin.format === 'dsh'
    ? `DSH · ${plugin.dsh?.hasHost ? 'host+client' : 'client'}`
    : `EAB · ${plugin.pages.length} 页`
  const search = [plugin.name, plugin.id, plugin.version, plugin.format].filter(Boolean).join(' ')
  return `<button class="plugin-rail-item${selected ? ' is-active' : ''}" type="button" data-select-plugin="${esc(plugin.id)}" data-plugin-item data-search="${esc(search)}">
    <span class="plugin-rail-avatar">${esc(initial)}</span>
    <span class="plugin-rail-text">
      <strong>${esc(plugin.name)}</strong>
      <small><span class="mono">${esc(plugin.version)}</span> · ${esc(sub)}</small>
    </span>
    <span class="plugin-rail-dot ${!plugin.valid ? 'bad' : plugin.enabled ? 'ok' : 'warn'}" title="${plugin.valid ? (plugin.enabled ? '启用' : '停用') : '清单不合法'}"></span>
  </button>`
}

function personalPluginRailItem(plugin, selected) {
  const initial = (plugin.name || plugin.pluginId || '?').trim().slice(0, 1).toUpperCase()
  const search = [plugin.name, plugin.pluginId, plugin.key, plugin.userName, plugin.version].filter(Boolean).join(' ')
  return `<button class="plugin-rail-item is-personal${selected ? ' is-active' : ''}" type="button" data-select-personal-plugin="${esc(plugin.key)}" data-plugin-item data-search="${esc(search)}">
    <span class="plugin-rail-avatar">${esc(initial)}</span>
    <span class="plugin-rail-text">
      <strong>${esc(plugin.name)}</strong>
      <small><span class="plugin-personal-badge">个人</span> ${esc(plugin.userName)} · <span class="mono">${esc(plugin.version)}</span></small>
    </span>
    <span class="plugin-rail-dot ${!plugin.valid ? 'bad' : plugin.enabled ? 'ok' : 'warn'}" title="${plugin.valid ? (plugin.enabled ? '个人启用' : '个人停用') : '清单不合法'}"></span>
  </button>`
}

function pluginOverviewBody(data, plugin, host) {
  const dsh = plugin.dsh
  const pages = plugin.pages.length
    ? plugin.pages
        .map(
          (page) =>
            `<button class="btn sm" type="button" data-open-page="${esc(page.id)}"${plugin.valid && plugin.enabled ? '' : ' disabled'}>打开「${esc(page.title)}」</button>`,
        )
        .join(' ')
    : '<span class="muted">这个插件没有贡献页面</span>'
  const injects = dsh?.clientInject?.length
    ? dsh.clientInject.map((item) => `<span class="chip mono">${esc(item.replace('@deepseek-ai/dsh-client-', ''))}</span>`).join('')
    : '<span class="muted">未声明 client.inject</span>'
  const protocol = plugin.format === 'dsh'
    ? `<div><span>DSH 包名</span><strong class="mono">${esc(dsh?.packageName || plugin.id)}</strong></div>
      <div><span>宿主版本要求</span><strong>${esc(dsh?.compatibility?.dsh || '未声明')}</strong></div>
      <div><span>profile</span><strong>${esc(dsh?.compatibility?.profiles?.join(' / ') || '未声明')}</strong></div>
      <div><span>host 入口</span><strong class="mono">${esc(dsh?.hostEntry || '—（纯 client 插件）')}</strong></div>
      <div><span>client 入口</span><strong class="mono">${esc(dsh?.clientEntry || '—')}</strong></div>
      <div><span>bundle patch</span><strong class="mono">${esc(dsh?.bundlePatch || '—')}</strong></div>
      <div><span>host 运行</span><strong>${host ? (host.error ? `异常：${esc(host.error)}` : `已运行 · ${host.routes.length} 条通道`) : '未加载'}</strong></div>`
    : `<div><span>清单格式</span><strong>EAB plugin.json</strong></div>
      <div><span>声明权限</span><strong class="caps-inline">${plugin.scopes.length ? plugin.scopes.map((scope) => `<span class="chip" title="${esc(scope)}">${esc(scope)}</span>`).join('') : '<span class="muted">未声明</span>'}</strong></div>`
  const source = plugin.install
    ? `<div class="plugin-source-ref"><span>${esc(PLUGIN_SOURCE_LABEL[plugin.install.source] || plugin.install.source)}</span><span class="mono" title="${esc(plugin.install.sourceRef || plugin.install.source)}">${esc(plugin.install.sourceRef || plugin.install.source)}</span></div>`
    : '<strong class="muted">部署侧放进 plugins/，尚未登记安装</strong>'
  const installAt = plugin.install
    ? `${esc(fmtPluginTime(plugin.install.installedAt))} · ${esc(plugin.install.installedBy || '未知操作人')}`
    : '—'

  return `<div class="plugin-overview">
    <div class="plugin-block">
      <h3>清单与协议</h3>
      <div class="kv plugin-kv">
        <div><span>作者 / 许可</span><strong>${esc(plugin.author || '未填写')}${plugin.license ? ` · ${esc(plugin.license)}` : ''}</strong></div>
        <div><span>关键词</span><strong>${plugin.keywords.length ? plugin.keywords.map((item) => `<span class="chip">${esc(item)}</span>`).join('') : '<span class="muted">没有标签</span>'}</strong></div>
        ${protocol}
      </div>
      ${plugin.format === 'dsh' ? `<div class="plugin-inject-row"><span>client.inject</span><div>${injects}</div></div>` : ''}
    </div>
    <div class="plugin-block">
      <h3>安装与来源</h3>
      <div class="kv plugin-kv">
        <div><span>安装来源</span>${source}</div>
        <div><span>安装记录</span><strong>${installAt}</strong></div>
        <div><span>清单指纹</span><strong class="mono">${esc(plugin.checksum || '—')}</strong></div>
        <div><span>启停归属</span><strong>${plugin.personal ? '个人安装' : '当前公司'}</strong></div>
      </div>
      <div class="plugin-page-list"><span>贡献页面</span><div>${pages}</div></div>
    </div>
  </div>
  ${plugin.valid ? '' : `<div class="banner danger" style="margin-top:12px"><strong>${esc(plugin.error || '清单不合法')}</strong><span>修好清单后点「更新…」重新安装，或直接卸载。</span></div>`}`
}

function pluginPagesBody(data, plugin) {
  if (!plugin.valid) return `<div class="banner danger"><strong>清单不合法，页面不可用</strong><span>${esc(plugin.error || '')}</span></div>`
  if (!plugin.enabled) {
    return `<div class="plugin-page-blocked"><strong>当前公司已停用这个插件</strong><span>启用后页面才能加载，插件的 RPC 通道也只在启用时运行。</span>
      <button class="btn primary sm" type="button" data-enable-plugin="${esc(plugin.id)}">启用（本司）</button></div>`
  }
  if (!plugin.pages.length) return '<div class="empty plugin-empty-inline">这个插件没有贡献页面（只提供 host 能力或工具）。</div>'
  const activeKey = state.pluginPageKey && plugin.pages.some((page) => page.id === state.pluginPageKey)
    ? state.pluginPageKey
    : plugin.pages[0].id
  const page = plugin.pages.find((item) => item.id === activeKey) || plugin.pages[0]
  const src = pluginPageUrl(data, plugin, page)
  const switchButtons = plugin.pages.length > 1
    ? `<div class="plugin-page-switch">${plugin.pages
        .map(
          (item) =>
            `<button class="plugin-page-tab${item.id === page.id ? ' is-active' : ''}" type="button" data-open-page="${esc(item.id)}">${esc(item.title)}</button>`,
        )
        .join('')}</div>`
    : ''
  return `${switchButtons}
    <div class="plugin-frame"><iframe data-plugin-frame src="${esc(src)}" title="${esc(page.title)}" sandbox="allow-same-origin allow-scripts allow-forms"></iframe></div>`
}

function pluginVersionsBody(data, plugin) {
  const install = plugin.install
  const installed = install ? fmtPluginTime(install.installedAt) : '—'
  const updated = install?.updatedAt ? fmtPluginTime(install.updatedAt) : '—'
  const registry = install?.sourceRef || install?.source || '—'
  return `<div class="plugin-version-current">
      <div><span class="plugin-version-label">当前版本</span><strong class="mono">${esc(plugin.version)}</strong></div>
      <div class="plugin-version-actions">
        <button class="btn sm" type="button" data-update-plugin="${esc(plugin.id)}"${plugin.format === 'dsh' ? '' : ''}>更新…</button>
      </div>
    </div>
    <div class="kv plugin-kv">
      <div><span>安装版本</span><strong class="mono">${esc(install?.version || plugin.version)}</span></div>
      <div><span>清单指纹</span><strong class="mono">${esc(plugin.checksum || install?.checksum || '—')}</strong></div>
      <div><span>首次安装</span><strong>${esc(installed)}</strong></div>
      <div><span>最后更新</span><strong>${esc(updated)}</strong></div>
      <div><span>来源</span><strong class="mono">${esc(registry)}</strong></div>
      <div><span>安装范围</span><strong>${plugin.personal ? '个人' : '当前公司'}</strong></div>
    </div>
    ${hintNote('更新说明', '更新只改版本 / 来源 / 指纹，保留首次安装时间；旧版本目录在替换成功后直接删除。同版本也可重装（覆盖更新）。')}`
}

function pluginSettingsBody(data, plugin, host) {
  const hostLogs = host?.logs?.length ? esc(host.logs.slice(-8).join('\n')) : '（暂无宿主日志）'
  const routes = host?.routes?.length
    ? host.routes.map((route) => `<span class="chip mono">${esc(route)}</span>`).join('')
    : '<span class="muted">没有挂载 RPC 通道</span>'
  const dshSettings = plugin.format === 'dsh'
    ? `<div class="plugin-setting-row">
        <div><strong>宿主运行状态</strong><span>host 侧 apply() 是否跑通、注册了哪些 RPC 通道；插件页面通过它们读写自己的数据。</span></div>
        <span class="pill ${host && !host.error ? 'ok' : 'warn'}">${host && !host.error ? '运行中' : host?.error ? '异常' : '未加载'}</span>
      </div>
      <div class="plugin-host-detail">
        <div class="plugin-host-routes">${routes}</div>
        ${host?.error ? `<div class="banner danger"><strong>${esc(host.error)}</strong><span>检查 host 入口、依赖或插件日志；修好后重新启停或更新插件。</span></div>` : ''}
        <pre class="plugin-host-log">${hostLogs}</pre>
        <div class="plugin-actions"><button class="btn sm" type="button" data-reload-host>刷新宿主状态</button></div>
      </div>`
    : `<div class="plugin-setting-row"><div><strong>页面运行方式</strong><span>EAB 原生插件页面：静态 HTML + iframe 沙箱，可自行调用 EAB 的 HTTP API。</span></div><span class="pill">HTML</span></div>`

  return `<div class="plugin-setting-row">
      <div><strong>当前公司启用</strong><span>启停只记在「${esc(data.companyId)}」名下；停用后页面与宿主通道一起下线。</span></div>
      <button class="btn ${plugin.enabled ? 'sm' : 'primary sm'}" type="button" data-toggle-plugin="${esc(plugin.id)}" data-next="${plugin.enabled ? 'false' : 'true'}">${plugin.enabled ? '停用（本司）' : '启用（本司）'}</button>
    </div>
    ${dshSettings}
    <div class="plugin-danger-zone">
      <div><strong>卸载</strong><span>解除当前公司的安装与启停记录；最后一家公司卸载时直接删除插件目录。</span></div>
      <button class="btn danger sm" type="button" data-uninstall-plugin="${esc(plugin.id)}">卸载…</button>
    </div>`
}

function pluginLogsBody(data, plugin) {
  const events = (data.events || []).filter((event) => event.pluginId === plugin.id)
  return `<table class="data plugin-events-table">
    <thead><tr><th>时间</th><th>动作</th><th>操作人</th><th>详情</th></tr></thead>
    <tbody>${events.length
      ? events
          .map(
            (event) => `<tr>
        <td class="mono">${esc(fmtPluginTime(event.at))}</td>
        <td><span class="pill">${esc(PLUGIN_EVENT_LABEL[event.event] || event.event)}</span></td>
        <td>${esc(event.actorId || '—')}</td>
        <td>${pluginEventDetail(event)}</td>
      </tr>`,
          )
          .join('')
      : '<tr><td colspan="4" class="muted">这个插件还没有生命周期记录</td></tr>'}</tbody>
  </table>`
}

function pluginDetailHtml(data, plugin) {
  const host = pluginHostOf(data, plugin.id)
  const tab = state.pluginTab || 'overview'
  const tabs = [
    ['overview', '概览', ''],
    ['pages', `页面${plugin.pages.length ? ` <span class="plugin-tab-count">${plugin.pages.length}</span>` : ''}`, ''],
    ['versions', '版本', ''],
    ['settings', '设置', ''],
    ['logs', `生命周期${(data.events || []).filter((event) => event.pluginId === plugin.id).length ? ` <span class="plugin-tab-count">${(data.events || []).filter((event) => event.pluginId === plugin.id).length}</span>` : ''}`, ''],
  ]
  const tabBar = tabs
    .map(
      ([key, label]) =>
        `<button class="plugin-tab${tab === key ? ' is-active' : ''}" type="button" data-plugin-tab="${key}">${label}</button>`,
    )
    .join('')
  let body = pluginOverviewBody(data, plugin, host)
  if (tab === 'pages') body = pluginPagesBody(data, plugin)
  else if (tab === 'versions') body = pluginVersionsBody(data, plugin)
  else if (tab === 'settings') body = pluginSettingsBody(data, plugin, host)
  else if (tab === 'logs') body = pluginLogsBody(data, plugin)
  const initial = (plugin.name || plugin.id || '?').trim().slice(0, 1).toUpperCase()

  return `<section class="panel plugin-detail">
    <div class="plugin-detail-head">
      <div class="plugin-title">
        <div class="plugin-avatar">${esc(initial)}</div>
        <div class="plugin-title-text">
          <div class="plugin-title-row"><h2>${esc(plugin.name)}</h2>${pluginFormatBadge(plugin)}${pluginStatusPill(plugin, host)}</div>
          <div class="plugin-subline"><span class="mono">${esc(plugin.id)}@${esc(plugin.version)}</span>${plugin.format === 'dsh' ? `<span class="muted">· DSH 插件协议</span>` : ''}</div>
        </div>
      </div>
      <div class="plugin-detail-actions">
        <button class="btn ghost sm" type="button" data-close-plugin>收起</button>
        <button class="btn sm" type="button" data-toggle-plugin="${esc(plugin.id)}" data-next="${plugin.enabled ? 'false' : 'true'}">${plugin.enabled ? '停用' : '启用'}</button>
        <button class="btn sm" type="button" data-update-plugin="${esc(plugin.id)}">更新…</button>
        <button class="btn ghost sm" type="button" data-uninstall-plugin="${esc(plugin.id)}">卸载…</button>
      </div>
    </div>
    <div class="plugin-tabs">${tabBar}</div>
    <div id="plugin-tab-body">${body}</div>
  </section>`
}

